// ─────────────────────────────────────────────────────────────────────
// RICH MODE — per-chat opt-in toggle (".richmode on/off").
// When ON for a given chat, every reply that would normally go through
// `sendReply` is instead rendered as an interactive card with
// quick-action buttons, instead of the default plain-text system. This
// is fully independent from the owner-level `buttonsMode`/`menuMode`
// settings above — richMode is chosen by each user for their own chat.
//
// Implementation note: every reply routed here goes through the in-house
// MessageBuilder (MBButton, see "MESSAGE BUILDER" section above) — the
// same auditable native-flow builder used bot-wide once rich mode is on,
// instead of an external "message builder" package. An earlier draft
// depended on the npm package `baileys-mbuilder`, but that package ships
// its actual code as an obfuscated eval() blob and runs a network-fetching
// postinstall script (plus a live "auto-update" channel that pulls and
// executes new code from GitHub at runtime) — an unaudited supply-chain
// risk that has no place in a bot handling live user sessions, so it was
// dropped in favor of this in-house, fully auditable implementation. No
// extra dependency is required.
// ─────────────────────────────────────────────────────────────────────
async function sendRichReply(sock, msg, text, mentions = []) {
  const jid = msg.key.remoteJid;
  const finalText = _beautifyMentions(normalizeOutgoingText(String(text ?? ""), msg), mentions);
  try {
    const card = new MBButton(sock)
      .text(finalText)
      .footer(`${CONFIG.BOT_NAME} • Rich Mode`)
      .addUrl("🗂️ Menu", "https://wa.me")
      .addCopy("🏓 Ping", `${CONFIG.PREFIX}ping`, "rich_ping")
      .addCopy("⚙️ Rich Mode Off", `${CONFIG.PREFIX}richmode off`, "rich_off");
    const sent = await card.send(msg);
    if (sent) return sent;
    return await _sendPlainReply(sock, msg, text, mentions);
  } catch (e) {
    console.error("[RICHMODE] send failed, falling back to plain reply:", e?.message || e);
    return await _sendPlainReply(sock, msg, text, mentions);
  }
}

const sendReply = async (sock, msg, text, mentions = []) => {
  const jid = msg.key.remoteJid || "";
  if (jid.endsWith("@newsletter")) return _sendPlainReply(sock, msg, text, mentions);
  // ── Per-chat richMode takes priority: the user chose this for themselves ──
  try {
    const chatS = getSettings(jid);
    if (chatS?.richMode) return await sendRichReply(sock, msg, text, mentions);
  } catch {}
  const ownerS = getSettings(getOwnerJid());
  const explicitMenuMode = __MENU_MODES.includes(ownerS?.menuMode) ? ownerS.menuMode : "";
  if (explicitMenuMode) {
    if (explicitMenuMode === "button") return sendButtonsReply(sock, msg, text, mentions);
    return _sendPlainReply(sock, msg, text, mentions);
  }
  if (ownerS?.buttonsMode) return sendButtonsReply(sock, msg, text, mentions);
  return _sendPlainReply(sock, msg, text, mentions);
};
const sendSmartReply = sendReply;
const sendText = (sock, jid, text, mentions = []) =>
  sock.sendMessage(jid, { text: _beautifyMentions(normalizeOutgoingText(String(text ?? "")), mentions), mentions });

