// ADULT VIDEO HELPER + per-chat picker store (.xxnx → numbered list → reply N)
// ─────────────────────────────────────────────────────────────────────
const _lastAdultResults = new Map(); // jid → [{ title, url, thumb }]

async function sendAdultVideo(sock, jid, msg, item, opts = {}) {
  const caption = `${opts.captionPrefix || "🔞"}\n\n*${item.title || ""}*${item.duration ? `\n⏱ ${item.duration}` : ""}${item.views ? `\n👁 ${item.views}` : ""}`;
  const pageUrl = _itemPageUrl(item);
  try {
    // 1. Try direct mp4 field from item first
    const direct = _pickDirectFromItem(item);
    let mp4 = direct;
    // 2. Resolve from page URL using multi-provider downloader
    if (!mp4) mp4 = await _resolvePageToMp4(pageUrl);
    if (mp4) {
      // Try to buffer and send as video
      try {
        let buf = await _downloadVideoBuf(mp4, pageUrl);
        if (buf) { try { const _vn = require("./lib/portableVideo.cjs"); buf = await _vn.normalizeVideoBuffer(buf, { timeoutMs: 120000 }); } catch (_e) {} }
        if (buf && buf.length > 50000) {
          // If too large for WhatsApp (~64MB limit), send as document
          if (buf.length > 60 * 1024 * 1024) {
            await sock.sendMessage(jid, {
              document: buf, mimetype: "video/mp4", fileName: `${(item.title || "video").slice(0,40).replace(/[^a-zA-Z0-9]/g,"_")}.mp4`,
              caption,
            }, { quoted: msg });
            return true;
          }
          await sock.sendMessage(jid, { video: buf, mimetype: "video/mp4", caption }, { quoted: msg });
          return true;
        }
      } catch {}
      // Buffer failed — stream via URL directly before falling back to text link
      try {
        await sock.sendMessage(jid, { video: { url: mp4 }, mimetype: "video/mp4", caption }, { quoted: msg });
        return true;
      } catch {}
      try {
        await sendReply(sock, msg, `${caption}\n\n📥 *Direct link:*\n${mp4}`);
        return true;
      } catch {}
    }
    // 3. No mp4 found — send page URL as fallback
    if (pageUrl) {
      await sendReply(sock, msg, `${caption}\n\n🔗 *Watch here:*\n${pageUrl}\n\n_(tap to open in browser)_`);
      return true;
    }
    return false;
  } catch (e) { console.error("[sendAdultVideo]", e?.message); return false; }
}

async function sendLongText(sock, jid, text, quoted = null, mentions = []) {
  const value = String(text || "").trim();
  if (!value) return;
  const limit = 3500;
  let remaining = value;

  while (remaining.length) {
    let chunk = remaining.slice(0, limit);
    if (remaining.length > limit) {
      const breakAt = Math.max(
        chunk.lastIndexOf("\n\n"),
        chunk.lastIndexOf("\n"),
        chunk.lastIndexOf(". "),
        chunk.lastIndexOf(" ")
      );
      if (breakAt > 1000) {
        chunk = chunk.slice(0, breakAt + (chunk[breakAt] === " " ? 0 : 1));
      }
    }

    const payload = mentions.length ? { text: normalizeOutgoingText(chunk), mentions } : { text: normalizeOutgoingText(chunk) };
    await sock.sendMessage(jid, payload, quoted ? { quoted } : {});
    remaining = remaining.slice(chunk.length).trimStart();
  }
}

// react() honors the per-owner autoReact toggle (.autoreact ON/OFF). When OFF,
// every command's react() call becomes a no-op so the bot stays silent.
const react = (sock, msg, emoji) => {
  try {
    const ownerJ = (CONFIG.OWNER_NUMBER || "").replace(/[^0-9]/g, "") + "@s.whatsapp.net";
    const _s = (typeof getSettings === "function" ? getSettings(ownerJ) : null);
    if (_s && _s.autoReact === false) return Promise.resolve();
  } catch {}
  const _reactKey = {
    remoteJid: msg.key.remoteJid,
    fromMe: msg.key.fromMe ?? false,
    id: msg.key.id,
  };
  if (msg.key.participant) _reactKey.participant = msg.key.participant;
  return sock.sendMessage(msg.key.remoteJid, { react: { text: emoji, key: _reactKey } }).catch(() => {});
};
// Selection/download feedback must not depend on the owner's autoReact
// preference.  A TikTok format picker otherwise looks broken: the media may
// be processing while no progress reaction is shown.
const forceReaction = (sock, msg, emoji) => {
  const key = {
    remoteJid: msg.key.remoteJid,
    fromMe: msg.key.fromMe ?? false,
    id: msg.key.id,
  };
  if (msg.key.participant) key.participant = msg.key.participant;
  return sock.sendMessage(msg.key.remoteJid, { react: { text: emoji, key } })
    .catch(() => sock.sendMessage(msg.key.remoteJid, { react: { text: emoji, key: msg.key } }))
    .catch(() => {});
};

// ═══════════════════════════════════════════════════════════════════════════
//  ERROR NOTIFICATION SYSTEM — auto-DM owner when any command errors
// ═══════════════════════════════════════════════════════════════════════════
const _errNotifCooldown = new Map();
const notifyOwnerError = async (sock, msg, cmdName, err) => {
  try {
    const ownerNum = (CONFIG.OWNER_NUMBER || LOCKED_OWNER_NUMBER || "").replace(/[^0-9]/g, "");
    if (!ownerNum) return;
    const ownerJid = ownerNum + "@s.whatsapp.net";
    // Rate-limit: max 1 DM per cmd per 3 minutes to avoid spam
    const lastSent = _errNotifCooldown.get(cmdName) || 0;
    if (Date.now() - lastSent < 3 * 60 * 1000) return;
    _errNotifCooldown.set(cmdName, Date.now());
    const sender = (msg?.key?.participant || msg?.key?.remoteJid || "Unknown").split("@")[0];
    const chat = (msg?.key?.remoteJid || "Unknown");
    const isGrp = chat.endsWith("@g.us");
    const errMsg = (err?.message || String(err) || "Unknown error").slice(0, 500);
    const report =
`🚨 *BOT ERROR REPORT*
━━━━━━━━━━━━━━━━━━━━

🤖 *Bot:* ${CONFIG.BOT_NAME}
⌨️ *Command:* ${CONFIG.PREFIX}${cmdName}
👤 *Triggered by:* @${sender}
📍 *Chat:* ${isGrp ? "Group 👥" : "DM 💬"} (${chat.split("@")[0]})
🕒 *Time:* ${new Date().toLocaleString("en-NG", { timeZone: "Africa/Lagos" })}

❌ *Error Message:*
\`\`\`
${errMsg}
\`\`\`

_Check your server console for the full stack trace._`;
    await sock.sendMessage(ownerJid, { text: report });
  } catch {}
};

const processedMessages = new Set();
// ── Message store for retry decryption ──
const _msgRetryStore = new Map();
function storeMessage(msg) {
  if (msg?.key?.id && msg?.message) {
    let stored = null;
    try {
      stored = JSON.parse(JSON.stringify(unwrapMessageContent(msg.message) || msg.message));
    } catch {
      stored = unwrapMessageContent(msg.message) || msg.message;
    }
    if (!stored || typeof stored !== "object") return;
    stored._jid = msg.key.remoteJid;
    stored._fromMe = !!msg.key.fromMe;
    stored._participant = msg.key.participant || msg.participant || msg.key.remoteJid;
    // Cache pushName for richer anti-delete headers
    stored._pushName = msg.pushName || msg.verifiedBizName || "";
    const ts = msg.messageTimestamp?.low || msg.messageTimestamp || Math.floor(Date.now() / 1000);
    stored._ts = Number(ts) * 1000;
    _msgRetryStore.set(msg.key.id, stored);
    if (_msgRetryStore.size > 3000) {
      const first = _msgRetryStore.keys().next().value;
      _msgRetryStore.delete(first);
    }
  }
}
async function downloadStoredMediaBuffer(mediaNode, type) {
  const stream = await downloadContentFromMessage(mediaNode, type);
  let buf = Buffer.from([]);
  for await (const chunk of stream) buf = Buffer.concat([buf, chunk]);
  return buf;
}
function rememberMessage(msg) {
  const key = [msg?.key?.remoteJid || "", msg?.key?.participant || "", msg?.key?.id || ""].join("|");
  if (!key.replace(/\|/g, "").trim()) return false;
  if (processedMessages.has(key)) return false;
  processedMessages.add(key);
  if (processedMessages.size > 10000) {
    const iter = processedMessages.values();
    for (let i = 0; i < 2000; i++) {
      const val = iter.next().value;
      if (val) processedMessages.delete(val);
    }
  }
  return true;
}

// ─────────────────────────────────────────────────────────────────────
// v15: AUTO CACHE CLEANER — runs every 2 minutes to keep RAM low and
// reply latency snappy on small panels (Pterodactyl 256–512MB, Heroku,
// Termux, low-spec VPS). Clears transient/in-memory caches but PRESERVES:
//   • pushNameCache   (push names — needed for nice mentions, persisted to disk)
//   • settings/economy/sudoUsers/bannedUsers/etc. (persistent stores)
//   • _msgRetryStore  (decryption retry counters — clearing breaks msgs)
//   • _lidToJidMap    (LID resolution map — re-fetching is expensive)
//   • _ownerLidJid / _botJid (owner identity)
// Tunable via CACHE_CLEAN_MIN env var (default 2).
// ─────────────────────────────────────────────────────────────────────
const CACHE_CLEAN_MS = Math.max(1, parseInt(process.env.CACHE_CLEAN_MIN || "1", 10)) * 60 * 1000;
function autoCleanCaches() {
  try {
    const before = {
      msgRetry: _msgRetryStore.size,
      processed: processedMessages.size,
      adult: (typeof _lastAdultResults !== "undefined" ? _lastAdultResults.size : 0),
    };
    processedMessages.clear();
    if (typeof _lastAdultResults !== "undefined" && _lastAdultResults.clear) _lastAdultResults.clear();
    if (global.gc) { try { global.gc(); } catch {} }
    const memMb = Math.round(process.memoryUsage().rss / 1024 / 1024);
    console.log(`🧹 [auto-clean ${CACHE_CLEAN_MS/60000}m] kept msgRetry=${before.msgRetry} pushNames=${pushNameCache.size} | cleared processed=${before.processed} adult=${before.adult} | RAM=${memMb}MB`);
  } catch (e) { console.log("[auto-clean] error:", e?.message); }
}
const _autoCleanTimer = setInterval(autoCleanCaches, CACHE_CLEAN_MS);
if (_autoCleanTimer.unref) _autoCleanTimer.unref();
console.log(`⏱️  Auto cache cleaner armed — every ${CACHE_CLEAN_MS/60000} min (msgRetry + pushNames preserved).`);

// ─────────────────────────────────────────────────────────────────────
// v16: KEEP-ALIVE WATCHDOG — three independent layers to keep the bot
// online and replies fast on Optiklink/Pterodactyl/Heroku/Termux/VPS.
// All layers are safe to disable individually via env vars.
//
//  Layer A — Socket presence heartbeat (every 30s, default ON)
//    Sends sock.sendPresenceUpdate("available") to keep the WhatsApp
//    WebSocket warm. Panels and intermediate proxies kill idle sockets
//    after ~60s — this prevents that without spamming WhatsApp.
//    Disable: KEEPALIVE_PRESENCE=0
//
//  Layer B — Self HTTP ping (every 4 min, default ON)
//    Curls the bot's own status page so the panel sees HTTP activity
//    and never sleeps the process. No external dependency.
//    Disable: KEEPALIVE_SELFPING=0
//
//  Layer C — Connection health watchdog (every 60s, default ON)
//    If the socket is missing OR the underlying ws is not OPEN,
//    triggers scheduleReconnect() instead of waiting for Baileys to
//    notice (which can take 2–5 min on flaky networks).
//    Disable: KEEPALIVE_WATCHDOG=0
//
// All timers .unref() so they never block process exit.
// Wrapped in try/catch so a bad iteration cannot crash the bot.
// ─────────────────────────────────────────────────────────────────────
let _lastKeepaliveOk = Date.now();

// Layer A: presence heartbeat
if (process.env.KEEPALIVE_PRESENCE !== "0") {
  // Keep the interval below the idle timeout used by many mobile/proxy paths.
  // The in-flight guard prevents a slow presence request from overlapping the
  // next tick and creating a request storm on a congested connection.
  const PRESENCE_MS = Math.max(10000, parseInt(process.env.KEEPALIVE_PRESENCE_MS || "30000", 10));
  let _presenceInFlight = false;
  const t = setInterval(async () => {
    try {
      const s = (typeof sockGlobal !== "undefined") ? sockGlobal : null;
      if (!s || !botConnected) return;
      if (_presenceInFlight) return;
      // Only broadcast presence if alwaysOnline is explicitly enabled by owner
      const _kaOwnerJ = (typeof getOwnerJid === "function") ? getOwnerJid() : null;
      const _kaOwnerS = _kaOwnerJ && (typeof getSettings === "function") ? getSettings(_kaOwnerJ) : null;
      if (_kaOwnerS?.alwaysOnline === false) return;
      _presenceInFlight = true;
      try {
        await s.sendPresenceUpdate("available");
        _lastKeepaliveOk = Date.now();
      } catch {}
      finally { _presenceInFlight = false; }
    } catch {}
  }, PRESENCE_MS);
  if (t.unref) t.unref();
  console.log(`💓 [keepalive] presence heartbeat armed — every ${PRESENCE_MS/1000}s`);
}

// Layer B: self HTTP ping
if (process.env.KEEPALIVE_SELFPING !== "0") {
  const SELFPING_MS = Math.max(60000, parseInt(process.env.KEEPALIVE_SELFPING_MS || "240000", 10));
  const t = setInterval(() => {
    try {
      const port = process.env.PORT || 3000;
      const url = `http://127.0.0.1:${port}/`;
      const req = http.get(url, (res) => { res.resume(); });
      req.on("error", () => {}); // status server may have moved ports — silently ignore
      req.setTimeout(5000, () => { try { req.destroy(); } catch {} });
    } catch {}
  }, SELFPING_MS);
  if (t.unref) t.unref();
  console.log(`💓 [keepalive] self HTTP ping armed — every ${SELFPING_MS/1000}s`);
}

// Layer C: connection health watchdog
if (process.env.KEEPALIVE_WATCHDOG !== "0") {
  const WATCHDOG_MS = Math.max(30000, parseInt(process.env.KEEPALIVE_WATCHDOG_MS || "60000", 10));
  let _consecutiveBad = 0;
  const t = setInterval(() => {
    try {
      const s = (typeof sockGlobal !== "undefined") ? sockGlobal : null;
      // OK states: socket exists, botConnected, and underlying ws is OPEN (1) or CONNECTING (0)
      const wsState = s?.ws?.readyState;
      const healthy = !!s && botConnected && (wsState === 1 || wsState === 0 || wsState === undefined);
      if (healthy) { _consecutiveBad = 0; return; }
      _consecutiveBad++;
      // Only act after 2 consecutive bad checks (avoids racing transient reconnects)
      if (_consecutiveBad >= 2) {
        console.log(`🚑 [keepalive] socket unhealthy (ws=${wsState}, connected=${botConnected}) — forcing reconnect`);
        _consecutiveBad = 0;
        try { if (typeof scheduleReconnect === "function") scheduleReconnect("keepalive-watchdog", 1000); } catch {}
      }
    } catch {}
  }, WATCHDOG_MS);
  if (t.unref) t.unref();
  console.log(`💓 [keepalive] connection watchdog armed — every ${WATCHDOG_MS/1000}s`);
}

function shouldProcessIncomingMessage(msg) {
  // v15.1: per-message FILTER logs were firing on every protocol/system msg
  // (group LID refresh, presence, receipts) and flooding stdout — that alone
  // slows the bot on shared hosts because console writes are synchronous.
  // Gate them behind DEBUG_FILTER=1 so logs stay clean and replies stay fast.
  const _DBG = !!process.env.DEBUG_FILTER;
  if (!msg?.message || !msg?.key?.remoteJid) {
    if (_DBG) console.log("[FILTER] no message or no remoteJid — skipped");
    return false;
  }

  const contentKeys = Object.keys(msg.message || {});
  if (!contentKeys.length) {
    if (_DBG) console.log("[FILTER] empty content keys — skipped");
    return false;
  }
  const ignorable = new Set(["protocolMessage", "messageContextInfo", "senderKeyDistributionMessage"]);
  if (contentKeys.every(key => ignorable.has(key))) {
    if (_DBG) console.log("[FILTER] protocol/system msg — skipped");
    return false;
  }

  // Some panels/hosts can deliver fresh WhatsApp messages with delayed timestamps.
  // Never drop actual command messages or active settings-menu replies because of age.
  let body = "";
  try { body = typeof getBody === "function" ? (getBody(msg) || "") : ""; } catch {}
  try { body = _extractButtonCommand(body) || body; } catch {}
  const text = String(body || "").trim();
  const isCommand = isCommandBody(text);
  const isSettingsReply = !!settingsSession.get(msg.key.remoteJid) && /^(\d{1,2}(\.\d{1,2})?|0)$|^set:[\w]+(:[\w]+)?$/.test(text);

  // Only ignore clearly stale non-text backlog messages during early boot.
  const ts = (msg.messageTimestamp?.low || msg.messageTimestamp || 0);
  const age = Math.abs(Math.floor(Date.now() / 1000) - Number(ts));
  const uptimeSec = process.uptime();
  const hasInteractivePayload = !!(msg.message?.buttonsResponseMessage || msg.message?.listResponseMessage || msg.message?.templateButtonReplyMessage || msg.message?.interactiveResponseMessage);
  // NEVER filter owner/fromMe messages, commands, settings replies, or real text/button inputs by age.
  if (ts && age > (6 * 60 * 60) && uptimeSec < 20 && !msg.key.fromMe && !isCommand && !isSettingsReply && !text && !hasInteractivePayload) {
    if (_DBG) console.log(`[FILTER] stale backlog msg (age=${age}s, uptime=${Math.round(uptimeSec)}s) — skipped`);
    return false;
  }
  return rememberMessage(msg);
}

async function isGroupAdmin(sock, gid, jid) {
  // v4.9.9 FIX: check _groupMetaCache FIRST so demote/promote is visible
  // immediately (group-participants.update refreshes the cache before messages
  // arrive, so the cache is always fresher than sock.groupMetadata()).
  try {
    const raw = String(jid || "").toLowerCase();
    const resolved = String(resolveLid(jid) || "").toLowerCase();
    const cleanJid = _cleanNum(resolved || raw);
    const _checkMeta = (meta) => {
      if (!meta?.participants) return false;
      return meta.participants.some(p => {
        if (!(p.admin === "admin" || p.admin === "superadmin")) return false;
        const ids = [p.id, p.lid, p.pn, p.phoneNumber]
          .filter(Boolean)
          .map(v => String(v).toLowerCase());
        return ids.some(id => id === raw || id === resolved || String(resolveLid(id) || "").toLowerCase() === resolved || _cleanNum(id) === cleanJid);
      });
    };
    // 1) Try fresh cache first (updated immediately on group-participants.update)
    const cached = _groupMetaCache.get(gid);
    if (cached) {
      // Always also do a live fetch in background to keep cache fresh
      sock.groupMetadata(gid).then(live => {
        if (live) { updateLidMappingsFromMeta(live); _groupMetaCache.set(gid, live); }
      }).catch(() => {});
      return _checkMeta(cached);
    }
    // 2) No cache yet  fetch live, store in cache
    const live = await sock.groupMetadata(gid);
    if (live) { updateLidMappingsFromMeta(live); _groupMetaCache.set(gid, live); }
    return _checkMeta(live);
  } catch { return false; }
}
function requireGroup(msg) { return (msg.key.remoteJid || "").endsWith("@g.us"); }

function cdCheck(store, jid, ms) {
  const now = Date.now(), last = store.get(jid) || 0;
  if (now - last < ms) return Math.ceil((ms - (now - last)) / 1000);
  store.set(jid, now); return 0;
}

function fmtUptime(s, verbose = false) {
  const ms = Math.floor((s % 1) * 1000);
  const d = Math.floor(s / 86400), h = Math.floor((s % 86400) / 3600), m = Math.floor((s % 3600) / 60), sec = Math.floor(s % 60);
  if (verbose) return `${d} day ${h} hour ${m} minute ${sec} second ${ms} millisecond`;
  return `${d}𝐝 ${h}𝐡 ${m}𝐦 ${sec}𝐬`;
}
function parseDurationMs(input, fallbackMs = 5 * 60 * 1000) {
  const raw = String(input || "").toLowerCase().trim();
  const m = raw.match(/^(\d+)(s|sec|secs|m|min|mins|h|hr|hrs|d|day|days)?$/);
  if (!m) return fallbackMs;
  const n = Math.max(1, parseInt(m[1], 10));
  const unit = m[2] || "m";
  if (unit.startsWith("s") || unit === "sec" || unit === "secs") return n * 1000;
  if (unit.startsWith("h") || unit === "hr" || unit === "hrs") return n * 60 * 60 * 1000;
  if (unit.startsWith("d") || unit === "day" || unit === "days") return n * 24 * 60 * 60 * 1000;
  return n * 60 * 1000;
}
function normalizeAnswerText(text) { return String(text || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim(); }
function sameAnswer(got, expected) { const a = normalizeAnswerText(got), b = normalizeAnswerText(expected); return !!a && !!b && (a === b || a.includes(b) || b.includes(a)); }
const ADMIN_ALLOWED_CMDS = new Set(["tagall","everyone","botall","hidetag","tag","mention","mentionall","antilink","antic","allowlink","denylink","antisticker","antibad","addbadword","removebadword","listbadwords","warn","warning","warns","warnlist","resetwarn","kick","tkick","tempkick","tk","mute","unmute","promote","demote","link","revoke","autodelete","autodel","ephemeral","pinchat","unpinchat","group","closetime","opentime","approval","disapproval","listrequest","antispam","antiraid","lockmedia","nomedia","medlock","medialocked"]);
async function isBotGroupAdmin(sock, gid) {
  // v4.9.5 FIX: prefer the _groupMetaCache (updated by group-participants.update
  // which fires immediately on promotion) over sock.groupMetadata() which can
  // return WhatsApp-server-side stale data for several seconds after promotion.
  try {
    const me = _cleanNum(sock.user?.id || _botJid || "");
    const checkMeta = (meta) =>
      (meta?.participants || []).some(p =>
        (_cleanNum(p.id) === me || _cleanNum(p.lid || "") === me) &&
        (p.admin === "admin" || p.admin === "superadmin")
      );
    // 1) Check the freshly-updated local cache first
    const cached = _groupMetaCache.get(gid);
    if (cached && checkMeta(cached)) return true;
    // 2) Fetch live from socket (may be stale) — if cache already said false, this
    //    is the authoritative last check
    const live = await sock.groupMetadata(gid);
    // 3) Update cache with the live result for future calls
    if (live) _groupMetaCache.set(gid, live);
    return checkMeta(live);
  } catch { return false; }
}
async function applyGuardAction(sock, gid, target, msgKey, mode, label, type = "") {
  const cleanTarget = resolveLid(target || "");
  const botAdmin = await isBotGroupAdmin(sock, gid);
  const action = String(mode || "delete").toLowerCase();
  let done = "";
  if (["delete", "warn", "kick", "tkick"].includes(action) && botAdmin) { try { await sock.sendMessage(gid, { delete: msgKey }); done = "message deleted"; } catch {} }
  if (!botAdmin && ["delete", "kick", "tkick"].includes(action)) done = "need bot admin before I can delete/kick";
  if (action === "warn") { const gw = warns.get(gid) || new Map(); warns.set(gid, gw); gw.set(cleanTarget, (gw.get(cleanTarget) || 0) + 1); done = `warned (${gw.get(cleanTarget)}/3)`; if (gw.get(cleanTarget) >= 3 && botAdmin) { try { await sock.groupParticipantsUpdate(gid, [cleanTarget], "remove"); done = "warned 3/3 + kicked"; gw.delete(cleanTarget); } catch {} } }
  else if (action === "kick" && botAdmin) { try { await sock.groupParticipantsUpdate(gid, [cleanTarget], "remove"); done = "kicked"; } catch { done = done || "delete done, kick failed"; } }
  else if (action === "tkick" && botAdmin) { try { await sock.groupParticipantsUpdate(gid, [cleanTarget], "remove"); done = "temp-kicked"; setTimeout(() => sock.groupParticipantsUpdate(gid, [cleanTarget], "add").catch(() => {}), parseDurationMs("5m")); } catch { done = done || "delete done, temp-kick failed"; } }
  if (!done) done = action === "delete" ? "message deleted" : action;
  await sock.sendMessage(gid, { text: `🚫 *${label} triggered*${type ? `\n\n🔎 Type: *${type}*` : ""}\n👤 User: @${cleanTarget.split("@")[0]}\n🛡️ Mode: *${action.toUpperCase()}*\n✅ Action: *${done}*${!botAdmin ? "\n\n⚠️ Make the bot admin to delete/kick automatically." : ""}`, mentions: [cleanTarget] }).catch(() => {});
}

