cmd(["igstory","instastory"], { desc: "Instagram Story Downloader", category: "DOWNLOAD" }, async (sock, msg, args) => {
  const uname = (args.join(" ") || "").replace(/https?:\/\/(www\.)?instagram\.com\//i, '').replace(/\//g, '').trim();
  if (!uname) return await sendReply(sock, msg, `📸 *Instagram Story*\n\nUsage: ${CONFIG.PREFIX}igstory <username>`);
  await react(sock, msg, "📸");
  await sendReply(sock, msg, '⏳ Fetching Instagram stories...');
  try {
    const r = await _paGet('/api/download/igstory', { username: uname });
    if (r.ok && r.data?.success && r.data.result) {
      const stories = Array.isArray(r.data.result) ? r.data.result : [r.data.result];
      if (!stories.length) return await sendReply(sock, msg, '❌ No stories found.');
      let sent = 0;
      for (const s of stories.slice(0, 5)) {
        const sUrl = s?.url || s?.media_url || s;
        if (typeof sUrl !== 'string') continue;
        try {
          if (/\.(mp4|mov|webm)/i.test(sUrl)) {
            await sock.sendMessage(msg.key.remoteJid, { video: { url: sUrl }, mimetype: 'video/mp4', caption: `📸 Story ${sent+1}` }, { quoted: msg });
          } else {
            await sock.sendMessage(msg.key.remoteJid, { image: { url: sUrl }, caption: `📸 Story ${sent+1}` }, { quoted: msg });
          }
          sent++;
        } catch (_) {}
      }
      if (sent === 0) return await sendReply(sock, msg, '❌ Could not download stories.');
      return await react(sock, msg, '✅');
    }
    await sendReply(sock, msg, '❌ Could not fetch stories. Account may be private.');
  } catch (e) { await sendReply(sock, msg, `❌ Error: ${e.message}`); }
});

