cmd("mode", { desc: "Set public/private mode", category: "OWNER", ownerOnly: true }, async (sock, msg, args) => {
  const m = args[0]?.toLowerCase();
  if (!["public", "private"].includes(m)) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}mode public/private\n\nCurrent: *${getSettings(getOwnerJid())?.privateMode ? "PRIVATE 🔒" : "PUBLIC 🌐"}*`); return; }
  // Already-set check
  const _mOwnerS = getSettings(getOwnerJid());
  const _curPrivate = !!_mOwnerS?.privateMode;
  if (m === "private" && _curPrivate) { await sendReply(sock, msg, `🔒 Mode is *already set to PRIVATE* — no change made.`); return; }
  if (m === "public" && !_curPrivate) { await sendReply(sock, msg, `🌐 Mode is *already set to PUBLIC* — no change made.`); return; }
  // Store globally on owner JID so it persists across all chats
  const ownerJid = getOwnerJid();
  const s = getSettings(ownerJid);
  setWorkModeState(s, m);
  // Also store on current chat
  const cs = getSettings(msg.key.remoteJid);
  setWorkModeState(cs, m);
  saveNow();
  await sendReply(sock, msg, `${m === "private" ? "🔒" : "🌐"} Mode set to *${m.toUpperCase()}*`);
});

