cmd(["debug", "logs", "console"], { desc: "Live debug snapshot — runtime state + recent logs in chat", category: "OWNER", ownerOnly: true }, async (sock, msg, args) => {
  // v4.9.3: show *real* runtime state inline instead of just dumping a URL.
  // Pulls from the same source as the /debug-api endpoint (getRuntimeDebugState)
  // so what you see in chat matches the web console.
  const base = String(process.env.BOT_URL || "").trim().replace(/\/$/, "");
  const webUrl = base ? `${base}/debug` : `http://localhost:${PORT}/debug`;
  const apiUrl = base ? `${base}/debug-api` : `http://localhost:${PORT}/debug-api`;

  let state = {};
  try { state = getRuntimeDebugState() || {}; } catch (e) { state = { error: e?.message || String(e) }; }

  // How many log lines to show (default 15, or .debug logs N)
  let nLogs = 15;
  const subFlag = (args[0] || "").toLowerCase();
  const nArg = parseInt(args[1] || args[0] || "", 10);
  if (Number.isFinite(nArg) && nArg > 0 && nArg <= 200) nLogs = nArg;

  const upSec = Number(state.uptimeSec || Math.floor(process.uptime()));
  const upH = Math.floor(upSec / 3600);
  const upM = Math.floor((upSec % 3600) / 60);
  const upS = upSec % 60;
  const upStr = `${upH}h ${upM}m ${upS}s`;

  const connEmoji = state.connected ? "🟢" : "🔴";
  const connTxt   = state.connected ? "CONNECTED" : "DISCONNECTED";

  const recent = Array.isArray(state.recentLogs) ? state.recentLogs.slice(-nLogs) : [];
  const logBlock = recent.length
    ? recent.map(l => {
        const t = (l?.ts || "").slice(11, 19);
        const lvl = String(l?.level || "log").toUpperCase().padEnd(5);
        const text = String(l?.text || "").replace(/\s+/g, " ").slice(0, 220);
        return `[${t}] ${lvl} ${text}`;
      }).join("\n")
    : "(no logs captured yet)";

  // Truncate the whole reply to keep WhatsApp happy (avoid >4096 chars).
  let logSection = "```\n" + logBlock + "\n```";
  if (logSection.length > 2800) logSection = "```\n" + logBlock.slice(-2800) + "\n```";

  const text =
`🧪 *${CONFIG.BOT_NAME} — DEBUG SNAPSHOT*

╭───「 *RUNTIME* 」───
│ ${connEmoji} Connection: *${connTxt}*
│ 🤖 Bot: *${state.botName || CONFIG.BOT_NAME}* v${state.version || CONFIG.VERSION}
│ 👑 Owner: ${state.ownerNumber || "(auto-detect)"}
│ ⚙️  Mode: *${state.workMode || "public"}*${state.privateMode ? " / private gate" : ""}
│ 🗂️  Menu: ${state.buttonsMode ? "interactive" : "plain text"}
│ 🔣 Prefix: \`${state.prefix || CONFIG.PREFIX || "."}\`
│ 📦 Commands: *${state.commandCount || commands.size}*
│ 🧠 Memory: ${state.memoryMb || Math.round(process.memoryUsage().rss/1048576)} MB
│ ⏱️  Uptime: ${upStr}
│ 🔑 Session: ${state.credsExists ? "creds.json found" : "❌ missing creds.json"}
╰─────────────────

📜 *Recent logs* (last ${recent.length})
${logSection}

🌐 Web: ${webUrl}
🧾 JSON: ${apiUrl}

_Tip: \`${CONFIG.PREFIX}debug 50\` shows the last 50 log lines._`;

  await _sendPlainReply(sock, msg, text);
});

