// YouTube search helper — scrapes YouTube search results
async function ytSearch(query) {
  try {
    const { data } = await axios.get(`https://www.youtube.com/results?search_query=${encodeURIComponent(query)}&sp=EgIQAQ%253D%253D`, {
      headers: { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36", "Accept-Language": "en-US,en" },
      timeout: 15000
    });
    const results = [];
    const regex = /"videoRenderer":\{"videoId":"([a-zA-Z0-9_-]{11})".*?"title":\{"runs":\[\{"text":"(.*?)"\}\]/g;
    let match;
    while ((match = regex.exec(data)) !== null && results.length < 5) {
      results.push({ url: `https://www.youtube.com/watch?v=${match[1]}`, title: match[2], videoId: match[1] });
    }
    return results;
  } catch { return []; }
}

// ── Bot branding used in Play output cards ───────────────────────────────────
const PLAY_BRAND = process.env.BOT_BRAND || "𝑷𝑹𝑬𝑪𝑰𝑶𝑼𝑺 x";

// Download + validate a Play thumbnail/cover image. Returns a Buffer only when
// the response really is an image; any failure returns null so the audio is
// still sent (never crashes, never sent as the audio itself).
async function fetchPlayThumb(url, timeout = 12000) {
  if (!url || typeof url !== "string" || !/^https?:\/\//i.test(url)) return null;
  try {
    const res = await axios.get(url, {
      responseType: "arraybuffer", timeout, maxRedirects: 5,
      headers: { "User-Agent": "Mozilla/5.0" },
    });
    const buf = Buffer.from(res.data || []);
    if (buf.length < 512) return null;
    const ct = String(res.headers?.["content-type"] || "").toLowerCase();
    const isJpg = buf[0] === 0xFF && buf[1] === 0xD8;
    const isPng = buf.slice(0, 8).toString("hex") === "89504e470d0a1a0a";
    const isWebp = buf.slice(0, 4).toString("ascii") === "RIFF" && buf.slice(8, 12).toString("ascii") === "WEBP";
    if (!isJpg && !isPng && !isWebp && !/^image\//.test(ct)) return null;
    return buf;
  } catch { return null; }
}

/* ══════════════════════════════════════════════════════════════════════════════
   PRECIOUS PLAY v2 — inserted into mias/index.js by PATCH.cjs (do not delete)

   .play <song name | link>
        → sends a PLAYER IMAGE CARD (thumbnail + Title, Author, Duration, Views)
        → the card lists the formats:

             1 = Audio
             2 = Document (.mp3)
             3 = Voice note
             4 = Video (mp4 with sound)

        → the user QUOTES (replies to) the card with a number 1–4 and receives
          exactly that format. The choice stays open for 20 minutes.

   Every name below is prefixed (_P2_ / _p2) and every helper that could clash
   with the host file is required locally inside the function body, so this
   fragment is safe to inject into a 39k-line module.
   ══════════════════════════════════════════════════════════════════════════════ */

// V25-OK: _p2HasVideoTrack helper
function _p2HasVideoTrack(buf) {
  try {
    const cp = require('child_process');
    const fsx = require('fs');
    const osx = require('os');
    const pathx = require('path');
    let ff = 'ffmpeg';
    try { ff = require('ffmpeg-static') || 'ffmpeg'; } catch {}
    const dir = fsx.mkdtempSync(pathx.join(osx.tmpdir(), 'p2vt-'));
    const f = pathx.join(dir, 'v.bin');
    fsx.writeFileSync(f, buf);
    const r = cp.spawnSync(ff, ['-hide_banner', '-i', f], { timeout: 30000 });
    try { fsx.rmSync(dir, { recursive: true, force: true }); } catch {}
    const err = String(r.stderr || '');
    return /Stream #\d+:\d+.*: Video:/i.test(err) || /Video:\s/i.test(err);
  } catch (e) {
    // If ffmpeg is unavailable we cannot prove the absence of a video track —
    // do not block a possibly-good download.
    return true;
  }
}

const _P2_TTL = 20 * 60 * 1000;
const _P2_PENDING = new Map();

// V25-OK: play pending probe exposed
// The settings consumer used to steal a bare "4" typed after a .play card and
// answer "❌ Unknown settings option *4*", because the play store is keyed by
// MESSAGE id while the probe asked by CHAT jid. These globals close that gap.
globalThis.__P2_PENDING__ = _P2_PENDING;
const _P2_CHAT_PENDING = new Map();
globalThis.__P2_CHAT_PENDING__ = _P2_CHAT_PENDING;
function _p2MarkChatPending(jid, on) {
  try {
    const k = _p2NormJid(jid);
    if (!k) return;
    if (on) _P2_CHAT_PENDING.set(k, Date.now()); else _P2_CHAT_PENDING.delete(k);
  } catch {}
}
globalThis.__miasPlayPending = function (jid) {
  try {
    const k = _p2NormJid(jid);
    const ts = _P2_CHAT_PENDING.get(k);
    if (ts && Date.now() - ts < _P2_TTL) return true;
    for (const kv of _P2_PENDING) {
      const e = kv[1];
      if (e && Date.now() - e.ts < _P2_TTL && _p2SameChat(e.jid, jid)) return true;
    }
  } catch {}
  return false;
};

// PRECIOUS FIX (silent numbered reply):
// WhatsApp can deliver the command message with ":12@s.whatsapp.net" and the
// reply with the bare jid (or @lid). A raw string compare therefore failed and
// the handler returned with no output at all — the "quote it with a number and
// nothing happens" bug. Compare on the normalised chat identity instead.
function _p2NormJid(jid) {
  let s = String(jid || "");
  if (!s) return "";
  s = s.replace(/:\d+(?=@)/, "");
  try {
    if (typeof resolveLid === "function") {
      const r = resolveLid(s);
      if (r) s = String(r).replace(/:\d+(?=@)/, "");
    }
  } catch {}
  return s;
}
function _p2NumOnly(jid) {
  return String(_p2NormJid(jid) || "").replace(/[^0-9]/g, "");
}
function _p2SameChat(a, b) {
  const na = _p2NumOnly(a);
  const nb = _p2NumOnly(b);
  if (na && nb) return na === nb;
  return _p2NormJid(a) === _p2NormJid(b);
}
const _P2_BOUND = new WeakSet();

function _p2Views(v) {
  if (v === undefined || v === null || v === '') return 'N/A';
  const n = Number(String(v).replace(/[^0-9.]/g, ''));
  if (!Number.isFinite(n) || n <= 0) return String(v).slice(0, 24);
  if (n >= 1e9) return (n / 1e9).toFixed(1).replace(/\.0$/, '') + 'B';
  if (n >= 1e6) return (n / 1e6).toFixed(1).replace(/\.0$/, '') + 'M';
  if (n >= 1e3) return (n / 1e3).toFixed(1).replace(/\.0$/, '') + 'K';
  return String(Math.round(n));
}

function _p2Dur(v) {
  if (v === undefined || v === null || v === '') return 'N/A';
  if (typeof v === 'string' && v.includes(':')) return v;
  const n = Number(String(v).replace(/[^0-9.]/g, ''));
  if (!Number.isFinite(n) || n <= 0) return String(v);
  const total = Math.round(n);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  if (h > 0) return h + ':' + String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
  return m + ':' + String(s).padStart(2, '0');
}

function _p2YtId(u) {
  const m = String(u || '').match(/(?:v=|youtu\.be\/|shorts\/|embed\/)([A-Za-z0-9_-]{11})/);
  return m ? m[1] : '';
}

function _p2ThumbOf(meta) {
  meta = meta || {};
  return meta.thumbUrl || meta.thumbnail || meta.cover || meta.image ||
    (meta.videoId ? 'https://img.youtube.com/vi/' + meta.videoId + '/hqdefault.jpg' : null);
}

async function _p2ThumbBuf(meta) {
  const u = _p2ThumbOf(meta);
  if (!u) return null;
  try {
    const r = await axios.get(u, {
      responseType: 'arraybuffer', timeout: 20000, maxRedirects: 5,
      validateStatus: function (s) { return s >= 200 && s < 400; },
      headers: { 'User-Agent': 'Mozilla/5.0' },
    });
    const b = Buffer.from(r.data || []);
    return b.length > 2000 ? b : null;
  } catch (e) {
    return null;
  }
}

async function _p2Get(url, timeout) {
  // PRECIOUS 403 FIX: CDN links (googlevideo etc.) expire or reject plain
  // requests with "Request failed with status code 403". Retry once with a
  // full browser header set before giving up on the URL.
  const attempts = [
    { 'User-Agent': 'Mozilla/5.0', 'Accept': '*/*' },
    {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36',
      'Accept': '*/*',
      'Accept-Language': 'en-US,en;q=0.9',
      'Referer': 'https://www.youtube.com/',
      'Origin': 'https://www.youtube.com',
      'Range': 'bytes=0-',
    },
  ];
  let lastErr = null;
  for (const headers of attempts) {
    try {
      const r = await axios.get(url, {
        responseType: 'arraybuffer', timeout: timeout || 180000, maxRedirects: 5,
        validateStatus: function (s) { return s >= 200 && s < 400; },
        headers,
      });
      const b = Buffer.from(r.data || []);
      if (b.length < 8000) throw new Error('file too small (' + b.length + ' bytes)');
      const head = b.slice(0, 5).toString('utf8').toLowerCase();
      if (head.startsWith('<!doc') || head.startsWith('<html')) throw new Error('got an HTML page, not media');
      return b;
    } catch (e) {
      lastErr = e;
      if (e?.response?.status !== 403) throw e; // only retry on 403
    }
  }
  throw lastErr || new Error('download failed');
}

function _p2Sweep() {
  const now = Date.now();
  for (const kv of _P2_PENDING) {
    if (!kv[1] || now - kv[1].ts > _P2_TTL) _P2_PENDING.delete(kv[0]);
  }
}

/* ── media resolvers ───────────────────────────────────────────────────────── */

async function _p2AudioBuf(meta) {
  const raw = meta.videoUrl || meta.url || '';
  const id = meta.videoId || _p2YtId(raw);
  const ytUrl = raw && _p2YtId(raw) ? raw : (id ? 'https://www.youtube.com/watch?v=' + id : raw);
  const tries = [];

  // PRIMARY: the download link DavidCyril already returned for this exact
  // track when the card was built — no second lookup, no drift.
  if (meta.dlUrl) tries.push(async () => meta.dlUrl);
  if (ytUrl) tries.push(async () => {
    const r = await dcGet('/download/ytmp3', { url: ytUrl }, 30000);
    const d = r && r.ok ? extractDcPlay(r.data) : null;
    return d ? (d.dlUrl || d.url || null) : null;
  });
  if (meta.title) tries.push(async () => {
    const r = await dcGet('/play', { query: meta.title }, 30000);
    const d = r && r.ok ? extractDcPlay(r.data) : null;
    return d ? (d.dlUrl || d.url || null) : null;
  });
  if (ytUrl) tries.push(async () => {
    const res = await axios.get(
      CONFIG.GIFTED_API + '/api/download/ytmp3?apikey=' + CONFIG.GIFTED_KEY +
      '&url=' + encodeURIComponent(ytUrl),
      { timeout: 60000 }
    );
    const r = res.data && (res.data.result || res.data.data);
    return r ? (r.download_url || r.url || r.audio || r.mp3 || null) : null;
  });
  if (ytUrl) tries.push(async () => {
    const res = await axios.post('https://co.wuk.sh/api/json',
      { url: ytUrl, downloadMode: 'audio', audioFormat: 'mp3' },
      { headers: { 'Accept': 'application/json', 'Content-Type': 'application/json' }, timeout: 30000 });
    return res.data && (res.data.url || res.data.audio) ? (res.data.url || res.data.audio) : null;
  });
  if (ytUrl) tries.push(async () => {
    const res = await axios.post('https://cobalt-api.kwiatekmiki.com/',
      { url: ytUrl, downloadMode: 'audio', audioFormat: 'mp3' },
      { headers: { 'Accept': 'application/json', 'Content-Type': 'application/json' }, timeout: 30000 });
    return res.data && res.data.url ? res.data.url : null;
  });

  for (const t of tries) {
    try {
      const u = await t();
      if (!u) continue;
      return await _p2Get(u, 180000);
    } catch (e) { /* next provider */ }
  }

  // last resort — bundled ytdl-core
  try {
    const mod = await import('@distube/ytdl-core').catch(function () { return null; });
    const ytdl = mod && (mod.default || mod);
    if (ytdl && ytUrl) {
      const info = await ytdl.getInfo(ytUrl, { requestOptions: { headers: { 'User-Agent': 'Mozilla/5.0' } } });
      const fmt = ytdl.chooseFormat(info.formats, { quality: 'highestaudio', filter: 'audioonly' });
      const chunks = [];
      const stream = ytdl.downloadFromInfo(info, { format: fmt });
      await new Promise(function (resolve, reject) {
        stream.on('data', function (c) { chunks.push(c); });
        stream.on('end', resolve);
        stream.on('error', reject);
        setTimeout(function () { reject(new Error('ytdl timeout')); }, 120000);
      });
      const b = Buffer.concat(chunks);
      if (b.length > 8000) return b;
    }
  } catch (e) { /* give up */ }

  throw new Error('every audio provider failed — try again in a moment');
}

async function _p2VideoBuf(meta) {
  const raw = meta.videoUrl || meta.url || '';
  const id = meta.videoId || _p2YtId(raw);
  const ytUrl = raw && _p2YtId(raw) ? raw : (id ? 'https://www.youtube.com/watch?v=' + id : raw);
  const tries = [];

  if (ytUrl) tries.push(async () => {
    const r = await dcGet('/download/ytmp4', { url: ytUrl }, 40000);
    const d = r && r.ok ? extractDcPlay(r.data) : null;
    return d ? (d.dlUrl || d.url || null) : null;
  });
  if (ytUrl) tries.push(async () => {
    const res = await axios.get(
      CONFIG.GIFTED_API + '/api/download/ytmp4?apikey=' + CONFIG.GIFTED_KEY +
      '&url=' + encodeURIComponent(ytUrl),
      { timeout: 60000 }
    );
    const r = res.data && (res.data.result || res.data.data);
    return r ? (r.download_url || r.url || r.video || r.mp4 || null) : null;
  });
  if (ytUrl) tries.push(async () => {
    const res = await axios.post('https://co.wuk.sh/api/json',
      { url: ytUrl, downloadMode: 'video', videoQuality: '480' },
      { headers: { 'Accept': 'application/json', 'Content-Type': 'application/json' }, timeout: 30000 });
    return res.data && res.data.url ? res.data.url : null;
  });
  if (ytUrl) tries.push(async () => {
    const res = await axios.get('https://p.oceansaver.in/ajax/download.php?format=mp4&url=' + encodeURIComponent(ytUrl), { timeout: 30000 });
    const d = res.data || {};
    if (d.success && d.progress_url) {
      for (let i = 0; i < 12; i++) {
        await new Promise(function (r) { setTimeout(r, 3000); });
        const p = await axios.get(d.progress_url, { timeout: 20000 });
        const pd = p.data || {};
        if (pd.success === 1 && pd.download_url) return pd.download_url;
      }
    }
    return null;
  });

  // V25-OK: video track probe
  // WHY THE VIDEO WAS BLACK: some providers hand back an mp4 that contains an
  // AUDIO-ONLY stream (or an HTML error page). WhatsApp then plays the sound
  // over a black frame. Every candidate is now probed for a real video stream
  // and rejected when it has none, so the next provider is tried instead.
  for (const t of tries) {
    try {
      const u = await t();
      if (!u) continue;
      const buf = await _p2Get(u, 240000);
      if (!buf || buf.length < 32 * 1024) continue;
      const head = buf.slice(0, 40).toString('utf8').trim().toLowerCase();
      if (/^<!doctype|^<html|^\{|^<\?xml/.test(head)) continue;
      if (!_p2HasVideoTrack(buf)) continue;
      return buf;
    } catch (e) { /* next provider */ }
  }
  throw new Error('every video provider failed — try again in a moment');
}

// V25-OK: expose play providers
// ytmate reuses the exact provider chain this (working) play pipeline uses, so
// it stops depending on the dead mirrors the v24 pack shipped.
try { globalThis.__MIAS_P2_VIDEO_BUF__ = _p2VideoBuf; } catch {}
try { if (typeof _p2AudioBuf === 'function') globalThis.__MIAS_P2_AUDIO_BUF__ = _p2AudioBuf; } catch {}

/* ══════════════════════════════════════════════════════════════════════════
   MIAS MEDIA FORMAT FIX v19
   Sniff the real bytes and transcode to the canonical container BEFORE every
   send. This is what fixes:
     • "this video isn't available"            -> webm/mislabeled video re-muxed
     • "wrong format / may be dangerous"       -> audio/video bytes now match the
                                                  file extension and MIME type
     • "something is wrong with this file"     -> voice notes are real OGG/Opus
     • "documents that arrive as media"        -> document branch now honoured
   Self-contained: no imports at module load, ffmpeg resolved lazily.
   ══════════════════════════════════════════════════════════════════════════ */
function _mfFfmpegPath() {
  try { const p = require("ffmpeg-static"); if (p && typeof p === "string") return p; } catch (e) {}
  return "ffmpeg";
}
function _mfBinaryOk() {
  try {
    const cp = require("child_process");
    const r = cp.spawnSync(_mfFfmpegPath(), ["-version"], { timeout: 15000 });
    return !!(r && r.status === 0);
  } catch (e) { return false; }
}
function _mfTmp() {
  const fs = require("fs"), os = require("os"), path = require("path");
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "miasfmt-"));
  return { dir: dir, file: path.join(dir, "in.bin") };
}
function _mfSniff(buf) {
  const UNK = { kind: "unknown", ext: ".bin", mime: "application/octet-stream" };
  try {
    if (!buf || buf.length < 16) return UNK;
    const at = (i, s) => buf.slice(i, i + s.length).toString("latin1") === s;
    const hex = (i, s) => buf.slice(i, i + s.length).toString("hex") === s;
    const head = buf.slice(0, 256).toString("utf8").trim().toLowerCase();
    if (head.startsWith("<!doctype") || head.startsWith("<html") || head.startsWith("<?xml")) return { kind: "html", ext: ".html", mime: "text/html" };
    if (head.startsWith("{") || head.startsWith("[")) return { kind: "json", ext: ".json", mime: "application/json" };
    if (at(0, "ID3")) return { kind: "mp3", ext: ".mp3", mime: "audio/mpeg" };
    if (buf[0] === 0xff && (buf[1] & 0xe0) === 0xe0) return { kind: "mp3", ext: ".mp3", mime: "audio/mpeg" };
    if (at(0, "OggS")) return { kind: "ogg", ext: ".ogg", mime: "audio/ogg; codecs=opus" };
    if (at(0, "RIFF") && at(8, "WAVE")) return { kind: "wav", ext: ".wav", mime: "audio/wav" };
    if (at(0, "fLaC")) return { kind: "flac", ext: ".flac", mime: "audio/flac" };
    if (hex(0, "1a45dfa3")) return { kind: "webm", ext: ".webm", mime: "video/webm" };
    if (at(0, "%PDF")) return { kind: "pdf", ext: ".pdf", mime: "application/pdf" };
    if (buf.slice(0, 64).toString("latin1").includes("ftyp")) {
      const brand = buf.slice(8, 12).toString("latin1");
      if (/^M4A|^M4B/i.test(brand)) return { kind: "m4a", ext: ".m4a", mime: "audio/mp4" };
      return { kind: "mp4", ext: ".mp4", mime: "video/mp4" };
    }
    if (at(0, "moov") || at(0, "mdat") || at(0, "wide") || at(0, "free")) return { kind: "mp4", ext: ".mp4", mime: "video/mp4" };
    if (at(0, "PK")) return { kind: "zip", ext: ".zip", mime: "application/zip" };
    return UNK;
  } catch (e) { return UNK; }
}
function _mfTranscode(buf, args, outName, timeoutMs) {
  try {
    if (!buf || buf.length < 512) return null;
    if (buf.length > 120 * 1024 * 1024) return null;
    const fs = require("fs"), cp = require("child_process"), path = require("path");
    const t = _mfTmp();
    const out = path.join(t.dir, outName);
    fs.writeFileSync(t.file, buf);
    const r = cp.spawnSync(_mfFfmpegPath(), ["-y", "-hide_banner", "-loglevel", "error", "-i", t.file].concat(args).concat([out]), { timeout: timeoutMs || 180000, maxBuffer: 1 << 28 });
    let res = null;
    try { if (r && r.status === 0 && fs.existsSync(out)) { const o = fs.readFileSync(out); if (o.length > 1024) res = o; } } catch (e) {}
    try { fs.rmSync(t.dir, { recursive: true, force: true }); } catch (e) {}
    return res;
  } catch (e) { return null; }
}
async function _mfToMp3(buf) { return _mfTranscode(buf, ["-vn", "-c:a", "libmp3lame", "-b:a", "128k", "-ar", "44100"], "out.mp3", 180000); }
async function _mfToOggOpus(buf) { return _mfTranscode(buf, ["-vn", "-c:a", "libopus", "-b:a", "64k", "-ar", "48000", "-ac", "1"], "out.ogg", 180000); }
async function _mfToMp4(buf) { return _mfTranscode(buf, ["-c:v", "libx264", "-preset", "veryfast", "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "128k", "-movflags", "+faststart"], "out.mp4", 300000); }
/* Audio that WhatsApp will actually play as an inline audio bubble. */
async function _mfPrepareAudio(buf) {
  const s = _mfSniff(buf);
  if (s.kind === "mp3") return { buf: buf, ext: ".mp3", mime: "audio/mpeg", kind: "mp3" };
  const o = await _mfToMp3(buf);
  if (o) return { buf: o, ext: ".mp3", mime: "audio/mpeg", kind: "mp3", converted: true };
  return { buf: buf, ext: (s.ext === ".bin" ? ".mp3" : s.ext), mime: (s.kind === "unknown" ? "audio/mpeg" : s.mime), kind: s.kind };
}
/* Same bytes, but named/mimed so it opens as a real file. */
async function _mfPrepareAudioDoc(buf) {
  const a = await _mfPrepareAudio(buf);
  return { buf: a.buf, ext: a.ext, mime: a.mime };
}
/* Returns ok:true only when the bytes are a real MP4 WhatsApp can play. */
async function _mfPrepareVideo(buf) {
  const s = _mfSniff(buf);
  if (s.kind === "mp4") return { ok: true, buf: buf, ext: ".mp4", mime: "video/mp4", note: "" };
  const o = await _mfToMp4(buf);
  if (o) return { ok: true, buf: o, ext: ".mp4", mime: "video/mp4", converted: true, note: "" };
  return {
    ok: false, buf: buf,
    ext: (s.ext === ".bin" ? ".mp4" : s.ext),
    mime: (s.mime === "application/octet-stream" ? "video/mp4" : s.mime),
    note: "sent as a file — this clip could not be re-encoded into a playable video.",
  };
}
async function _mfPrepareVideoDoc(buf) {
  const s = _mfSniff(buf);
  if (s.kind === "mp4") return { buf: buf, ext: ".mp4", mime: "video/mp4" };
  const o = await _mfToMp4(buf);
  if (o) return { buf: o, ext: ".mp4", mime: "video/mp4" };
  return { buf: buf, ext: (s.ext === ".bin" ? ".mp4" : s.ext), mime: (s.mime === "application/octet-stream" ? "video/mp4" : s.mime) };
}
/* ══════════════════════════════════════════ end MIAS MEDIA FORMAT FIX v19 */

/** ffmpeg → real voice note (ogg/opus). Returns null when unavailable. */
async function _p2ToPtt(buf) {
  try {
    const fsx = require('fs');
    const osx = require('os');
    const pathx = require('path');
    const cp = require('child_process');
    const dir = fsx.mkdtempSync(pathx.join(osx.tmpdir(), 'p2ptt-'));
    const inF = pathx.join(dir, 'in.bin');
    const outF = pathx.join(dir, 'out.ogg');
    fsx.writeFileSync(inF, buf);
    const r = cp.spawnSync(_mfFfmpegPath(), [
      '-y', '-i', inF, '-vn', '-c:a', 'libopus',
      '-b:a', '64k', '-ar', '48000', '-ac', '1', outF,
    ], { timeout: 150000 });
    let out = null;
    try {
      if (r.status === 0 && fsx.existsSync(outF)) {
        const o = fsx.readFileSync(outF);
        if (o.length > 2000) out = o;
      }
    } catch (e) {}
    try { fsx.rmSync(dir, { recursive: true, force: true }); } catch (e) {}
    return out;
  } catch (e) {
    return null;
  }
}

/* ── delivery ──────────────────────────────────────────────────────────────── */

async function _p2Deliver(sock, entry, n, quotedKey) {
  const jid = entry.jid;
  const meta = entry.meta || {};
  const title = meta.title || 'audio';
  const safe = String(title).replace(/[^a-zA-Z0-9 _-]/g, '').trim().slice(0, 60) || 'audio';

  if (n === 4) {
    const vbuf = await _p2VideoBuf(meta);
    const _v = await _mfPrepareVideo(vbuf);
    if (_v.ok) {
      const _rawThumb = await _p2ThumbBuf(meta).catch(function () { return null; });
      // PRECIOUS FIX (black-screen video): a raw video-frame thumbnail is
      // routinely >100 KB and WhatsApp's muxer rejects it, degrading the
      // player to audio-only. Only attach thumbs under the safe cap.
      const thumb = (_rawThumb && _rawThumb.length <= 100 * 1024) ? _rawThumb : null;
      const payload = {
        video: _v.buf,
        mimetype: 'video/mp4',
        fileName: safe + '.mp4',
        caption: '🎬 *' + title + '*\n👤 ' + (meta.artists || meta.author || 'Unknown') + '  ⏱️ ' + _p2Dur(meta.duration),
      };
      if (thumb) payload.jpegThumbnail = thumb;
      try {
        await sock.sendMessage(jid, payload, { quoted: quotedKey });
      } catch (_eVid) {
        // If the inline-video send itself fails, fall back to document so the
        // user still receives the file instead of a silent black audio frame.
        await sock.sendMessage(jid, {
          document: _v.buf, mimetype: 'video/mp4', fileName: safe + '.mp4',
          caption: '🎬 *' + title + '* (sent as document)',
        }, { quoted: quotedKey });
      }
    } else {
      await sock.sendMessage(jid, {
        document: _v.buf, mimetype: _v.mime, fileName: safe + _v.ext,
        caption: '🎬 *' + title + '*\n📎 ' + _v.note,
      }, { quoted: quotedKey });
    }
    return;
  }

  const abuf = await _p2AudioBuf(meta);

  if (n === 2) {
    const _docA = await _mfPrepareAudioDoc(abuf);
    await sock.sendMessage(jid, {
      document: _docA.buf,
      mimetype: _docA.mime,
      fileName: safe + _docA.ext,
      caption: '📄 *' + title + '*\n👤 ' + (meta.artists || meta.author || 'Unknown') + '  ⏱️ ' + _p2Dur(meta.duration) + '  👁️ ' + _p2Views(meta.views),
    }, { quoted: quotedKey });
    return;
  }

  if (n === 3) {
    const ogg = (await _p2ToPtt(abuf)) || (await _mfToOggOpus(abuf));
    if (ogg && _mfSniff(ogg).kind === "ogg") {
      await sock.sendMessage(jid, { audio: ogg, mimetype: 'audio/ogg; codecs=opus', ptt: true }, { quoted: quotedKey });
    } else {
      const _av = await _mfPrepareAudio(abuf);
      await sock.sendMessage(jid, { audio: _av.buf, mimetype: _av.mime, ptt: false, fileName: safe + _av.ext }, { quoted: quotedKey });
    }
    return;
  }

  const _out = await _mfPrepareAudio(abuf);
  await sock.sendMessage(jid, { audio: _out.buf, mimetype: _out.mime, ptt: false, fileName: safe + _out.ext }, { quoted: quotedKey });
}

/* ── reply-to-card picker ──────────────────────────────────────────────────── */

function _p2Body(m) {
  const msg = (m && m.message) || {};
  const c =
    msg.conversation ||
    (msg.extendedTextMessage && msg.extendedTextMessage.text) ||
    (msg.imageMessage && msg.imageMessage.caption) ||
    (msg.videoMessage && msg.videoMessage.caption) ||
    (msg.buttonsResponseMessage && msg.buttonsResponseMessage.selectedButtonId) ||
    (msg.listResponseMessage && msg.listResponseMessage.singleSelectReply && msg.listResponseMessage.singleSelectReply.selectedRowId) ||
    (msg.templateButtonReplyMessage && msg.templateButtonReplyMessage.selectedId) ||
    // PRECIOUS FIX: native-flow taps arrive as paramsJson, not plain text.
    (msg.interactiveResponseMessage && msg.interactiveResponseMessage.nativeFlowResponseMessage && msg.interactiveResponseMessage.nativeFlowResponseMessage.paramsJson) ||
    (msg.interactiveResponseMessage && msg.interactiveResponseMessage.buttonReply && msg.interactiveResponseMessage.buttonReply.id) ||
    (msg.interactiveResponseMessage && msg.interactiveResponseMessage.buttonReply && msg.interactiveResponseMessage.buttonReply.displayText) ||
    '';
  let out = String(c || '').trim();
  // Pull the real id out of {"id":"1","selectedRowId":"1",...}
  if (out && (out[0] === '{' || out[0] === '[')) {
    try {
      const seen = new Set();
      const queue = [JSON.parse(out)];
      while (queue.length) {
        const cur = queue.shift();
        if (cur === null || cur === undefined) continue;
        if (typeof cur === 'string') { out = cur; break; }
        if (typeof cur !== 'object' || seen.has(cur)) continue;
        seen.add(cur);
        for (const k of ['id', 'selectedId', 'selectedRowId', 'selectedButtonId', 'rowId', 'body', 'text']) {
          if (cur[k] !== undefined) queue.unshift(cur[k]);
        }
        for (const v of Object.values(cur)) if (v && typeof v === 'object') queue.push(v);
      }
    } catch {}
  }
  return out;
}

function _p2QuotedId(m) {
  const msg = (m && m.message) || {};
  const keys = ['extendedTextMessage', 'imageMessage', 'videoMessage', 'audioMessage', 'documentMessage',
    'buttonsResponseMessage', 'listResponseMessage', 'templateButtonReplyMessage', 'conversation'];
  for (const k of keys) {
    const ctx = msg[k] && msg[k].contextInfo;
    if (ctx && ctx.stanzaId) return ctx.stanzaId;
  }
  return null;
}

async function _p2OnMsg(sock, m) {
  const jid = (m && m.key && m.key.remoteJid) || '';
  if (!jid) return;
  const body = _p2Body(m);
  if (!body) return;
  const digits = String(body).replace(/[^0-9]/g, '');
  if (digits.length !== 1) return;
  const n = Number(digits);
  const qid = _p2QuotedId(m);
  if (!qid) return;
  const entry = _P2_PENDING.get(qid);
  // PRECIOUS FIX: normalised chat compare (was entry.jid !== jid -> silent).
  if (!entry || !_p2SameChat(entry.jid, jid)) return;
  if (n < 1 || n > 4) {
    // The card is still open — say WHY nothing was sent instead of going quiet.
    _P2_PENDING.delete(qid);
    await sock.sendMessage(jid, {
      text: '⚠️ *' + n + '* is not a format on that card. Quote it again with *1* audio, *2* document, *3* voice, *4* video.',
    }, { quoted: m }).catch(function () {});
    return;
  }
  _P2_PENDING.delete(qid);
  try { _p2MarkChatPending(_p2NormJid(jid), false); } catch {}
  if (typeof react === 'function') await react(sock, m, '⏳').catch(function () {});
  try {
    // PRECIOUS v20 — use the hardened deliver when it has been installed.
    if (typeof globalThis.__PRECIOUS_PLAY_DELIVER__ === 'function') {
      await globalThis.__PRECIOUS_PLAY_DELIVER__(sock, entry, n, m);
    } else {
      await _p2Deliver(sock, entry, n, m);
    }
    if (typeof react === 'function') await react(sock, m, '✅').catch(function () {});
  } catch (e) {
    const labels = { 1: 'audio', 2: 'document', 3: 'voice note', 4: 'video' };
    await sock.sendMessage(jid, {
      text: '❌ Could not send the ' + labels[n] + ' for *' + (entry.meta && entry.meta.title ? entry.meta.title : 'that song') + '*.\n_' + (e && e.message ? e.message : e) + '_',
    }, { quoted: m }).catch(function () {});
  }
}

function _p2Bind(sock) {
  try {
    if (!sock || !sock.ev || typeof sock.ev.on !== 'function') return;
    if (_P2_BOUND.has(sock)) return;
    _P2_BOUND.add(sock);
    sock.ev.on('messages.upsert', async function (evt) {
      if (!evt || evt.type !== 'notify') return;
      for (const m of (evt.messages || [])) {
        try { await _p2OnMsg(sock, m); } catch (e) { console.log('[play2] picker error:', e && e.message); }
      }
    });
    console.log('[play2] format-picker listener attached');
  } catch (e) {
    console.log('[play2] bind failed:', e && e.message);
  }
}

/* ── .play ─────────────────────────────────────────────────────────────────── */

const _p2PlayCardImpl = async (sock, msg, args) => {
  {
    const __rdl = (typeof globalThis.__RDL_PLAY_CARD__ === 'function') ? globalThis.__RDL_PLAY_CARD__ : null;
    if (__rdl) return __rdl(sock, msg, args);
  }
  const jid = msg.key.remoteJid;
  if (!args || !args.length) {
    await sendReply(sock, msg,
      '🎧 *' + CONFIG.BOT_NAME + ' PLAYER*\n\n' +
      'Usage: ' + CONFIG.PREFIX + 'play <song name or link>\n' +
      'Then quote the card with 1, 2, 3 or 4:\n' +
      '  1 = Audio   2 = Document   3 = Voice   4 = Video');
    return;
  }
  const query = args.join(' ').trim();
  const isUrl = /^https?:\/\//i.test(query);
  await react(sock, msg, '🎧').catch(function () {});

  const status = await sock.sendMessage(jid, {
    text: '🎧 *' + CONFIG.BOT_NAME + ' Player*\n\n🔍 Searching *' + query + '* …',
  }, { quoted: msg }).catch(function () { return null; });

  let meta = null;
  try {
    if (isUrl) {
      const vid = _p2YtId(query);
      const attempts = [
        function () { return dcGet('/download/ytmp3', { url: query }, 30000); },
        function () { return dcGet('/play', { query: query }, 30000); },
      ];
      if (vid) attempts.push(function () { return dcGet('/play', { query: 'https://www.youtube.com/watch?v=' + vid }, 30000); });
      for (const a of attempts) {
        try {
          const r = await a();
          const d = r && r.ok ? extractDcPlay(r.data) : null;
          if (d && (d.title || d.dlUrl)) {
            meta = { ...d, videoUrl: d.videoUrl || query, videoId: _p2YtId(d.videoUrl || query) };
            break;
          }
        } catch (e) {}
      }
    } else {
      try {
        const r = await dcGet('/play', { query: query }, 30000);
        const d = r && r.ok ? extractDcPlay(r.data) : null;
        if (d && (d.title || d.dlUrl)) meta = { ...d, videoId: _p2YtId(d.videoUrl) };
      } catch (e) {}
      if (!meta) {
        try {
          const res = await ytSearch(query);
          const v = res && res[0];
          if (v && v.url) meta = { title: v.title || query, videoUrl: v.url, videoId: _p2YtId(v.url) };
        } catch (e) {}
      }
    }
  } catch (e) {
    console.log('[play2] metadata error:', e && e.message);
  }

  if (!meta) meta = { title: query, videoUrl: isUrl ? query : '', videoId: _p2YtId(query) };
  if (!meta.videoUrl && meta.videoId) meta.videoUrl = 'https://www.youtube.com/watch?v=' + meta.videoId;

  // DavidCyril /play does not return the channel name, and /download/ytmp3
  // returns neither duration nor views. Fill only the blanks from yt-search so
  // the card never shows "Unknown / N/A" for a real track.
  if (!meta.artists && !meta.author || !meta.duration || !meta.views) {
    try {
      const ys = require('yt-search');
      const q = meta.videoId ? { videoId: meta.videoId } : (meta.title || query);
      const r = await ys(q);
      const v = meta.videoId ? r : (r && r.videos && r.videos[0]);
      if (v) {
        if (!meta.title) meta.title = v.title || meta.title;
        if (!meta.artists && !meta.author) meta.author = (v.author && v.author.name) || v.author || null;
        if (!meta.duration) meta.duration = (v.timestamp || (v.duration && v.duration.timestamp)) || meta.duration;
        if (!meta.views) meta.views = v.views || meta.views;
        if (!meta.thumbUrl && v.thumbnail) meta.thumbUrl = v.thumbnail;
        if (!meta.videoUrl && v.url) meta.videoUrl = v.url;
        if (!meta.videoId && v.videoId) meta.videoId = v.videoId;
      }
    } catch (e) { /* card still renders with what DavidCyril gave us */ }
  }

  const title = meta.title || query;
  const author = meta.artists || meta.author || meta.channel || 'Unknown';
  const card = [
    '🎧 *' + CONFIG.BOT_NAME + ' — PLAYER*',
    '',
    '🎵 *Title:*     ' + title,
    '👤 *Author:*    ' + author,
    '⏱️ *Duration:*  ' + _p2Dur(meta.duration),
    '👁️ *Views:*     ' + _p2Views(meta.views),
    '',
    '━━━━━━━━━━━━━━━━━━━━',
    '📥 *Choose a format — quote THIS message with the number:*',
    '',
    '  1️⃣  *Audio* — playable audio',
    '  2️⃣  *Document* — .mp3 file to download',
    '  3️⃣  *Voice* — voice note',
    '  4️⃣  *Video* — mp4 with sound',
    '',
    '_Example: reply to this card with_ `1` _for audio, `4` _for video._',
  ].join('\n');

  const thumb = await _p2ThumbBuf(meta).catch(function () { return null; });
  const sent = thumb
    ? await sock.sendMessage(jid, { image: thumb, caption: card }, { quoted: msg }).catch(function () { return null; })
    : await sock.sendMessage(jid, { text: card }, { quoted: msg }).catch(function () { return null; });

  if (status && status.key) { try { await sock.sendMessage(jid, { delete: status.key }); } catch (e) {} }

  if (!sent || !sent.key || !sent.key.id) {
    await sendReply(sock, msg, '❌ Could not send the player card for *' + title + '*.');
    return;
  }

  _p2Sweep();
  try { _p2MarkChatPending(jid, true); } catch {}
  _P2_PENDING.set(sent.key.id, {
    jid: _p2NormJid(jid),
    user: (typeof getSender === 'function' ? String(getSender(msg) || '') : ''),
    ts: Date.now(),
  });
  const _p2Timer = setTimeout(function () { _P2_PENDING.delete(sent.key.id); }, _P2_TTL);
  if (typeof _p2Timer.unref === 'function') _p2Timer.unref();
  _p2Bind(sock);
  await react(sock, msg, '✅').catch(function () {});
};

// The .play command entry (kept, so help/menu listings still show .play).
// disabled by v21 dedupe: legacy .play registration removed in favor of precious-fixes-v21
cmd(["play_legacy_disabled", "music_legacy_disabled", "song_legacy_disabled"], { desc: "Legacy disabled", category: "DOWNLOAD" }, _p2PlayCardImpl);

// Registrar used by the late re-registration block near the end of the file,
// which is what actually makes the card handler win over older overrides.
function _p2ResolveCardRegistrar() { return (typeof globalThis.__RDL_PLAY_HANDLER__ === "function") ? globalThis.__RDL_PLAY_HANDLER__ : _p2PlayCardImpl; }

cmd(["playvid","playvideo","vidplay"], { desc: "Download song as video (mp4)", category: "DOWNLOAD" }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `❌ Usage: ${CONFIG.PREFIX}playvid <song name or YouTube URL>`); return; }
  await react(sock, msg, "🎬");
  const query = args.join(" ").trim();
  const isUrl = /^https?:\/\//i.test(query);
  const jid = msg.key.remoteJid;
  const statusMsg = await sock.sendMessage(jid, { text: `🎬 *${CONFIG.BOT_NAME} Video Player*\n\n🔍 Searching *"${query}"*...` }, { quoted: msg });
  const sKey = statusMsg.key;
  try {
    let videoUrl = isUrl ? query : null, title = query, thumb = null;
    if (!isUrl) {
      // Search for video URL
      const _searchApis = [
        async () => { const { data } = await axios.get(`${CONFIG.GIFTED_API}/api/search/ytsearch?apikey=${CONFIG.GIFTED_KEY}&q=${encodeURIComponent(query)}`, { timeout: 15000 }); const v = data?.result?.[0] || data?.results?.[0]; if (v?.url) return { url: v.url, title: v.title, thumb: v.thumbnail }; },
        async () => { const { data } = await axios.get(`https://api.siputzx.my.id/api/y/search?query=${encodeURIComponent(query)}`, { timeout: 15000 }); const v = data?.data?.[0]; if (v?.url) return { url: v.url, title: v.title, thumb: v.thumbnail }; },
        async () => { const results = await ytSearch(query); if (results?.[0]?.url) return { url: results[0].url, title: results[0].title, thumb: results[0].thumbnail }; },
      ];
      for (const sf of _searchApis) { try { const r = await sf(); if (r?.url) { videoUrl = r.url; title = r.title || query; thumb = r.thumb; break; } } catch {} }
    }
    if (!videoUrl) { await editMessage(sock, jid, sKey, `🎬 *${CONFIG.BOT_NAME} Video Player*\n\n❌ No results for *"${query}"*`); return; }
    await editMessage(sock, jid, sKey, `🎬 *${CONFIG.BOT_NAME} Video Player*\n\n🔍 Found: *${title}*\n⏳ Downloading video...`);

    // Send thumbnail if available
    if (thumb) { try { const _tb = Buffer.from((await axios.get(thumb, { responseType: "arraybuffer", timeout: 10000 })).data); await sock.sendMessage(jid, { image: _tb, caption: `🎬 *${title}*\n_Downloading video..._` }, { quoted: msg }); } catch {} }

    let vBuf = null;
    try { vBuf = await _p2VideoBuf({ videoUrl, title, videoId: _p2YtId(videoUrl) || "" }); } catch {}

    if (vBuf && vBuf.length > 10000) {
      const safeTitle = String(title || "video").replace(/[^\w\s.-]/g, "_").trim().slice(0, 60) || "video";
      try {
        await sock.sendMessage(jid, { video: vBuf, mimetype: "video/mp4", caption: `🎬 *${title}*` }, { quoted: msg });
      } catch {
        await sock.sendMessage(jid, { document: vBuf, mimetype: "video/mp4", fileName: `${safeTitle}.mp4`, caption: `🎬 *${title}*` }, { quoted: msg });
      }
      await editMessage(sock, jid, sKey, `🎬 *${CONFIG.BOT_NAME} Video Player*\n\n✅ *${title}* sent!`);
      await react(sock, msg, "✅");
    } else {
      await editMessage(sock, jid, sKey, `🎬 *${CONFIG.BOT_NAME} Video Player*\n\n❌ All video providers failed.\n🔗 ${videoUrl}`);
      await react(sock, msg, "❌");
    }
  } catch (e) {
    await editMessage(sock, jid, sKey, `🎬 *Video Player Error:* ${e?.message || e}`).catch(() => {});
    await react(sock, msg, "❌");
  }
});

cmd(["play2", "playdoc", "songdoc"], { desc: "Play song delivered as a downloadable document (mp3 file)", category: "DOWNLOAD" }, async (sock, msg, args) => {
  if (!args.length) return sendReply(sock, msg, `❌ Usage: ${CONFIG.PREFIX}play2 <song name>`);
  await react(sock, msg, "🎼");
  const query = args.join(" ").trim();
  const isUrl = /^https?:\/\//i.test(query);
  const jid = msg.key.remoteJid;
  const statusMsg = await sock.sendMessage(jid, { text: `🎼 *${CONFIG.BOT_NAME} Player (Doc)*\n\n🔍 Searching for *"${query}"*...` }, { quoted: msg });
  const statusKey = statusMsg.key;
  try {
    // NEXORA FAST PATH — direct MP3 document (highest priority, query-only)
    let title = query, artist = "", thumb = null, videoUrl = isUrl ? query : null;
    if (!isUrl) {
      try {
        const nexRes = await dcGet("/play", { query }, 30000);
        const nex = nexRes.ok ? nexRes.data : null;
        if (nex?.status && nex?.result?.download_url) {
          const nexAudio = await axios.get(nex.result.download_url, {
            responseType: "arraybuffer", timeout: 120000, maxRedirects: 5,
            headers: { "User-Agent": "Mozilla/5.0" }
          });
          const nexBuf = Buffer.from(nexAudio.data || []);
          if (nexBuf.length > 8000) {
            title = (nex.result.title || query).slice(0, 80);
            const fileName = `${title.replace(/[^\w\s.-]/g, "_").slice(0, 60)}.mp3`;
            await sock.sendMessage(jid, {
              document: nexBuf, fileName, mimetype: "audio/mpeg",
              caption: `🎼 *${title}*\n📁 Sent as document — tap to download.`,
            }, { quoted: msg });
            await editMessage(sock, jid, statusKey, `🎼 *${CONFIG.BOT_NAME} Player (Doc)*\n\n✅ *${title}* sent as document!`);
            return;
          }
        }
      } catch {}
    }

    // FAST PATH — toxicapis ytmp3 returns a direct CDN URL
    try {
      const tox = (await toxicCall("/download/ytmp3", { url: isUrl ? query : "", q: isUrl ? "" : query }))
                || (await toxicCall("/d/ytmp3",       { url: isUrl ? query : "", q: isUrl ? "" : query }));
      if (tox?.url) {
        const buf = await urlToBuffer(tox.url).catch(() => null);
        if (buf && buf.length > 8000) {
          title = (tox.title || query).slice(0, 80);
          const fileName = `${title.replace(/[^\w\s.-]/g, "_").slice(0, 60)}.mp3`;
          await sock.sendMessage(jid, {
            document: buf, fileName, mimetype: "audio/mpeg",
            caption: `🎼 *${title}*\n📁 Sent as document — tap to download.`,
          }, { quoted: msg });
          await editMessage(sock, jid, statusKey, `🎼 *${CONFIG.BOT_NAME} Player (Doc)*\n\n✅ *${title}* sent as document!`);
          return;
        }
      }
    } catch {}

    // 1) Resolve a YouTube URL via the same search APIs play() uses
    if (!videoUrl) {
      const searchApis = [
        async () => { const { data } = await axios.get(`${CONFIG.GIFTED_API}/api/search/ytsearch?apikey=${CONFIG.GIFTED_KEY}&q=${encodeURIComponent(query)}`, { timeout: 15000 }); const v = data?.result?.[0] || data?.results?.[0]; if (v?.url || v?.link) return { url: v.url || v.link, title: v.title || query, thumb: v.thumbnail }; },
        async () => { const { data } = await axios.get(`https://api.siputzx.my.id/api/y/search?query=${encodeURIComponent(query)}`, { timeout: 15000 }); const v = data?.data?.[0] || data?.result?.[0]; if (v?.url || v?.link) return { url: v.url || v.link, title: v.title || query, thumb: v.thumbnail }; },
        async () => { const r = await ytSearch(query); if (r?.[0]?.url) return { url: r[0].url, title: r[0].title || query, thumb: r[0].thumbnail }; },
        async () => { const { data } = await axios.get(`https://www.youtube.com/results?search_query=${encodeURIComponent(query)}`, { headers: { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36" }, timeout: 15000 }); const m = data.match(/"videoId":"([a-zA-Z0-9_-]{11})"/); if (m) return { url: `https://www.youtube.com/watch?v=${m[1]}`, title: query }; },
      ];
      for (const fn of searchApis) {
        try { const r = await fn(); if (r?.url) { videoUrl = r.url; title = r.title || query; thumb = r.thumb || null; break; } } catch {}
      }
      if (!videoUrl) {
        await editMessage(sock, jid, statusKey, `🎼 *${CONFIG.BOT_NAME} Player (Doc)*\n\n🔍 Searching for *"${query}"*... ✅\n❌ No results found`);
        return;
      }
    }
    await editMessage(sock, jid, statusKey, `🎼 *${CONFIG.BOT_NAME} Player (Doc)*\n\n🔍 Searching for *"${query}"*... ✅\n📌 Found: *${title}*\n⏳ Downloading audio...`);

    // 2) Same proven dlApis as play() — no ytdl-core (YT blocks shared IPs)
    // v4.9.5 FIX: cobalt entries updated to match the working URLs from play():
    //   co.wuk.sh/api/json is the community mirror (old root / was retired),
    //   api.cobalt.tools/api/json has the correct sub-path.
    const dlApis = [
      // PRIMARY: DavidCyril
      async () => { const r = await dcGet("/download/ytmp3", { url: videoUrl }, 30000); const d = r?.ok ? extractDcPlay(r.data) : null; return d?.dlUrl || null; },
      async () => { const r = await dcGet("/play", { query: videoUrl }, 30000); const d = r?.ok ? extractDcPlay(r.data) : null; return d?.dlUrl || null; },
      async () => {
        const { data } = await axios.post("https://co.wuk.sh/api/json",
          { url: videoUrl, downloadMode: "audio", audioFormat: "mp3", filenameStyle: "basic" },
          { headers: { Accept: "application/json", "Content-Type": "application/json", "User-Agent": "Mozilla/5.0" }, timeout: 30000 });
        return data?.url || data?.audio;
      },
      async () => {
        const { data } = await axios.post("https://cobalt-api.kwiatekmiki.com/",
          { url: videoUrl, downloadMode: "audio", audioFormat: "mp3" },
          { headers: { Accept: "application/json", "Content-Type": "application/json" }, timeout: 30000 });
        return data?.url;
      },
      async () => {
        const { data } = await axios.post("https://api.cobalt.tools/api/json",
          { url: videoUrl, downloadMode: "audio", audioFormat: "mp3" },
          { headers: { Accept: "application/json", "Content-Type": "application/json", "User-Agent": "Mozilla/5.0" }, timeout: 30000 });
        return data?.url || data?.audio;
      },
      async () => {
        const { data } = await axios.get(
          `https://api.axeel.my.id/api/download/audio?url=${encodeURIComponent(videoUrl)}`,
          { headers: { "User-Agent": "Mozilla/5.0" }, timeout: 30000 });
        return data?.downloadUrl || data?.url || data?.result?.url || data?.data?.url;
      },
      async () => {
        const videoId = videoUrl.match(/(?:v=|youtu\.be\/)([a-zA-Z0-9_-]{11})/)?.[1];
        if (!videoId) return;
        const { data } = await axios.get(
          `https://api.vevioz.com/api/button/mp3/${videoId}`,
          { headers: { "User-Agent": "Mozilla/5.0", Accept: "text/html,application/json" }, timeout: 25000 });
        if (typeof data === "string") { const m = data.match(/href="(https?:\/\/[^"]+\.mp3[^"]*)"/); if (m) return m[1]; }
        return data?.url;
      },
      async () => { const id = videoUrl.match(/(?:v=|youtu\.be\/)([a-zA-Z0-9_-]{11})/)?.[1]; if (!id) return; const { data } = await axios.get(`https://inv.nadeko.net/api/v1/videos/${id}`, { timeout: 20000 }); const a = data?.adaptiveFormats?.find(f => f.type?.includes("audio") && f.url); return a?.url; },
      async () => { const { data } = await axios.get(`https://p.oceansaver.in/ajax/download.php?format=mp3&url=${encodeURIComponent(videoUrl)}`, { timeout: 30000 }); if (data?.success && data?.download) return data.download; },
      async () => { const { data } = await axios.get(`${CONFIG.GIFTED_API}/api/download/ytmp3?apikey=${CONFIG.GIFTED_KEY}&url=${encodeURIComponent(videoUrl)}`, { timeout: 60000 }); if (data?.success && data?.result) return data.result.download_url || data.result.url || data.result.audio || data.result.mp3; },
      async () => { const r = await APIs.getEliteProTechDownloadByUrl(videoUrl); return r?.download; },
      async () => { const r = await APIs.getYupraDownloadByUrl(videoUrl); return r?.download; },
      async () => { const r = await APIs.getOkatsuDownloadByUrl(videoUrl); return r?.download; },
      async () => { const r = await APIs.getIzumiDownloadByUrl(videoUrl); return r?.download; },
      async () => { const { data } = await axios.get(`https://api.ssyoutube.com/v2/?url=${encodeURIComponent(videoUrl)}`, { headers: { "User-Agent": "Mozilla/5.0" }, timeout: 20000 }); const a = data?.audio?.find(x => x.url) || data?.links?.find(l => l.url && l.type === "audio"); return a?.url; },
    ];

    let sent = false;
    for (const tryDl of dlApis) {
      let dlUrl = null;
      try { dlUrl = await tryDl(); } catch {}
      if (!dlUrl) continue;
      try {
        const audioRes = await axios.get(dlUrl, { responseType: "arraybuffer", timeout: 120000, headers: { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36", Accept: "*/*" }, maxRedirects: 5, validateStatus: s => s >= 200 && s < 400 });
        const buf = Buffer.from(audioRes.data || []);
        const ct = String(audioRes.headers?.["content-type"] || "").toLowerCase();
        const looksHtml = buf.length >= 5 && (buf.slice(0, 5).toString("utf8").toLowerCase() === "<!doc" || buf.slice(0, 5).toString("utf8").toLowerCase() === "<html");
        const looksJson = buf.length >= 1 && (buf[0] === 0x7B || buf[0] === 0x5B);
        const hasId3      = buf.length >= 3 && buf.slice(0, 3).toString("utf8") === "ID3";
        const hasMpegSync = buf.length >= 2 && buf[0] === 0xFF && (buf[1] & 0xE0) === 0xE0;
        const hasOggS     = buf.length >= 4 && buf.slice(0, 4).toString("utf8") === "OggS";
        const hasRiff     = buf.length >= 4 && buf.slice(0, 4).toString("utf8") === "RIFF";
        const ctOk        = /audio|mpeg|mp3|ogg|m4a|aac|wav|octet-stream|binary/i.test(ct);
        const looksAudio  = hasId3 || hasMpegSync || hasOggS || hasRiff || (ctOk && !looksHtml && !looksJson);
        if (buf.length < 5000 || !looksAudio) {
          console.log(`[PLAY2] skipped corrupt buffer (len=${buf.length}, ct=${ct})`);
          continue;
        }
        // Always send as audio/mpeg .mp3 for maximum WhatsApp compatibility
        const _p2hasOggS = buf.length >= 4 && buf.slice(0, 4).toString("utf8") === "OggS";
        const _p2Mime = _p2hasOggS ? "audio/ogg" : "audio/mpeg";
        const _p2Ext = _p2hasOggS ? ".ogg" : ".mp3";
        const fileName = `${title.replace(/[^\w\s.-]/g, "_").slice(0, 60)}${_p2Ext}`;
        const thumbBuf = thumb ? await urlToBuffer(thumb).catch(() => null) : null;
        await sock.sendMessage(jid, {
          document: buf, fileName, mimetype: _p2Mime,
          caption: `🎼 *${title}*${artist ? `\n👤 ${artist}` : ""}\n📁 Sent as document — tap to download.`,
          ...(thumbBuf ? { jpegThumbnail: thumbBuf } : {}),
        }, { quoted: msg });
        await editMessage(sock, jid, statusKey, `🎼 *${CONFIG.BOT_NAME} Player (Doc)*\n\n🔍 Searching for *"${query}"*... ✅\n📌 Found: *${title}*\n⏳ Downloading audio... ✅\n📤 Sending document... ✅\n\n✅ *Done!*`);
        sent = true;
        break;
      } catch (e) { console.log("[PLAY2] provider failed:", e?.message || e); }
    }
    if (!sent) {
      await editMessage(sock, jid, statusKey, `🎼 *${CONFIG.BOT_NAME} Player (Doc)*\n\n🔍 Searching for *"${query}"*... ✅\n📌 Found: *${title}*\n⏳ Downloading audio... ❌\n\n⚠️ All audio providers failed. Try again in a bit.\n🔗 ${videoUrl}`);
    }
  } catch (e) {
    console.error("[PLAY2 ERROR]", e?.message);
    await editMessage(sock, jid, statusKey, `❌ Play2 error: ${e?.message || "could not fetch song"}`).catch(() => {});
  }
});

cmd(["statusmention", "smention"], { desc: "Toggle status-author contact card relay to owner DM", category: "OWNER", ownerOnly: true }, async (sock, msg, args) => {
  const ownerS = getSettings(getOwnerJid());
  const a = (args[0] || "").toLowerCase();
  if (a === "on" || a === "enable")  ownerS.statusMention = true;
  else if (a === "off" || a === "disable") ownerS.statusMention = false;
  else ownerS.statusMention = !ownerS.statusMention;
  saveNow();
  await sendReply(sock, msg,
    `📇 *Status Mention: ${ownerS.statusMention ? "✅ ON" : "❌ OFF"}*\n\n` +
    `When ON, the bot relays a *contact card* of every status author to your DM, so you can tap the card and chat them directly.\n_Throttled to once per author per 6 hours._`);
});

// ════════════════════════════════════════════════════════════════════════════
// play! / play2! — MIME-type picker (fallback when default format is corrupt)
// ════════════════════════════════════════════════════════════════════════════
// In-memory store: jid → { videoUrl, title, ts }  (expires in 10 min)
const _playPickStore = new Map();
const _saveTubePickStore = new Map();

// Shared compact download chain used by playget / playgetdoc
async function _fetchYtAudioBuf(videoUrl, preferFmt = "mp3") {
  const cobaltFmt = preferFmt === "m4a" ? "best" : (preferFmt === "ogg" ? "ogg" : "mp3");
  const dlApis = [
    // PRIMARY: DavidCyril
    async () => { const r = await dcGet("/download/ytmp3", { url: videoUrl }, 30000); const d = r?.ok ? extractDcPlay(r.data) : null; return d?.dlUrl || null; },
    async () => { const r = await dcGet("/play", { query: videoUrl }, 30000); const d = r?.ok ? extractDcPlay(r.data) : null; return d?.dlUrl || null; },
    async () => { const { data } = await axios.post("https://co.wuk.sh/api/json", { url: videoUrl, downloadMode: "audio", audioFormat: cobaltFmt, filenameStyle: "basic" }, { headers: { Accept: "application/json", "Content-Type": "application/json", "User-Agent": "Mozilla/5.0" }, timeout: 30000 }); return data?.url || data?.audio; },
    async () => { const { data } = await axios.post("https://cobalt-api.kwiatekmiki.com/", { url: videoUrl, downloadMode: "audio", audioFormat: cobaltFmt }, { headers: { Accept: "application/json", "Content-Type": "application/json" }, timeout: 30000 }); return data?.url; },
    async () => { const { data } = await axios.post("https://api.cobalt.tools/api/json", { url: videoUrl, downloadMode: "audio", audioFormat: cobaltFmt }, { headers: { Accept: "application/json", "Content-Type": "application/json", "User-Agent": "Mozilla/5.0" }, timeout: 30000 }); return data?.url || data?.audio; },
    async () => { const { data } = await axios.get(`https://api.axeel.my.id/api/download/audio?url=${encodeURIComponent(videoUrl)}`, { headers: { "User-Agent": "Mozilla/5.0" }, timeout: 30000 }); return data?.downloadUrl || data?.url || data?.result?.url || data?.data?.url; },
    async () => { const id = videoUrl.match(/(?:v=|youtu\.be\/)([a-zA-Z0-9_-]{11})/)?.[1]; if (!id) return; const { data } = await axios.get(`https://api.vevioz.com/api/button/mp3/${id}`, { headers: { "User-Agent": "Mozilla/5.0", Accept: "text/html,application/json" }, timeout: 25000 }); if (typeof data === "string") { const m = data.match(/href="(https?:\/\/[^"]+\.mp3[^"]*)"/); if (m) return m[1]; } return data?.url; },
    async () => { const id = videoUrl.match(/(?:v=|youtu\.be\/)([a-zA-Z0-9_-]{11})/)?.[1]; if (!id) return; const { data } = await axios.get(`https://inv.nadeko.net/api/v1/videos/${id}`, { timeout: 20000 }); const a = data?.adaptiveFormats?.find(f => f.type?.includes("audio") && f.url); return a?.url; },
    async () => { const { data } = await axios.get(`https://p.oceansaver.in/ajax/download.php?format=mp3&url=${encodeURIComponent(videoUrl)}`, { timeout: 30000 }); if (data?.success && data?.download) return data.download; },
    async () => { const tox = await toxicCall("/download/ytmp3", { url: videoUrl, q: "" }); return tox?.url; },
    async () => { const { data } = await axios.get(`${CONFIG.GIFTED_API}/api/download/ytmp3?apikey=${CONFIG.GIFTED_KEY}&url=${encodeURIComponent(videoUrl)}`, { timeout: 60000 }); if (data?.success && data?.result) return data.result.download_url || data.result.url || data.result.audio || data.result.mp3; },
    async () => { const r = await APIs.getEliteProTechDownloadByUrl(videoUrl); return r?.download; },
    async () => { const r = await APIs.getYupraDownloadByUrl(videoUrl); return r?.download; },
  ];
  for (const fn of dlApis) {
    let dlUrl = null;
    try { dlUrl = await fn(); } catch {}
    if (!dlUrl) continue;
    try {
      const res = await axios.get(dlUrl, { responseType: "arraybuffer", timeout: 120000, headers: { "User-Agent": "Mozilla/5.0" }, maxRedirects: 5, validateStatus: s => s >= 200 && s < 400 });
      const buf = Buffer.from(res.data || []);
      if (buf.length < 5000) continue;
      const ct = String(res.headers?.["content-type"] || "").toLowerCase();
      const looksHtml = buf.slice(0, 5).toString("utf8").toLowerCase().startsWith("<!doc") || buf.slice(0, 5).toString("utf8").toLowerCase().startsWith("<html");
      const hasId3      = buf.length >= 3 && buf.slice(0, 3).toString("utf8") === "ID3";
      const hasMpegSync = buf.length >= 2 && buf[0] === 0xFF && (buf[1] & 0xE0) === 0xE0;
      const hasOggS     = buf.length >= 4 && buf.slice(0, 4).toString("utf8") === "OggS";
      const hasRiff     = buf.length >= 4 && buf.slice(0, 4).toString("utf8") === "RIFF";
      const hasM4A      = buf.length >= 12 && buf.slice(4, 8).toString("ascii") === "ftyp";
      const hasWebm     = buf.length >= 4 && buf[0] === 0x1a && buf[1] === 0x45 && buf[2] === 0xdf && buf[3] === 0xa3;
      const ctOk        = /audio|mpeg|mp3|ogg|m4a|aac|wav|octet-stream|binary/i.test(ct);
      const looksAudio  = hasId3 || hasMpegSync || hasOggS || hasRiff || hasM4A || hasWebm || (ctOk && !looksHtml);
      if (!looksAudio) continue;
      // Determine detected format
      const detectedFmt = hasM4A ? "m4a" : hasOggS ? "ogg" : hasRiff ? "wav" : hasWebm ? "webm" : "mp3";
      const detectedMime = hasM4A ? "audio/mp4" : hasOggS ? "audio/ogg; codecs=opus" : hasRiff ? "audio/wav" : hasWebm ? "audio/webm" : "audio/mpeg";
      const detectedExt  = hasM4A ? ".m4a" : hasOggS ? ".ogg" : hasRiff ? ".wav" : hasWebm ? ".webm" : ".mp3";
      return { buf, detectedFmt, detectedMime, detectedExt };
    } catch {}
  }
  return null;
}

// ── play! — search then show MIME-type format picker buttons ─────────────────
cmd(["play!", "musicpick", "songpick"], { desc: "Play song — pick audio format (MIME picker)", category: "DOWNLOAD" }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `🎵 *Usage:* ${CONFIG.PREFIX}play! <song name or URL>\n\n_Bot searches the song, then lets you pick the audio format before downloading — handy when the default returns a corrupt file._`); return; }
  await react(sock, msg, "🎵");
  const query = args.join(" ");
  const isUrl = /^https?:\/\//i.test(query);
  const jid = msg.key.remoteJid;
  const statusMsg = await sock.sendMessage(jid, { text: `🎵 *MIAS MDX Player (Pick)*\n\n🔍 Searching for *"${query}"*...` }, { quoted: msg });
  const statusKey = statusMsg.key;
  try {
    let videoUrl = isUrl ? query : null;
    let title = query;
    if (!videoUrl) {
      const searchApis = [
        async () => { const { data } = await axios.get(`${CONFIG.GIFTED_API}/api/search/ytsearch?apikey=${CONFIG.GIFTED_KEY}&q=${encodeURIComponent(query)}`, { timeout: 15000 }); const v = data?.result?.[0] || data?.results?.[0]; if (v?.url || v?.link) return { url: v.url || v.link, title: v.title || query }; },
        async () => { const { data } = await axios.get(`https://api.siputzx.my.id/api/y/search?query=${encodeURIComponent(query)}`, { timeout: 15000 }); const v = data?.data?.[0] || data?.result?.[0]; if (v?.url || v?.link) return { url: v.url || v.link, title: v.title || query }; },
        async () => { const r = await ytSearch(query); if (r?.[0]?.url) return { url: r[0].url, title: r[0].title || query }; },
        async () => { const { data } = await axios.get(`https://www.youtube.com/results?search_query=${encodeURIComponent(query)}`, { headers: { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36" }, timeout: 15000 }); const m = data.match(/"videoId":"([a-zA-Z0-9_-]{11})"/); if (m) return { url: `https://www.youtube.com/watch?v=${m[1]}`, title: query }; },
      ];
      for (const fn of searchApis) {
        try { const r = await fn(); if (r?.url) { videoUrl = r.url; title = r.title || query; break; } } catch {}
      }
    }
    if (!videoUrl) {
      await editMessage(sock, jid, statusKey, `🎵 *MIAS MDX Player (Pick)*\n\n❌ No results found for: *"${query}"*`);
      return;
    }
    __miasMapSet(_playPickStore, jid, { videoUrl, title, ts: Date.now(), picker: "audio" });
    await sock.sendMessage(jid, { delete: statusKey }).catch(() => {});
    const shortTitle = title.slice(0, 55);
    const pickerText = `🎵 *${shortTitle}*\n\n🎧 Choose the audio format you want to receive:\n_Tip: if one format sounds corrupt, pick another_`;
    const buttons = [
      { text: "🎵 MP3  (standard audio)", id: `${CONFIG.PREFIX}playget mp3` },
      { text: "📦 M4A  (high quality)",   id: `${CONFIG.PREFIX}playget m4a` },
      { text: "🎶 OGG  (opus/ogg)",       id: `${CONFIG.PREFIX}playget ogg` },
      { text: "📄 Send as MP3 Document",  id: `${CONFIG.PREFIX}playget doc` },
    ];
    try { await sendNativeFlowButtons(sock, jid, msg, pickerText, buttons, `${CONFIG.BOT_NAME} • Audio Format Picker`); }
    catch { await sendReply(sock, msg, `${pickerText}\n\nReply with:\n1. MP3\n2. M4A\n3. OGG\n4. MP3 document`); }
  } catch (e) {
    await editMessage(sock, jid, statusKey, `❌ Error: ${e.message}`).catch(() => {});
  }
});

