cmd(["removebg", "rmbg", "rmwbg", "bgremove"], { desc: "Remove image background", category: "AI" }, async (sock, msg) => {
  const q = msg.message?.extendedTextMessage?.contextInfo?.quotedMessage;
  const img = msg.message?.imageMessage || q?.imageMessage;
  if (!img) { await sendReply(sock, msg, `❌ Reply to an image with *${CONFIG.PREFIX}removebg*`); return; }
  const jid = msg.key.remoteJid;
  const statusMsg = await sock.sendMessage(jid, { text: `🖼️ *MIAS MDX RemoveBG*\n\n⬡ Downloading image...\n◻ Removing background...\n◻ Sending result...` }, { quoted: msg });
  const bgKey = statusMsg.key;
  try {
    const stream = await downloadContentFromMessage(img, imgType);
    let buf = Buffer.from([]);
    for await (const c of stream) buf = Buffer.concat([buf, c]);
    await editMessage(sock, jid, bgKey, `🖼️ *MIAS MDX RemoveBG*\n\n⬢ Image downloaded ✅\n⬡ Removing background...\n◻ Sending result...`).catch(() => {});

    // Helper: POST image buf and return PNG buffer (or null)
    const _tryProvider = async (url, extraParams = {}) => {
      let FD; try { FD = (await import("form-data")).default; } catch { return null; }
      const form = new FD();
      form.append("image", buf, { filename: "image.jpg", contentType: img.mimetype || "image/jpeg" });
      for (const [k, v] of Object.entries(extraParams)) form.append(k, String(v));
      const res = await axios.post(url, form, { headers: form.getHeaders(), timeout: 60000, responseType: "arraybuffer" });
      const raw = Buffer.from(res.data);
      // Check if it's actually an image (PNG magic bytes: 89 50 4E 47)
      if (raw.length > 1000 && (raw[0] === 0x89 || raw[0] === 0xFF || raw[0] === 0x47 || raw[0] === 0x52)) return raw;
      // Maybe JSON with URL
      try {
        const j = JSON.parse(raw.toString());
        const resultUrl = j?.result?.url || j?.result?.image || j?.data?.url || j?.url || (typeof j?.result === "string" ? j.result : null);
        if (resultUrl) {
          const imgRes = await axios.get(resultUrl, { responseType: "arraybuffer", timeout: 30000 });
          return Buffer.from(imgRes.data);
        }
      } catch {}
      return null;
    };

    const providers = [
      // 1. Prexzy (own server — fastest)
      () => _tryProvider(`${CONFIG.PREXZY_API}/tools/removebg`),
      // 2. Ryzendesu
      () => _tryProvider("https://api.ryzendesu.vip/api/tools/removebg"),
      // 3. Siputzx
      () => _tryProvider("https://api.siputzx.my.id/api/tools/removebg"),
      // 4. GiftedTech
      () => _tryProvider(`${CONFIG.GIFTED_API}/api/tools/removebg?apikey=${CONFIG.GIFTED_KEY}`),
      // 5. Nexoracle base64 JSON
      async () => {
        const { data } = await axios.post("https://api.nexoracle.com/misc/remove-bg?apikey=free_key@maher_apis",
          { image: buf.toString("base64") }, { headers: { "Content-Type": "application/json" }, timeout: 60000, responseType: "arraybuffer" });
        const raw = Buffer.from(data);
        if (raw.length > 1000 && raw[0] === 0x89) return raw;
        return null;
      },
    ];

    let resultBuf = null;
    for (const prov of providers) {
      try { resultBuf = await prov(); if (resultBuf) break; } catch {}
    }

    await sock.sendMessage(jid, { delete: bgKey }).catch(() => {});

    if (!resultBuf) {
      await sendCTAButtons(sock, jid, msg,
        `🖼️ *Remove Background*\n\n⚠️ All providers failed right now.\nTry the link below for free background removal.`,
        [{ type: "url", text: "🌐 Remove.bg (Free)", url: "https://remove.bg" }],
        `${CONFIG.BOT_NAME} • RemoveBG`
      ).catch(() => sendReply(sock, msg, `🖼️ *Remove Background*\n\n⚠️ All providers failed.\n🔗 Try: https://remove.bg`));
      return;
    }

    await sock.sendMessage(jid, { image: resultBuf, caption: `🖼️ *Background Removed!*` }, { quoted: msg });
    await react(sock, msg, "✅");
  } catch (e) {
    await sock.sendMessage(jid, { delete: bgKey }).catch(() => {});
    await sendReply(sock, msg, `❌ *RemoveBG failed:* ${e.message}\n🔗 Try: https://remove.bg`);
  }
});
