cmd(["autochat", "autoreply"], { desc: "Toggle auto-chatbot for this chat — .autochat on/off", category: "OWNER", ownerOnly: true }, async (sock, msg, args) => {
  const chatS = getSettings(msg.key.remoteJid);
  const sub = (args[0] || "").toLowerCase();
  if (sub === "on" || sub === "enable") chatS.autoReply = true;
  else if (sub === "off" || sub === "disable") chatS.autoReply = false;
  else chatS.autoReply = !chatS.autoReply;
  saveNow();
  const status = chatS.autoReply ? "✅ ON" : "❌ OFF";
  const scope   = getSettings(getOwnerJid())?.chatbotScope || "all";
  await sendReply(sock, msg,
    `💬 *Auto-Chatbot: ${status}*\n\n` +
    (chatS.autoReply
      ? `The bot will now reply to every non-command message in this chat with AI.\n_Scope filter: *${scope}* (change with ${CONFIG.PREFIX}chatbotscope)_`
      : `The bot will stop auto-replying in this chat.`) +
    ``
  );
});

