cmd(["chatbotscope", "chatscope"], { desc: "Set autochat scope — .chatbotscope all|dm|group", category: "OWNER", ownerOnly: true }, async (sock, msg, args) => {
  const ownerS = getSettings(getOwnerJid());
  const sub = (args[0] || "").toLowerCase();
  const valid = ["all", "dm", "group"];
  if (!valid.includes(sub)) {
    await sendReply(sock, msg,
      `⚙️ *Chatbot Scope*\n\nCurrent: *${ownerS.chatbotScope || "all"}*\n\nUsage:\n  *${CONFIG.PREFIX}chatbotscope all*   — reply in DMs AND groups\n  *${CONFIG.PREFIX}chatbotscope dm*    — DMs only\n  *${CONFIG.PREFIX}chatbotscope group* — groups only`
    );
    return;
  }
  ownerS.chatbotScope = sub;
  saveNow();
  await sendReply(sock, msg,
    `⚙️ *Chatbot Scope → ${sub.toUpperCase()}*\n\nAuto-chatbot will now reply in: *${sub === "all" ? "DMs + groups" : sub === "dm" ? "DMs only" : "groups only"}*.`
  );
});

