// ── MYNETNAIJA MOVIE API ─────────────────────────────────────────────────────
// David Cyril's search endpoint returns stable movie-page URLs.  The matching
// /info endpoint resolves those pages to the real hosted file URL, so we do
// not send a web page or a "download" landing page as the movie file.
const _mynetMoviePicks = new Map();

function _mynetMovieList(data) {
  const list = data?.results || data?.data?.results || data?.data || data?.movies || [];
  return Array.isArray(list) ? list.filter((item) => item && (item.url || item.link)) : [];
}

function _mynetMovieInfo(data) {
  const d = data?.data || data;
  const download = d?.download || {};
  const fileUrl = download?.url || download?.download_url || download?.direct_url || d?.download_url || d?.file_url;
  return {
    title: d?.title || d?.name || "Movie",
    description: d?.description || d?.overview || "",
    thumbnail: d?.thumbnail || d?.poster || d?.image || "",
    genre: d?.genre || d?.genres || "",
    sourceUrl: d?.source_url || d?.url || "",
    fileUrl: typeof fileUrl === "string" && /^https?:\/\//i.test(fileUrl) ? fileUrl : null,
    fileName: download?.file_name || "",
    fileExt: String(download?.file_ext || "").toLowerCase(),
    fileSize: download?.file_size || "",
    host: download?.host || "",
  };
}

// PRECIOUS FIX: the movie API answers HTTP 500 {"success":false,
// "message":"timeout of 12000ms exceeded"} when its own upstream is slow.
// That is transient — retry it and return the parsed body either way instead
// of throwing into the catch-all that made .moviedl look broken.
async function _dcMovieJson(url, params, timeoutMs) {
  let lastErr = null;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      const res = await axios.get(url, {
        params: params || {},
        timeout: timeoutMs || 20000,
        headers: { "User-Agent": "Mozilla/5.0", Accept: "application/json" },
        validateStatus: function () { return true; },
      });
      const data = res.data;
      if (data && data.success === false && /timeout/i.test(String(data.message || data.error || "")) && attempt < 3) {
        console.warn("[movie] provider timeout, retrying (" + attempt + "/3)");
        await new Promise(function (r) { setTimeout(r, 900 * attempt); });
        continue;
      }
      return { ok: !!(data && (data.success === true || data.results || data.data || data.result)), data: data };
    } catch (e) {
      lastErr = e;
      if (attempt < 3) { await new Promise(function (r) { setTimeout(r, 800 * attempt); }); continue; }
    }
  }
  console.warn("[movie] provider request failed:", (lastErr && lastErr.message) || "unknown");
  return { ok: false, data: null };
}

async function _fetchMynetMovieInfo(pageUrl) {
  // The old guard rejected every URL that was not on mynetnaija.ng, which meant
  // even a correct search result could never be resolved. Accept any http(s)
  // page and let the API decide.
  if (!pageUrl || !/^https?:\/\//i.test(pageUrl)) return null;
  const r = await _dcMovieJson(`${CONFIG.MYNETNAIJA_API}/info`, { url: pageUrl });
  if (!r.ok || !r.data) return null;
  return _mynetMovieInfo(r.data);
}

function _movieMime(ext = "") {
  const value = String(ext).toLowerCase().replace(/^\./, "");
  return value === "mp4" || value === "m4v" ? "video/mp4"
    : value === "mkv" ? "video/x-matroska"
    : value === "webm" ? "video/webm"
    : value === "avi" ? "video/x-msvideo"
    : "application/octet-stream";
}

function _looksLikeMovieFile(buf, contentType = "") {
  if (!Buffer.isBuffer(buf) || buf.length < 1024) return false;
  const head = buf.subarray(0, 32).toString("utf8").toLowerCase();
  if (/^<!doctype|^<html|^\s*[{[]/.test(head)) return false;
  const isMp4 = buf.length >= 12 && buf.subarray(4, 8).toString("ascii") === "ftyp";
  const isMkv = buf.length >= 4 && buf[0] === 0x1a && buf[1] === 0x45 && buf[2] === 0xdf && buf[3] === 0xa3;
  return isMp4 || isMkv || /video\/|octet-stream|application\/x-matroska|binary/i.test(contentType);
}

async function _downloadMovieToTemp(fileUrl) {
  const maxBytes = Math.floor((Number(process.env.MOVIE_MAX_MB) > 0
    ? Number(process.env.MOVIE_MAX_MB)
    : 2048) * 1024 * 1024);
  const response = await axios.get(fileUrl, {
    responseType: "stream",
    timeout: 300000,
    maxRedirects: 5,
    maxContentLength: maxBytes,
    maxBodyLength: maxBytes,
    headers: { "User-Agent": "Mozilla/5.0", Accept: "*/*" },
    validateStatus: (code) => code >= 200 && code < 400,
  });
  const contentType = String(response.headers?.["content-type"] || "").toLowerCase();
  const advertisedSize = Number(response.headers?.["content-length"] || 0);
  if (advertisedSize > maxBytes) {
    response.data?.destroy?.();
    throw new Error(`movie is larger than the ${Math.floor(maxBytes / 1024 / 1024)} MB limit`);
  }

  // Reserve space before writing. This keeps a large download from filling the
  // container and taking the WhatsApp process down with it.
  ensureDiskSpace(advertisedSize || Math.min(maxBytes, 768 * 1024 * 1024));
  const dir = await fs.promises.mkdtemp(path.join(os.tmpdir(), "mias-movie-"));
  const filePath = path.join(dir, "movie.bin");
  let bytes = 0;
  const limiter = new Transform({
    transform(chunk, encoding, callback) {
      bytes += chunk.length;
      if (bytes > maxBytes) {
        callback(new Error(`movie is larger than the ${Math.floor(maxBytes / 1024 / 1024)} MB limit`));
        return;
      }
      callback(null, chunk);
    },
  });
  try {
    await pipeline(response.data, limiter, fs.createWriteStream(filePath));
    const head = Buffer.alloc(4096);
    const handle = await fs.promises.open(filePath, "r");
    try { await handle.read(head, 0, head.length, 0); } finally { await handle.close(); }
    if (!_looksLikeMovieFile(head, contentType)) {
      throw new Error("the provider returned a web page instead of a movie file");
    }
    const isWebm = head[0] === 0x1a && head[1] === 0x45 && head[2] === 0xdf && head[3] === 0xa3;
    return { dir, filePath, bytes, contentType, isWebm };
  } catch (error) {
    await fs.promises.rm(dir, { recursive: true, force: true }).catch(() => {});
    throw error;
  }
}

async function _sendMovieDocumentFromPath(sock, jid, filePath, {
  fileName, mimetype, caption, quoted,
} = {}) {
  const content = { document: { url: filePath }, fileName, mimetype, caption };
  try {
    return await sock.sendMessage(jid, content, { quoted });
  } catch (firstError) {
    // Some Baileys forks do not accept the { url: localPath } source shape.
    // A read stream still avoids loading the complete movie into the heap.
    try {
      return await sock.sendMessage(jid, {
        document: fs.createReadStream(filePath), fileName, mimetype, caption,
      }, { quoted });
    } catch {
      throw firstError;
    }
  }
}

cmd(["movie"], { desc: "Search & download movies", category: "SEARCH" }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}movie <name>`); return; }
  await react(sock, msg, "🎬");
  const q = args.join(" ");

  // Primary source: MynetNaija search.  Keep the URLs in a short-lived,
  // per-chat picker so ".moviedl 1" downloads the exact selected result.
  try {
    const _searchRes = await _dcMovieJson(`${CONFIG.MYNETNAIJA_API}/search`, { q: q });
    const data = _searchRes.data;
    const results = _mynetMovieList(data).slice(0, 10);
    if (data?.success && results.length) {
      const jid = msg.key.remoteJid;
      const pickerState = { ts: Date.now(), results, promptKeys: [] };
      __miasMapSet(_mynetMoviePicks, jid, pickerState);
      setTimeout(() => {
        const current = __miasMapGet(_mynetMoviePicks, jid);
        if (current && Date.now() - current.ts >= 10 * 60 * 1000) __miasMapDelete(_mynetMoviePicks, jid);
      }, 10 * 60 * 1000 + 1000).unref?.();

      let text = `🎬 *MynetNaija Movie Search*\n🔎 *${q}*\n\n`;
      results.forEach((item, index) => {
        const title = item.title || item.name || "Untitled movie";
        text += `*${index + 1}.* ${title}\n`;
        text += `   📥 ${CONFIG.PREFIX}moviedl ${index + 1}\n\n`;
      });
      text += `_Reply with a number or use the download command shown above._`;
      const prompt = await sendReply(sock, msg, text);
      if (prompt?.key) pickerState.promptKeys.push(prompt.key);
      await react(sock, msg, "✅");
      return;
    }
  } catch (error) {
    console.warn("[movie] MynetNaija search failed:", error?.message || error);
  }

  // Existing fallbacks remain available if the primary API is temporarily
  // unavailable.
  let items = null;
  try {
    const r = await prexzyGet("/moviesearch", { query: q }, 20000);
    const d = r.data;
    const list = d?.data || d?.results || d?.movies || d?.result || [];
    if (r.ok && Array.isArray(list) && list.length) items = list.slice(0, 5);
  } catch {}
  if (!items) {
    try {
      const r = await prexzyGet("/search", { q, page: "1" }, 20000);
      const d = r.data;
      const list = d?.data || d?.results || d?.movies || d?.result || [];
      if (r.ok && Array.isArray(list) && list.length) items = list.slice(0, 5);
    } catch {}
  }
  if (!items) {
    try {
      const r = await prexzyGet("/search/imdb", { query: q }, 20000);
      const d = r.data?.data || r.data;
      const list = Array.isArray(d) ? d : (d?.results || d?.result || (d?.title ? [d] : []));
      if (r.ok && list.length) items = list.slice(0, 5);
    } catch {}
  }
  if (!items) {
    try {
      const { data } = await axios.get(`${CONFIG.MOVIE_API}/search/${encodeURIComponent(q)}?page=1`, { headers: { Authorization: `Bearer ${CONFIG.GIFTED_KEY}` }, timeout: 15000 });
      if (data?.results?.items?.length) items = data.results.items.slice(0, 5);
    } catch {}
  }
  if (items?.length) {
    let t = `🎬 *Movie Search: ${q}*\n\n`;
    items.forEach((m, i) => {
      const title = m.title || m.name || m.Title || "Unknown";
      const year = m.year || m.Year || m.release_date?.slice(0, 4) || "N/A";
      const rating = m.rating || m.imdbRating || m.vote_average || "N/A";
      const id = m.id || m.subjectId || m.imdbID || m.tt || "";
      t += `${i+1}. *${title}* (${year}) ⭐${rating}\n`;
      if (id) t += `   🆔 \`${id}\`\n`;
      const link = m.url || m.link || (m.imdbID ? `https://www.imdb.com/title/${m.imdbID}/` : "");
      if (link) t += `   🔗 ${link}\n`;
      t += "\n";
    });
    t += `ℹ️ Use: *${CONFIG.PREFIX}movieinfo <title>* for details\n`;
    t += `📥 Use: *${CONFIG.PREFIX}moviedetail <title>* for full info`;
    await sendReply(sock, msg, t);
  } else {
    await sendReply(sock, msg, `❌ No movies found for: *${q}*\n\n🔗 https://www.imdb.com/find?q=${encodeURIComponent(q)}`);
  }
});
cmd("movieinfo", { desc: "Get movie details", category: "SEARCH" }, async (sock, msg, args) => {
  if (!args[0]) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}movieinfo <title or ID>`); return; }
  await react(sock, msg, "🎬");
  const query = args.join(" ");
  let m = null;
  if (/^(tt\d+|\d+)$/i.test(query)) {
    try {
      const r = await prexzyGet("/detail", { id: query }, 20000);
      const d = r.data?.data || r.data;
      if (r.ok && d?.title) m = d;
    } catch {}
  }
  if (!m) {
    try {
      const r = await prexzyGet("/search/imdb", { query }, 20000);
      const d = r.data?.data || r.data;
      const list = Array.isArray(d) ? d : (d?.results || d?.result || (d?.title ? [d] : []));
      if (r.ok && list.length) m = list[0];
    } catch {}
  }
  if (!m) {
    try {
      const r = await prexzyGet("/moviedetail", { title: query }, 20000);
      const d = r.data?.data || r.data;
      if (r.ok && d?.title) m = d;
    } catch {}
  }
  if (!m) {
    try {
      const { data } = await axios.get(`${CONFIG.MOVIE_API}/info/${query}`, { headers: { Authorization: `Bearer ${CONFIG.GIFTED_KEY}` }, timeout: 15000 });
      if (data?.result) m = data.result;
    } catch {}
  }
  if (!m) { await sendReply(sock, msg, `❌ Movie not found: *${query}*\n\n🔗 https://www.imdb.com/find?q=${encodeURIComponent(query)}`); return; }
  const title = m.title || m.name || m.Title || query;
  const year = m.year || m.Year || m.release_date?.slice(0, 4) || "N/A";
  const rating = m.rating || m.imdbRating || m.vote_average || "N/A";
  const genre = m.genre || m.genres || m.Genre || "";
  const synopsis = m.synopsis || m.overview || m.plot || m.Plot || m.description || "No synopsis.";
  const posterRaw = m.poster || m.poster_path || m.thumbnail || m.image || m.Poster || "";
  const poster = posterRaw && posterRaw.startsWith("/") ? `https://image.tmdb.org/t/p/w500${posterRaw}` : posterRaw;
  const director = m.director || m.Director || (Array.isArray(m.directors) ? m.directors.join(", ") : "");
  const duration = m.duration || m.runtime || m.Runtime || "";
  let t = `🎬 *${title}* (${year})\n\n`;
  if (rating && rating !== "N/A") t += `⭐ *Rating:* ${rating}\n`;
  if (genre) t += `📌 *Genre:* ${Array.isArray(genre) ? genre.join(", ") : genre}\n`;
  if (director) t += `🎥 *Director:* ${director}\n`;
  if (duration) t += `⏱ *Duration:* ${duration}\n`;
  t += `\n📝 *Synopsis:*\n${(typeof synopsis === "string" ? synopsis : "").slice(0, 400)}...`;
  if (poster && String(poster).startsWith("http")) {
    try {
      const buf = Buffer.from((await axios.get(poster, { responseType: "arraybuffer", timeout: 15000 })).data);
      await sock.sendMessage(msg.key.remoteJid, { image: buf, caption: t }, { quoted: msg }); return;
    } catch {}
  }
  await sendReply(sock, msg, t);
});
cmd(["moviedl"], { desc: "Get movie download links — .moviedl <title or IMDB ID>", category: "DOWNLOAD" }, async (sock, msg, args) => {
  if (!args[0]) { await sendReply(sock, msg, `📥 *Movie Download*\n\nUsage: ${CONFIG.PREFIX}moviedl <title or IMDB ID>\nExample: ${CONFIG.PREFIX}moviedl Avengers Endgame`); return; }
  await react(sock, msg, "📥");
  const query = args.join(" ");
  const jid = msg.key.remoteJid;

  // MynetNaija direct-file path.  This runs before the older link providers so
  // the command sends the actual movie bytes, not an HTML download page.
  try {
    const cached = __miasMapGet(_mynetMoviePicks, jid);
    const selected = /^\d+$/.test(query) && cached && Date.now() - cached.ts <= 10 * 60 * 1000
      ? cached.results[Number(query) - 1]
      : null;
    const pageUrl = selected?.url || selected?.link || (/^https?:\/\/(?:www\.)?mynetnaija\.ng\//i.test(query) ? query : null);
    if (pageUrl) {
      if (selected && cached) await __deletePickerMessages(sock, jid, cached);
      const info = await _fetchMynetMovieInfo(pageUrl);
      if (!info) throw new Error("movie details were not returned by the API");
      const caption = [
        `🎬 *${info.title}*`,
        info.genre ? `🏷️ ${Array.isArray(info.genre) ? info.genre.join(", ") : info.genre}` : "",
        info.fileSize ? `📦 ${info.fileSize}` : "",
        info.description ? `\n📝 ${String(info.description).slice(0, 500)}` : "",
      ].filter(Boolean).join("\n");

      if (info.thumbnail && /^https?:\/\//i.test(info.thumbnail)) {
        try {
          const poster = await axios.get(info.thumbnail, {
            responseType: "arraybuffer", timeout: 15000, maxRedirects: 5,
            headers: { "User-Agent": "Mozilla/5.0" },
          });
          await sock.sendMessage(jid, { image: Buffer.from(poster.data), caption }, { quoted: msg });
        } catch {}
      }

      if (!info.fileUrl) {
        // PRECIOUS FIX: do not stop here. The movie API has the title but no
        // direct file for it, so continue into the link providers below and
        // only report the page URL if those find nothing either.
        console.warn("[moviedl] no direct file for " + info.title + " — trying link providers");
        __miasMapDelete(_mynetMoviePicks, jid);
      } else {

      const status = await sock.sendMessage(jid, { text: `⬇️ Downloading *${info.title}*...\nPlease wait while I fetch the real movie file.` }, { quoted: msg });
      const ext = String(info.fileExt || path.extname(info.fileName || "") || ".mp4").toLowerCase();
      const safeName = String(info.fileName || info.title || "movie")
        .replace(/\.[a-z0-9]{2,5}$/i, "")
        .replace(/[^\w\s.-]/g, "_")
        .trim().slice(0, 80) || "movie";
      const movieFile = await _downloadMovieToTemp(info.fileUrl);
      try {
        await _sendMovieDocumentFromPath(sock, jid, movieFile.filePath, {
        fileName: `${safeName}${ext.startsWith(".") ? ext : `.${ext}`}`,
        mimetype: _movieMime(ext),
        caption,
          quoted: msg,
        });
      } finally {
        await fs.promises.rm(movieFile.dir, { recursive: true, force: true }).catch(() => {});
      }
      try { await sock.sendMessage(jid, { delete: status.key }); } catch {}
      __miasMapDelete(_mynetMoviePicks, jid);
      await react(sock, msg, "✅");
      return;
      }
    }
  } catch (error) {
    console.warn("[moviedl] movie API direct download failed:", error?.message || error);
    // Fall through to the link providers below rather than dead-ending.
  }

  // (status message removed for speed)
  let m = null, dlLinks = [];

  // ── Step 1: Find movie metadata ──────────────────────────────────────────
  if (/^(tt\d+|\d+)$/i.test(query)) {
    try { const r = await prexzyGet("/detail", { id: query }, 20000); const d = r.data?.data || r.data; if (r.ok && d?.title) m = d; } catch {}
  }
  if (!m) {
    try { const r = await prexzyGet("/search/imdb", { query }, 20000); const d = r.data?.data || r.data; const list = Array.isArray(d) ? d : (d?.results || d?.result || (d?.title ? [d] : [])); if (r.ok && list.length) m = list[0]; } catch {}
  }
  if (!m) {
    try { const r = await prexzyGet("/moviesearch", { query }, 20000); const d = r.data?.data || r.data?.results || r.data?.movies || r.data || []; if (r.ok && Array.isArray(d) && d.length) m = d[0]; } catch {}
  }

  const title = m?.title || m?.name || m?.Title || query;
  const year = m?.year || m?.Year || m?.release_date?.slice(0,4) || "";
  const imdbId = m?.imdbID || m?.id || m?.tt || "";

  // ── Step 2: Try multiple download link sources ────────────────────────────

  // 2a: Gifted API sources
  if (!dlLinks.length) {
    try {
      let url = `${CONFIG.MOVIE_API}/sources/${imdbId || query}`;
      const { data } = await axios.get(url, { headers: { Authorization: `Bearer ${CONFIG.GIFTED_KEY}` }, timeout: 15000 });
      const sources = data?.result || data?.sources || [];
      if (Array.isArray(sources) && sources.length) sources.slice(0,5).forEach(s => dlLinks.push({ label: s.quality || s.label || "HD", url: s.url || s.link || s.source }));
    } catch {}
  }

  // 2b: YTS API — real torrent + magnet links for movies
  if (!dlLinks.length) {
    try {
      const { data } = await axios.get(`https://yts.mx/api/v2/list_movies.json?query_term=${encodeURIComponent(title)}&limit=3`, { timeout: 15000, headers: { "User-Agent": "Mozilla/5.0" } });
      const movies = data?.data?.movies || [];
      for (const mv of movies.slice(0,2)) {
        for (const t of (mv.torrents || []).slice(0,4)) {
          dlLinks.push({ label: `${t.quality} ${t.type?.toUpperCase() || "WEB"} (${t.size || "?"})`, url: t.url, magnet: `magnet:?xt=urn:btih:${t.hash}&dn=${encodeURIComponent(mv.title_english || mv.title)}` });
        }
      }
    } catch {}
  }

  // 2c: prexzy movie download
  if (!dlLinks.length) {
    try { const r = await prexzyGet("/moviedl", { title, year }, 25000); const d = r.data?.data || r.data; if (r.ok && d) { const lnk = d.url || d.download || d.link; if (lnk) dlLinks.push({ label: d.quality || "HD", url: lnk }); } } catch {}
  }

  // 2d: archive.org search (public domain movies)
  if (!dlLinks.length) {
    try {
      const { data } = await axios.get(`https://archive.org/advancedsearch.php?q=${encodeURIComponent(title)}&fl[]=identifier&fl[]=title&rows=3&page=1&output=json`, { timeout: 12000, headers: { "User-Agent": "Mozilla/5.0" } });
      const docs = data?.response?.docs || [];
      for (const doc of docs.slice(0,3)) dlLinks.push({ label: "Archive.org", url: `https://archive.org/download/${doc.identifier}` });
    } catch {}
  }

  // (edit removed for speed)

  // ── Build response ────────────────────────────────────────────────────────
  const imdbUrl = imdbId ? `https://www.imdb.com/title/${imdbId}/` : `https://www.imdb.com/find?q=${encodeURIComponent(title)}`;
  const googleDl = `https://www.google.com/search?q=${encodeURIComponent(title + " " + year + " download 1080p")}`;

  let out = `📥 *${title}${year ? ` (${year})` : ""}*\n\n`;

  // ── Try to send a direct downloadable file (small direct-stream MP4) ──────
  let sentAsDoc = false;
  for (const lnk of dlLinks.filter(l => l.url && /\.(mp4|mkv|avi|mov)(\?|$)/i.test(l.url)).slice(0,3)) {
    try {
      const head = await axios.head(lnk.url, { timeout: 10000, maxRedirects: 5 }).catch(() => null);
      const clen = parseInt(head?.headers?.["content-length"] || "0", 10);
      if (clen > 0 && clen < 180 * 1024 * 1024) { // < 180 MB — sendable as WA document
        const vidRes = await axios.get(lnk.url, { responseType: "arraybuffer", timeout: 90000, maxRedirects: 5 });
        let vidBuf = Buffer.from(vidRes.data || []);
     try {
       const _vn = require("./lib/portableVideo.cjs");
       const _nv = await _vn.normalizeVideoBuffer(vidBuf, { timeoutMs: 120000 });
       if (Buffer.isBuffer(_nv) && _nv.length > 10000) vidBuf = _nv;
     } catch (_videoNormalizeErr) { console.warn("[video] normalization unavailable:", _videoNormalizeErr?.message || _videoNormalizeErr); }
        if (vidBuf.length > 10000) {
          const safeName = title.replace(/[^a-zA-Z0-9 ]/g, "").slice(0, 60) || "movie";
          const ext = (lnk.url.match(/\.(mp4|mkv|avi|mov)/i)?.[1] || "mp4").toLowerCase();
          const mime = ext === "mkv" ? "video/x-matroska" : "video/mp4";
          // Send poster + document together
          const poster = m?.poster || m?.poster_path || m?.thumbnail || m?.image || m?.Poster || "";
          const posterUrl = poster && poster.startsWith("/") ? `https://image.tmdb.org/t/p/w500${poster}` : poster;
          const cap = `📥 *${title}${year ? ` (${year})` : ""}*\n🎞️ Quality: *${lnk.label || "HD"}*`;
          if (posterUrl?.startsWith("http")) {
            try { const pb = Buffer.from((await axios.get(posterUrl, { responseType: "arraybuffer", timeout: 12000 })).data); await sock.sendMessage(jid, { image: pb, caption: cap }, { quoted: msg }); } catch {}
          }
          await sock.sendMessage(jid, { document: vidBuf, fileName: `${safeName}.${ext}`, mimetype: mime, caption: cap }, { quoted: msg });
          await react(sock, msg, "✅");
          sentAsDoc = true;
          break;
        }
      }
    } catch {}
  }
  if (sentAsDoc) return;

  // ── Fallback: send links with CTA URL buttons ─────────────────────────────
  if (dlLinks.length) {
    out += `📌 *Download Links:*\n\n`;
    dlLinks.slice(0,6).forEach((l, i) => {
      out += `${i+1}. *${l.label || "Link"}*\n`;
      out += `   🔗 ${l.url}\n`;
      if (l.magnet) out += `   🧲 Magnet: \`${l.magnet.slice(0, 80)}...\`\n`;
      out += "\n";
    });
  } else {
    out += `⚠️ No direct download links found. Try:\n\n`;
  }
  out += `🔗 *IMDB:* ${imdbUrl}\n`;
  out += `🎬 *Watch:* https://www.justwatch.com/us/search?q=${encodeURIComponent(title)}\n\n`;
  out += ``;

  // Build CTA buttons for top links
  const ctaBtns = [];
  dlLinks.slice(0,3).forEach(l => { if (l.url?.startsWith("http")) ctaBtns.push({ type: "url", text: `📥 ${l.label || "Download"}`, url: l.url }); });
  ctaBtns.push({ type: "url", text: "🎬 JustWatch", url: `https://www.justwatch.com/us/search?q=${encodeURIComponent(title)}` });
  ctaBtns.push({ type: "url", text: "🔍 IMDB", url: imdbUrl });

  // Send with poster if available
  const poster = m?.poster || m?.poster_path || m?.thumbnail || m?.image || m?.Poster || "";
  const posterUrl = poster && poster.startsWith("/") ? `https://image.tmdb.org/t/p/w500${poster}` : poster;
  if (posterUrl && posterUrl.startsWith("http")) {
    try {
      const buf = Buffer.from((await axios.get(posterUrl, { responseType: "arraybuffer", timeout: 12000 })).data);
      try {
        await sendCTAButtons(sock, jid, msg, out, ctaBtns, `${CONFIG.BOT_NAME} • Movie Download`);
        await sock.sendMessage(jid, { image: buf, caption: `🎬 *${title}${year ? ` (${year})` : ""}*` }, { quoted: msg });
      } catch {
        await sock.sendMessage(jid, { image: buf, caption: out }, { quoted: msg });
      }
      await react(sock, msg, dlLinks.length ? "✅" : "📥");
      return;
    } catch {}
  }
  try {
    await sendCTAButtons(sock, jid, msg, out, ctaBtns, `${CONFIG.BOT_NAME} • Movie Download`);
  } catch {
    await sendReply(sock, msg, out);
  }
  await react(sock, msg, dlLinks.length ? "✅" : "📥");
});
// ═══════════════════════════════════════════════════════════════════════════════
