cmd(["ftball", "football"], { desc: "Football/soccer news & scores", category: "SEARCH" }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}ftball <team/query>`); return; }
  await react(sock, msg, "⚽");
  const q = args.join(" ");
  let results = [];
  const ftApis = [
    async () => {
      const { data } = await axios.get(`${CONFIG.GIFTED_API}/api/search/google?apikey=${CONFIG.GIFTED_KEY}&q=${encodeURIComponent("football " + q)}`, { timeout: 12000 });
      return data?.result || data?.results || [];
    },
    async () => {
      const { data } = await axios.get(`https://api.siputzx.my.id/api/s/google?q=${encodeURIComponent("football " + q)}`, { timeout: 12000 });
      return data?.data || data?.result || [];
    },
    async () => {
      const r = await prexzyGet("/sports/football", { q }, 12000);
      const d = r.data;
      const list = d?.data || d?.results || d?.matches || [];
      return Array.isArray(list) ? list.map(m => ({ title: m.title || `${m.home || ""} vs ${m.away || ""}`, description: m.score || m.result || "", url: m.url || "" })) : [];
    },
    async () => {
      const { data } = await axios.get(`https://api.duckduckgo.com/?q=${encodeURIComponent("football " + q)}&format=json&no_html=1`, { timeout: 10000 });
      const items = [];
      if (data.Abstract) items.push({ title: `Football: ${q}`, description: data.Abstract, url: data.AbstractURL || "" });
      (data.RelatedTopics || []).slice(0, 4).forEach(r => { if (r.Text) items.push({ title: r.Text.slice(0, 80), description: "", url: r.FirstURL || "" }); });
      return items;
    },
  ];
  for (const tryFn of ftApis) {
    try { const r = await tryFn(); if (Array.isArray(r) && r.length) { results = r; break; } } catch {}
  }
  if (results.length) {
    let txt = `⚽ *Football: ${q}*\n\n`;
    results.slice(0, 5).forEach((r, i) => { txt += `${i + 1}. *${r.title || ""}*\n${r.description ? r.description.slice(0, 100) + "\n" : ""}${r.url ? `🔗 ${r.url}\n` : ""}\n`; });
    txt += ``;
    await sendReply(sock, msg, txt);
  } else {
    await sendReply(sock, msg, `⚽ *Football: ${q}*\n\n🔗 https://www.google.com/search?q=${encodeURIComponent("football " + q)}`);
  }
});

