cmd("repeat", { desc: "Repeat text — sends each word separately, one by one", category: "FUN" }, async (sock, msg, args) => {
  const n = Math.min(parseInt(args[0]) || 3, 15);
  const text = args.slice(1).join(" ");
  // Use .trim() check so whitespace-only input is caught (prevents empty message bubbles)
  if (!text.trim()) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}repeat <times> <text>\n\nExample: ${CONFIG.PREFIX}repeat 5 Hello!`); return; }
  // .filter(Boolean) removes any empty strings that "".split() produces
  const words = text.trim().split(/\s+/).filter(Boolean);
  if (!words.length) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}repeat <times> <text>`); return; }
  const jid = msg.key.remoteJid;
  for (let i = 0; i < n; i++) {
    for (const word of words) {
      await sock.sendMessage(jid, { text: word });
      await new Promise(r => setTimeout(r, 350));
    }
  }
  await react(sock, msg, "✅");
});
