cmd("vcf", { desc: "Save group contacts as VCF file", category: "INFO" }, async (sock, msg, args) => {
  await react(sock, msg, "📇");
  try {
    if (isGroup(msg)) {
      // Save all group members as VCF
      const meta = await sock.groupMetadata(msg.key.remoteJid);
      // Update lid→jid mappings from fresh metadata (atassa fix for @lid numbers)
      updateLidMappingsFromMeta(meta);
      let vcfContent = "";
      let savedCount = 0;
      // ── pre-batch: resolve push-names for all members at once ──
      try {
        const _batchNums = [];
        for (const p of meta.participants) {
          const _r = resolveLid(p.id);
          const _n = p.pn ? p.pn.replace(/\D/g,"") : _cleanNum(_r);
          if (_n && _n.length >= 7 && !pushNameCache.has(_n)) _batchNums.push(_n + "@s.whatsapp.net");
        }
        if (_batchNums.length) {
          const _wr = await sock.onWhatsApp(..._batchNums).catch(() => []);
          for (const w of (_wr || [])) {
            if (w?.jid && w?.notify && !/^\d+$/.test(w.notify) && !w.notify.startsWith("+"))
              pushNameCache.set(_cleanNum(w.jid), w.notify);
          }
        }
      } catch {}
      for (const p of meta.participants) {
        // p.pn = real phone number (WhatsApp provides this in newer versions)
        // Fall back to resolving @lid, then _cleanNum
        const resolvedId = resolveLid(p.id);
        const num = p.pn ? p.pn.replace(/\D/g, "") : _cleanNum(resolvedId);
        if (!num || num.length < 6 || num === resolvedId.split("@")[0]) {
          // num matches lid digits exactly — skip @lid-only entries with no real phone
          if (resolvedId.endsWith("@lid") && !p.pn) continue;
        }
        if (!num || num.length < 5) continue;
        let name = p.notify || p.verifiedName || pushNameCache.get(num) || "";
        if (!name || !name.trim()) {
          try { name = await getDisplayName(sock, p.id, msg.key.remoteJid); } catch {}
        }
        // Cache any found name for future use
        if (name && name.trim() && !/^\d+$/.test(name.trim()) && !name.startsWith("+")) {
          pushNameCache.set(num, name.trim());
        }
        // Try onWhatsApp as a last resort name source
        if (!name || !name.trim() || /^\d+$/.test(name.trim()) || name.startsWith("+") || name.includes("@")) {
          try {
            const _wa = await sock.onWhatsApp(num + "@s.whatsapp.net").then(r => (r || [])[0]).catch(() => null);
            if (_wa?.notify && !/^\d+$/.test(_wa.notify) && !_wa.notify.startsWith("+")) name = _wa.notify;
            else if (_wa?.verifiedName) name = _wa.verifiedName;
          } catch {}
        }
        // Final fallback: use pushName format if still no name
        if (!name || !name.trim() || /^\d+$/.test(name.trim()) || name.startsWith("+") || name.includes("@")) {
          name = "+" + num;
        }
        // ── v4.9.4 EXTRA NAME SOURCES (vcf "real names" fix) ────────
        // 1) sock.contactStore (some Baileys forks expose this)
        if (!name || !name.trim() || /^\d+$/.test(name.trim()) || name.startsWith("+") || name.includes("@")) {
          try {
            const cs = sock.contactStore;
            const cand = (await cs?.getContact?.(num + "@s.whatsapp.net"))
                      || cs?.contacts?.[num + "@s.whatsapp.net"]
                      || cs?.contacts?.[resolvedId];
            const cn = cand?.name || cand?.notify || cand?.verifiedName || "";
            if (cn && !/^\d+$/.test(cn) && !cn.startsWith("+")) name = cn;
          } catch {}
        }
        // 2) Scan recent stored messages for a past _pushName from
        //    this participant — works even if they never spoke since
        //    the bot started but appeared in another group convo.
        if (!name || !name.trim() || /^\d+$/.test(name.trim()) || name.startsWith("+") || name.includes("@")) {
          try {
            const wantA = num + "@s.whatsapp.net";
            const wantB = String(p.id || "");
            for (const stored of _msgRetryStore.values()) {
              const part = stored?._participant || "";
              if (part === wantA || part === wantB) {
                const pn = stored._pushName;
                if (pn && pn.trim() && !/^\d+$/.test(pn) && !pn.startsWith("+") && !pn.includes("@")) {
                  name = pn.trim();
                  break;
                }
              }
            }
          } catch {}
        }
        // 3) _contactsStore direct (mirrors pushNameCache, but cheap)
        if (!name || !name.trim() || /^\d+$/.test(name.trim()) || name.startsWith("+") || name.includes("@")) {
          const cn2 = _contactsStore.get(num);
          if (cn2 && cn2.trim()) name = cn2.trim();
        }
        // Persist whatever we just resolved so later runs are faster.
        if (name && name.trim() && !/^\d+$/.test(name.trim()) && !name.startsWith("+") && !name.includes("@")) {
          try { saveContact(num, name.trim()); } catch {}
        }
        // Final fallback: use formatted number as name
        if (!name || !name.trim() || /^\d+$/.test(name.trim()) || name.startsWith("+") || name.includes("@")) {
          name = "+" + num;
        }
        saveContact(num, name);
        vcfContent += `BEGIN:VCARD\nVERSION:3.0\nFN:${name} 🥀\nTEL;type=CELL;type=VOICE;waid=${num}:+${num}\nEND:VCARD\n`;
        savedCount++;
      }
      const buf = Buffer.from(vcfContent, "utf8");
      await sock.sendMessage(msg.key.remoteJid, {
        document: buf, fileName: `${meta.subject.replace(/[^a-zA-Z0-9]/g, "_")}_contacts.vcf`,
        mimetype: "text/vcard"
      }, { quoted: msg });
      await sendReply(sock, msg, `📇 Saved *${savedCount}* contacts as VCF!\n_(${meta.participants.length} total members, lids resolved to real numbers)_`);
    } else {
      // Single contact VCF
      const mentions = msg.message?.extendedTextMessage?.contextInfo?.mentionedJid || [];
      let targetJid, targetNum;
      if (mentions.length) { targetJid = toStandardJid(mentions[0]); targetNum = _cleanNum(mentions[0]); }
      else if (args[0]) { targetNum = args[0].replace(/\D/g, ""); targetJid = targetNum + "@s.whatsapp.net"; }
      else { targetJid = toStandardJid(getSender(msg)); targetNum = _cleanNum(getSender(msg)); }
      const name = await getDisplayName(sock, targetJid, isGroup(msg) ? msg.key.remoteJid : null);
      const cleanNum = _cleanNum(targetJid);
      const vcard = `BEGIN:VCARD\nVERSION:3.0\nFN:${name} 🥀\nTEL;type=CELL;type=VOICE;waid=${cleanNum}:+${cleanNum}\nEND:VCARD`;
      await sock.sendMessage(msg.key.remoteJid, { contacts: { displayName: name + " 🥀", contacts: [{ vcard }] } }, { quoted: msg });
      await react(sock, msg, "✅");
    }
  } catch (e) { await sendReply(sock, msg, `❌ VCF error: ${e.message}`); }
});
cmd(["device","getdevice","checkdevice"], { desc: "Check device/platform of a user — reply, @mention, or .device <number>", category: "INFO" }, async (sock, msg, args) => {
  const ctx = getContextInfo(msg);
  let targetJid = toStandardJid(resolveLid(ctx?.mentionedJid?.[0] || ctx?.participant || ""));
  if (!targetJid && args[0]) {
    const _num = args[0].replace(/[^0-9]/g, "");
    if (_num.length >= 7) targetJid = _num + "@s.whatsapp.net";
  }
  if (!targetJid) targetJid = toStandardJid(resolveLid(getSender(msg) || ""));
  const id = String(ctx?.stanzaId || msg.key.id || "");
  // Use Baileys' exact message-id classifier here. Do not add guesses from
  // prefixes, linked-device suffixes, country codes, or platform marketing
  // labels: the command should report only the real detected device.
  const detected = getBaileysDevice ? String(getBaileysDevice(id) || "").toLowerCase() : "unknown";
  const device = ["android", "ios", "web", "desktop"].includes(detected) ? detected : "unknown";
  const num = _cleanNum(targetJid);
  let name = num;
  try { name = await getDisplayName(sock, targetJid, isGroup(msg) ? msg.key.remoteJid : null); } catch {}
  const username = String(name || num || "user").trim();
  await sock.sendMessage(msg.key.remoteJid, {
    text: `${username} is ${device} user`,
    mentions: targetJid ? [targetJid] : [],
  }, { quoted: msg });
});
// ── v5.4.0 — isonline: check if a WhatsApp user is currently online ──────────
cmd(["isonline","online","checkstatus","onlinecheck"], { desc: "Check if a user is currently online — .isonline @mention or .isonline <number>", category: "INFO" }, async (sock, msg, args) => {
  await react(sock, msg, "🔍");
  const ctx = msg.message?.extendedTextMessage?.contextInfo;
  const mentioned = ctx?.mentionedJid?.[0] || ctx?.participant;
  let targetJid;
  if (mentioned) {
    targetJid = toStandardJid(resolveLid(mentioned));
  } else if (args[0]) {
    const _num = args[0].replace(/[^0-9]/g, "");
    if (_num.length < 7) { await sendReply(sock, msg, `Usage: *${CONFIG.PREFIX}isonline @mention*\nOr: *${CONFIG.PREFIX}isonline <number>*\n\nExample: *${CONFIG.PREFIX}isonline 2349068551055*`); return; }
    targetJid = _num + "@s.whatsapp.net";
  } else {
    await sendReply(sock, msg, `Usage: *${CONFIG.PREFIX}isonline @mention*\nOr: *${CONFIG.PREFIX}isonline <number>*`); return;
  }
  const num = _cleanNum(targetJid);
  let displayName = num;
  try { displayName = await getDisplayName(sock, targetJid, isGroup(msg) ? msg.key.remoteJid : null); } catch {}

  // Verify registered
  let isRegistered = false;
  try { const [_r] = await sock.onWhatsApp(targetJid); isRegistered = !!_r?.exists; } catch {}
  if (!isRegistered) {
    await sendReply(sock, msg, `❌ +${num} is *not registered* on WhatsApp.`);
    return;
  }

  // Fetch bio / about
  let waBio = null;
  try { const s = await sock.fetchStatus(targetJid); waBio = s?.status || null; } catch {}

  // Subscribe to presence and wait up to 5s
  let presenceStatus = "unknown";
  let lastSeenMs = null;
  try {
    if (typeof sock.presenceSubscribe === "function") await sock.presenceSubscribe(targetJid);
    const presResult = await new Promise((resolve) => {
      let _resolved = false;
      const _done = (val) => { if (!_resolved) { _resolved = true; sock.ev.off("presence.update", _h); resolve(val); } };
      const _h = (upd) => {
        if (String(upd?.id || upd?.jid || "") === targetJid || (upd?.presences && upd.presences[targetJid])) {
          clearTimeout(_t); _done(upd);
        }
      };
      const _t = setTimeout(() => _done(null), 5000);
      sock.ev.on("presence.update", _h);
    });
    if (presResult) {
      const pe = (presResult.presences || {})[targetJid] || Object.values(presResult.presences || {})[0] || {};
      presenceStatus = pe.lastKnownPresence || "unavailable";
      if (pe.lastSeen) lastSeenMs = pe.lastSeen * 1000;
    } else {
      presenceStatus = "private";
    }
  } catch { presenceStatus = "private"; }

  const statusMap = {
    available:   "🟢 *ONLINE RIGHT NOW*",
    composing:   "🟡 *ONLINE* — ✍️ Typing...",
    recording:   "🟡 *ONLINE* — 🎙️ Recording voice",
    unavailable: "🔴 *OFFLINE*",
    paused:      "🔴 *OFFLINE*",
    private:     "🔒 Privacy ON — status hidden",
    unknown:     "❓ Could not determine",
  };
  const statusIcon   = { available: "🟢", composing: "🟡", recording: "🟡", unavailable: "🔴", paused: "🔴", private: "🔒", unknown: "❓" };
  const isOnlineNow  = ["available","composing","recording"].includes(presenceStatus);
  const stText = statusMap[presenceStatus] || "❓ Unknown";
  const stIcon = statusIcon[presenceStatus] || "❓";

  let lastSeenText = "";
  if (lastSeenMs) {
    const diff = Date.now() - lastSeenMs;
    const _sm = Math.floor(diff / 60000), _sh = Math.floor(diff / 3600000), _sd = Math.floor(diff / 86400000);
    lastSeenText = _sd > 0 ? `${_sd}d ${Math.floor((diff % 86400000) / 3600000)}h ago` : _sh > 0 ? `${_sh}h ${_sm % 60}m ago` : _sm > 0 ? `${_sm}m ago` : "Just now";
  }

  const pp = await sock.profilePictureUrl(targetJid, "preview").catch(() => null);
  const country = _countryFromNumber(num);
  const _liveBar = isOnlineNow ? "▰▰▰▰▰ LIVE ▰▰▰▰▰" : "▱▱▱▱▱ OFFLINE ▱▱▱▱▱";

  const out =
`${stIcon} *WhatsApp Status Check*
━━━━━━━━━━━━━━━━━━━━

👤 *Name:* ${displayName}
📱 *Number:* +${num}
${country.flag} *Country:* ${country.name}

${_liveBar}
📶 ${stText}
${!isOnlineNow && lastSeenText ? `🕐 *Last Seen:* ${lastSeenText}` : isOnlineNow ? `🕐 *Checked:* Just now ⚡` : "🕐 *Last Seen:* Unknown"}
${waBio ? `
💬 *About:* _${waBio.slice(0, 120)}_` : ""}
🖼️ *Profile Pic:* ${pp ? "Public ✅" : "Private 🔒"}
🔗 wa.me/${num}

_Presence checked at ${new Date().toLocaleTimeString("en-GB")}_`;

  if (pp) {
    try {
      const _buf = Buffer.from((await axios.get(pp, { responseType: "arraybuffer", timeout: 10000 })).data);
      await sock.sendMessage(msg.key.remoteJid, { image: _buf, caption: out, mentions: [targetJid] }, { quoted: msg });
      await react(sock, msg, isOnlineNow ? "🟢" : "🔴"); return;
    } catch {}
  }
  await sendReply(sock, msg, out);
  await react(sock, msg, isOnlineNow ? "🟢" : "🔴");
});


// ── .check <number> — quick online / last seen checker ──────────────────────
cmd(["check","checkuser","chk"], {
  desc: "Check if someone is online or their last seen — .check <number>",
  category: "INFO"
}, async (sock, msg, args) => {
  await react(sock, msg, "🔍");

  const ctx = msg.message?.extendedTextMessage?.contextInfo
            || msg.message?.imageMessage?.contextInfo
            || msg.message?.videoMessage?.contextInfo
            || null;
  const mentioned = ctx?.mentionedJid?.[0] || ctx?.participant;
  let targetJid;

  if (mentioned) {
    targetJid = toStandardJid(resolveLid(mentioned));
  } else if (args[0]) {
    const _num = String(args[0]).replace(/[^0-9]/g, "");
    if (_num.length < 7) {
      await sendReply(sock, msg,
        `📱 *Check User*\n\nUsage: *${CONFIG.PREFIX}check <number>*\n\nExample:\n*${CONFIG.PREFIX}check 2349068551055*\n\nOr tag: *${CONFIG.PREFIX}check @user*`
      );
      return;
    }
    targetJid = _num + "@s.whatsapp.net";
  } else {
    await sendReply(sock, msg,
      `📱 *Check User*\n\nUsage: *${CONFIG.PREFIX}check <number>*\n\nExample:\n*${CONFIG.PREFIX}check 2349068551055*`
    );
    return;
  }

  const num = _cleanNum(targetJid);

  let isRegistered = false;
  try { const [_r] = await sock.onWhatsApp(targetJid); isRegistered = !!_r?.exists; } catch {}
  if (!isRegistered) {
    await react(sock, msg, "❌");
    await sendReply(sock, msg, `❌ *+${num}* is not registered on WhatsApp.`);
    return;
  }

  let displayName = num;
  let waBio = null;
  try { displayName = await getDisplayName(sock, targetJid, msg.key.remoteJid?.endsWith("@g.us") ? msg.key.remoteJid : null); } catch {}
  try { const _s = await sock.fetchStatus(targetJid); waBio = _s?.status || null; } catch {}

  let presenceStatus = "unknown";
  let lastSeenMs = null;
  try {
    if (typeof sock.presenceSubscribe === "function") await sock.presenceSubscribe(targetJid);
    const presResult = await new Promise((resolve) => {
      let _resolved = false;
      const _done = (val) => { if (!_resolved) { _resolved = true; sock.ev.off("presence.update", _h); resolve(val); } };
      const _h = (upd) => {
        const hasTarget = String(upd?.id || upd?.jid || "") === targetJid
          || (upd?.presences && upd.presences[targetJid]);
        if (hasTarget) { clearTimeout(_t); _done(upd); }
      };
      const _t = setTimeout(() => _done(null), 6000);
      sock.ev.on("presence.update", _h);
    });
    if (presResult) {
      const pe = (presResult.presences || {})[targetJid] || Object.values(presResult.presences || {})[0] || {};
      presenceStatus = pe.lastKnownPresence || "unavailable";
      if (pe.lastSeen) lastSeenMs = pe.lastSeen * 1000;
    } else {
      presenceStatus = "private";
    }
  } catch { presenceStatus = "private"; }

  let lastSeenText = "Unknown";
  if (lastSeenMs) {
    const diff = Date.now() - lastSeenMs;
    const _sm = Math.floor(diff / 60000), _sh = Math.floor(diff / 3600000), _sd = Math.floor(diff / 86400000);
    if (_sd > 0) lastSeenText = `${_sd} day${_sd > 1 ? "s" : ""} ${Math.floor((diff % 86400000) / 3600000)}h ago`;
    else if (_sh > 0) lastSeenText = `${_sh}h ${_sm % 60}m ago`;
    else if (_sm > 0) lastSeenText = `${_sm} min${_sm > 1 ? "s" : ""} ago`;
    else lastSeenText = "Just now";
  }

  const isOnline   = ["available","composing","recording"].includes(presenceStatus);
  const isTyping   = presenceStatus === "composing";
  const isRecording= presenceStatus === "recording";
  const country    = _countryFromNumber(num);

  let statusLine;
  if (isTyping)        statusLine = "🟡 *ONLINE* — ✍️ Currently typing...";
  else if (isRecording)statusLine = "🟡 *ONLINE* — 🎙️ Currently recording...";
  else if (isOnline)   statusLine = "🟢 *ONLINE RIGHT NOW*";
  else if (presenceStatus === "unavailable" || presenceStatus === "paused") statusLine = "🔴 *OFFLINE*";
  else if (presenceStatus === "private")   statusLine = "🔒 *Last seen: Hidden* (privacy on)";
  else                 statusLine = "❓ Status unknown";

  const pp = await sock.profilePictureUrl(targetJid, "preview").catch(() => null);

  const out =
`📱 *User Check*
━━━━━━━━━━━━━━━━━━━━

👤 *Name:* ${displayName}
🔢 *Number:* +${num}
${country.flag} *Country:* ${country.name}

${isOnline ? "▰▰▰▰▰ LIVE ▰▰▰▰▰" : "▱▱▱▱▱ OFFLINE ▱▱▱▱▱"}
📶 ${statusLine}
🕐 *Last Seen:* ${isOnline ? "Active right now ⚡" : lastSeenText}
${waBio ? `\n💬 *About:* _${waBio.slice(0, 120)}_` : ""}
🖼️ *Profile Pic:* ${pp ? "Public ✅" : "Private 🔒"}
🔗 wa.me/${num}

_Checked at ${new Date().toLocaleTimeString("en-GB")}_`;

  try {
    if (pp) {
      const _buf = Buffer.from(
        (await axios.get(pp, { responseType: "arraybuffer", timeout: 10000 })).data
      );
      await sock.sendMessage(msg.key.remoteJid, { image: _buf, caption: out, mentions: [targetJid] }, { quoted: msg });
    } else {
      await sendReply(sock, msg, out);
    }
  } catch { await sendReply(sock, msg, out); }

  await react(sock, msg, isOnline ? "🟢" : "🔴");
});

// ── v4.9.4 ── tiny country-prefix table for whois enrichment.
// Just the ones common in this bot's audience; add more as needed.
function _countryFromNumber(num) {
  const n = String(num || "").replace(/\D/g, "");
  if (!n) return { name: "Unknown", flag: "🌐" };
  const TBL = [
    ["234","Nigeria","🇳🇬"], ["233","Ghana","🇬🇭"], ["254","Kenya","🇰🇪"],
    ["27","South Africa","🇿🇦"], ["256","Uganda","🇺🇬"], ["255","Tanzania","🇹🇿"],
    ["260","Zambia","🇿🇲"], ["263","Zimbabwe","🇿🇼"], ["237","Cameroon","🇨🇲"],
    ["1","USA / Canada","🇺🇸"], ["44","United Kingdom","🇬🇧"], ["91","India","🇮🇳"],
    ["92","Pakistan","🇵🇰"], ["62","Indonesia","🇮🇩"], ["60","Malaysia","🇲🇾"],
    ["63","Philippines","🇵🇭"], ["66","Thailand","🇹🇭"], ["55","Brazil","🇧🇷"],
    ["52","Mexico","🇲🇽"], ["971","UAE","🇦🇪"], ["966","Saudi Arabia","🇸🇦"],
    ["20","Egypt","🇪🇬"], ["212","Morocco","🇲🇦"], ["33","France","🇫🇷"],
    ["49","Germany","🇩🇪"], ["39","Italy","🇮🇹"], ["34","Spain","🇪🇸"],
    ["7","Russia / Kazakhstan","🇷🇺"], ["86","China","🇨🇳"], ["81","Japan","🇯🇵"],
    ["82","South Korea","🇰🇷"], ["61","Australia","🇦🇺"], ["64","New Zealand","🇳🇿"],
  ];
  // Check 3-digit prefixes first, then 2, then 1.
  for (const len of [3, 2, 1]) {
    const p = n.slice(0, len);
    const hit = TBL.find(t => t[0] === p);
    if (hit) return { name: hit[1], flag: hit[2] };
  }
  return { name: "Unknown", flag: "🌐" };
}

cmd("whois", { desc: "Full user info", category: "INFO" }, async (sock, msg, args) => {
  await react(sock, msg, "🔍");
  const ctx = msg.message?.extendedTextMessage?.contextInfo
    || msg.message?.imageMessage?.contextInfo
    || msg.message?.videoMessage?.contextInfo;
  let rawTarget = ctx?.mentionedJid?.[0] || ctx?.participant || "";
  // Explicit target number wins (e.g. .whois 2348152433778)
  if (!rawTarget && args?.length) {
    const n = String(args.join(" ")).replace(/[^0-9]/g, "");
    if (n.length >= 7) rawTarget = n + "@s.whatsapp.net";
  }
  if (!rawTarget && !isGroup(msg)) {
    const chatJid = msg.key.remoteJid || "";
    const botNum = _cleanNum(_botJid || sock.user?.id || "");
    // In a DM: target the chat partner, EXCEPT when chatting with the bot itself
    if (!msg.key.fromMe || !botNum || _cleanNum(chatJid) === botNum) {
      rawTarget = getSender(msg) || chatJid;
    } else {
      rawTarget = chatJid;
    }
  }
  if (!rawTarget) rawTarget = getSender(msg);

  let target = toStandardJid(rawTarget);
  // v2.1: resolve @lid → real number so we show the NAME, not the LID
  try { if (/@lid$/.test(String(rawTarget))) target = toStandardJid(resolveLid(rawTarget)); } catch {}
  const num = _cleanNum(target);

  // ── v4.9.4 ── pull pp + WA-existence + business profile in parallel
  let pp = null, exists = false, isBusiness = false, businessProfile = null;
  await Promise.all([
    (async () => { try { pp = await sock.profilePictureUrl(target, "image"); } catch {} })(),
    (async () => { try { const [r] = await sock.onWhatsApp(target); exists = !!r?.exists; } catch {} })(),
    (async () => { try { businessProfile = await sock.getBusinessProfile?.(target).catch(() => null); if (businessProfile) isBusiness = true; } catch {} })(),
  ]);

  let waBio = "Not available";
  let bioUpdated = "";
  try {
    const statusInfo = await sock.fetchStatus(target).catch(() => sock.fetchStatus(num + "@s.whatsapp.net").catch(() => null));
    if (statusInfo?.status && String(statusInfo.status).trim()) {
      waBio = String(statusInfo.status).trim();
    }
    const setAt = statusInfo?.setAt;
    const ts = setAt instanceof Date
      ? setAt.getTime()
      : typeof setAt === "number"
        ? (setAt > 1e12 ? setAt : setAt * 1000)
        : null;
    if (ts) bioUpdated = new Date(ts).toLocaleDateString("en-NG");
  } catch {}

  const customBio = getUserCustomBio(target) || getUserCustomBio(rawTarget) || waBio || "Not set";
  let name = await getDisplayName(sock, target, isGroup(msg) ? msg.key.remoteJid : null).catch(()=>null);
  if (!name || /^\+?[0-9]+$/.test(String(name))) { try { name = (await sock.getName?.(target)) || name || "+" + num; } catch {} }

  const msgId = String(ctx?.stanzaId || msg.key.id || "");
  const device = humanizeDeviceName(msgId, target);

  const isAdm = isGroup(msg) ? await isGroupAdmin(sock, msg.key.remoteJid, target) : false;
  const country = _countryFromNumber(num);
  const isOwnerFlag = String(num) === String(CONFIG.OWNER_NUMBER);
  const isYou       = toStandardJid(getSender(msg)) === target;

  const text = `👤 *WHO IS — @${num}*

╭─────────────────────
│ 📛 *Name:* ${name}${isOwnerFlag ? "  👑" : ""}${isYou ? "  (you)" : ""}
│ 📱 *Number:* +${num}
│ ${country.flag} *Country:* ${country.name}
│ ✅ *On WhatsApp:* ${exists ? "Yes" : "Unknown"}
│ 💼 *Business Acct:* ${isBusiness ? "Yes" : "No"}${isBusiness && businessProfile?.description ? `
│ 📃 *Bus. Desc:* _${String(businessProfile.description).slice(0,80)}_` : ""}
│ 📝 *WhatsApp Bio:* _${waBio}_${bioUpdated ? `
│ 📅 *Bio Updated:* ${bioUpdated}` : ""}
│ ✨ *User Bio:* _${customBio}_
│ 📲 *Device:* ${device}
│ 👑 *Admin:* ${isAdm ? "Yes ✅" : "No"}
│ 🖼️ *Profile Pic:* ${pp ? "Public ✅" : "Private / None"}
│ 🔗 *Link:* wa.me/${num}
╰─────────────────────`;

  if (pp) {
    const buf = await axios.get(pp, { responseType: "arraybuffer", timeout: 10000 });
    await sock.sendMessage(msg.key.remoteJid, { image: Buffer.from(buf.data), caption: text, mentions: [target] }, { quoted: msg });
  } else {
    await sock.sendMessage(msg.key.remoteJid, { text, mentions: [target] }, { quoted: msg });
  }
});
cmd(["getpp","getdp","dp","pfp2"], { desc: "Get profile picture — .getpp @mention | .getpp <number> | reply to message", category: "INFO" }, async (sock, msg, args) => {
  await react(sock, msg, "📷");
  const chatJid = msg.key.remoteJid || "";
  const ctx = msg.message?.extendedTextMessage?.contextInfo;
  const mentioned = ctx?.mentionedJid?.[0] || ctx?.participant;
  let target;

  // Priority 1: @mention or reply quote
  if (mentioned) {
    target = toStandardJid(resolveLid(mentioned));
  }
  // Priority 2: phone number in args (e.g. .getpp 2349068551055)
  else if (args[0] && /^[0-9]/.test(args[0].replace(/[^0-9]/g, ""))) {
    const _n = args[0].replace(/[^0-9]/g, "");
    if (_n.length >= 7) target = _n + "@s.whatsapp.net";
  }
  // Priority 3: in DM — use the chat partner (not self)
  else if (!isGroup(msg) && !msg.key.fromMe) {
    target = toStandardJid(resolveLid(chatJid));
  }
  // Priority 4: self
  else {
    const resolved = await resolveCommandTarget(sock, msg, []);
    const fallback = toStandardJid(resolveLid(getSender(msg) || ""));
    target = toStandardJid(resolveLid(resolved?.targetJid || fallback || ""));
  }

  if (!target) { await sendReply(sock, msg, `❌ Could not resolve target.\n\nUsage: *${CONFIG.PREFIX}getpp @mention* | *${CONFIG.PREFIX}getpp <number>* | reply to a message`); return; }

  try {
    const num = _cleanNum(target);
    let targetName = null;
    try { targetName = await getDisplayName(sock, target, isGroup(msg) ? chatJid : null); } catch {}

    // Try HD first, then preview
    let pp = null, isHd = false;
    try { pp = await sock.profilePictureUrl(target, "image"); isHd = true; } catch {}
    if (!pp) { try { pp = await sock.profilePictureUrl(target, "preview"); } catch {} }

    if (!pp) {
      await sendReply(sock, msg, `❌ No profile picture for +${num} — it's either *private* or not set.`);
      return;
    }

    const buf = await axios.get(pp, { responseType: "arraybuffer", timeout: 15000 });
    const sizeKb = Math.round((buf.data?.length || 0) / 1024);
    const meaningful = isMeaningfulName(targetName || "");
    const label = meaningful ? targetName : `@${num}`;
    const mentions = meaningful ? [] : [target];
    const country = _countryFromNumber(num);

    // Send image only — no caption text
    await sock.sendMessage(chatJid, { image: Buffer.from(buf.data) }, { quoted: msg });
    await react(sock, msg, "✅");
  } catch (e) {
    await sendReply(sock, msg, `❌ Profile picture fetch failed.\n_${e?.message || e}_`);
  }
});
