cmd("calc", { desc: "Calculator — .calc <expression>", category: "TOOLS" }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}calc <expression>`); return; }
  try {
    const expr = args.join(" ").replace(/[^0-9+\-*/.() ]/g, "");
    const result = Function('"use strict"; return (' + expr + ')')();
    await sendReply(sock, msg, `🧮 *Calculator*\n\n${expr} = *${result}*`);
  } catch { await sendReply(sock, msg, "❌ Invalid expression."); }
});

// ── v4.9.4 UPGRADE ─────────────────────────────────────────────────
// Calendar now renders as an actual IMAGE (PNG) instead of monospace
// text. We build a self-contained SVG (no external fonts), upload it
// to catbox.moe, then ask wsrv.nl to convert it to PNG before sending
// to WhatsApp. The text calendar is kept as the caption so the
// command keeps working even when the image pipeline fails.
cmd("calendar", { desc: "Show calendar for current month (image)", category: "TOOLS" }, async (sock, msg, args) => {
  const now = new Date();
  const year = parseInt(args[0]) || now.getFullYear();
  const month = parseInt(args[1]) || now.getMonth() + 1;
  const monthNames = ["January","February","March","April","May","June","July","August","September","October","November","December"];
  const dayNames = ["Su","Mo","Tu","We","Th","Fr","Sa"];
  const firstDay = new Date(year, month - 1, 1).getDay();
  const daysInMonth = new Date(year, month, 0).getDate();
  const today = now.getDate();
  const isCurrentMonth = year === now.getFullYear() && month === now.getMonth() + 1;

  // 1) Build a nice text caption (also serves as fallback)
  let cal = `📅 *${monthNames[month-1]} ${year}*\n\n`;
  cal += dayNames.join("  ") + "\n";
  cal += "──────────────\n";
  let line = "   ".repeat(firstDay);
  for (let d = 1; d <= daysInMonth; d++) {
    const dayStr = d < 10 ? ` ${d}` : `${d}`;
    if (isCurrentMonth && d === today) line += `[${dayStr}]`;
    else line += ` ${dayStr} `;
    if ((firstDay + d) % 7 === 0) { cal += line + "\n"; line = ""; }
  }
  if (line) cal += line + "\n";
  if (isCurrentMonth) cal += `\n📍 Today: *${today} ${monthNames[month-1]} ${year}*\n`;
  const ngTime = now.toLocaleString("en-NG", { timeZone: "Africa/Lagos", hour12: true });
  cal += `🕐 Nigeria Time: ${ngTime}`;

  // 2) Build the SVG calendar (vector, scales perfectly)
  const W = 720, H = 800;
  const PAD = 40, HEADER_H = 130;
  const GRID_TOP = PAD + HEADER_H + 20;
  const COLS = 7;
  const cellW = (W - PAD * 2) / COLS;
  const cellH = 78;
  const rows = Math.ceil((firstDay + daysInMonth) / 7);
  const totalH = GRID_TOP + 50 + rows * cellH + 80;
  const escXml = (s) => String(s).replace(/[&<>"']/g, c => ({ "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;" }[c]));
  let svg = `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${totalH}" width="${W}" height="${totalH}">
  <defs>
    <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stop-color="#1a1033"/>
      <stop offset="100%" stop-color="#2d1b69"/>
    </linearGradient>
    <linearGradient id="hdr" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0%" stop-color="#ff6b9d"/>
      <stop offset="100%" stop-color="#a855f7"/>
    </linearGradient>
  </defs>
  <rect width="${W}" height="${totalH}" rx="32" ry="32" fill="url(#bg)"/>
  <rect x="${PAD}" y="${PAD}" width="${W - PAD * 2}" height="${HEADER_H}" rx="20" ry="20" fill="url(#hdr)" opacity="0.95"/>
  <text x="${W/2}" y="${PAD + 60}" text-anchor="middle" font-family="Arial, sans-serif" font-size="44" font-weight="bold" fill="#ffffff">${escXml(monthNames[month-1])} ${year}</text>
  <text x="${W/2}" y="${PAD + 100}" text-anchor="middle" font-family="Arial, sans-serif" font-size="20" fill="#ffe4f1">𝑷𝑹𝑬𝑪𝑰𝑶𝑼𝑺 x  ·  Calendar</text>`;
  // Day-of-week header row
  for (let i = 0; i < COLS; i++) {
    const cx = PAD + cellW * i + cellW / 2;
    const isWeekend = (i === 0 || i === 6);
    svg += `\n  <text x="${cx}" y="${GRID_TOP + 10}" text-anchor="middle" font-family="Arial, sans-serif" font-size="22" font-weight="bold" fill="${isWeekend ? "#ff6b9d" : "#c4b5fd"}">${dayNames[i]}</text>`;
  }
  // Day cells
  for (let d = 1; d <= daysInMonth; d++) {
    const idx = firstDay + d - 1;
    const r = Math.floor(idx / 7);
    const c = idx % 7;
    const x = PAD + c * cellW + 6;
    const y = GRID_TOP + 30 + r * cellH;
    const isWeekend = (c === 0 || c === 6);
    const isToday = isCurrentMonth && d === today;
    const w = cellW - 12, h = cellH - 12;
    if (isToday) {
      svg += `\n  <rect x="${x}" y="${y}" width="${w}" height="${h}" rx="14" ry="14" fill="#ff6b9d"/>`;
      svg += `\n  <text x="${x + w/2}" y="${y + h/2 + 12}" text-anchor="middle" font-family="Arial, sans-serif" font-size="32" font-weight="bold" fill="#ffffff">${d}</text>`;
    } else {
      svg += `\n  <rect x="${x}" y="${y}" width="${w}" height="${h}" rx="14" ry="14" fill="#ffffff" opacity="0.06"/>`;
      svg += `\n  <text x="${x + w/2}" y="${y + h/2 + 10}" text-anchor="middle" font-family="Arial, sans-serif" font-size="28" fill="${isWeekend ? "#fbcfe8" : "#ffffff"}">${d}</text>`;
    }
  }
  // Footer
  svg += `\n  <text x="${W/2}" y="${totalH - 30}" text-anchor="middle" font-family="Arial, sans-serif" font-size="18" fill="#c4b5fd">${escXml(ngTime)}  ·  Africa/Lagos</text>`;
  svg += `\n</svg>`;

  // 3) Render SVG → PNG.
  // v4.9.5: Try three methods in order:
  //   A) wsrv.nl data-URL (no catbox needed — avoids catbox rate-limits)
  //   B) catbox upload → wsrv.nl URL (original method, now a fallback)
  //   C) send text fallback
  let pngBuf = null;
  const _isPng = (b) => b.length > 1000 && b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47;

  // Method A: inline SVG as base64 data-URL → wsrv.nl (no external upload)
  if (!pngBuf) {
    try {
      const b64 = Buffer.from(svg, "utf8").toString("base64");
      const dataUrl = `data:image/svg+xml;base64,${b64}`;
      const pngUrl = `https://wsrv.nl/?url=${encodeURIComponent(dataUrl)}&output=png&w=${W}&h=${totalH}`;
      const { data } = await axios.get(pngUrl, { responseType: "arraybuffer", timeout: 25000 });
      const b = Buffer.from(data);
      if (_isPng(b)) pngBuf = b;
    } catch (e) { console.error("[calendar] wsrv data-url method failed:", e.message); }
  }

  // Method B: catbox → wsrv (fallback if method A failed)
  if (!pngBuf) {
    try {
      const FormData = (await import("form-data")).default;
      const form = new FormData();
      form.append("reqtype", "fileupload");
      form.append("fileToUpload", Buffer.from(svg, "utf8"), { filename: `cal_${year}_${month}.svg`, contentType: "image/svg+xml" });
      const { data: svgUrl } = await axios.post("https://catbox.moe/user/api.php", form, { headers: form.getHeaders(), timeout: 18000 });
      if (typeof svgUrl === "string" && svgUrl.startsWith("http")) {
        const pngUrl = `https://wsrv.nl/?url=${encodeURIComponent(svgUrl)}&output=png&w=${W}&h=${totalH}`;
        const { data } = await axios.get(pngUrl, { responseType: "arraybuffer", timeout: 20000 });
        const b = Buffer.from(data);
        if (_isPng(b)) pngBuf = b;
      }
    } catch (e) { console.error("[calendar] catbox+wsrv method failed:", e.message); }
  }

  // Method C: prexzyvilla html2img (last resort before text fallback)
  if (!pngBuf) {
    try {
      // Build HTML string using concatenation to avoid nested template literal issues
      const _dayNames2 = ["Su","Mo","Tu","We","Th","Fr","Sa"];
      let _calGrid = _dayNames2.map(function(d,i){ return "<div class=\"day-header" + (i===0||i===6?" weekend":"") + "\">" + d + "</div>"; }).join("");
      _calGrid += "<div></div>".repeat(firstDay);
      for (let _di = 1; _di <= daysInMonth; _di++) {
        const _idx = firstDay + _di - 1;
        const _dc = _idx % 7;
        const _isTod = isCurrentMonth && _di === today;
        _calGrid += "<div class=\"day-cell" + (_isTod?" today":"") + (_dc===0||_dc===6?" weekend":"") + "\">" + _di + "</div>";
      }
      const calHtml = "<!DOCTYPE html><html><head><meta charset=\"utf-8\"><style>body{margin:0;background:linear-gradient(135deg,#1a1033,#2d1b69);font-family:Arial,sans-serif;color:#fff;padding:20px;width:680px}.header{background:linear-gradient(90deg,#ff6b9d,#a855f7);border-radius:16px;padding:20px;text-align:center;margin-bottom:16px}.month{font-size:36px;font-weight:bold}.sub{font-size:16px;color:#ffe4f1;margin-top:4px}.grid{display:grid;grid-template-columns:repeat(7,1fr);gap:4px}.day-header{text-align:center;padding:8px;font-weight:bold;color:#c4b5fd;font-size:15px}.day-header.weekend{color:#ff6b9d}.day-cell{text-align:center;padding:10px 6px;border-radius:10px;font-size:18px;background:rgba(255,255,255,.06)}.day-cell.today{background:#ff6b9d;font-weight:bold}.day-cell.weekend{color:#fbcfe8}.footer{text-align:center;color:#c4b5fd;margin-top:12px;font-size:14px}</style></head><body>" +
        "<div class=\"header\"><div class=\"month\">" + monthNames[month-1] + " " + year + "</div><div class=\"sub\">User Name   · Calendar</div></div>" +
        "<div class=\"grid\">" + _calGrid + "</div>" +
        "<div class=\"footer\">" + ngTime + "</div></body></html>";
      const _calr = await prexzyGet("/tools/html2img", { html: calHtml, width: "720", format: "png" }, 30000);
      if (_calr.ok) {
        const _cald = _calr.data?.data || _calr.data;
        const _calUrl = _cald?.url || _cald?.image_url || (typeof _cald === "string" ? _cald : null);
        if (_calUrl) {
          const _calBuf = Buffer.from((await axios.get(_calUrl, { responseType: "arraybuffer", timeout: 20000 })).data);
          const _isP = (b) => b.length > 500 && b[0] === 0x89 && b[1] === 0x50;
          if (_isP(_calBuf)) pngBuf = _calBuf;
        }
      }
    } catch (e) { console.error("[calendar] html2img method failed:", e.message); }
  }

  // 4) Send: image with caption when available, otherwise text fallback
  if (pngBuf) {
    await sock.sendMessage(msg.key.remoteJid, { image: pngBuf, caption: cal }, { quoted: msg });
  } else {
    await sendReply(sock, msg, cal);
  }
});

cmd("afk", { desc: "Set AFK status — .afk [reason]", category: "TOOLS" }, async (sock, msg, args) => {
  const jid = getSender(msg);
  const reason = args.join(" ") || "No reason";
  afkUsers.set(jid, { reason, time: Date.now() });
  const senderName = msg.pushName || "You";
  await sendReply(sock, msg,
    `😴 *AFK Activated!*\n\n` +
    `👤 *User:* ${senderName}\n` +
    `💬 *Reason:* ${reason}\n` +
    `🕒 *Since:* ${new Date().toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit" })}\n\n` +
    `_I'll notify senders that you're away._`);
});
cmd("unafk", { desc: "Remove AFK status", category: "TOOLS" }, async (sock, msg) => {
  const jid = getSender(msg);
  const afk = afkUsers.get(jid);
  afkUsers.delete(jid);
  const senderName = msg.pushName || "You";
  let durStr = "just now";
  if (afk) {
    const ms = Date.now() - afk.time;
    const totalMins = Math.floor(ms / 60000);
    const hrs = Math.floor(totalMins / 60);
    const mins = totalMins % 60;
    durStr = hrs > 0 ? `${hrs}h ${mins}m` : `${mins} minute${mins !== 1 ? "s" : ""}`;
  }
  await sendReply(sock, msg,
    `✅ *Welcome Back!*\n\n` +
    `👤 *User:* ${senderName}\n` +
    `⏱ *Away for:* ${durStr}\n` +
    (afk ? `💬 *Was:* ${afk.reason}\n` : "") +
    ``);
});
cmd("qr", { desc: "Generate QR code", category: "TOOLS" }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}qr <text or URL>`); return; }
  const text = args.join(" ");
  await react(sock, msg, "⏳");
  try {
    const url = `https://api.qrserver.com/v1/create-qr-code/?data=${encodeURIComponent(text)}&size=300x300&bgcolor=ffffff&color=000000`;
    const { data: buf } = await axios.get(url, { responseType: "arraybuffer", timeout: 10000 });
    await sock.sendMessage(msg.key.remoteJid, { image: Buffer.from(buf), caption: `📱 *QR Code*\n\n_${text}_` }, { quoted: msg });
    const _qrCtaBtns = [{ type: "copy", text: "📋 Copy Encoded Text", value: text, id: "qr_text_copy" }];
    if (/^https?:\/\//i.test(text)) _qrCtaBtns.unshift({ type: "url", text: "🌐 Open URL", url: text });
    await sendCTAButtons(sock, msg.key.remoteJid, msg, `📱 *QR Code generated!*\n_Encoded: ${text.slice(0, 70)}${text.length > 70 ? "..." : ""}_`, _qrCtaBtns, `${CONFIG.BOT_NAME} • QR Generator`).catch(() => {});
  } catch { await sendReply(sock, msg, "❌ Failed to generate QR code."); }
});
cmd("shorten", { desc: "Shorten URL", category: "TOOLS" }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}shorten <url>`); return; }
  await react(sock, msg, "🔗");
  const shortApis = [
    async () => { const { data } = await axios.get(`https://is.gd/create.php?format=simple&url=${encodeURIComponent(args[0])}`, { timeout: 8000 }); return data; },
    async () => { const { data } = await axios.get(`https://tinyurl.com/api-create.php?url=${encodeURIComponent(args[0])}`, { timeout: 8000 }); return data; },
    async () => { const { data } = await axios.get(`https://ulvis.net/api.php?url=${encodeURIComponent(args[0])}&private=1`, { timeout: 8000 }); return data; },
    async () => { const { data } = await axios.get(`https://clck.ru/--?url=${encodeURIComponent(args[0])}`, { timeout: 8000 }); return data; },
  ];
  for (const tryApi of shortApis) {
    try {
      const result = await tryApi();
      if (result && typeof result === "string" && result.startsWith("http")) {
        await sendReply(sock, msg, `🔗 *Shortened URL!*\n\n📎 Original: ${args[0]}\n🔗 Short: *${result}*`);
        await sendCTAButtons(sock, msg.key.remoteJid, msg,
          `🔗 *URL Shortened!*\n_Tap to open or copy the short link_`,
          [
            { type: "url",  text: "🌐 Open Short URL",  url: result },
            { type: "copy", text: "📋 Copy Short URL",   value: result, id: "shorten_copy" },
          ],
          `${CONFIG.BOT_NAME} • URL Shortener`
        ).catch(() => {});
        return;
      }
    } catch { continue; }
  }
  await sendReply(sock, msg, "❌ Failed to shorten URL. Check if it's valid.");
});
cmd("ip", { desc: "IP lookup", category: "TOOLS" }, async (sock, msg, args) => {
  await react(sock, msg, "🌐");
  const ip = args[0]?.replace(/[^0-9a-f.:]/gi, "") || "";
  const ipApis = [
    async () => {
      const { data } = await axios.get(`https://ip-api.com/json/${ip}?fields=status,country,regionName,city,isp,org,query`, { timeout: 8000 });
      if (data?.status !== "success") return null;
      return { ip: data.query, country: data.country, city: data.city, region: data.regionName, isp: data.isp || data.org };
    },
    async () => {
      const { data } = await axios.get(`https://ipapi.co/${ip}/json/`, { timeout: 8000 });
      if (data?.error) return null;
      return { ip: data.ip, country: data.country_name, city: data.city, region: data.region, isp: data.org };
    },
    async () => {
      const { data } = await axios.get(`https://ipinfo.io/${ip}/json`, { timeout: 8000 });
      return { ip: data.ip, country: data.country, city: data.city, region: data.region, isp: data.org };
    },
  ];
  let result = null;
  for (const fn of ipApis) { try { result = await fn(); if (result?.ip) break; } catch {} }
  if (result?.ip) {
    await sendReply(sock, msg, `🌐 *IP Lookup*\n\n📍 IP: *${result.ip}*\n🌍 Country: ${result.country || "N/A"}\n🏙️ City: ${result.city || "N/A"}\n📌 Region: ${result.region || "N/A"}\n📡 ISP: ${result.isp || "N/A"}`);
    const mapQuery = [result.city, result.country].filter(Boolean).join(", ");
    await sendCTAButtons(sock, msg.key.remoteJid, msg,
      `🌐 *IP:* \`${result.ip}\` — ${result.city || ""}${result.country ? ", " + result.country : ""}`,
      [
        { type: "url",  text: "🗺️ View on Google Maps", url: `https://www.google.com/maps/search/${encodeURIComponent(mapQuery)}` },
        { type: "copy", text: "📋 Copy IP Address",      value: result.ip, id: "ip_copy" },
      ],
      `${CONFIG.BOT_NAME} • IP Lookup`
    ).catch(() => {});
  } else {
    await sendReply(sock, msg, `❌ IP lookup failed for: *${ip || "your IP"}*`);
  }
});
cmd("time", { desc: "Current time/date", category: "TOOLS" }, async (sock, msg) => {
  const now = new Date();
  await sendReply(sock, msg, `🕐 *Current Time*\n\n📅 Date: ${now.toDateString()}\n🕐 Time: ${now.toLocaleTimeString()}\n🌍 UTC: ${now.toUTCString()}`);
});
cmd("remind", { desc: "Set reminder — .remind <time> <msg>  (e.g. .remind 10m Call John)", category: "UTILITY" }, async (sock, msg, args) => {
  if (args.length < 2) {
    await sendReply(sock, msg,
`⏰ *Reminder Usage*

${CONFIG.PREFIX}remind <time> <message>

*Time formats:*
• \`30\` or \`30m\` — 30 minutes
• \`2h\` — 2 hours
• \`1h30m\` — 1 hour 30 min
• \`90s\` — 90 seconds

*Examples:*
• ${CONFIG.PREFIX}remind 10m Call John
• ${CONFIG.PREFIX}remind 1h Take medicine
• ${CONFIG.PREFIX}remind 2h30m Meeting starts`);
    return;
  }
  const jid = getSender(msg) || msg.key.remoteJid;
  const timeStr = args[0].toLowerCase();
  let ms = 0;
  const hMatch = timeStr.match(/(\d+)h/);
  const mMatch = timeStr.match(/(\d+)m(?!s)/);
  const sMatch = timeStr.match(/(\d+)s/);
  if (hMatch) ms += parseInt(hMatch[1]) * 3600000;
  if (mMatch) ms += parseInt(mMatch[1]) * 60000;
  if (sMatch) ms += parseInt(sMatch[1]) * 1000;
  if (!ms && !isNaN(parseInt(timeStr))) ms = parseInt(timeStr) * 60000;
  if (!ms || ms < 5000)  { await sendReply(sock, msg, `❌ Invalid time. Minimum is 5 seconds.\n\nUsage: ${CONFIG.PREFIX}remind <time> <message>`); return; }
  if (ms > 86400000)     { await sendReply(sock, msg, `❌ Max reminder time is 24 hours.`); return; }
  const text = args.slice(1).join(" ");
  const fireAt = new Date(Date.now() + ms).toLocaleTimeString("en-NG", { timeZone: "Africa/Lagos", hour: "2-digit", minute: "2-digit" });
  const h = Math.floor(ms / 3600000), m = Math.floor((ms % 3600000) / 60000), s = Math.floor((ms % 60000) / 1000);
  const disp = h > 0 ? `${h}h ${m}m` : m > 0 ? `${m}m` : `${s}s`;
  setTimeout(async () => {
    try {
      await sock.sendMessage(jid, { text: `⏰ *REMINDER*\n━━━━━━━━━━━━━━━━━━━━\n\n📌 ${text}\n\n🕐 Time: ${new Date().toLocaleTimeString("en-NG", { timeZone: "Africa/Lagos", hour12: true })}` });
    } catch {}
  }, ms);
  await sendReply(sock, msg, `⏰ *Reminder Set!*\n\n📌 Message: *${text}*\n⏱️ In: *${disp}*\n🕐 Fires at: *~${fireAt} (Lagos)*`);
});
cmd(["vv", "viewonce"], { desc: "Reveal view-once message (reply to it)", category: "TOOLS" }, async (sock, msg) => {
  const ctx = msg.message?.extendedTextMessage?.contextInfo
    || msg.message?.imageMessage?.contextInfo
    || msg.message?.videoMessage?.contextInfo
    || msg.message?.documentMessage?.contextInfo
    || null;
  if (!ctx?.quotedMessage) { await react(sock, msg, "❌"); return; }
  await react(sock, msg, "🌀");
  // FIX (vv not working): unwrap EVERY wrapper layer — ephemeralMessage,
  // viewOnce v1 / v2 / v2Extension, documentWithCaption. The old code only
  // unwrapped one level, so any view-once media that arrived inside an
  // ephemeral (or double-wrapped) container fell through to the ❌ silently.
  let vo = ctx.quotedMessage;
  for (let i = 0; i < 5; i++) {
    const inner = vo?.viewOnceMessage?.message
      || vo?.viewOnceMessageV2?.message
      || vo?.viewOnceMessageV2Extension?.message
      || vo?.ephemeralMessage?.message
      || vo?.documentWithCaptionMessage?.message;
    if (!inner || inner === vo) break;
    vo = inner;
  }
  const jid = msg.key.remoteJid;
  let _vvSent = false;
  try {
    if (vo.imageMessage) {
      const stream = await downloadContentFromMessage(vo.imageMessage, "image");
      let buf = Buffer.from([]);
      for await (const c of stream) buf = Buffer.concat([buf, c]);
      await sock.sendMessage(msg.key.remoteJid, { image: buf, caption: vo.imageMessage.caption || undefined }, { quoted: msg });
      _vvSent = true;
    } else if (vo.videoMessage) {
      const stream = await downloadContentFromMessage(vo.videoMessage, "video");
      let buf = Buffer.from([]);
      for await (const c of stream) buf = Buffer.concat([buf, c]);
      await sock.sendMessage(msg.key.remoteJid, { video: buf, caption: vo.videoMessage.caption || undefined }, { quoted: msg });
      _vvSent = true;
    } else if (vo.audioMessage) {
      const stream = await downloadContentFromMessage(vo.audioMessage, "audio");
      let buf = Buffer.from([]);
      for await (const c of stream) buf = Buffer.concat([buf, c]);
      await sock.sendMessage(msg.key.remoteJid, { audio: buf, mimetype: vo.audioMessage.mimetype || "audio/mp4", ptt: !!vo.audioMessage.ptt }, { quoted: msg });
      _vvSent = true;
    } else {
      await react(sock, msg, "❌");
    }
    if (_vvSent) {
      await react(sock, msg, "✅");
    }
  } catch (e) { await react(sock, msg, "❌"); }
});

// ── v4.9.4 NEW: .vv2 — save view-once silently to OWNER DM ──────────
// Unlike .vv (which reveals the media in the current chat), .vv2 keeps
// the original chat untouched and forwards a clean copy of the media
// straight to the bot owner's DM. Ideal for archiving without alerting
// the sender or other group members.
cmd(["vv2","lol","wow","hehe","😂","🙂","omor","chai","🥀"], { desc: "Save replied view-once media silently to OWNER DM", category: "TOOLS", ownerOnly: true }, async (sock, msg) => {
  const ctx = getContextInfo(msg);
  if (!ctx?.quotedMessage) { return; } // not replying → ignore (prevents accidental trigger on normal chat)
  let vo = ctx.quotedMessage;
  for (let i = 0; i < 5; i++) {
    const inner = vo?.viewOnceMessage?.message
      || vo?.viewOnceMessageV2?.message
      || vo?.viewOnceMessageV2Extension?.message
      || vo?.ephemeralMessage?.message
      || vo?.documentWithCaptionMessage?.message;
    if (!inner || inner === vo) break;
    vo = inner;
  }
  // STRICT: only proceed if the unwrapped payload is actual view-once media.
  // Prevents "hehe/omor" replied to a normal image/text from dumping into your DM.
  const _isVO = !!(vo && (vo.imageMessage?.viewOnce || vo.videoMessage?.viewOnce || vo.audioMessage?.viewOnce || vo.imageMessage || vo.videoMessage || vo.audioMessage));
  const _cameFromVO = /viewOnce/i.test(JSON.stringify(ctx.quotedMessage).slice(0, 400)) || _isVO;
  if (!vo || !(vo.imageMessage || vo.videoMessage || vo.audioMessage) || !_cameFromVO) { return; } // silent
  let senderJid = resolveLid(
    ctx.participant ||
    ctx.remoteJid ||
    msg.key.participant ||
    msg.participant ||
    msg.key.remoteJid ||
    ""
  );
  // A quoted group message may identify its author with an @lid.  Refresh the
  // group mapping before falling back to the numeric session identity.
  if (senderJid.endsWith("@lid") && isGroup(msg)) {
    try {
      // PERF FIX: cache-first lookup — a network groupMetadata() round-trip
      // on every quoted message made big accounts feel very slow.
      const meta = _groupMetaCache.get(msg.key.remoteJid) || await sock.groupMetadata(msg.key.remoteJid).catch(() => null);
      if (meta) {
        updateLidMappingsFromMeta(meta);
        senderJid = resolveLid(senderJid);
      }
    } catch {}
  }
  const senderMentionJid = senderJid.endsWith("@s.whatsapp.net") ? senderJid : "";
  const senderTag = _cleanNum(senderJid) || "unknown";
  let ownerJid = "";
  const configuredOwnerJid = String(CONFIG.OWNER_JID || "").trim();
  const configuredOwnerNumber = String(CONFIG.OWNER_NUMBER || "").replace(/[^0-9]/g, "");
  const sessionOwnerNumber = _cleanNum(sock.user?.id || _botJid || "");
  if (configuredOwnerJid.includes("@")) ownerJid = toStandardJid(configuredOwnerJid);
  else if (configuredOwnerNumber) ownerJid = `${configuredOwnerNumber}@s.whatsapp.net`;
  else if (sessionOwnerNumber) ownerJid = `${sessionOwnerNumber}@s.whatsapp.net`;
  if (!ownerJid) { return; } // silent
  const chatLabel = msg.key.remoteJid?.endsWith("@g.us")
    ? `Group: ${msg.key.remoteJid}`
    : `Chat: ${msg.key.remoteJid}`;
  const cap = `🔒 *ViewOnce Saved*\n👤 From: @${senderTag}\n📍 ${chatLabel}\n🕐 ${new Date().toLocaleString()}`;
  const mentions = senderMentionJid ? [senderMentionJid] : [];
  try {
    let mediaPayload = null;
    if (vo.imageMessage) {
      const stream = await downloadContentFromMessage(vo.imageMessage, "image");
      let buf = Buffer.from([]);
      for await (const c of stream) buf = Buffer.concat([buf, c]);
      mediaPayload = { image: buf, caption: cap, ...(mentions.length ? { mentions } : {}) };
    } else if (vo.videoMessage) {
      const stream = await downloadContentFromMessage(vo.videoMessage, "video");
      let buf = Buffer.from([]);
      for await (const c of stream) buf = Buffer.concat([buf, c]);
      mediaPayload = { video: buf, mimetype: "video/mp4", caption: cap, ...(mentions.length ? { mentions } : {}) };
    } else if (vo.audioMessage) {
      const stream = await downloadContentFromMessage(vo.audioMessage, "audio");
      let buf = Buffer.from([]);
      for await (const c of stream) buf = Buffer.concat([buf, c]);
      // Audio can't carry a caption — send caption as a separate text first.
      await sock.sendMessage(ownerJid, { text: cap, ...(mentions.length ? { mentions } : {}) }).catch(() => {});
      mediaPayload = { audio: buf, mimetype: "audio/mp4", ptt: !!vo.audioMessage.ptt };
    } else { return; } // silent — unknown media type in view-once
    await sock.sendMessage(ownerJid, mediaPayload);
    // v12: fully silent — no reaction, no chat reply
  } catch (e) {
    // v12: stay silent on failure too (do not spam the chat)
    try { console.error("[vv2]", e?.message || e); } catch {}
  }
});

cmd("note", { desc: "Save a note", category: "TOOLS" }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}note <text to save>`); return; }
  const jid = msg.key.remoteJid;
  if (!groupRules.has(jid + "_notes")) groupRules.set(jid + "_notes", []);
  groupRules.get(jid + "_notes").push(args.join(" "));
  await sendReply(sock, msg, `📝 *Note saved!*\n\n"${args.join(" ")}"`);
});
cmd("uuid", { desc: "Generate UUID", category: "TOOLS" }, async (sock, msg) => {
  const uuid = "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, c => { const r = Math.random() * 16 | 0; return (c === "x" ? r : (r & 0x3 | 0x8)).toString(16); });
  await sendReply(sock, msg, `🆔 *UUID*\n\n\`${uuid}\``);
});
cmd("ss", { desc: "Screenshot a website", category: "TOOLS" }, async (sock, msg, args) => {
  if (!args[0]) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}ss <url>`); return; }
  const jid = msg.key.remoteJid;
  const statusMsg = await sock.sendMessage(jid, { text: `📸 *MIAS MDX Screenshot*\n\n⬡ Loading website...\n◻ Capturing screenshot...\n◻ Sending image...` }, { quoted: msg });
  const ssKey = statusMsg.key;
  try {
    const url = args[0].startsWith("http") ? args[0] : "https://" + args[0];
    let ssBuf;
    try {
      const ssUrl = `https://image.thum.io/get/width/1280/crop/720/${encodeURIComponent(url)}`;
      const { data } = await axios.get(ssUrl, { responseType: "arraybuffer", timeout: 15000 });
      ssBuf = Buffer.from(data);
    } catch {
      // Fallback: use api.js screenshot
      try {
        const result = await APIs.screenshotWebsite(url);
        ssBuf = Buffer.isBuffer(result) ? result : null;
        if (!ssBuf && typeof result === "string") {
          const { data } = await axios.get(result, { responseType: "arraybuffer", timeout: 15000 });
          ssBuf = Buffer.from(data);
        }
      } catch {}
    }
    if (ssBuf && ssBuf.length > 1000) {
      await sock.sendMessage(msg.key.remoteJid, { image: ssBuf, caption: `📸 *Screenshot*\n${url}` }, { quoted: msg });
    } else { await sendReply(sock, msg, "❌ Failed to capture screenshot."); }
  } catch { await sendReply(sock, msg, "❌ Failed to capture screenshot."); }
});
cmd("trt", { desc: "Translate text", category: "TOOLS" }, async (sock, msg, args) => {
  if (args.length < 2) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}trt <lang> <text>\nExample: ${CONFIG.PREFIX}trt fr Hello world`); return; }
  const lang = args[0]; const text = args.slice(1).join(" ");
  try {
    const { data } = await axios.get(`https://api.mymemory.translated.net/get?q=${encodeURIComponent(text)}&langpair=auto|${lang}`, { timeout: 10000 });
    await sendReply(sock, msg, `🌐 *Translation*\n\n📝 Original: _${text}_\n🔤 ${lang.toUpperCase()}: *${data.responseData.translatedText}*`);
  } catch { await sendReply(sock, msg, "❌ Translation failed."); }
});
cmd("take", { desc: "Rename sticker — .take <name> | <author>", category: "TOOLS" }, async (sock, msg, args) => {
  const q = msg.message?.extendedTextMessage?.contextInfo?.quotedMessage;
  const stk = q?.stickerMessage;
  if (!stk) {
    await sendReply(sock, msg,
      `❌ Reply to a sticker with ${CONFIG.PREFIX}take\n\n` +
      `Usage: ${CONFIG.PREFIX}take <pack name> | <author>\n` +
      `Or: ${CONFIG.PREFIX}take <name>  (sets both pack & author)\n\n` +
      `Example: ${CONFIG.PREFIX}take MyPack | John`
    );
    return;
  }
  try {
    const stream = await downloadContentFromMessage(stk, "sticker");
    let buf = Buffer.from([]);
    for await (const c of stream) buf = Buffer.concat([buf, c]);
    const rawText = args.join(" ").trim();
    const parts = rawText.split("|").map(p => p.trim());
    // Default: blank pack name/author so no metadata text appears
    const packName   = parts[0] || "";
    const authorName = parts[1] || parts[0] || "";
    const exifBuf = buildStickerExif(packName, authorName);
    const tagged = await injectWebpExif(buf, exifBuf);
    // Send sticker only — no reply/quote, no text, no reaction
    await sock.sendMessage(msg.key.remoteJid, { sticker: tagged });
  } catch (e) { await sendReply(sock, msg, `❌ Take failed: ${e.message}`); }
});
cmd(["tourl", "litterbox", "tour"], { desc: "Upload media to catbox.moe URL", category: "UTILITY" }, async (sock, msg) => {
  await react(sock, msg, "🌀").catch(()=>{});
  const q = msg.message?.extendedTextMessage?.contextInfo?.quotedMessage;
  const img = msg.message?.imageMessage || q?.imageMessage;
  const vid = q?.videoMessage || msg.message?.videoMessage;
  const aud = q?.audioMessage || msg.message?.audioMessage;
  const doc = q?.documentMessage || msg.message?.documentMessage;
  const stk = q?.stickerMessage || msg.message?.stickerMessage;
  const media = img || vid || aud || doc || stk;
  if (!media) { await sendReply(sock, msg, `❌ Reply to an image/video/audio/document with ${CONFIG.PREFIX}tourl`); return; }
  const jid = msg.key.remoteJid;
  const statusMsg = await sock.sendMessage(jid, { text: `🔗 *MIAS MDX Uploader*\n\n⬡ Downloading media...\n◻ Uploading to server...\n◻ Generating link...` }, { quoted: msg });
  const sKey = statusMsg.key;
  try {
    const type = img ? "image" : vid ? "video" : aud ? "audio" : stk ? "sticker" : "document";
    const stream = await downloadContentFromMessage(media, type);
    let buf = Buffer.from([]);
    for await (const c of stream) buf = Buffer.concat([buf, c]);
    const ext = img ? "jpg" : vid ? "mp4" : aud ? "ogg" : stk ? "webp" : (doc?.fileName?.split(".").pop() || "bin");
    const mime = media.mimetype || (img ? "image/jpeg" : vid ? "video/mp4" : aud ? "audio/ogg" : stk ? "image/webp" : "application/octet-stream");
    await editMessage(sock, jid, sKey, `🔗 *MIAS MDX Uploader*\n\n⬢ Downloading media... ✅\n⬡ Uploading to server...\n◻ Generating link...`);
    const FormData = (await import("form-data")).default;
    // Try catbox first, then litterbox fallback
    let resultUrl = null;
    const uploadApis = [
      async () => {
        const form = new FormData();
        form.append("reqtype", "fileupload");
        form.append("fileToUpload", buf, { filename: `upload.${ext}`, contentType: mime });
        const { data } = await axios.post("https://catbox.moe/user/api.php", form, { headers: form.getHeaders(), timeout: 60000 });
        if (data && typeof data === "string" && data.startsWith("https://")) return data;
        return null;
      },
      async () => {
        const form = new FormData();
        form.append("reqtype", "fileupload");
        form.append("time", "72h");
        form.append("fileToUpload", buf, { filename: `upload.${ext}`, contentType: mime });
        const { data } = await axios.post("https://litterbox.catbox.moe/resources/internals/api.php", form, { headers: form.getHeaders(), timeout: 60000 });
        if (data && typeof data === "string" && data.startsWith("https://")) return data;
        return null;
      },
      async () => {
        const form = new FormData();
        form.append("file", buf, { filename: `upload.${ext}`, contentType: mime });
        const { data } = await axios.post("https://tmpfiles.org/api/v1/upload", form, { headers: form.getHeaders(), timeout: 60000 });
        if (data?.data?.url) return data.data.url.replace("tmpfiles.org/", "tmpfiles.org/dl/");
        return null;
      },
    ];
    for (const tryUpload of uploadApis) {
      try { resultUrl = await tryUpload(); if (resultUrl) break; } catch { continue; }
    }
    if (resultUrl) {
      await editMessage(sock, jid, sKey, `${resultUrl}`);
      await sock.sendMessage(jid, { text: resultUrl }, { quoted: msg }).catch(() => {});
      await react(sock, msg, "✅").catch(()=>{});
    } else {
      await editMessage(sock, jid, sKey, `🔗 *MIAS MDX Uploader*\n\n⬢ Downloading media... ✅\n⬢ Uploading to server... ❌\n\n⚠️ All upload servers busy — try again later`);
    }
  } catch (e) {
    await editMessage(sock, jid, sKey, `🔗 *MIAS MDX Uploader*\n\n❌ Upload failed: ${e.message}`);
  }

  // ── FALLBACK ENDPOINTS (merged from duplicate cmd registrations) ──
  // fallback URL: https://litterbox.catbox.moe\n\nFiles
  // fallback URL: https://haveibeenpwned.com`);
});
