cmd(["timezone", "tz"], { desc: "Show current time in a timezone — .tz Lagos | London | New_York", category: "UTILITY" }, async (sock, msg, args) => {
  if (!args.length) {
    const zones = [
      ["🇳🇬 Lagos / Africa",   "Africa/Lagos"],
      ["🇬🇧 London / UK",      "Europe/London"],
      ["🇺🇸 New York / US",    "America/New_York"],
      ["🇺🇸 Los Angeles / US", "America/Los_Angeles"],
      ["🇦🇪 Dubai / UAE",      "Asia/Dubai"],
      ["🇮🇳 India / IST",      "Asia/Kolkata"],
      ["🇨🇳 China / CST",      "Asia/Shanghai"],
      ["🇯🇵 Tokyo / JST",      "Asia/Tokyo"],
      ["🇦🇺 Sydney / AEST",    "Australia/Sydney"],
    ];
    let t = `🌍 *World Timezones*\n━━━━━━━━━━━━━━━━━━━━\n\n`;
    for (const [label, zone] of zones) {
      const time = new Date().toLocaleTimeString("en-US", { timeZone: zone, hour: "2-digit", minute: "2-digit", hour12: true });
      const date = new Date().toLocaleDateString("en-US", { timeZone: zone, weekday: "short", month: "short", day: "numeric" });
      t += `${label}\n🕐 ${time}  •  ${date}\n\n`;
    }
    t += `Usage: *${CONFIG.PREFIX}tz <timezone>*\nExample: *${CONFIG.PREFIX}tz London*`;
    await sendReply(sock, msg, t);
    return;
  }
  const tz = args.join("_");
  try {
    const time = new Date().toLocaleTimeString("en-US", { timeZone: tz, hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: true });
    const date = new Date().toLocaleDateString("en-US", { timeZone: tz, weekday: "long", year: "numeric", month: "long", day: "numeric" });
    const offset = new Date().toLocaleString("en-US", { timeZone: tz, timeZoneName: "short" }).split(" ").pop();
    await sendReply(sock, msg, `🌍 *Timezone: ${tz}*\n\n🕐 Time: *${time}*\n📅 Date: *${date}*\n📍 Zone: *${offset}*`);
  } catch { await sendReply(sock, msg, `❌ Unknown timezone: *${tz}*\nTry: Africa/Lagos, Europe/London, America/New_York, Asia/Dubai`); }
});

cmd(["countdown", "cd"], { desc: "Countdown to a date — .countdown 2025-12-25", category: "UTILITY" }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}countdown <date>\nExample: ${CONFIG.PREFIX}countdown 2025-12-25\nOr: ${CONFIG.PREFIX}countdown Dec 25 2025`); return; }
  const dateStr = args.join(" ");
  const target = new Date(dateStr);
  if (isNaN(target.getTime())) { await sendReply(sock, msg, `❌ Invalid date: *${dateStr}*\nTry: \`2025-12-25\` or \`Dec 25 2025\``); return; }
  const now = Date.now();
  const diff = target.getTime() - now;
  if (diff < 0) {
    const ago = Math.abs(diff);
    const d = Math.floor(ago / 86400000), h = Math.floor((ago % 86400000) / 3600000), m = Math.floor((ago % 3600000) / 60000);
    await sendReply(sock, msg, `⏰ *Countdown — ${target.toDateString()}*\n\n⚠️ That date has already passed!\n⏱️ It was *${d}d ${h}h ${m}m* ago.`);
    return;
  }
  const d = Math.floor(diff / 86400000), h = Math.floor((diff % 86400000) / 3600000), m = Math.floor((diff % 3600000) / 60000), s = Math.floor((diff % 60000) / 1000);
  const weeks = Math.floor(d / 7), days = d % 7;
  await sendReply(sock, msg,
`⏳ *Countdown — ${target.toDateString()}*
━━━━━━━━━━━━━━━━━━━━

📅 *${d} days* remaining
⏱️ *${weeks}w ${days}d ${h}h ${m}m ${s}s*

🕐 From now: ${new Date().toDateString()}
📍 Target  : ${target.toDateString()}`);
});

cmd(["genpass", "password", "pw"], { desc: "Generate a secure password — .genpass [length]", category: "UTILITY" }, async (sock, msg, args) => {
  const len = Math.min(64, Math.max(8, parseInt(args[0]) || 16));
  const upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  const lower = "abcdefghijklmnopqrstuvwxyz";
  const nums  = "0123456789";
  const syms  = "!@#$%^&*()-_=+[]{}|;:,.<>?";
  const all   = upper + lower + nums + syms;
  let pass = "";
  pass += upper[Math.floor(Math.random() * upper.length)];
  pass += lower[Math.floor(Math.random() * lower.length)];
  pass += nums[Math.floor(Math.random() * nums.length)];
  pass += syms[Math.floor(Math.random() * syms.length)];
  for (let i = 4; i < len; i++) pass += all[Math.floor(Math.random() * all.length)];
  pass = pass.split("").sort(() => 0.5 - Math.random()).join("");
  const strength = len >= 20 ? "🟢 Strong" : len >= 12 ? "🟡 Medium" : "🔴 Weak";
  const passText = `🔐 *Password Generator*\n━━━━━━━━━━━━━━━━━━━━\n\n\`\`\`${pass}\`\`\`\n\n🔒 Length: *${len}* chars\n💪 Strength: *${strength}*\n\n⚠️ _Save this somewhere safe — do NOT share it!_`;
  try {
    await sendCTAButtons(sock, msg.key.remoteJid, msg, passText, [
      { type: "copy", text: "📋 Copy Password", value: pass, id: "gen_pass" },
    ], `${CONFIG.BOT_NAME} • Password Generator`);
  } catch {
    await sendReply(sock, msg, passText);
  }
});

cmd(["choose", "decide", "c"], { desc: "Pick randomly from options — .choose A | B | C", category: "UTILITY" }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}choose option1 | option2 | option3\nExample: ${CONFIG.PREFIX}choose Pizza | Jollof Rice | Fried Rice`); return; }
  const full = args.join(" ");
  const opts = full.split("|").map(o => o.trim()).filter(Boolean);
  if (opts.length < 2) { await sendReply(sock, msg, `❌ Give at least 2 options separated by *|*\nExample: ${CONFIG.PREFIX}choose Yes | No | Maybe`); return; }
  const chosen = opts[Math.floor(Math.random() * opts.length)];
  let t = `🎲 *Decision Maker*\n━━━━━━━━━━━━━━━━━━━━\n\n`;
  t += opts.map((o, i) => `${i + 1}. ${o}`).join("\n");
  t += `\n\n🏆 *Chosen:* *${chosen}*`;
  await sendReply(sock, msg, t);
});

cmd(["wc", "wordcount", "charcount"], { desc: "Count words & chars in replied message", category: "UTILITY" }, async (sock, msg, args) => {
  const ctx = msg.message?.extendedTextMessage?.contextInfo;
  const qText = ctx?.quotedMessage?.conversation || ctx?.quotedMessage?.extendedTextMessage?.text || args.join(" ");
  if (!qText) { await sendReply(sock, msg, `Usage: *Reply* to a text message with ${CONFIG.PREFIX}wc\nOr: ${CONFIG.PREFIX}wc <your text here>`); return; }
  const words = qText.trim().split(/\s+/).filter(Boolean).length;
  const chars = qText.length;
  const charsNoSpace = qText.replace(/\s/g, "").length;
  const lines = qText.split("\n").length;
  const sentences = (qText.match(/[.!?]+/g) || []).length;
  await sendReply(sock, msg,
`📊 *Word Count Analysis*
━━━━━━━━━━━━━━━━━━━━

📝 Words     : *${words.toLocaleString()}*
🔤 Characters: *${chars.toLocaleString()}* (with spaces)
✂️ Characters: *${charsNoSpace.toLocaleString()}* (no spaces)
📄 Lines     : *${lines.toLocaleString()}*
💬 Sentences : *${sentences.toLocaleString()}*`);
});

