// ═══════════════════════════════════════════════════════════════════════════════
//  MEDIA COMMANDS
// ═══════════════════════════════════════════════════════════════════════════════
cmd(["sticker", "s"], { desc: "Image/video → sticker", category: "MEDIA" }, async (sock, msg, args) => {
  const unwrap = (node) => node?.ephemeralMessage?.message
    || node?.viewOnceMessage?.message
    || node?.viewOnceMessageV2?.message
    || node?.documentWithCaptionMessage?.message
    || node
    || {};
  const message = unwrap(msg.message);
  const context = message?.extendedTextMessage?.contextInfo
    || message?.imageMessage?.contextInfo
    || message?.videoMessage?.contextInfo
    || message?.documentMessage?.contextInfo;
  const q = unwrap(context?.quotedMessage);
  const img = message?.imageMessage || q?.imageMessage;
  const vid = message?.videoMessage || q?.videoMessage;
  if (!img && !vid) { await sendReply(sock, msg, "❌ Reply to an image or short video!"); return; }
  const jid = msg.key.remoteJid;
  const packName = args.join(" ") || CONFIG.BOT_NAME;
  const statusMsg = await sock.sendMessage(jid, { text: `✨ *MIAS MDX Sticker*\n\n⬡ Downloading media...\n◻ Converting to sticker...` }, { quoted: msg });
  const stkKey = statusMsg.key;
  try {
    const media = img || vid;
    const type = img ? "image" : "video";
    const stream = await downloadContentFromMessage(media, type);
    let buf = Buffer.from([]);
    for await (const c of stream) buf = Buffer.concat([buf, c]);
    await editMessage(sock, jid, stkKey, `✨ *MIAS MDX Sticker*\n\n⬢ Downloading media... ✅\n⬡ Converting to sticker...`);
    const _stkWebpBuf = await createStickerFromBuffer(buf, {
      mediaType: img?.mimetype || (vid ? "video/mp4" : "image/jpeg"),
      pack: packName,
      author: CONFIG.OWNER_NAME || "MIAS MDX",
    });
    await editMessage(sock, jid, stkKey, `✨ *MIAS MDX Sticker*\n\n⬢ Downloading media... ✅\n⬢ Converting to WebP... ✅\n⬡ Sending...`);
    // WhatsApp answers a sticker whose payload is not a real WebP with
    // "Sorry, this media file doesn't exist on your internal storage".
    // Verify the RIFF/WEBP magic bytes here instead of shipping a dead sticker.
    if (!Buffer.isBuffer(_stkWebpBuf)
        || _stkWebpBuf.length < 64
        || _stkWebpBuf.subarray(0, 4).toString("ascii") !== "RIFF"
        || _stkWebpBuf.subarray(8, 12).toString("ascii") !== "WEBP") {
      throw new Error("sticker encoder returned an unreadable file");
    }
    await sock.sendMessage(jid, {
      sticker: _stkWebpBuf,
      mimetype: "image/webp",
    }, { quoted: msg });
    await editMessage(sock, jid, stkKey, `✨ *MIAS MDX Sticker*\n\n⬢ Downloading image... ✅\n⬢ Converting to sticker... ✅\n\n✅ *Done!*`);
  } catch (e) {
    await editMessage(sock, jid, stkKey, `✨ *MIAS MDX Sticker*\n\n❌ Sticker failed: ${(e?.message || e).toString().slice(0, 240)}\n\n💡 Reply to a supported image or short video and try again.`);
  }
});
cmd("toimg", { desc: "Sticker → Image", category: "MEDIA" }, async (sock, msg) => {
  const q = msg.message?.extendedTextMessage?.contextInfo?.quotedMessage;
  const stk = msg.message?.stickerMessage || q?.stickerMessage;
  if (!stk) { await sendReply(sock, msg, "❌ Reply to a sticker!"); return; }
  await react(sock, msg, "⏳");
  try {
    const stream = await downloadContentFromMessage(stk, "sticker");
    let buf = Buffer.from([]);
    for await (const c of stream) buf = Buffer.concat([buf, c]);
    const inPath = `/tmp/stk_${Date.now()}.webp`;
    const outPath = `/tmp/stk_${Date.now()}.png`;
    fs.writeFileSync(inPath, buf);
    const { execSync } = await import("child_process");
    try {
      execSync(`ffmpeg -i ${inPath} -y ${outPath}`, { timeout: 15000, stdio: "pipe" });
      const outBuf = fs.readFileSync(outPath);
      await sock.sendMessage(msg.key.remoteJid, { image: outBuf, caption: `🖼️ *Sticker → Image*` }, { quoted: msg });
    } catch { await sock.sendMessage(msg.key.remoteJid, { image: buf, caption: `🖼️ *Sticker → Image*` }, { quoted: msg }); }
    try { fs.unlinkSync(inPath); fs.unlinkSync(outPath); } catch {}
    await react(sock, msg, "✅");
  } catch (e) { await sendReply(sock, msg, "❌ Conversion failed: " + e.message); }
});
cmd(["tomp3", "toaudio"], { desc: "Video/Audio → MP3", category: "MEDIA" }, async (sock, msg) => {
  const q = msg.message?.extendedTextMessage?.contextInfo?.quotedMessage;
  const vid = msg.message?.videoMessage || q?.videoMessage;
  const aud = msg.message?.audioMessage || q?.audioMessage;
  const media = vid || aud;
  if (!media) { await sendReply(sock, msg, "❌ Reply to a video or audio!"); return; }
  const jid = msg.key.remoteJid;
  const statusMsg = await sock.sendMessage(jid, { text: `🎵 *MIAS MDX Converter*\n\n⬡ Downloading media...\n◻ Converting to MP3...\n◻ Sending audio...` }, { quoted: msg });
  const mp3Key = statusMsg.key;
  try {
    const type = vid ? "video" : "audio";
    const stream = await downloadContentFromMessage(media, type);
    let buf = Buffer.from([]);
    for await (const c of stream) buf = Buffer.concat([buf, c]);
    const ext = vid ? "mp4" : "ogg";
    const inPath = `/tmp/conv_${Date.now()}.${ext}`;
    const outPath = `/tmp/conv_${Date.now()}.mp3`;
    fs.writeFileSync(inPath, buf);
    const { execSync } = await import("child_process");
    try {
      execSync(`ffmpeg -i ${inPath} -vn -acodec libmp3lame -q:a 2 -y ${outPath}`, { timeout: 60000, stdio: "pipe" });
      const outBuf = fs.readFileSync(outPath);
      await sock.sendMessage(msg.key.remoteJid, { audio: outBuf, mimetype: "audio/mpeg", ptt: false }, { quoted: msg });
    } catch { await sock.sendMessage(msg.key.remoteJid, { audio: buf, mimetype: "audio/mpeg", ptt: false }, { quoted: msg }); }
    try { fs.unlinkSync(inPath); fs.unlinkSync(outPath); } catch {}
    await react(sock, msg, "✅");
  } catch (e) { await sendReply(sock, msg, "❌ Conversion failed: " + e.message); }
});
cmd("toptt", { desc: "Audio → Voice Note", category: "MEDIA" }, async (sock, msg) => {
  const q = msg.message?.extendedTextMessage?.contextInfo?.quotedMessage;
  const aud = msg.message?.audioMessage || q?.audioMessage;
  const vid = msg.message?.videoMessage || q?.videoMessage;
  const media = aud || vid;
  if (!media) { await sendReply(sock, msg, "❌ Reply to audio or video!"); return; }
  await react(sock, msg, "⏳");
  try {
    const type = aud ? "audio" : "video";
    const stream = await downloadContentFromMessage(media, type);
    let buf = Buffer.from([]);
    for await (const c of stream) buf = Buffer.concat([buf, c]);
    const inPath = `/tmp/ptt_${Date.now()}.${aud ? "ogg" : "mp4"}`;
    const outPath = `/tmp/ptt_${Date.now()}.ogg`;
    fs.writeFileSync(inPath, buf);
    const { execSync } = await import("child_process");
    try {
      execSync(`ffmpeg -i ${inPath} -acodec libopus -b:a 48k -y ${outPath}`, { timeout: 30000, stdio: "pipe" });
      const outBuf = fs.readFileSync(outPath);
      await sock.sendMessage(msg.key.remoteJid, { audio: outBuf, mimetype: "audio/ogg; codecs=opus", ptt: true }, { quoted: msg });
    } catch { await sock.sendMessage(msg.key.remoteJid, { audio: buf, mimetype: "audio/ogg; codecs=opus", ptt: true }, { quoted: msg }); }
    try { fs.unlinkSync(inPath); fs.unlinkSync(outPath); } catch {}
    await react(sock, msg, "✅");
  } catch (e) { await sendReply(sock, msg, "❌ Conversion failed: " + e.message); }
});// ── .trim — Lossless video/audio trimmer (reply to media, specify time ranges) ──
cmd(["trim","trimvid","videotrim","cuttrim","trimcut"], { desc: "Trim video or audio by time — .trim start end (e.g. .trim 0:30 1:45) or multiple clips .trim 0:00-0:30 1:00-1:30", category: "MEDIA" }, async (sock, msg, args) => {
  const jid = msg.key.remoteJid;
  const q = msg.message?.extendedTextMessage?.contextInfo?.quotedMessage;
  const vid = msg.message?.videoMessage || q?.videoMessage;
  const aud = msg.message?.audioMessage || q?.audioMessage;
  const media = vid || aud;
  const mediaType = vid ? "video" : aud ? "audio" : null;

  if (!media) {
    await sendReply(sock, msg,
`✂️ *Video / Audio Trimmer*

*Reply to a video or audio*, then:

*Single clip:*
  ${CONFIG.PREFIX}trim 0:30 1:45   _(from 30s to 1m45s)_
  ${CONFIG.PREFIX}trim 1:30        _(first 1m30s)_

*Multiple clips at once:*
  ${CONFIG.PREFIX}trim 0:00-0:30 1:00-1:30 2:00-2:45

*Formats accepted:* mm:ss · hh:mm:ss · plain seconds`);
    return;
  }

  if (!args.length) {
    await sendReply(sock, msg, `✂️ Usage: *${CONFIG.PREFIX}trim 0:30 1:45*\n_Reply to a video/audio with start and end time._`);
    return;
  }

  const parseTime = (str) => {
    str = String(str || "").trim();
    if (/^\d+$/.test(str)) return parseInt(str, 10);
    const parts = str.split(":").map(Number);
    if (parts.some(isNaN)) return null;
    if (parts.length === 2) return parts[0] * 60 + parts[1];
    if (parts.length === 3) return parts[0] * 3600 + parts[1] * 60 + parts[2];
    return null;
  };
  const fmtTime = (s) => {
    s = Math.round(s);
    const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), sec = s % 60;
    return h > 0 ? `${h}:${String(m).padStart(2,"0")}:${String(sec).padStart(2,"0")}` : `${m}:${String(sec).padStart(2,"0")}`;
  };

  let segments = [];
  const _rawArgs = args.join(" ");
  const _rangeRx = /(\d{1,2}(?::\d{2}){0,2})-(\d{1,2}(?::\d{2}){0,2})/g;
  let _rm;
  while ((_rm = _rangeRx.exec(_rawArgs)) !== null) {
    const s = parseTime(_rm[1]), e = parseTime(_rm[2]);
    if (s !== null && e !== null && e > s) segments.push({ start: s, end: e });
  }
  if (!segments.length) {
    if (args.length >= 2) {
      const s = parseTime(args[0]), e = parseTime(args[1]);
      if (s !== null && e !== null && e > s) segments.push({ start: s, end: e });
      else { await sendReply(sock, msg, `❌ Invalid time range. End must be after start.\nExample: *${CONFIG.PREFIX}trim 0:30 1:45*`); return; }
    } else {
      const dur = parseTime(args[0]);
      if (!dur || dur <= 0) { await sendReply(sock, msg, `❌ Invalid time.\nExample: *${CONFIG.PREFIX}trim 1:30*`); return; }
      segments.push({ start: 0, end: dur });
    }
  }
  if (!segments.length) { await sendReply(sock, msg, `❌ Could not parse time.\nExample: *${CONFIG.PREFIX}trim 0:30 1:45*`); return; }
  if (segments.length > 10) { await sendReply(sock, msg, `❌ Max 10 clips at once.`); return; }

  await react(sock, msg, "✂️");
  const statusMsg = await sock.sendMessage(jid, { text: `✂️ Downloading media...` }, { quoted: msg });
  const trimKey = statusMsg.key;

  try {
    const stream = await downloadContentFromMessage(media, mediaType);
    let buf = Buffer.from([]);
    for await (const chunk of stream) buf = Buffer.concat([buf, chunk]);
    if (buf.length < 1000) throw new Error("Empty media download");

    const { execSync } = await import("child_process");
    const ext = mediaType === "video" ? "mp4" : "ogg";
    const ts = Date.now();
    const inPath = `/tmp/trim_in_${ts}.${ext}`;
    fs.writeFileSync(inPath, buf);
    const _sizeMB = (buf.length / 1024 / 1024).toFixed(1);
    await editMessage(sock, jid, trimKey, `✂️ Trimming ${segments.length} clip${segments.length > 1 ? "s" : ""}... ⚡`);

    let sent = 0;
    for (let idx = 0; idx < segments.length; idx++) {
      const { start, end } = segments[idx];
      const outPath = `/tmp/trim_out_${ts}_${idx}.${ext}`;
      let clipped = false;
      // Attempt 1: stream copy (lossless — no quality loss at all)
      try {
        execSync(`ffmpeg -y -i ${inPath} -ss ${start} -to ${end} -c copy -avoid_negative_ts make_zero ${outPath}`, { timeout: 120000, stdio: "pipe" });
        if (fs.existsSync(outPath) && fs.statSync(outPath).size > 100) clipped = true;
      } catch {}
      // Attempt 2: re-encode if copy failed (e.g. keyframe alignment issues)
      if (!clipped) {
        try {
          const reEncCmd = mediaType === "video"
            ? `ffmpeg -y -i ${inPath} -ss ${start} -to ${end} -c:v libx264 -crf 18 -preset fast -c:a aac -movflags +faststart ${outPath}`
            : `ffmpeg -y -i ${inPath} -ss ${start} -to ${end} -c:a libopus -b:a 128k ${outPath}`;
          execSync(reEncCmd, { timeout: 120000, stdio: "pipe" });
          if (fs.existsSync(outPath) && fs.statSync(outPath).size > 100) clipped = true;
        } catch {}
      }
      if (!clipped) { await sock.sendMessage(jid, { text: `⚠️ Clip ${idx+1}: could not trim this segment (${fmtTime(start)}→${fmtTime(end)})` }, { quoted: msg }); try { fs.unlinkSync(outPath); } catch {} continue; }

      const outBuf = fs.readFileSync(outPath);
      const clipSizeMB = (outBuf.length / 1024 / 1024).toFixed(1);
      const cap = `✂️ *Clip ${idx+1}/${segments.length}*\n⏱️ *${fmtTime(start)} → ${fmtTime(end)}* _(${fmtTime(end-start)} long)_\n📦 ${clipSizeMB} MB`;
      if (mediaType === "video") {
        try { await sock.sendMessage(jid, { video: outBuf, caption: cap }, { quoted: msg }); }
        catch { await sock.sendMessage(jid, { document: outBuf, mimetype: "video/mp4", fileName: `clip${idx+1}_${fmtTime(start).replace(/:/g,"-")}_to_${fmtTime(end).replace(/:/g,"-")}.mp4`, caption: cap }, { quoted: msg }); }
      } else {
        await sock.sendMessage(jid, { audio: outBuf, mimetype: "audio/ogg; codecs=opus", ptt: false }, { quoted: msg });
        await sendReply(sock, msg, cap);
      }
      sent++;
      try { fs.unlinkSync(outPath); } catch {}
      if (idx < segments.length - 1) await new Promise(r => setTimeout(r, 700));
    }
    try { fs.unlinkSync(inPath); } catch {}
    await editMessage(sock, jid, trimKey, `✅ *Done — ${sent}/${segments.length} clip${segments.length > 1 ? "s" : ""} trimmed!* ✂️\n📦 Original: ${_sizeMB} MB`);
    await react(sock, msg, "✅");
  } catch (e) {
    await editMessage(sock, jid, trimKey, `❌ Trim failed: ${e.message}`);
    await react(sock, msg, "❌");
  }
});

