cmd(["tagall", "everyone", "botall"], { desc: "Tag all members (shows group pic + name + admin list)", ownerOnly: true, category: "GROUP" }, async (sock, msg) => {
  if (!requireGroup(msg)) return;
  const jid = msg.key.remoteJid;
  const meta = await sock.groupMetadata(jid);
  const _rawFull = getBody(msg);
  const _cmdName = _rawFull.split(" ")[0].slice(CONFIG.PREFIX.length);
  const body = _rawFull.slice(CONFIG.PREFIX.length + _cmdName.length).trim() || "🔔 Attention everyone!";

  const groupName = meta.subject || "Group";
  const totalMembers = meta.participants.length;
  const adminCount = meta.participants.filter(p => p.admin).length;
  const desc = meta.desc ? meta.desc.slice(0, 80) : "";

  let t = `╭──────────────────╮\n`;
  t += `│  👥 *${groupName}*\n`;
  if (desc) t += `│  📝 ${desc}${meta.desc?.length > 80 ? "..." : ""}\n`;
  t += `│\n`;
  t += `│  📢 *${body}*\n`;
  t += `│\n`;
  t += `│  👤 Members: *${totalMembers}*   👑 Admins: *${adminCount}*\n`;
  t += `╰──────────────────╯\n\n`;

  const jids = [];
  for (const m of meta.participants) {
    const num = _cleanNum(resolveLid(m.id));
    const isSuperAdmin = m.admin === "superadmin";
    const isAdmin = m.admin === "admin" || isSuperAdmin;
    const badge = isSuperAdmin ? " 👑" : isAdmin ? " ⭐" : "";
    const adminLabel = isSuperAdmin ? " *(owner)*" : isAdmin ? " *(admin)*" : "";
    const cname = pushNameCache.get(_cleanNum(m.id)) || m.notify || "";
    const nice = cname && !/^\d+$/.test(cname) ? ` — ${cname}` : "";
    t += `• @${num}${badge}${adminLabel}${nice}\n\n`;
    jids.push(m.id);
  }
  t += ``;

  // Try to send with group picture
  let gpicBuf = null;
  try {
    const gpicUrl = await sock.profilePictureUrl(jid, "image");
    if (gpicUrl) {
      const r = await axios.get(gpicUrl, { responseType: "arraybuffer", timeout: 15000 });
      if (r.data && r.data.byteLength > 1000) gpicBuf = Buffer.from(r.data);
    }
  } catch {}

  if (gpicBuf) {
    await sock.sendMessage(jid, { image: gpicBuf, caption: t, mentions: jids }, { quoted: msg });
  } else {
    await sock.sendMessage(jid, { text: t, mentions: jids }, { quoted: msg });
  }
});
cmd("tag", { desc: "Tag specific people — shows who tagged them by pushName", category: "GROUP" }, async (sock, msg, args) => {
  const mentions = msg.message?.extendedTextMessage?.contextInfo?.mentionedJid || [];
  const text = args.filter(a => !a.startsWith("@")).join(" ") || "Hey!";
  if (!mentions.length) { await sendReply(sock, msg, "❌ Tag some people!"); return; }
  // Resolve tagger pushName for the header so the message reads "[name] tagged you" instead of "@number"
  const taggerJid = getSender(msg);
  let taggerName = "";
  try { taggerName = await getDisplayName(sock, taggerJid, isGroup(msg) ? msg.key.remoteJid : null); } catch {}
  if (!isMeaningfulName(taggerName || "")) taggerName = msg.pushName || `+${_cleanNum(taggerJid)}`;
  let t = `🏷️ *${taggerName}* tagged you:\n\n${text}\n\n`;
  for (const j of mentions) {
    const nm = await getDisplayName(sock, j, isGroup(msg) ? msg.key.remoteJid : null).catch(() => null);
    const display = isMeaningfulName(nm || "") ? nm : `@${j.split("@")[0]}`;
    t += `• ${display} `;
  }
  await sock.sendMessage(msg.key.remoteJid, { text: t.trim() + ``, mentions }, { quoted: msg });
});
cmd("kick", { desc: "Kick member or N random members (e.g .kick 5)", category: "GROUP", ownerOnly: true }, async (sock, msg, args) => {
    if (!requireGroup(msg)) return;
    const jid = msg.key.remoteJid;
    const ctx = msg.message?.extendedTextMessage?.contextInfo;

    // Check if first arg is a number (bulk kick N members)
    const bulkN = args[0] && /^\d+$/.test(args[0]) ? parseInt(args[0]) : 0;
    
    if (bulkN > 0) {
      // Bulk kick N random non-admin members
      if (bulkN > 50) { await sendReply(sock, msg, "❌ Max bulk kick is 50 at once."); return; }
      let meta;
      try { meta = await sock.groupMetadata(jid); } catch { await sendReply(sock, msg, "❌ Could not fetch group info."); return; }
      const botNum = _cleanNum(sock.user?.id);
      const ownerNum = CONFIG.OWNER_NUMBER;
      const admins = meta.participants.filter(p => p.admin).map(p => _cleanNum(p.id));
      const kickable = meta.participants.filter(p => {
        const n = _cleanNum(p.id);
        return !p.admin && n !== botNum && n !== ownerNum && !admins.includes(n);
      });
      if (!kickable.length) { await sendReply(sock, msg, "❌ No non-admin members to kick."); return; }
      const toKick = kickable.slice(0, bulkN).map(p => p.id);
      const statusMsg = await sock.sendMessage(jid, { text: `👢 *MIAS MDX Bulk Kick*\n\n⬡ Kicking *${toKick.length}* random non-admin members...` }, { quoted: msg });
      let kicked = 0;
      for (const t of toKick) {
        try { await sock.groupParticipantsUpdate(jid, [t], "remove"); kicked++; await new Promise(r => setTimeout(r, 500)); } catch {}
      }
      await editMessage(sock, jid, statusMsg.key, `👢 *MIAS MDX Bulk Kick Done!*\n\n✅ Kicked *${kicked}* of *${toKick.length}* members.`);
      return;
    }

    // Single/tagged kick
    let m = ctx?.mentionedJid || [];
    if (!m.length && ctx?.participant) {
      const quotedNum = _cleanNum(ctx.participant);
      try {
        const meta = await sock.groupMetadata(jid);
        const found = meta.participants.find(p => _cleanNum(p.id) === quotedNum);
        m = [found?.id || ctx.participant];
      } catch { m = [ctx.participant]; }
    }
    if (!m.length) { await sendReply(sock, msg, `❌ Tag or reply to someone to kick.\n\nBulk kick: *${CONFIG.PREFIX}kick 5* (kicks 5 random members)`); return; }
    
    const statusMsg = await sock.sendMessage(jid, { text: `👢 *MIAS MDX Kick*\n\n⬡ Removing ${m.length} member(s)...` }, { quoted: msg });
    let kicked = 0;
    // v12 FIX: resolve every mention to the EXACT participant.id (LID-aware)
    let _kMeta = null; try { _kMeta = await sock.groupMetadata(jid); } catch {}
    const _resolveKickId = (t) => {
      const tn = _cleanNum(t);
      if (!_kMeta) return t;
      const hit = (_kMeta.participants || []).find(p =>
        _cleanNum(p.id) === tn || (p.pn && _cleanNum(p.pn) === tn) || p.id === t);
      return hit?.id || t;
    };
    for (const t of m) {
      const tNum = _cleanNum(t);
      if (tNum === CONFIG.OWNER_NUMBER || tNum === CREATOR_NUMBER) continue;
      const realId = _resolveKickId(t);
      let _ok = false;
      for (const _id of Array.from(new Set([realId, t, tNum + "@s.whatsapp.net", tNum + "@lid"]))) {
        try { await sock.groupParticipantsUpdate(jid, [_id], "remove"); _ok = true; break; }
        catch (e) { try { console.error("[kick]", _id, e?.data?.reason || e?.message); } catch {} }
      }
      if (_ok) kicked++;
    }
    await editMessage(sock, jid, statusMsg.key, `👢 *MIAS MDX Kick Done!*\n\n✅ Kicked *${kicked}* member(s).`);
  });
cmd(["tkick","tempkick","tk"], { desc: "Temporarily kick a member and re-add them after a delay", category: "GROUP", adminOnly: true, groupOnly: true }, async (sock, msg, args) => {
  const jid = msg.key.remoteJid;
  const mentioned = msg.message?.extendedTextMessage?.contextInfo?.mentionedJid ||
                    msg.message?.buttonsResponseMessage?.contextInfo?.mentionedJid || [];
  const replied = msg.message?.extendedTextMessage?.contextInfo?.participant ||
                  msg.message?.buttonsResponseMessage?.contextInfo?.participant;
  const rawTarget = mentioned[0] || replied || args.find(a => a.includes("@"));
  if (!rawTarget) {
    await sendReply(sock, msg, `❌ *Tag or reply to someone to temp-kick.*
Usage: ${CONFIG.PREFIX}tkick @user [minutes]
Example: ${CONFIG.PREFIX}tkick @user 5`);
    return;
  }
  const target = rawTarget.includes("@") ? rawTarget : rawTarget + "@s.whatsapp.net";
  // Parse duration: supports raw number (minutes), or e.g. 30s / 5m / 2h
  let _tkSeconds = 60; // default 1 minute
  const _durArg = args.find(a => /^\d+[smh]?$/i.test(a.trim()));
  if (_durArg) {
    const _dm = _durArg.match(/^(\d+)([smh]?)$/i);
    const _dv = parseInt(_dm[1]);
    const _du = (_dm[2] || 'm').toLowerCase();
    _tkSeconds = _du === 's' ? _dv : _du === 'h' ? _dv * 3600 : _dv * 60;
  }
  const seconds = Math.max(5, Math.min(_tkSeconds, 86400)); // 5s min, 24h max
  const minutes = Math.ceil(seconds / 60);
  await react(sock, msg, "⏱️");
    // Pre-check: bot must be admin
    const _tkBotAdmin = await isBotGroupAdmin(sock, jid).catch(() => false);
    if (!_tkBotAdmin) {
      await sendReply(sock, msg, `❌ I need to be a group admin to temp-kick.`); return;
    }
    try {
      await sock.groupParticipantsUpdate(jid, [target], "remove");
      await sendReply(sock, msg, `⏱️ *Temp-Kicked @${target.split("@")[0]}*
They will be re-added in *${minutes} minute(s)*.`, [target]);
      try { globalThis.__tkickSock = sock; if (globalThis._tkickPersistAdd) globalThis._tkickPersistAdd(jid, target, Date.now() + seconds * 1000); } catch {}
      setTimeout(async () => {
        let _readded = false;
        // Try up to 3 times with a short delay between attempts
        for (let _att = 0; _att < 3 && !_readded; _att++) {
          try { await sock.groupParticipantsUpdate(jid, [target], "add"); _readded = true; } catch { await new Promise(r => setTimeout(r, 3000)); }
        }
        if (_readded) {
          try { await sock.sendMessage(jid, { text: `✅ @${target.split("@")[0]} has been re-added after the temp-kick.`, mentions: [target] }); } catch {}
        } else {
          // Fallback: send invite link directly to the kicked user
          try {
            const code = await sock.groupInviteCode(jid);
            if (code) {
              try { await sock.sendMessage(target, { text: `👋 *Your temp-kick has ended.*
Rejoin: https://chat.whatsapp.com/${code}` }); } catch {}
              try { await sock.sendMessage(jid, { text: `🔗 @${target.split("@")[0]} couldn't be re-added — invite link DM'd to them.`, mentions: [target] }); } catch {}
            }
          } catch {}
        }
      }, seconds * 1000);
    } catch (e) {
      await sendReply(sock, msg, `❌ Kick failed: ${e.message || "Unknown error"}
Make sure I'm an admin and the user is in the group.`);
    }
  });

cmd("getlid", { desc: "Get LID (linked device ID) of group members or a specific user", category: "GROUP", ownerOnly: true, groupOnly: true }, async (sock, msg, args) => {
  if (!isGroup(msg)) { await sendReply(sock, msg, "❌ Use this command in a group."); return; }
  await react(sock, msg, "🔍");
  const jid = msg.key.remoteJid;
  try {
    const meta = await sock.groupMetadata(jid);
    const ctx = msg.message?.extendedTextMessage?.contextInfo;
    const mentioned = ctx?.mentionedJid?.[0] || ctx?.participant;
    let out = `🆔 *Group LID Info*\n📌 *${meta.subject}*\n\n`;
    if (mentioned) {
      const num = _cleanNum(mentioned);
      const lid = lidStore?.get?.(mentioned) || lidStore?.get?.(num + "@s.whatsapp.net") || "Not found";
      out += `👤 @${num}\n🔗 JID: \`${mentioned}\`\n🪪 LID: \`${lid}\``;
      await sendReply(sock, msg, out + ``, [mentioned]);
      try {
        const _lidBtns = [
          { text: "🔄 Refresh All LIDs", id: `${CONFIG.PREFIX}getlid` },
          { text: "👤 Check Another",    id: `${CONFIG.PREFIX}getlid ` },
        ];
        if (lid && lid !== "Not found") _lidBtns.push({ text: "📋 Copy LID", id: `${CONFIG.PREFIX}copy ${lid}` });
        await sendNativeFlowButtons(sock, jid, msg, `🆔 LID lookup complete`, _lidBtns, `${CONFIG.BOT_NAME} • LID Info`);
      } catch {}
    } else {
      const members = meta.participants || [];
      out += `👥 Total: ${members.length} members\n\n`;
      let i = 0;
      for (const p of members.slice(0, 20)) {
        const pJid = p.id || p.jid || "";
        const num = _cleanNum(pJid);
        const lid = p.lid || (typeof lidStore?.get === "function" ? lidStore.get(pJid) : null) || "—";
        out += `${++i}. +${num}\n   🪪 \`${lid}\`\n`;
      }
      if (members.length > 20) out += `\n_...and ${members.length - 20} more. Mention a user for their specific LID._\n`;
      await sendReply(sock, msg, out + ``);
      try {
        await sendNativeFlowButtons(sock, jid, msg, `🆔 *LID list — ${members.length} members*\n_Mention someone for their specific LID_`, [
          { text: "🔄 Refresh List", id: `${CONFIG.PREFIX}getlid` },
        ], `${CONFIG.BOT_NAME} • LID Info`);
      } catch {}
    }
  } catch (e) { await sendReply(sock, msg, `❌ Failed: ${e.message}`); }
});

