cmd("add", { desc: "Add member(s) — .add <number> or .add num1,num2,num3", category: "GROUP", ownerOnly: true }, async (sock, msg, args) => {
  if (!requireGroup(msg)) return;
  if (!args[0]) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}add <phone>\nor multi: ${CONFIG.PREFIX}add num1,num2,num3`); return; }
  const gJid = msg.key.remoteJid;
  const rawInput = args.join(" ").trim();
  const numbers = rawInput.split(",").map(n => n.trim().replace(/\D/g, "")).filter(n => n.length >= 7);
  if (!numbers.length) { await sendReply(sock, msg, `❌ No valid numbers. Usage: ${CONFIG.PREFIX}add 2349001234567,2348001234567`); return; }
  const statusMsg = await sock.sendMessage(gJid, { text: `➕ *MIAS MDX Add*\n\n⬡ Adding ${numbers.length} number(s)...` }, { quoted: msg });
  const addKey = statusMsg.key;
  const results = [];
  for (const num of numbers) {
    const targetJid = num + "@s.whatsapp.net";
    try {
      await sock.groupParticipantsUpdate(gJid, [targetJid], "add");
      results.push("✅ +" + num);
    } catch (e) {
      results.push("❌ +" + num + ": " + (e?.message?.slice(0, 60) || "failed"));
    }
    if (numbers.length > 1) await new Promise(r => setTimeout(r, 900));
  }
  const ok = results.filter(r => r.startsWith("✅")).length;
  await editMessage(sock, gJid, addKey, `➕ *MIAS MDX Add*\n\n${results.join("\n")}\n\n${ok}/${numbers.length} added.`);
});
