// ── Anti-Tag / Anti-Group-Mention — block mass-tagging in groups ─────────────
cmd(["antitag","antigroupmention","antitagall","antimention","antiping"], { desc: "Toggle anti-tag: block mass @mentions and @everyone in group", category: "GROUP", ownerOnly: true }, async (sock, msg, args) => {
  if (!requireGroup(msg)) return;
  const s = getSettings(msg.key.remoteJid);
  const v = (args[0] || "").toLowerCase();
  const action = args[1] || s.antiTagAction || "delete";
  if (["on","1","enable","true"].includes(v)) s.antiTag = true;
  else if (["off","0","disable","false"].includes(v)) s.antiTag = false;
  else s.antiTag = !s.antiTag;
  if (["delete","warn","kick"].includes(action)) s.antiTagAction = action;
  const thresh = parseInt(args[2]) || s.antiTagThreshold || 4;
  s.antiTagThreshold = thresh;
  saveNow();
  const status = s.antiTag ? `✅ ON` : `❌ OFF`;
  const actionLabel = (s.antiTagAction || "delete").toUpperCase();
  await sendReply(sock, msg,
`🏷️ *Anti-Tag / Anti-Group-Mention*

Status: *${status}*
Action: *${actionLabel}*
Threshold: *${thresh}+ mentions triggers guard*

*What it blocks:*
• @everyone / @all / @here tags
• Tagging ${thresh}+ people at once

*Usage:*
• *${CONFIG.PREFIX}antitag on* — enable (delete)
• *${CONFIG.PREFIX}antitag on warn* — warn only
• *${CONFIG.PREFIX}antitag on kick* — kick on tag
• *${CONFIG.PREFIX}antitag off* — disable
• *${CONFIG.PREFIX}antitag on delete 3* — trigger at 3+ mentions`);
});
cmd(["addbadword", "removebadword", "listbadwords", "antibad", "antisticker", "antic", "antistatus", "allowlink", "denylink"], { desc: "Group protection", category: "GROUP", ownerOnly: true }, async (sock, msg, args) => {
  if (!requireGroup(msg)) return;
  const c = extractCommandName(msg);
  const s = getSettings(msg.key.remoteJid);
  if (c === "addbadword") {
    if (!args[0]) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}addbadword <word>`); return; }
    if (!badWords.has(msg.key.remoteJid)) badWords.set(msg.key.remoteJid, new Set());
    badWords.get(msg.key.remoteJid).add(args[0].toLowerCase());
    await sendReply(sock, msg, `✅ Bad word added: *${args[0]}*`);
  } else if (c === "removebadword") {
    badWords.get(msg.key.remoteJid)?.delete(args[0]?.toLowerCase());
    await sendReply(sock, msg, `✅ Word removed.`);
  } else if (c === "listbadwords") {
    const bw = [...(badWords.get(msg.key.remoteJid) || [])];
    await sendReply(sock, msg, `🔞 Bad words: ${bw.join(", ") || "None"}`);
  } else if (c === "antibad") {
    s.antiBad = !s.antiBad;
    saveNow();
    await sendReply(sock, msg, `🚫 Anti Bad Words: ${s.antiBad ? "✅ ON" : "❌ OFF"}`);
  } else if (c === "antisticker") {
    const loweredArgs = args.map(v => String(v || "").toLowerCase()).filter(Boolean);
    const hasOn = loweredArgs.some(v => ["on", "1", "enable", "true"].includes(v));
    const hasOff = loweredArgs.some(v => ["off", "0", "disable", "false"].includes(v));
    const modeArg = loweredArgs.find(v => ["delete", "warn", "kick", "tkick"].includes(v)) || s.stickerGuard || "delete";
    if (hasOn) s.antiSticker = true;
    else if (hasOff) s.antiSticker = false;
    else s.antiSticker = !s.antiSticker;
    s.stickerGuard = modeArg;
    saveNow();
    await sendReply(sock, msg, `🚫 *Anti-Sticker: ${s.antiSticker ? "✅ ON" : "❌ OFF"}*\n🛡️ Action: *${(s.stickerGuard || "delete").toUpperCase()}*\n\nUsage: ${CONFIG.PREFIX}antisticker on delete/warn/kick/tkick | off\nBot must be admin to delete/kick.`);
  } else if (c === "antic") {
    s.antiLink = !s.antiLink;
    saveNow();
    await sendReply(sock, msg, `🔗 Anti-Link: ${s.antiLink ? "✅ ON" : "❌ OFF"}`);
  } else if (c === "antistatus") {
    s.antiStatus = !s.antiStatus;
    saveNow();
    await sendReply(sock, msg, `📊 Anti Status: ${s.antiStatus ? "✅ ON" : "❌ OFF"}`);
  } else if (c === "allowlink") {
    s.antiLink = false;
    saveNow();
    await sendReply(sock, msg, `✅ *Links ALLOWED in this group!*

All links are now permitted.
Use ${CONFIG.PREFIX}denylink to block links again.`);
  } else if (c === "denylink") {
    s.antiLink = true;
    saveNow();
    await sendReply(sock, msg, `🚫 *Links DENIED in this group!*

🔍 The following link types will be detected & deleted:
• WhatsApp Group invites & Channels
• Telegram, YouTube, TikTok
• Instagram, Facebook, Twitter/X
• Discord, and all external URLs

Sender will be kicked if bot has admin rights.

Use ${CONFIG.PREFIX}allowlink to re-enable links.`);
  }
});
cmd(["lockmedia","nomedia","medlock","medialocked"], { desc: "Block media in group — images/videos/docs from non-admins", category: "GROUP", ownerOnly: true }, async (sock, msg, args) => {
  if (!requireGroup(msg)) return;
  const s = getSettings(msg.key.remoteJid);
  const v        = (args[0] || "").toLowerCase();
  const modeArg  = (args[1] || args[0] || "").toLowerCase();
  if (["on","1","enable","true"].includes(v))  s.lockMedia = true;
  else if (["off","0","disable","false"].includes(v)) s.lockMedia = false;
  else if (!["delete","warn","kick","tkick"].includes(v)) s.lockMedia = !s.lockMedia;
  if (["delete","warn","kick","tkick"].includes(modeArg)) s.mediaGuard = modeArg;
  if (!s.mediaGuard) s.mediaGuard = "delete";
  saveNow();
  const status = s.lockMedia ? "✅ ON" : "❌ OFF";
  const action = (s.mediaGuard).toUpperCase();
  const lockText =
`🚫 *Lock Media: ${status}*
🛡️ Action: *${action}*

When *ON*, any image, video, document or audio sent by non-admins will be *${action}*d.
Admins and bot owner are always exempt.

*Usage:*
• ${CONFIG.PREFIX}lockmedia on — enable (action: delete)
• ${CONFIG.PREFIX}lockmedia on warn — enable, action = warn
• ${CONFIG.PREFIX}lockmedia on tkick — enable, action = temp-kick
• ${CONFIG.PREFIX}lockmedia off — disable

Bot must be *admin* to delete/kick.`;
  try {
    await sendCTAButtons(sock, msg.key.remoteJid, msg, lockText, [
      { type: "quick_reply", text: s.lockMedia ? "🔓 Turn OFF" : "🔒 Turn ON",   id: `BTN:${CONFIG.PREFIX}lockmedia ${s.lockMedia ? "off" : "on"}` },
      { type: "quick_reply", text: "🗑️ Action: Delete",  id: `BTN:${CONFIG.PREFIX}lockmedia on delete` },
      { type: "quick_reply", text: "⚠️ Action: Warn",    id: `BTN:${CONFIG.PREFIX}lockmedia on warn` },
      { type: "quick_reply", text: "⏱️ Action: TKick",   id: `BTN:${CONFIG.PREFIX}lockmedia on tkick` },
    ], `${CONFIG.BOT_NAME} • Lock Media`);
  } catch { await sendReply(sock, msg, lockText); }
});

