cmd(["gclockmedia","gclm","gcmedia","gcmlock"], { desc: "GC lock media — quickly toggle media lock in a group chat", category: "GROUP", ownerOnly: true }, async (sock, msg, args) => {
  if (!requireGroup(msg)) return;
  const s = getSettings(msg.key.remoteJid);
  const v = (args[0] || "").toLowerCase();
  if (["on","1","enable","lock"].includes(v))   s.lockMedia = true;
  else if (["off","0","disable","unlock"].includes(v)) s.lockMedia = false;
  else s.lockMedia = !s.lockMedia;
  if (!s.mediaGuard) s.mediaGuard = "delete";
  saveNow();
  const icon = s.lockMedia ? "🔒" : "🔓";
  const st   = s.lockMedia ? "✅ LOCKED"  : "❌ UNLOCKED";
  const msg2 = s.lockMedia
    ? `🚫 *GC Media Lock — ON*

${icon} Non-admins can NO LONGER send images, videos, documents or audio in this group.

Action: *${(s.mediaGuard).toUpperCase()}*

_Bot must be admin to enforce this._`
    : `✅ *GC Media Lock — OFF*

${icon} Non-admins can now send media freely.`;
  try {
    await sendCTAButtons(sock, msg.key.remoteJid, msg, msg2, [
      { type: "quick_reply", text: s.lockMedia ? "🔓 Unlock Media" : "🔒 Lock Media",   id: `BTN:${CONFIG.PREFIX}gclockmedia ${s.lockMedia ? "off" : "on"}` },
      { type: "quick_reply", text: "🗑️ Action: Delete",  id: `BTN:${CONFIG.PREFIX}lockmedia on delete` },
      { type: "quick_reply", text: "⚠️ Action: Warn",    id: `BTN:${CONFIG.PREFIX}lockmedia on warn`   },
    ], `${CONFIG.BOT_NAME} • GC Media Lock`);
  } catch { await sendReply(sock, msg, msg2); }
});

