cmd(["setprefix", "prefix"], { desc: "Change bot prefix — use 'null' or 'none' for no prefix", category: "CONFIG", ownerOnly: true }, async (sock, msg, args) => {
  if (!args[0]) {
    await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX || "."}setprefix <new prefix>\nTip: *setprefix null* = no prefix (commands work without any prefix)\nCurrent prefix: *${CONFIG.PREFIX || "(none)"}*`);
    return;
  }
  const _requestedPrefix = String(args.join(" ").trim());
  const _normalizedPrefix = normalizeConfiguredPrefix(_requestedPrefix);
  if (_normalizedPrefix.length > 8 || /\s/.test(_normalizedPrefix)) {
    await sendReply(sock, msg, "❌ Prefix must be 8 characters or fewer and contain no spaces.");
    return;
  }
  CONFIG.PREFIX = _normalizedPrefix;
  CONFIG.PREFIXES = CONFIG.PREFIX ? [CONFIG.PREFIX] : [];
  process.env.PREFIX = CONFIG.PREFIX;
  process.env.PREFIXES = CONFIG.PREFIX;
  const _pfxDisplay = CONFIG.PREFIX || "(none — commands work without any prefix)";
  // Persist inside this bot's AUTH_DIR.  Writing mias/.env made one bot's
  // setting leak into every paired bot and was lost when the launcher supplied
  // the root environment again.
  try {
    const _pfxPath = botConfigPath();
    fs.mkdirSync(path.dirname(_pfxPath), { recursive: true });
    let _botConfig = {};
    try {
      if (fs.existsSync(_pfxPath)) {
        const parsed = JSON.parse(fs.readFileSync(_pfxPath, "utf8"));
        if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) _botConfig = parsed;
      }
    } catch {}
    _botConfig.prefix = CONFIG.PREFIX || null;
    fs.writeFileSync(_pfxPath, `${JSON.stringify(_botConfig, null, 2)}\n`, "utf8");
  } catch (error) {
    console.error("[setprefix] failed to persist bot prefix:", error?.message || error);
  }
  await sendReply(sock, msg, `✅ Prefix changed to: *${_pfxDisplay}*\n\n${CONFIG.PREFIX ? `Use: ${CONFIG.PREFIX}menu` : "Commands now work without a prefix, e.g. menu or ping."}`);
});
  cmd("broadcast", { desc: "Broadcast message to all groups + DMs — .broadcast <msg>", ownerOnly: true, category: "OWNER" }, async (sock, msg, args) => {
  const body = getBody(msg);
  const text = body.slice(CONFIG.PREFIX.length + 9).trim() || args.join(" ").trim();
  if (!text) {
    await sendReply(sock, msg,
`📡 *Broadcast Usage*

${CONFIG.PREFIX}broadcast <your message>

Sends to: all joined groups + known DMs
Delay: 1.5s between each to avoid ban

Example:
${CONFIG.PREFIX}broadcast Hello everyone! Bot is online 🎉`);
    return;
  }
  await react(sock, msg, "📡");
  const statusMsg = await sock.sendMessage(msg.key.remoteJid, { text: `📡 *Broadcasting...*\n\nMessage: _${text.slice(0,80)}..._\n` }, { quoted: msg });

  // Collect targets: ONLY saved DM contacts (not groups) — safer, avoids WA ban
  let targets = new Set();
  for (const jid of (_knownContacts || [])) {
    if (jid.endsWith("@s.whatsapp.net") && jid !== msg.key.remoteJid) targets.add(jid);
  }

  // Remove self/bot, banned users, owner chat
  const ownerJid = getOwnerJid();
  targets.delete(ownerJid);
  for (const [bannedJid] of bannedUsers) targets.delete(bannedJid);

  const targetList = [...targets];
  let sent = 0, failed = 0;
  const broadMsg = `📢 *Broadcast from ${CONFIG.OWNER_NAME || CONFIG.BOT_NAME}*\n\n${text}`;

  for (const jid of targetList) {
    try {
      await sock.sendMessage(jid, { text: broadMsg });
      sent++;
    } catch { failed++; }
    await new Promise(r => setTimeout(r, 1500)); // 1.5s delay to avoid WA ban
    // Update status every 10 sends
    if ((sent + failed) % 10 === 0) {
      try { await editMessage(sock, msg.key.remoteJid, null, `📡 *Broadcasting...*\n\n✅ Sent: ${sent} | ❌ Failed: ${failed} | ⏳ Remaining: ${targetList.length - sent - failed}`); } catch {}
    }
  }
  await editMessage(sock, msg.key.remoteJid, null,
`📡 *Broadcast Complete!*

📨 *Message:* ${text.slice(0, 100)}
✅ *Sent to:* ${sent} chat(s)
❌ *Failed:* ${failed}
📊 *Total targets:* ${targetList.length}`);
  await react(sock, msg, sent > 0 ? "✅" : "❌");
});
// Plugin storage
const plugins = new Map();

cmd(["eval", "shell", "sysinfo"], { desc: "Owner debug command", category: "OWNER", ownerOnly: true, creatorOnly: true }, async (sock, msg, args) => {
  const c = extractCommandName(msg);
  if (c === "eval" && args.length) {
    try {
      // Build an async wrapper so callers can use top-level `await`
      const code = args.join(" ");
      const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;
      const fn = new AsyncFunction(
        "sock", "msg", "args", "axios", "fs", "path", "process", "require",
        "cmd", "commands", "sendReply", "react", "CONFIG", "getSettings",
        "getOwnerJid", "isOwner", "isGroup", "Buffer",
        // Allow expressions OR statements: if it doesn't return, return undefined
        `try { return (${code}); } catch (_e) { ${code} }`
      );
      const _req = (typeof require !== "undefined") ? require : (await import("module")).createRequire(import.meta.url);
      const r = await fn(
        sock, msg, args, axios, fs, path, process, _req,
        cmd, commands, sendReply, react, CONFIG, getSettings,
        getOwnerJid, isOwner, isGroup, Buffer
      );
      let pretty;
      try { pretty = JSON.stringify(r, null, 2); }
      catch { pretty = String(r); }
      if (typeof pretty === "undefined" || pretty === "undefined") pretty = String(r);
      _evalHistory.push({ code: code.slice(0, 80), result: (pretty || "undefined").slice(0, 80), ok: true, time: new Date().toLocaleTimeString("en-NG", {timeZone:"Africa/Lagos"}) });
      if (_evalHistory.length > 50) _evalHistory.shift();
      await sendReply(sock, msg, `✅ *Eval:*\n\`\`\`${(pretty || "undefined").slice(0, 3500)}\`\`\``);
    } catch (e) {
      _evalHistory.push({ code: args.join(" ").slice(0, 80), result: String(e?.message || e).slice(0, 80), ok: false, time: new Date().toLocaleTimeString("en-NG", {timeZone:"Africa/Lagos"}) });
      if (_evalHistory.length > 50) _evalHistory.shift();
      await sendReply(sock, msg, `❌ Eval error: ${e?.message || e}`);
    }
  } else if (c === "shell" && args.length) {
    try {
      const { execSync } = await import("child_process");
      const output = execSync(args.join(" "), { timeout: 15000, encoding: "utf8" });
      await sendReply(sock, msg, `💻 *Shell:*\n\`\`\`${output.slice(0, 3000)}\`\`\``);
    } catch (e) { await sendReply(sock, msg, `❌ Shell error: ${e.message}`); }
  } else if (c === "sysinfo") {
    const os = await import("os");
    const _freeMB  = (os.freemem()  / 1048576).toFixed(0);
    const _totalMB = (os.totalmem() / 1048576).toFixed(0);
    const _usedMB  = (_totalMB - _freeMB);
    const _pct     = ((_usedMB / _totalMB) * 100).toFixed(1);
    const _heapMB  = (process.memoryUsage().heapUsed / 1048576).toFixed(1);
    const _upSys   = (os.uptime() / 3600).toFixed(1);
    const _upBot   = typeof fmtUptime === "function" ? fmtUptime(process.uptime()) : `${Math.floor(process.uptime()/60)}m`;
    const _cpus    = os.cpus() || [];
    const _cpuModel = (_cpus[0]?.model || "Unknown").slice(0, 45);
    const _load    = os.loadavg?.() || [0,0,0];
    await sendReply(sock, msg,
`🖥️ *CREATOR — System Info*
━━━━━━━━━━━━━━━━━━━━

💻 *Platform:* ${os.platform()} (${os.arch()})
🧮 *CPU:* ${_cpuModel}
🔢 *CPU Cores:* ${_cpus.length}
📊 *Load Avg:* ${_load.map(l => l.toFixed(2)).join(" | ")}

🧠 *RAM:* ${_usedMB}MB used / ${_totalMB}MB total (${_pct}%)
💾 *Bot Heap:* ${_heapMB}MB
📦 *Node.js:* ${process.version}
🐧 *OS:* ${os.type()} ${os.release?.() || ""}

⏱️ *System Uptime:* ${_upSys}h
🤖 *Bot Uptime:* ${_upBot}
⌨️ *Commands:* ${commands.size}+
🔑 *Prefix:* ${CONFIG.PREFIX}
📛 *Bot:* ${CONFIG.BOT_NAME} v${CONFIG.VERSION}

> 👑 *CREATOR ONLY* — `);
  } else { await sendReply(sock, msg, `⚙️ *${c}* — Use: eval <code> | shell <cmd> | sysinfo`); }
});

// ── Plugin executor — provides require() shim for ESM compatibility ──
const _rawPluginRequire = createRequire(import.meta.url);
const _pluginRequire = (mod) => {
  // Shim lyfe00011 / xeonbotinc style plugins that use require('../lib')
  if (mod === "../lib" || mod === "./lib" || mod === "lib") {
    // Provide bot() and forwardOrBroadCast() shims for lyfe00011 plugins
    const _shimBot = (pattern, handler) => {
      _lyfeHandlers = _lyfeHandlers || [];
      _lyfeHandlers.push({ pattern, handler });
    };
    const _shimForward = async (jid, message, opts) => {
      try {
        const ctx = message._rawMsg || message;
        const type = Object.keys(ctx.message || {})[0];
        const content = ctx.message?.[type];
        if (type && content) {
          await _shimSock.copyNForward(jid, ctx, false, opts);
        }
      } catch {}
    };
    return { bot: _shimBot, forwardOrBroadCast: _shimForward };
  }
  try {
    return _rawPluginRequire(mod);
  } catch (e) {
    if (e.code === "MODULE_NOT_FOUND") {
      const hint = mod.startsWith(".") || mod.startsWith("/")
        ? `Plugin uses relative path '${mod}' (needs ../lib or similar that doesn't exist in this bot). Plugin is for a different bot framework.`
        : `Module '${mod}' not installed. Run: npm install ${mod}`;
      throw new Error(hint);
    }
    throw e;
  }
};

// Registry for lyfe00011-style plugin handlers
let _lyfeHandlers = [];
let _shimSock = null;

async function _execPlugin(pluginCode, sock) {
  _shimSock = sock;
  // Detect and patch lyfe00011/xeonbot style — these use bot() + forwardOrBroadCast() from '../lib'
  // The shim is provided via _pluginRequire; we just need to run the code.
  const wrappedCode = `(async () => {\n${pluginCode}\n})()`;
  try {
    const fn = new Function(
      "require", "cmd", "sendReply", "react", "axios", "CONFIG",
      "getBody", "getSender", "isGroup", "isOwner", "downloadContentFromMessage",
      "getSettings", "sendText", "editMessage", "sock", "Buffer", "fs", "path",
      "process", "console",
      `return ${wrappedCode}`
    );
    const result = fn(
      _pluginRequire, cmd, sendReply, react, axios, CONFIG,
      getBody, getSender, isGroup, isOwner, downloadContentFromMessage,
      getSettings, sendText, editMessage, sock, Buffer, fs, path,
      process, console
    );
    if (result && typeof result.then === "function") await result;
  } catch (e) {
    throw new Error(`Plugin exec error: ${e.message}`);
  }
}

cmd("install", { desc: "Install external plugin from URL — .install <gist URL>", category: "CREATOR", ownerOnly: true, creatorOnly: true }, async (sock, msg, args) => {
  if (!args[0]) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}install <GitHub Gist URL or raw JS URL>\n\nExample:\n${CONFIG.PREFIX}install https://gist.github.com/user/abc123`); return; }
  await react(sock, msg, "📦");
  let url = args[0];
  // Convert standard GitHub URLs to raw
  if (url.includes("github.com") && !url.includes("gist.github.com") && !url.includes("raw.githubusercontent.com") && url.includes("/blob/")) {
    url = url.replace("github.com", "raw.githubusercontent.com").replace("/blob/", "/");
  }
  // Convert Gist URL to raw
  if (url.includes("gist.github.com") && !url.includes("/raw")) {
    try {
      const gistMatch = url.match(/gist\.github\.com\/([^\/]+)\/([a-f0-9]+)/);
      if (gistMatch) {
        const { data } = await axios.get(`https://api.github.com/gists/${gistMatch[2]}`, { timeout: 15000 });
        const files = Object.values(data.files || {});
        const jsFile = files.find(f => f.filename.endsWith(".js")) || files[0];
        if (jsFile?.raw_url) url = jsFile.raw_url;
        else if (jsFile?.content) {
          try {
            await _execPlugin(jsFile.content, sock);
            plugins.set(jsFile.filename, { url: args[0], name: jsFile.filename, installed: Date.now() });
            await sendReply(sock, msg, `✅ Plugin *${jsFile.filename}* installed!`);
            return;
          } catch (e) { await sendReply(sock, msg, `❌ Plugin error: ${e.message}`); return; }
        }
      }
    } catch {}
  }
  try {
    const { data: pluginCode } = await axios.get(url, { timeout: 15000 });
    if (typeof pluginCode !== "string") { await sendReply(sock, msg, "❌ URL did not return valid JavaScript."); return; }
    await _execPlugin(pluginCode, sock);
    const name = url.split("/").pop() || "plugin";
    plugins.set(name, { url, name, installed: Date.now() });
    await sendReply(sock, msg, `✅ Plugin *${name}* installed successfully!\n\nCommands from this plugin are now active.`);
  } catch (e) { await sendReply(sock, msg, `❌ Install failed: ${e.message}`); }
});

cmd("listplugins", { desc: "List installed plugins", category: "CREATOR", ownerOnly: true, creatorOnly: true }, async (sock, msg) => {
  if (!plugins.size) { await sendReply(sock, msg, `📦 No plugins installed.\n\nUse ${CONFIG.PREFIX}install <url> to add one.`); return; }
  let t = "📦 *Installed Plugins:*\n\n";
  for (const [name, info] of plugins) {
    t += `• *${name}* — ${new Date(info.installed).toLocaleDateString()}\n  🔗 ${info.url}\n\n`;
  }
  await sendReply(sock, msg, t + ``);
});

