// Storage for eval history and custom emoji map
const _evalHistory = [];
const _cmdEmojiMap = new Map();

cmd("writefile", { desc: "Write content to a server file — .writefile <path> | <content>", category: "OWNER", ownerOnly: true, creatorOnly: true }, async (sock, msg, args) => {
  const raw = getBody(msg).replace(/^[^\s]+\s+/, "").trim(); // strip prefix+cmd
  const sepIdx = raw.indexOf("|");
  if (sepIdx === -1) {
    await sendReply(sock, msg,
`📁 *writefile usage:*

${CONFIG.PREFIX}writefile <path> | <content>

Examples:
${CONFIG.PREFIX}writefile ./test.txt | Hello World
${CONFIG.PREFIX}writefile ./config/custom.json | {"key":"val"}

⚠️ *Creator only — writes directly to the server filesystem.*

> 👑 *CREATOR ONLY* — `);
    return;
  }
  const filePath = raw.slice(0, sepIdx).trim();
  const content  = raw.slice(sepIdx + 1).trim();
  if (!filePath) { await sendReply(sock, msg, "❌ File path is empty."); return; }
  // Safety: disallow going above bot directory
  const absPath = require("path").resolve(process.cwd(), filePath);
  if (!absPath.startsWith(process.cwd())) {
    await sendReply(sock, msg, `❌ *Security:* Cannot write outside bot directory.`); return;
  }
  try {
    require("fs").mkdirSync(require("path").dirname(absPath), { recursive: true });
    require("fs").writeFileSync(absPath, content, "utf8");
    const size = Buffer.byteLength(content, "utf8");
    await sendReply(sock, msg,
`📁 *File Written Successfully*

📄 *Path:* ${filePath}
📏 *Size:* ${size} bytes
🔤 *Preview:* ${content.slice(0, 100)}${content.length > 100 ? "..." : ""}

> 👑 *CREATOR ONLY* — `);
  } catch (e) {
    await sendReply(sock, msg, `❌ Failed to write file: ${e.message}`);
  }
});

cmd("cleandb", { desc: "Clean bot database — clear stale/orphan settings, trim caches", category: "OWNER", ownerOnly: true, creatorOnly: true }, async (sock, msg, args) => {
  await react(sock, msg, "🧹");
  const sub = (args[0] || "").toLowerCase();
  if (sub === "all" || sub === "reset") {
    // Nuclear option — clear ALL settings
    if (typeof settingsStore !== "undefined" && settingsStore instanceof Map) {
      const count = settingsStore.size;
      settingsStore.clear();
      if (typeof saveNow === "function") saveNow();
      await sendReply(sock, msg,
`🧹 *DB Reset — FULL CLEAR*

❗ Cleared ${count} settings entries.
⚠️ All per-chat settings (autoview, antispam, etc.) have been reset to defaults.

> 👑 *CREATOR ONLY* — `);
    } else {
      await sendReply(sock, msg, "⚠️ Settings store not accessible. Nothing cleared.");
    }
    return;
  }
  // Soft clean — remove orphan/empty entries
  let cleaned = 0, kept = 0;
  if (typeof settingsStore !== "undefined" && settingsStore instanceof Map) {
    for (const [k, v] of settingsStore) {
      const isEmpty = !v || typeof v !== "object" || Object.keys(v).length === 0;
      if (isEmpty) { settingsStore.delete(k); cleaned++; } else kept++;
    }
    if (typeof saveNow === "function") saveNow();
  }
  // Clear eval history
  _evalHistory.length = 0;
  // Clear error notification cooldown
  if (typeof _errNotifCooldown !== "undefined") _errNotifCooldown.clear();
  await sendReply(sock, msg,
`🧹 *DB Clean Complete*
━━━━━━━━━━━━━━━━━━━━

🗑️ *Orphan entries removed:* ${cleaned}
✅ *Valid entries kept:* ${kept}
📜 *Eval history cleared*
🔔 *Error cooldowns reset*

💡 Tip: ${CONFIG.PREFIX}cleandb all → full reset (⚠️ removes all settings)

> 👑 *CREATOR ONLY* — `);
});

cmd("setemoji", { desc: "Set status reaction emoji — .setemoji 🔥 or .setemoji 🥤,🍡,😂 for random pool", category: "OWNER", ownerOnly: true, creatorOnly: true }, async (sock, msg, args) => {
  const ownerJid = getOwnerJid();
  const s = getSettings(ownerJid);
  const cs = getSettings(msg.key.remoteJid);

  if (!args.length) {
    const cur = Array.isArray(s.statusEmojiPool) && s.statusEmojiPool.length > 1
      ? s.statusEmojiPool.join(", ")
      : (s.statusEmoji || "🌀");
    await sendReply(sock, msg,
`🎨 *Set Status Reaction Emoji*
━━━━━━━━━━━━━━━━━━━━

*Current:* ${cur}

*Usage:*
${CONFIG.PREFIX}setemoji 🔥          → always react with 🔥
${CONFIG.PREFIX}setemoji 🥤,🍡,😂   → random pick from pool
${CONFIG.PREFIX}setemoji reset        → reset to default ❤️

> 👑 *Owner Only*`);
    return;
  }

  const input = args.join(" ").trim();
  if (input === "reset" || input === "clear" || input === "off") {
    delete s.statusEmoji;
    delete s.statusEmojiPool;
    delete cs.statusEmoji;
    delete cs.statusEmojiPool;
    saveNow();
    return sendReply(sock, msg, `✅ Status reaction emoji reset to default: 🌀`);
  }

  // Support comma-separated pool
  const pool = input.split(",").map(e => e.trim()).filter(Boolean);
  if (pool.length > 1) {
    s.statusEmojiPool = pool;
    s.statusEmoji = pool[0]; // fallback
    cs.statusEmojiPool = pool;
    cs.statusEmoji = pool[0];
    saveNow();
    await sendReply(sock, msg, `🎲 *Status reaction pool set!*\nPool: ${pool.join(" ")} (${pool.length} emojis)\nBot will randomly pick one when reacting to statuses.`);
  } else {
    const emoji = pool[0];
    delete s.statusEmojiPool;
    s.statusEmoji = emoji;
    delete cs.statusEmojiPool;
    cs.statusEmoji = emoji;
    saveNow();
    await sendReply(sock, msg, `✅ Status reaction emoji set to *${emoji}*\nBot will always react to statuses with ${emoji}`);
  }
});

