cmd("autoview", { desc: "Auto-view statuses — .autoview on/off | exclude <num> | unexclude <num> | listexclude", category: "OWNER", ownerOnly: true }, async (sock, msg, args) => {
    const ownerJid = getOwnerJid();
    const s = getSettings(ownerJid);
    if (!Array.isArray(s.viewStatusExclude)) s.viewStatusExclude = [];
    const v = (args[0] || '').toLowerCase();
    // ── exclude muted on/off
    if (v === "excludemuted" || v === "exclude-muted") {
      const subVal = (args[1] || '').toLowerCase();
      const _on  = ['on','1','enable','true'].includes(subVal);
      const _off = ['off','0','disable','false'].includes(subVal);
      if (!subVal || (!_on && !_off)) {
        await sendReply(sock, msg, `👁️ *AutoView Exclude Muted*\n\nCurrent: ${s.viewStatusExcludeMuted ? '✅ ON' : '❌ OFF'}\n\nUsage: ${CONFIG.PREFIX}autoview excludemuted on/off\n\nWhen ON, the bot will skip viewing statuses from contacts you have muted on WhatsApp.`);
        return;
      }
      s.viewStatusExcludeMuted = _on;
      saveNow();
      await sendReply(sock, msg, `👁️ *AutoView Exclude Muted: ${_on ? '✅ ON' : '❌ OFF'}*\n\n${_on ? '✅ Bot will now skip statuses from contacts you have muted.' : '❌ Bot will view statuses from all contacts including muted ones.'}`);
      return;
    }
    // ── exclude / unexclude / list
    if (v === "exclude" || v === "block") {
      const num = (args[1] || "").replace(/[^0-9]/g, "");
      if (!num) { await sendReply(sock, msg, `❌ Usage: ${CONFIG.PREFIX}autoview exclude <number>`); return; }
      if (!s.viewStatusExclude.includes(num)) s.viewStatusExclude.push(num);
      saveNow();
      await sendReply(sock, msg, ` *AutoView Exclude*\n\n✅ +${num} will no longer be auto-viewed.\nExcluded (${s.viewStatusExclude.length}): ${s.viewStatusExclude.join(", ")}`);
      return;
    }
    if (v === "unexclude" || v === "unblock") {
      const num = (args[1] || "").replace(/[^0-9]/g, "");
      if (!num) { await sendReply(sock, msg, `❌ Usage: ${CONFIG.PREFIX}autoview unexclude <number>`); return; }
      s.viewStatusExclude = s.viewStatusExclude.filter(n => n !== num);
      saveNow();
      await sendReply(sock, msg, ` *AutoView Unexclude*\n\n✅ +${num} will now be auto-viewed again.\nRemaining excluded: ${s.viewStatusExclude.join(", ") || "None"}`);
      return;
    }
    if (v === "listexclude" || v === "list") {
      await sendReply(sock, msg, ` *AutoView Excluded Numbers*\n\n${s.viewStatusExclude.length ? s.viewStatusExclude.map(n => `• +${n}`).join("\n") : "None"}`);
      return;
    }
    if (v === "delay" || v === "queue" || v === "timer") {
      const _rawDv = (args[1] || "").toLowerCase().trim();
      if (!_rawDv) {
        const _curDv = Number(s.statusViewDelay) || 0;
        await sendReply(sock, msg,
`⏱️ *Status View Queue / Delay*
━━━━━━━━━━━━━━━━━━━━

📌 *Current:* ${_curDv ? `*${_curDv}s* delay per status` : "Instant (0s — no delay)"}

*Usage:*
${CONFIG.PREFIX}autoview delay <seconds>  — set delay
${CONFIG.PREFIX}autoview delay 0          — instant (default)

*Examples:*
• ${CONFIG.PREFIX}autoview delay 5   → wait 5s before each status view
• ${CONFIG.PREFIX}autoview delay 30  → 30s queue delay
• ${CONFIG.PREFIX}autoview delay 120 → 2-minute delay (natural-looking)
• ${CONFIG.PREFIX}autoview delay 0   → instant view

_Delay mimics real human viewing behavior. Max: 300s (5 min)._`);
        return;
      }
      const _dvNum = parseInt(_rawDv, 10);
      if (isNaN(_dvNum) || _dvNum < 0) { await sendReply(sock, msg, `❌ Invalid delay. Use a number in seconds, e.g. *${CONFIG.PREFIX}autoview delay 5*`); return; }
      s.statusViewDelay = Math.min(300, _dvNum);
      saveNow();
      await sendReply(sock, msg, `⏱️ *Status View Delay: ${s.statusViewDelay}s*\n\n${s.statusViewDelay ? `✅ Bot will wait *${s.statusViewDelay} second(s)* before marking each status as viewed.\n_Mimics natural human viewing behavior — queue active._` : "✅ Bot will view statuses instantly (no queue delay)."}`);
      return;
    }
    if (['on','1','enable','true'].includes(v)) {
      if (s.viewStatus === true) { await sendReply(sock, msg, ` Auto View Status is *already ON* ✅`); return; }
      s.viewStatus = true;
    } else if (['off','0','disable','false'].includes(v)) {
      if (s.viewStatus === false) { await sendReply(sock, msg, ` Auto View Status is *already OFF* ❌`); return; }
      s.viewStatus = false;
    } else s.viewStatus = !s.viewStatus;
    // Also set on current chat settings to persist properly
    const cs = getSettings(msg.key.remoteJid);
    cs.viewStatus = s.viewStatus;
    saveNow();
    await sendReply(sock, msg, ` *Auto View Status: ${s.viewStatus ? '✅ ON' : '❌ OFF'}*\n\n${s.viewStatus ? '✅ Bot will automatically view ALL statuses from your contacts.' : '❌ Bot will NOT auto-view statuses.'}\n\nTip: ${CONFIG.PREFIX}autoview on / off\n💡 Exclude number: ${CONFIG.PREFIX}autoview exclude <number>\n🔇 Skip muted contacts: ${CONFIG.PREFIX}autoview excludemuted on/off\n   Muted skip is: ${s.viewStatusExcludeMuted ? '✅ ON' : '❌ OFF'}`);
  });
  cmd("autolike", { desc: "Auto-react/like statuses — .autolike on/off | 🔥 | 🥤,🍡,😂 (random pool)", category: "OWNER", ownerOnly: true }, async (sock, msg, args) => {
    const ownerJid = getOwnerJid();
    const s = getSettings(ownerJid);
    const v = (args[0] || '').toLowerCase();
    const isSwitch = ['on','1','enable','true','off','0','disable','false'].includes(v);
    if (['on','1','enable','true'].includes(v)) {
      if (s.reactStatus === true) { await sendReply(sock, msg, `❤️ Auto Like is *already ON* ✅`); return; }
      s.reactStatus = true;
    } else if (['off','0','disable','false'].includes(v)) {
      if (s.reactStatus === false) { await sendReply(sock, msg, `❤️ Auto Like is *already OFF* ❌`); return; }
      s.reactStatus = false;
    } else if (!args.length) {
      s.reactStatus = !s.reactStatus;
    }
    // Handle emoji — single or comma-separated pool
    const emojiArg = !isSwitch && args[0] ? args[0] : (args[1] || null);
    if (emojiArg) {
      const pool = emojiArg.split(",").map(e => e.trim()).filter(Boolean);
      if (pool.length > 1) {
        s.statusEmojiPool = pool;
        s.statusEmoji = pool[0];
      } else {
        delete s.statusEmojiPool;
        s.statusEmoji = pool[0];
      }
    }
    // Persist on current chat too
    const cs = getSettings(msg.key.remoteJid);
    cs.reactStatus = s.reactStatus;
    cs.statusEmoji = s.statusEmoji;
    cs.statusEmojiPool = s.statusEmojiPool;
    saveNow();
    const emojiDisplay = Array.isArray(s.statusEmojiPool) && s.statusEmojiPool.length > 1
      ? s.statusEmojiPool.join(" ") + " *(random)*"
      : (s.statusEmoji || '❤️');
    await sendReply(sock, msg,
`${s.statusEmoji || '❤️'} *Auto Like/React Status: ${s.reactStatus ? '✅ ON' : '❌ OFF'}*

${s.reactStatus
  ? '✅ Bot will automatically react to ALL statuses with: ' + emojiDisplay
  : '❌ Bot will NOT auto-react to statuses.'}

Tip: ${CONFIG.PREFIX}autolike on
Tip: ${CONFIG.PREFIX}autolike off
Tip: ${CONFIG.PREFIX}autolike 🔥        — single emoji
Tip: ${CONFIG.PREFIX}autolike 🔥,🌊,⭐  — random pool
Tip: ${CONFIG.PREFIX}setemoji 🥤,🍡,😂  — set pool separately`);
  });
  // ═══════════════════════════════════════════════════════════════════════════════
//  LOGOUT COMMAND — ask keep/delete then disconnect
// ═══════════════════════════════════════════════════════════════════════════════
if (!globalThis._logoutPending) globalThis._logoutPending = new Map();
cmd(["logout", "signout", "unlink"], { desc: "Logout this bot session — asks to keep or delete sessions/settings", category: "OWNER", ownerOnly: true }, async (sock, msg) => {
  const ownerJid = getOwnerJid();
  const senderJid = getSender(msg);
  if (!senderJid) return;
  const pendingKey = (sock.user?.id || "").split(":")[0].split("@")[0] || "bot";
  if (globalThis._logoutPending.has(pendingKey)) {
    return sendReply(sock, msg, "⏳ Logout confirmation already pending. Reply *YES* or *NO*.");
  }
  globalThis._logoutPending.set(pendingKey, {
    chatJid: msg.key.remoteJid,
    ownerJid,
    ts: Date.now(),
  });
  await sendReply(sock, msg,
`⚠️ *Logout Requested*
━━━━━━━━━━━━━━━━━━━━

You are about to *disconnect this bot session* from WhatsApp.

Do you want to keep your sessions and settings (so you can re-pair without losing data), or delete everything?

Reply in this chat:
• *YES* — logout and KEEP all sessions/settings
• *NO*  — logout and DELETE all sessions/settings

This request expires in 2 minutes. Type anything else to cancel.`);
  // Auto-expire after 2 minutes
  setTimeout(() => {
    if (globalThis._logoutPending.has(pendingKey)) {
      globalThis._logoutPending.delete(pendingKey);
      try { sendReply(sock, msg, `⏰ Logout request expired. No action taken.`); } catch {}
    }
  }, 2 * 60 * 1000);
});

// ── Interceptor: handle YES/NO reply to logout pending prompt ───────────────
// Hooked into message processing: see below (guarded by _logoutPending check)
globalThis._handleLogoutReply = async (sock, msg) => {
  try {
    const pendingKey = (sock.user?.id || "").split(":")[0].split("@")[0] || "bot";
    const pending = globalThis._logoutPending.get(pendingKey);
    if (!pending) return false;
    if (Date.now() - pending.ts > 2 * 60 * 1000) {
      globalThis._logoutPending.delete(pendingKey);
      return false;
    }
    if (msg.key.remoteJid !== pending.chatJid) return false;
    const senderJid = getSender(msg);
    const ownerJid = getOwnerJid();
    if (!senderJid || _cleanNum(senderJid) !== _cleanNum(ownerJid)) return false;
    const body = (getBody(msg) || "").trim().toUpperCase();
    if (body !== "YES" && body !== "NO") {
      globalThis._logoutPending.delete(pendingKey);
      await sendReply(sock, msg, "❌ Logout cancelled.");
      return true;
    }
    const keepFiles = (body === "YES");
    globalThis._logoutPending.delete(pendingKey);
    await sendReply(sock, msg,
      keepFiles
        ? "🔒 Logging out... Your session files are *KEPT*. Re-pair anytime with .pair"
        : "🗑️ Logging out... All session files will be *DELETED*.");
    await new Promise(r => setTimeout(r, 1200));
    if (!keepFiles) {
      try { require('../sessionPaths').quarantineDir(AUTH_DIR, 'stale/logout session — quarantined, never deleted'); } catch {}
    }
    try { await sock.logout(); } catch {}
    return true;
  } catch { return false; }
};

