  // Populated by .setcmd when a sticker is replied to.
  const stickerTriggers = new Map();
cmd("setcmd", { desc: "Set custom command (text or replied sticker)", category: "OWNER", ownerOnly: true }, async (sock, msg, args) => {
  const q = msg.message?.extendedTextMessage?.contextInfo?.quotedMessage;
  const quotedSticker = q?.stickerMessage;
  const name = (args[0] || "").toLowerCase();
  if (!name) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}setcmd <name> <response>
Or reply to a sticker with ${CONFIG.PREFIX}setcmd <name>`); return; }
  if (quotedSticker) {
      try {
        const stream = await downloadContentFromMessage(quotedSticker, "sticker");
        let buf = Buffer.from([]);
        for await (const chunk of stream) buf = Buffer.concat([buf, chunk]);
        // Save sticker as the bot's response when .name is typed
        customCmds.set(name, { type: "sticker", data: buf.toString("base64") });
        // ── Register the sticker itself as a trigger ──────────────────────────────
        // fileSha256 uniquely identifies the sticker. When anyone sends this
        // exact sticker the bot will fire a reply (text or run the custom cmd).
        const _sha256Key = quotedSticker.fileSha256
          ? Buffer.from(quotedSticker.fileSha256).toString("base64")
          : null;
        const _responseText = args.slice(1).join(" ").trim() || null;
        if (_sha256Key) {
          stickerTriggers.set(_sha256Key, { name, response: _responseText });
        }
        const _trigNote = _sha256Key
          ? `\n\n📌 *Sticker trigger set!*\nSending this sticker will ${_responseText ? `make me reply: _${_responseText}_` : `run *${CONFIG.PREFIX}${name}* (sends the sticker back)`}`
          : "";
        await sendReply(sock, msg, `✅ Sticker command *${name}* saved!${_trigNote}`);
        return;
      } catch (e) {
        await sendReply(sock, msg, `❌ Failed to save sticker command: ${e.message}`);
        return;
      }
    }
  if (args.length < 2) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}setcmd <name> <response>`); return; }
  const response = args.slice(1).join(" ");
  customCmds.set(name, { type: "text", text: response });
  await sendReply(sock, msg, `✅ Custom command *${name}* set!

Response: ${response}`);
});
cmd("removecmd", { desc: "Remove custom command", category: "OWNER", ownerOnly: true }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}removecmd <name>`); return; }
  const name = args[0].toLowerCase();
    // Also remove any sticker trigger linked to this command name
    for (const [_sha, _trig] of stickerTriggers.entries()) { if (_trig.name === name) stickerTriggers.delete(_sha); }
    if (customCmds.delete(name)) { await sendReply(sock, msg, `✅ Custom command *${name}* removed! (sticker trigger also cleared if any)`); }
    else { await sendReply(sock, msg, `❌ Command *${name}* not found.`); }
});
cmd("listsetcmd", { desc: "List custom commands", category: "OWNER", ownerOnly: true }, async (sock, msg) => {
  if (!customCmds.size) { await sendReply(sock, msg, "📋 No custom commands set."); return; }
  let txt = "📋 *Custom Commands*\n\n";
  customCmds.forEach((v, k) => {
      if (typeof v === "string") txt += `• ${CONFIG.PREFIX}${k} → ${v.slice(0,50)}\n`;
      else if (v?.type === "sticker") txt += `• ${CONFIG.PREFIX}${k} → [sticker response]\n`;
      else txt += `• ${CONFIG.PREFIX}${k} → ${(v?.text || "").slice(0,50)}\n`;
    });
    if (stickerTriggers.size) {
      txt += `\n🎴 *Sticker Triggers* (${stickerTriggers.size})\n`;
      stickerTriggers.forEach((v) => {
        txt += `• [sticker] → ${v.response ? v.response.slice(0,50) : `run *${CONFIG.PREFIX}${v.name}*`}\n`;
      });
    }
  await sendReply(sock, msg, txt);
});
