// Universal downloader with fallback chain
async function universalDownload(url, platform) {
  const apis = [
    // Prexzyvilla AIO (primary — works for all social platforms)
    async () => {
      const r = await prexzyGet("/download/aio", { url }, 30000);
      const d = r.data;
      if (!r.ok || !d) return;
      const dl = d?.data?.[0]?.url || d?.data?.video || d?.data?.audio || d?.data?.url || d?.url;
      const title = d?.data?.title || d?.title || platform;
      if (dl) return { dl, title };
    },
    // Cobalt.tools — best universal downloader
    async () => {
      const { data } = await axios.post("https://api.cobalt.tools/", {
        url, downloadMode: "auto", filenameStyle: "basic"
      }, { headers: { "Accept": "application/json", "Content-Type": "application/json" }, timeout: 30000 });
      if (data?.url) return { dl: data.url, title: data?.filename || platform };
      if (data?.picker) return { dl: data.picker[0]?.url, title: platform, picker: data.picker };
    },
    // GiftedTech
    async () => {
      const ep = { tiktok: "tiktok", twitter: "twitter", facebook: "facebook", instagram: "instagram",
        spotify: "spotify", snapchat: "snapchat", capcut: "capcut", threads: "threads",
        pinterest: "pinterest", mediafire: "mediafire", gdrive: "gdrive", soundcloud: "soundcloud",
        linkedin: "linkedin", reddit: "reddit" }[platform] || platform;
      const { data } = await axios.get(`${CONFIG.GIFTED_API}/api/download/${ep}?apikey=${CONFIG.GIFTED_KEY}&url=${encodeURIComponent(url)}`, { timeout: 30000 });
      if (data?.success && data?.result) {
        const r = data.result;
        return { dl: r.download_url || r.url || r.video || r.audio || r.mp4 || r.mp3 || r.image, title: r.title || platform };
      }
    },
    // Siputzx
    async () => {
      const { data } = await axios.get(`https://api.siputzx.my.id/api/d/${platform}?url=${encodeURIComponent(url)}`, { timeout: 20000 });
      const r = data?.data || data?.result;
      if (r) return { dl: r.url || r.download || r.video || r.audio || r.mp4, title: r.title || platform };
    },
    // Nexoracle
    async () => {
      const { data } = await axios.get(`https://api.nexoracle.com/downloader/${platform}?apikey=free_key@maher_apis&url=${encodeURIComponent(url)}`, { timeout: 20000 });
      const r = data?.result || data?.data;
      if (r) return { dl: r.url || r.download || r.video || r.audio || r.mp4 || r.hd || r.sd, title: r.title || platform };
    },
    // Ryzendesu
    async () => {
      const { data } = await axios.get(`https://api.ryzendesu.vip/api/downloader/${platform}?url=${encodeURIComponent(url)}`, { timeout: 20000 });
      const r = data?.data || data?.result || data;
      if (r) return { dl: r.url || r.download || r.video || r.audio || r.mp4, title: r.title || platform };
    },
    // Widipe
    async () => {
      const { data } = await axios.get(`https://widipe.com/download/${platform}dl?url=${encodeURIComponent(url)}`, { timeout: 20000 });
      const r = data?.result || data?.data;
      if (r) return { dl: r.url || r.download || r.video || r.audio || r.mp4, title: r.title || platform };
    },
    // DavidCyril
    async () => {
      const { data } = await axios.get(`https://api.davidcyriltech.my.id/${platform}?url=${encodeURIComponent(url)}`, { timeout: 20000 });
      const r = data?.result || data;
      if (r) return { dl: r.video || r.url || r.download || r.audio || r.mp4, title: r.title || platform };
    },
    // Diio
    async () => {
      const { data } = await axios.get(`https://api.diioffc.web.id/api/download/${platform}?url=${encodeURIComponent(url)}`, { timeout: 20000 });
      const r = data?.result || data?.data;
      if (r) return { dl: r.url || r.download || r.video || r.mp4, title: r.title || platform };
    },
    // BK9
    async () => {
      const { data } = await axios.get(`https://bk9.fun/download/${platform}?url=${encodeURIComponent(url)}`, { timeout: 20000 });
      const r = data?.BK9 || data?.result || data?.data;
      if (r) return { dl: r.url || r.download || r.video || r.mp4, title: r.title || platform };
    },
    // Aemt
    async () => {
      const { data } = await axios.get(`https://aemt.me/download/${platform}?url=${encodeURIComponent(url)}`, { timeout: 20000 });
      const r = data?.result || data?.data;
      if (r) return { dl: r.url || r.download || r.video || r.mp4, title: r.title || platform };
    },
    // FastURL
    async () => {
      const { data } = await axios.get(`https://api.fasturl.cloud/download/${platform}?url=${encodeURIComponent(url)}`, { timeout: 20000 });
      const r = data?.result || data?.data;
      if (r) return { dl: r.url || r.download || r.video || r.mp4, title: r.title || platform };
    },
  ];
  for (const tryApi of apis) {
    try { const r = await tryApi(); if (r?.dl) return r; } catch { continue; }
  }
  return null;
}

const DL_PLATFORMS = {
  tiktok: { emoji: "🎵", name: "TikTok" },
  twitter: { emoji: "🐦", name: "Twitter/X" },
  // facebook handled separately with quality options

  instagram: { emoji: "📸", name: "Instagram" },
  spotify: { emoji: "🎧", name: "Spotify" },
  snapchat: { emoji: "👻", name: "Snapchat" },
  capcut: { emoji: "✂️", name: "CapCut" },
  threads: { emoji: "🧵", name: "Threads" },
  gdrive: { emoji: "☁️", name: "Google Drive" },
  soundcloud: { emoji: "🔊", name: "SoundCloud" },
  linkedin: { emoji: "💼", name: "LinkedIn" },
  reddit: { emoji: "🤖", name: "Reddit" },
};
// Dedicated MediaFire handler with multiple scrapers
for (const [pCmd, pInfo] of Object.entries(DL_PLATFORMS)) {
  cmd(pCmd, { desc: `Download from ${pInfo.name}`, category: "DOWNLOAD" }, async (sock, msg, args) => {
    if (!args.length) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}${pCmd} <URL>`); return; }
    await react(sock, msg, pInfo.emoji);
    const jid = msg.key.remoteJid;
    const statusMsg = await sock.sendMessage(jid, { text: `${pInfo.emoji} *MIAS MDX — ${pInfo.name}*\n\n⬡ Fetching media...\n◻ Downloading...\n◻ Sending...` }, { quoted: msg });
    const dlKey = statusMsg.key;
    try {
      const result = await universalDownload(args[0], pCmd);
      if (result?.dl) {
        await editMessage(sock, jid, dlKey, `${pInfo.emoji} *MIAS MDX — ${pInfo.name}*\n\n⬢ Fetching media... ✅\n⬡ Downloading...\n◻ Sending...`);
        const buf = await axios.get(result.dl, { responseType: "arraybuffer", timeout: 120000 });
        await editMessage(sock, jid, dlKey, `${pInfo.emoji} *MIAS MDX — ${pInfo.name}*\n\n⬢ Fetching media... ✅\n⬢ Downloading... ✅\n⬡ Sending...`);
        const ct = buf.headers?.["content-type"] || "";
        if (ct.includes("audio") || pCmd === "spotify" || pCmd === "soundcloud") {
          await sock.sendMessage(jid, { audio: Buffer.from(buf.data), mimetype: "audio/mpeg", ptt: false }, { quoted: msg });
        } else if (ct.includes("video") || result.dl.includes(".mp4")) {
          await sock.sendMessage(jid, { video: Buffer.from(buf.data), caption: `${pInfo.emoji} *${pInfo.name}*\n\n${result.title || ""}` }, { quoted: msg });
        } else {
          await sock.sendMessage(jid, { image: Buffer.from(buf.data), caption: `${pInfo.emoji} *${pInfo.name}*\n\n${result.title || ""}` }, { quoted: msg });
        }
        await editMessage(sock, jid, dlKey, `${pInfo.emoji} *MIAS MDX — ${pInfo.name}*\n\n⬢ Fetching media... ✅\n⬢ Downloading... ✅\n⬢ Sending... ✅\n\n✅ *Done!*`);
      } else {
        await editMessage(sock, jid, dlKey, `${pInfo.emoji} *MIAS MDX — ${pInfo.name}*\n\n⬢ Fetching media... ❌\n\n⚠️ Download failed. URL may be private or unsupported.`);
      }
    } catch (e) {
      await editMessage(sock, jid, dlKey, `${pInfo.emoji} *MIAS MDX — ${pInfo.name}*\n\n❌ Error: ${e.message}`);
    }
  });
}

// Facebook — with quality options (video/audio/document)
cmd(["facebook", "fb"], { desc: "Download from Facebook — .fb <URL> [video|audio|doc|hd]", category: "DOWNLOAD" }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `Usage:\n${CONFIG.PREFIX}fb <URL> — auto-detect\n${CONFIG.PREFIX}fb <URL> video — video\n${CONFIG.PREFIX}fb <URL> audio — audio only\n${CONFIG.PREFIX}fb <URL> doc — as document\n${CONFIG.PREFIX}fb <URL> hd — high quality`); return; }
  await react(sock, msg, "📘");
  const url = args[0];
  const mode = (args[1] || "").toLowerCase();
  const jid = msg.key.remoteJid;
  const statusMsg = await sock.sendMessage(jid, { text: `📘 *MIAS MDX — Facebook*\n\n⬡ Fetching media...\n◻ Downloading${mode ? " (" + mode + ")" : ""}...\n◻ Sending...` }, { quoted: msg });
  const dlKey = statusMsg.key;
  try {
    let result = null;

    // 1) Prexzyvilla /download/facebook — fast dedicated endpoint
    if (!result) {
      try {
        const rf = await prexzyGet("/download/facebook", { url }, 30000);
        const df = rf.data;
        if (rf.ok && df) {
          const _d = df?.data || df;
          const dl = (mode === "hd" ? (_d?.hd || _d?.sd) : (_d?.sd || _d?.hd)) || _d?.url || _d?.video || _d?.download_url;
          if (dl) result = { dl, title: _d?.title || "Facebook Video" };
        }
      } catch {}
    }

    // 2) Prexzyvilla /download/facebookv2 — alternative endpoint
    if (!result) {
      try {
        const rf2 = await prexzyGet("/download/facebookv2", { url }, 30000);
        const df2 = rf2.data;
        if (rf2.ok && df2) {
          const _d2 = df2?.data || df2;
          const dl = _d2?.hd || _d2?.sd || _d2?.url || _d2?.video || _d2?.download_url;
          if (dl) result = { dl, title: _d2?.title || "Facebook Video" };
        }
      } catch {}
    }

    // 3) GiftedTech
    if (!result) {
      try {
        const { data: gd } = await axios.get(`${CONFIG.GIFTED_API}/api/download/facebook?apikey=${CONFIG.GIFTED_KEY}&url=${encodeURIComponent(url)}`, { timeout: 30000 });
        if (gd?.success && gd?.result) {
          const gr = gd.result;
          const dl = (mode === "hd" ? (gr.hd || gr.sd) : (gr.sd || gr.hd)) || gr.download_url || gr.url || gr.video;
          if (dl) result = { dl, title: gr.title || "Facebook Video" };
        }
      } catch {}
    }

    // 4) universalDownload chain (cobalt, siputzx, ryzendesu, etc.)
    if (!result) result = await universalDownload(url, "facebook").catch(() => null);

    if (result?.dl) {
      await editMessage(sock, jid, dlKey, `📘 *MIAS MDX — Facebook*\n\n⬢ Fetching media... ✅\n⬡ Downloading...\n◻ Sending...`);
      const buf = Buffer.from((await axios.get(result.dl, { responseType: "arraybuffer", timeout: 120000, headers: { "User-Agent": "Mozilla/5.0" } })).data);
      await editMessage(sock, jid, dlKey, `📘 *MIAS MDX — Facebook*\n\n⬢ Fetching media... ✅\n⬢ Downloading... ✅\n⬡ Sending...`);
      const cap = `📘 *Facebook${mode === "hd" ? " (HD)" : ""}*\n\n${result.title || ""}`;
      if (mode === "audio") {
        await sock.sendMessage(jid, { audio: buf, mimetype: "audio/mpeg", ptt: false }, { quoted: msg });
      } else if (mode === "doc" || mode === "document") {
        await sock.sendMessage(jid, { document: buf, mimetype: "video/mp4", fileName: `facebook_${Date.now()}.mp4`, caption: cap }, { quoted: msg });
      } else {
        // Try video; fall back to document if send fails
        try {
          await sock.sendMessage(jid, { video: buf, caption: cap }, { quoted: msg });
        } catch {
          await sock.sendMessage(jid, { document: buf, mimetype: "video/mp4", fileName: `facebook_${Date.now()}.mp4`, caption: cap }, { quoted: msg });
        }
      }
      await editMessage(sock, jid, dlKey, `📘 *MIAS MDX — Facebook*\n\n⬢ Fetching... ✅\n⬢ Downloading... ✅\n⬢ Sending... ✅\n\n✅ *Done!*`);
      await react(sock, msg, "✅");
    } else {
      await editMessage(sock, jid, dlKey, `📘 *MIAS MDX — Facebook*\n\n⬢ Fetching media... ❌\n\n⚠️ Could not download. The URL may be private or geo-restricted.\n💡 Try sharing the video URL directly (not a post link).`);
    }
  } catch (e) {
    await editMessage(sock, jid, dlKey, `📘 *MIAS MDX — Facebook*\n\n❌ Error: ${e.message}`);
  }
});

// Pinterest — special: supports search + URL download + limit for HD images AND videos
// ─── MISSING DOWNLOADERS ────────────────────────────────────────────────
async function _cobaltDl(url, opts = {}) {
  const endpoints = [
    "https://api.cobalt.tools/",
    "https://cobalt-api.kwiatekmiki.com/",
  ];
  for (const ep of endpoints) {
    try {
      const { data } = await axios.post(ep, { url, ...opts }, {
        headers: { "Accept": "application/json", "Content-Type": "application/json" },
        timeout: 25000,
      });
      if (data?.url) return data.url;
      if (data?.audio) return data.audio;
    } catch {}
  }
  return null;
}

// ── Video watermark helper ──────────────────────────────────────────────────
// Burns a small label (e.g. "TT" or "YT") at the bottom-left corner of a
// video buffer using system ffmpeg. Returns the original buffer on any error
// so the download still completes even if ffmpeg is unavailable.
async function _addVideoWatermark(videoBuf, label) {
  try {
    if (!videoBuf || videoBuf.length < 10000) return videoBuf;
    // Only watermark videos under 80 MB to avoid Railway timeout
    if (videoBuf.length > 80 * 1024 * 1024) return videoBuf;
    const { execFile } = await import("child_process");
    const _sfx = `${Date.now()}_${Math.random().toString(36).slice(2)}`;
    const tmpIn  = `/tmp/_wm_in_${_sfx}.mp4`;
    const tmpOut = `/tmp/_wm_out_${_sfx}.mp4`;
    try {
      await fs.promises.writeFile(tmpIn, videoBuf);
      await new Promise((resolve, reject) => {
        execFile("ffmpeg", [
          "-y", "-i", tmpIn,
          "-vf",
          // Small "×TT" or "×YT" at bottom-left; shadow for readability on any background
          `drawtext=text='x':x=12:y=h-28:fontsize=18:fontcolor=white@0.90:shadowcolor=black@0.65:shadowx=1:shadowy=1`,
          "-c:a", "copy",
          "-c:v", "libx264", "-preset", "ultrafast", "-crf", "28",
          tmpOut,
        ], { timeout: 90000 }, (err) => (err ? reject(err) : resolve()));
      });
      const result = await fs.promises.readFile(tmpOut);
      return result.length > 10000 ? result : videoBuf;
    } finally {
      // Always remove both files. A failed conversion used to leave media in
      // /tmp on every request until the container ran out of space.
      await Promise.all([
        fs.promises.unlink(tmpIn).catch(() => {}),
        fs.promises.unlink(tmpOut).catch(() => {}),
      ]);
    }
  } catch (_wmErr) {
    try { console.log("[watermark] ffmpeg unavailable or failed, skipping:", _wmErr?.message); } catch {}
    return videoBuf; // graceful fallback — always send the video
  }
}
// ────────────────────────────────────────────────────────────────────────────

cmd(["tiktok","tt","ttdl"], { desc: "Download TikTok video/audio — supports: .tiktok link1,link2,link3", category: "DOWNLOAD" }, async (sock, msg, args) => {
    // Immediate progress reaction so user knows bot is processing .tt
    await forceReaction(sock, msg, "⏳");
    args = __withQuotedUrl(msg, args, /tiktok\.com|vm\.tik/i);
    const _ttOptionIndex = args.findIndex((value) =>
      /^(audio|sticker|stickerize|stik)$/i.test(String(value))
      || parseTikTokMode(value)?.kind === "sticker"
    );
    const _ttMode = _ttOptionIndex >= 0 ? String(args[_ttOptionIndex]).toLowerCase() : "";
    if (_ttOptionIndex >= 0) args.splice(_ttOptionIndex, 1);
    if (!args[0]) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}tiktok <url> [audio|sticker]\nor reply to a message with the link and send ${CONFIG.PREFIX}tiktok\nor bulk: ${CONFIG.PREFIX}tiktok url1,url2,url3 sticker`); return; }
    // FIX v18.2: react() honors owner.autoReact toggle and goes silent when
    // OFF; forceReaction ignores the toggle so the user always sees 🌀.
    await forceReaction(sock, msg, "🌀");
    const jid = msg.key.remoteJid;
    // ── Multi-URL batch download ─────────────────────────────────────────────
    const _rawTt = args.join(" ").trim();
    // Extract all TikTok URLs via regex — supports space, comma, newline or any separator
    const _ttUrlRe = /https?:\/\/(?:www\.|vm\.|vt\.)?tiktok\.com\/[^\s,<>"]+|https?:\/\/vm\.tik\.com\/[^\s,<>"]+/gi;
    const _ttFoundRaw = _rawTt.match(_ttUrlRe) || [];
    // 🛠️ PRECIOUS FIX: the TikTok Lite share footer ("This post is shared via
    // TikTok Lite ... https://www.tiktok.com/tiktoklite") used to be scraped as
    // a SECOND video URL, which forced the bot into the batch immediate-download
    // branch (media sent directly, NO card). Strip non-video links so BOTH share
    // formats always land on the image-card + native-button + number picker path.
    const _ttSkipPaths = ["/tiktoklite", "/get-tiktok", "/share", "/@"];
    const _ttFoundUrls = _ttFoundRaw.filter((u) => !_ttSkipPaths.some((p) => String(u).toLowerCase().includes(p)));
    const _ttCommaFallback = _rawTt.split(/[,\s]+/).filter(u => u.length > 10 && (u.includes("tiktok") || u.includes("vm.tik") || u.includes("vt.tiktok")) && !/\/tiktoklite|\/get-tiktok/i.test(u));
    const _ttUrls = [...new Set([..._ttFoundUrls, ..._ttCommaFallback])];
    // 🛠️ PRECIOUS FIX: normalize args to ONLY the real video URL(s) so the blurb
    // text can never fall into the direct-downloader (immediate media, no card).
    if (_ttUrls.length > 0) args = _ttUrls.slice();
    if (_ttUrls.length > 1) {
      const _isAudioBatch = _ttMode === "audio";
      const _isStickerBatch = ["sticker", "stickerize", "stik", "3.1", "3.2"].includes(_ttMode)
        || parseTikTokMode(_ttMode)?.kind === "sticker";
      // silent — no intermediate text
      let _ttDone = 0, _ttFail = 0;
      for (let _tti = 0; _tti < _ttUrls.length; _tti++) {
        const _ttUrl = _ttUrls[_tti];
        try {
          let _ttDlUrl = null;
          try { const _r = await prexzyGet("/download/tiktok", { url: _ttUrl }); const _d = _r.data; if (_r.ok && _d) _ttDlUrl = _isAudioBatch ? (_d?.data?.music||_d?.data?.wmplay||_d?.data?.play) : (_d?.data?.hdplay||_d?.data?.play||_d?.hdplay||_d?.play||_d?.video||_d?.url); } catch {}
          if (!_ttDlUrl) { try { const _tw = await axios.get(`https://www.tikwm.com/api/?url=${encodeURIComponent(_ttUrl)}&hd=1`, { timeout: 20000 }); if (_tw.data?.data?.play) _ttDlUrl = _isAudioBatch ? (_tw.data.data.music||_tw.data.data.play) : (_tw.data.data.hdplay||_tw.data.data.play); } catch {} }
          if (!_ttDlUrl) { _ttFail++; continue; }
          const _ttBuf = Buffer.from((await axios.get(_ttDlUrl, { responseType: "arraybuffer", timeout: 90000, headers: { "User-Agent": "Mozilla/5.0", Referer: "https://www.tiktok.com/" }, maxRedirects: 10 })).data);
          if (_ttBuf.length < 4096) { _ttFail++; continue; }
          const _ttCap = `🎵 *TikTok* (${_tti+1}/${_ttUrls.length})`;
          if (_isStickerBatch) {
            const _sticker = await createStickerFromBuffer(_ttBuf, {
              mediaType: "video/mp4",
              pack: CONFIG.BOT_NAME || "MIAS",
              author: CONFIG.OWNER_NAME || "MIAS Bot",
            });
            await sock.sendMessage(jid, { sticker: _sticker, isAnimated: true }, { quoted: msg });
          } else if (_isAudioBatch) {
            await sock.sendMessage(jid, { audio: _ttBuf, mimetype: "audio/mpeg", ptt: false, fileName: `tiktok_${Date.now()}.mp3` }, { quoted: msg });
          } else {
            const _ttWm = await _addVideoWatermark(_ttBuf, "TT");
            try { await sock.sendMessage(jid, { video: _ttWm, mimetype: "video/mp4", caption: _ttCap }, { quoted: msg }); }
            catch { await sock.sendMessage(jid, { document: _ttWm, mimetype: "video/mp4", fileName: `tiktok_${Date.now()}.mp4`, caption: _ttCap }, { quoted: msg }); }
          }
          _ttDone++;
        } catch { _ttFail++; }
        if (_tti < _ttUrls.length - 1) await new Promise(r => setTimeout(r, 1200));
      }
      await react(sock, msg, _ttFail === _ttUrls.length ? "❌" : "✅");
      await sendReply(sock, msg, `🎵 *Batch done!*  ✅ ${_ttDone} sent  ❌ ${_ttFail} failed`);
      return;
    }
    // ── Single URL (original flow below) ────────────────────────────────────
  const url = args[0];
  const isAudio = _ttMode === "audio" || (args[1] || "").toLowerCase() === "audio";
  const isSticker = ["sticker", "stickerize", "stik", "3.1", "3.2"].includes(_ttMode)
    || parseTikTokMode(_ttMode)?.kind === "sticker";
    // New numbered picker for a single URL. The legacy direct download remains
    // available with `.tiktok URL audio`; picker state is bound to this chat
    // and expires so a number from another conversation cannot trigger media.
    if (!isAudio && !isSticker && !args[1]) {
      try {
        const info = await fetchTikTokInfo(url);
        __ttRememberSelection(jid, { info, url, ts: Date.now(), sourceMessage: msg });
        // Keep the source URL inside the quoted card. The picker is also
        // persisted by chat, but this makes a reply recoverable after a
        // reconnect or process restart when only the quoted card remains.
        const menuCaption = formatTikTokMenu(info, CONFIG.PREFIX);
        // Prefer a native WhatsApp single-select ("radio") picker. Its row
        // ids are 1.1–2.3, so a tap and a typed reply use the same path.
        let thumb = null;
        const _coverCandidates = (Array.isArray(info.covers) && info.covers.length)
          ? info.covers
          : (info.thumbnail ? [info.thumbnail] : []);
        for (const _cover of _coverCandidates) {
          try {
            const _buf = Buffer.from((await axios.get(_cover, {
              responseType: "arraybuffer", timeout: 15000, maxRedirects: 5,
              headers: { "User-Agent": "Mozilla/5.0", Referer: "https://www.tiktok.com/" },
            })).data);
            if (_buf && _buf.length > 1024) { thumb = _buf; break; }
          } catch {}
        }
        let pickerSent = false;
        let sentPickerMsg = null;
        try {
          sentPickerMsg = await sendNativeFlowListMenu(
            sock,
            jid,
            msg,
            menuCaption,
            buildTikTokPickerSections(),
            [],
            `${CONFIG.BOT_NAME} • TikTok`,
            { headerImage: thumb, headerText: info.title ? String(info.title).slice(0, 60) : "TikTok", headerSubtitle: "🎬 pick a format below" },
          );
          pickerSent = true;
          if (sentPickerMsg?.key?.id) {
            if (globalThis.__ttPromptStore) globalThis.__ttPromptStore.set(sentPickerMsg.key.id, { ...info, url: resolvedUrl, ts: Date.now(), jid });
            if (typeof __ttRememberSelection === "function") __ttRememberSelection(jid, { ...info, url: resolvedUrl, promptKey: sentPickerMsg.key, promptKeys: [sentPickerMsg.key] });
          }
        } catch (_pickerErr) {
          console.warn("[tiktok-picker] native radio menu unavailable:", _pickerErr?.message || _pickerErr);
        }
        if (!pickerSent) {
          // Older WhatsApp clients still get the same working numbered flow —
          // with the video image attached so the options never arrive bare.
          try {
            if (thumb) {
              sentPickerMsg = await sock.sendMessage(jid, { image: thumb, caption: menuCaption }, { quoted: msg });
            } else {
              sentPickerMsg = await sendReply(sock, msg, menuCaption);
            }
            pickerSent = true;
            if (sentPickerMsg?.key?.id) {
              if (globalThis.__ttPromptStore) globalThis.__ttPromptStore.set(sentPickerMsg.key.id, { ...info, url: resolvedUrl, ts: Date.now(), jid });
              if (typeof __ttRememberSelection === "function") __ttRememberSelection(jid, { ...info, url: resolvedUrl, promptKey: sentPickerMsg.key, promptKeys: [sentPickerMsg.key] });
            }
          } catch (_fbErr) {
            console.warn("[tiktok-picker] image fallback failed:", _fbErr?.message || _fbErr);
          }
        }
        if (!pickerSent) {
          // Last resort: plain-text menu so the picker is NEVER silent.
          await sendReply(sock, msg, menuCaption + "\n\n_Reply with a number (e.g. *1.3*) or *" + CONFIG.PREFIX + "pick 1.3*_").catch(() => {});
        }
        await forceReaction(sock, msg, pickerSent ? "✅" : "⚠️");
        return;
      } catch (_previewErr) {
        console.error("[tiktok-preview]", _previewErr?.message || _previewErr);
        // Fall through to the existing multi-provider direct downloader.
      }
    }
    // no intermediate status message — just 🌀 → ✅ reactions

    // Helper: validate downloaded buffer is a real MP4/audio file
    const _isValidVideo = (buf) => {
      if (!buf || buf.length < 4096) return false;
      // MP4 / M4V: bytes 4-8 = "ftyp"
      if (buf.slice(4, 8).toString("ascii") === "ftyp") return true;
      // Some MP4 streams start with moov/mdat atoms
      const hdr = buf.slice(0, 12).toString("ascii");
      if (hdr.includes("ftyp") || hdr.includes("mdat") || hdr.includes("moov")) return true;
      return false;
    };
    const _isValidAudio = (buf) => {
      if (!buf || buf.length < 2048) return false;
      if (buf.slice(0, 3).toString("utf8") === "ID3") return true;
      if (buf[0] === 0xFF && (buf[1] & 0xE0) === 0xE0) return true;
      if (buf.slice(0, 4).toString("ascii") === "OggS") return true;
      if (buf.slice(4, 8).toString("ascii") === "ftyp") return true;
      return false;
    };

    try {
      let dlUrl = null;

      // 0) PRIMARY: DavidCyril
      for (const _dcEp of ["/download/tiktok", "/download/tiktokv2", "/download/tiktokv3", "/download/tiktokv4"]) {
        if (dlUrl) break;
        try { const r = await dcGet(_dcEp, { url }, 20000); if (r.ok) dlUrl = extractDcTiktok(r.data, isAudio); } catch {}
      }

      // 1) Prexzyvilla fallback
      if (!dlUrl) {
        const r = await prexzyGet("/download/tiktok", { url });
        const d = r.data;
        if (r.ok && d) dlUrl = isAudio ? (d?.data?.music || d?.data?.wmplay || d?.data?.play || d?.music || d?.audio) : (d?.data?.hdplay || d?.data?.play || d?.hdplay || d?.play || d?.video || d?.url);
      }

      // 2) TikWM API
      if (!dlUrl) { try { const { data } = await axios.get(`https://www.tikwm.com/api/?url=${encodeURIComponent(url)}&hd=1`, { timeout: 20000 }); if (data?.data?.play) dlUrl = isAudio ? (data.data.music || data.data.play) : (data.data.hdplay || data.data.play); } catch {} }

      // 3) DavidCyril TikTok downloaders (multiple fallbacks)
      if (!dlUrl) { try { const r = await dcGet("/download/tiktok", { url }, 20000); if (r.ok) dlUrl = extractDcTiktok(r.data, isAudio); } catch {} }
      if (!dlUrl) { try { const r = await dcGet("/download/tiktokv2", { url }, 20000); if (r.ok) dlUrl = extractDcTiktok(r.data, isAudio); } catch {} }
      if (!dlUrl) { try { const r = await dcGet("/download/tiktokv3", { url }, 20000); if (r.ok) dlUrl = extractDcTiktok(r.data, isAudio); } catch {} }
      if (!dlUrl) { try { const r = await dcGet("/download/tiktokv4", { url }, 20000); if (r.ok) dlUrl = extractDcTiktok(r.data, isAudio); } catch {} }
      if (!dlUrl) { try { const r = await dcGet("/download/savetik", { url }, 20000); if (r.ok) { const d = r.data?.data || r.data; dlUrl = isAudio ? (d?.music || d?.audio) : (d?.video || d?.url); } } catch {} }
      if (!dlUrl) { try { const r = await dcGet("/download/vibetik", { url }, 20000); if (r.ok) { const d = r.data?.data || r.data; dlUrl = isAudio ? (d?.music || d?.audio) : (d?.video || d?.url); } } catch {} }
      if (!dlUrl) { try { const r = await dcGet("/download/tiktokdl-rapid", { url }, 20000); if (r.ok) dlUrl = extractDcTiktok(r.data, isAudio); } catch {} }

      // 4) Cobalt
      if (!dlUrl) dlUrl = await _cobaltDl(url, { downloadMode: isAudio ? "audio" : "auto" });

      if (!dlUrl) { await sendReply(sock, msg, `❌ Could not download. Try a direct TikTok video URL.`); await react(sock, msg, "❌"); return; }


      // Download with validation — retry a different URL if buffer is not valid media
      let buf = null;
      const _urlsToTry = [dlUrl];
      for (const _tryUrl of _urlsToTry) {
        try {
          const _res = await axios.get(_tryUrl, { responseType: "arraybuffer", timeout: 90000, headers: { "User-Agent": "Mozilla/5.0", Referer: "https://www.tiktok.com/" }, maxRedirects: 10 });
          const _b = Buffer.from(_res.data);
          const _valid = isAudio ? _isValidAudio(_b) : _isValidVideo(_b);
          // v-fix: require proper magic bytes OR very large buffer (>600KB) to avoid HTML error pages
          if (_valid || _b.length > 600000) { buf = _b; break; }
        } catch {}
      }
      if (!buf) { await sendReply(sock, msg, `❌ Download returned invalid data. Try again.`); await react(sock, msg, "❌"); return; }

      const sz = ` (${buf.length>=1048576?(buf.length/1048576).toFixed(2)+' MB':(buf.length/1024).toFixed(1)+' KB'})`;

      if (isSticker) {
        const _sticker = await createStickerFromBuffer(buf, {
          mediaType: "video/mp4",
          pack: CONFIG.BOT_NAME || "MIAS",
          author: CONFIG.OWNER_NAME || "MIAS Bot",
        });
        await sock.sendMessage(jid, { sticker: _sticker, isAnimated: true }, { quoted: msg });
      } else if (isAudio) {
        const _aMime = _isValidAudio(buf) && buf.slice(4, 8).toString("ascii") === "ftyp" ? "audio/mp4" : "audio/mpeg";
        await sock.sendMessage(jid, { audio: buf, mimetype: _aMime, ptt: false, fileName: "tiktok_audio.mp3" }, { quoted: msg });
      } else {
        const cap = `🎵 *TikTok*${sz}`;
        const _ttBufWm = await _addVideoWatermark(buf, "TT");
        try { await sock.sendMessage(jid, { video: _ttBufWm, mimetype: "video/mp4", caption: cap }, { quoted: msg }); }
        catch { await sock.sendMessage(jid, { document: _ttBufWm, mimetype: "video/mp4", fileName: `tiktok_${Date.now()}.mp4`, caption: cap }, { quoted: msg }); }
      }

      await react(sock, msg, "✅");
    } catch(e) { await sendReply(sock, msg, `❌ TikTok error: ${e.message}`); await react(sock, msg, '❌'); }
  });

for (const _ttn of ["tiktok", "tt", "ttdl"]) { const _te = commands.get(_ttn); if (_te) { _te.__ttCard = true; _te.__ttCardHandler = _te.handler; } }

cmd(["spotify","spot","spotdl"], { desc: "Download Spotify track as MP3 with cover art", category: "DOWNLOAD" }, async (sock, msg, args) => {
  if (!args[0]) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}spotify <spotify_track_url>\n\nExample:\n${CONFIG.PREFIX}spotify https://open.spotify.com/track/...`); return; }
  await react(sock, msg, "⏳");
  const url = args[0];
  const jid = msg.key.remoteJid;
  const _spotStMsg = await sock.sendMessage(jid, { text: `🎧 *MIAS MDX — Spotify*\n\n⏳ Fetching track info...\n⏳ Downloading audio...\n⏳ Sending...` }, { quoted: msg });
  const _spotStKey = _spotStMsg.key;
  let dlUrl = null, title = "Spotify Track", thumbUrl = null, artists = "", duration = "";

  // Helper to extract from prexzy response
  const _extractSpotify = (d) => {
    if (!d) return;
    const _d = d?.data || d;
    if (!dlUrl) dlUrl = _d?.download_url || _d?.audio || _d?.url || _d?.mp3;
    if (!thumbUrl) thumbUrl = _d?.thumbnail || _d?.cover || _d?.image || _d?.album_art || _d?.albumArt || _d?.cover_url;
    if (title === "Spotify Track") title = _d?.title || _d?.name || title;
    if (!artists) artists = Array.isArray(_d?.artists) ? _d.artists.map(a => a?.name || a).join(", ") : (_d?.artist || _d?.artists || "");
    if (!duration) duration = _d?.duration || _d?.duration_ms ? `${Math.floor((_d.duration || _d.duration_ms / 1000) / 60)}:${String(Math.floor((_d.duration || _d.duration_ms / 1000) % 60)).padStart(2,"0")}` : "";
  };

  // 0) PRIMARY: DavidCyril
  try {
    const r = await dcGet("/download/spotify", { url }, 30000);
    if (r.ok && r.data) _extractSpotify(r.data);
  } catch {}

  // 1) Prexzyvilla fallback /download/spotify
  if (!dlUrl) try {
    const r = await prexzyGet("/download/spotify", { url }, 30000);
    if (r.ok && r.data) _extractSpotify(r.data);
  } catch {}

  // 2) Prexzyvilla v2
  if (!dlUrl) {
    try {
      const r2 = await prexzyGet("/download/spotifyv2", { url }, 30000);
      if (r2.ok && r2.data) _extractSpotify(r2.data);
    } catch {}
  }

  // 3) GiftedTech
  if (!dlUrl) {
    try {
      const { data } = await axios.get(`${CONFIG.GIFTED_API}/api/download/spotify?apikey=${CONFIG.GIFTED_KEY}&url=${encodeURIComponent(url)}`, { timeout: 30000 });
      if (data?.success && data?.result) {
        const r = data.result;
        dlUrl = r.download_url || r.url || r.audio || r.mp3;
        if (!thumbUrl) thumbUrl = r.thumbnail || r.image || r.cover;
        if (title === "Spotify Track") title = r.title || title;
        if (!artists) artists = r.artists || r.artist || "";
      }
    } catch {}
  }

  // 4) Ryzendesu
  if (!dlUrl) {
    try {
      const { data } = await axios.get(`https://api.ryzendesu.vip/api/downloader/spotify?url=${encodeURIComponent(url)}`, { timeout: 25000 });
      _extractSpotify(data);
    } catch {}
  }

  // 5) DavidCyril Spotify downloaders (multiple fallbacks — no key needed)
  const _dcSpotifyEndpoints = [
    "/spotifydl", "/spotifydl2",
    "/download/spodownloader", "/download/spotdown",
    "/download/spotidown", "/download/spotidownloader", "/download/spotmate",
  ];
  for (const _ep of _dcSpotifyEndpoints) {
    if (dlUrl) break;
    try {
      const _r = await dcGet(_ep, { url }, 25000);
      if (_r.ok && _r.data) {
        const _ex = extractDcSpotify(_r.data);
        if (_ex.dlUrl) {
          dlUrl = _ex.dlUrl;
          if (!thumbUrl && _ex.thumbUrl) thumbUrl = _ex.thumbUrl;
          if (title === "Spotify Track" && _ex.title) title = _ex.title;
          if (!artists && _ex.artists) artists = _ex.artists;
          if (!duration && _ex.duration) duration = _ex.duration;
        }
      }
    } catch {}
  }

  if (dlUrl) await editMessage(sock, jid, _spotStKey, `🎧 *MIAS MDX — Spotify*\n\n✅ Fetching track info...\n⏳ Downloading audio...\n⏳ Sending...`).catch(()=>{});

  // 6) Cobalt
  if (!dlUrl) dlUrl = await _cobaltDl(url, { downloadMode: "audio", audioFormat: "mp3" });

  // 6) YouTube multi-search + full 11-provider audio chain fallback
  let _ytFallbackResult = null;
  if (!dlUrl) {
    let _ytUrl = null;
    const _ytQ = encodeURIComponent(`${title}${artists ? " " + artists : ""} audio`);
    const _ytSearchers = [
      async () => { const { data } = await axios.get(`${CONFIG.GIFTED_API}/api/search/youtube?apikey=${CONFIG.GIFTED_KEY}&q=${_ytQ}`, { timeout: 15000 }); return data?.result?.[0]?.url || data?.data?.[0]?.url; },
      async () => { const { data } = await axios.get(`${CONFIG.GIFTED_API}/api/search/ytsearch?apikey=${CONFIG.GIFTED_KEY}&q=${_ytQ}`, { timeout: 15000 }); return data?.result?.[0]?.url || data?.results?.[0]?.url; },
      async () => { const { data } = await axios.get(`https://api.siputzx.my.id/api/y/search?query=${_ytQ}`, { timeout: 15000 }); return data?.data?.[0]?.url || data?.result?.[0]?.url; },
      async () => { const { data } = await axios.get(`https://www.youtube.com/results?search_query=${_ytQ}`, { headers: { "User-Agent": "Mozilla/5.0" }, timeout: 15000 }); const m = data.match(/"videoId":"([a-zA-Z0-9_-]{11})"/); return m ? `https://www.youtube.com/watch?v=${m[1]}` : null; },
    ];
    for (const fn of _ytSearchers) {
      try { _ytUrl = await fn(); if (_ytUrl) break; } catch {}
    }
    if (_ytUrl) {
      dlUrl = await _cobaltDl(_ytUrl, { downloadMode: "audio", audioFormat: "mp3" });
      if (!dlUrl) _ytFallbackResult = await _fetchYtAudioBuf(_ytUrl, "mp3");
    }
  }

  if (!dlUrl && !_ytFallbackResult) {
    await react(sock, msg, "❌");
    await sendReply(sock, msg, `⚠️ Could not download this Spotify track.\nTry: *${CONFIG.PREFIX}play ${title}*`);
    return;
  }

  // Download audio (skip if _fetchYtAudioBuf already retrieved the buffer)
  let buf = _ytFallbackResult?.buf ?? null;
  if (!buf && dlUrl) {
    try {
      const _dlRes = await axios.get(dlUrl, { responseType: 'arraybuffer', timeout: 90000, headers: { 'User-Agent': 'Mozilla/5.0' }, maxRedirects: 5 });
      const _dlBuf = Buffer.from(_dlRes.data || []);
      const _hasId3  = _dlBuf.length >= 3 && _dlBuf.slice(0,3).toString('utf8') === 'ID3';
      const _hasSync = _dlBuf.length >= 2 && _dlBuf[0] === 0xFF && (_dlBuf[1] & 0xE0) === 0xE0;
      const _hasOgg  = _dlBuf.length >= 4 && _dlBuf.slice(0,4).toString('utf8') === 'OggS';
      const _hasM4A  = _dlBuf.length >= 12 && _dlBuf.slice(4,8).toString('ascii') === 'ftyp';
      const _ct      = (_dlRes.headers?.['content-type'] || '').toLowerCase();
      if (_dlBuf.length >= 5000 && (_hasId3 || _hasSync || _hasOgg || _hasM4A || /audio|mpeg|mp3|ogg|m4a/i.test(_ct))) {
        buf = _dlBuf;
      }
    } catch {}
  }
  if (!buf && dlUrl) {
    try { buf = Buffer.from((await axios.get(dlUrl, { responseType: 'arraybuffer', timeout: 90000 })).data); } catch {}
  }

  // Fetch thumbnail cover art
  let thumbBuf = null;
  if (thumbUrl) {
    try {
      const tr = await axios.get(thumbUrl, { responseType: "arraybuffer", timeout: 15000, headers: { "User-Agent": "Mozilla/5.0" } });
      thumbBuf = Buffer.from(tr.data);
    } catch {}
  }

  // Detect actual audio format from magic bytes BEFORE using it (prevents
  // "Cannot access '_spotExt' before initialization")
  let _mimeType = "audio/mpeg";
  let _spotExt = "mp3";
  if (buf) {
    const _h = buf.slice(0, 12);
    if (_h.slice(0, 4).toString("ascii") === "OggS") { _mimeType = "audio/ogg; codecs=opus"; _spotExt = "ogg"; }
    else if (_h.slice(4, 8).toString("ascii") === "ftyp") { _mimeType = "audio/mp4"; _spotExt = "m4a"; }
  }

  const safeName = title.replace(/[^a-zA-Z0-9 ]/g, "").slice(0, 60) || "spotify_track";
  const _spotFileName = `${safeName}.${_spotExt}`;
  const cap = `🎧 *${title}*${artists ? `\n🎤 ${artists}` : ""}${duration ? `\n⏱️ ${duration}` : ""}`;

  // Always send cover art image first so it shows in WhatsApp
  if (thumbBuf) {
    try { await sock.sendMessage(jid, { image: thumbBuf, caption: cap }, { quoted: msg }); } catch {}
  }

  // Send audio with embedded thumbnail too
  try {
    const _audioMsg = {
      audio: buf,
      mimetype: _mimeType,
      ptt: false,
      fileName: _spotFileName,
    };
    if (thumbBuf) _audioMsg.jpegThumbnail = thumbBuf;
    await sock.sendMessage(jid, _audioMsg, { quoted: msg });
  } catch {
    // Fallback: send as document
    if (thumbBuf) {
      try { await sock.sendMessage(jid, { image: thumbBuf, caption: cap }, { quoted: msg }); } catch {}
    }
    try {
      await sock.sendMessage(jid, {
        document: buf, mimetype: _mimeType, fileName: `${safeName}.mp3`, caption: cap
      }, { quoted: msg });
    } catch (_de) { await sendReply(sock, msg, `⚠️ Audio sent but WhatsApp rejected it. Try *${CONFIG.PREFIX}play ${title}*`); }
  }

  await react(sock, msg, "✅");
});

