    await sendReply(sock, msg, `📊 *Group Analytics*\n\n👥 Total Members: ${meta.participants.length}\n💬 Active Members: ${activeCount}\n📨 Total Messages: ${total}\n📈 Activity Rate: ${meta.participants.length ? ((activeCount / meta.participants.length) * 100).toFixed(1) : 0}%`);
