    const s = String(jid || "").trim();
    if (!s) return null;
    if (s.includes("@"))
      return s.includes(":") ? s.split(":")[0] + "@s.whatsapp.net" : s;
    const d = s.replace(/[^0-9]/g, "");
    return d.length >= 7 ? `${d}@s.whatsapp.net` : null;
