// ─── .pm / .pickmenu — select option N from last text-menu (buttonsMode OFF) ──
cmd(["pm","pickmenu"], { desc: "Pick option N from last text menu — .pm <number>", category: "UTILITY" }, async (sock, msg, args) => {
  const jid = msg.key.remoteJid;
  const stash = _menuPickStore.get(jid);
  if (!stash || (Date.now() - stash.ts) > 10 * 60 * 1000) {
    await sendReply(sock, msg, "❌ No recent menu found in this chat.");
    return;
  }
  const n = parseInt(args[0] || "", 10);
  if (!n || n < 1 || n > stash.items.length) {
    const _NUMS = ["1️⃣","2️⃣","3️⃣","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣","9️⃣","🔟"];
    let _listOut = `📋 *Available Options:*\n\n`;
    stash.items.forEach((it, i) => { _listOut += `${_NUMS[i] || `${i + 1}.`} ${it.text || "Option"}\n`; });
    await sendReply(sock, msg, _listOut);
    return;
  }
  const item = stash.items[n - 1];
  await react(sock, msg, "✅");

  if (item.type === "url") {
    // URL button — send the link
    await sendReply(sock, msg, `🌐 *Link for option ${n}:*\n\n${item.url}`);
  } else if (item.type === "copy") {
    // Copy button — send the copyable value
    await sendReply(sock, msg, `📋 *Copied — option ${n}:*\n\n${item.value}`);
  } else {
    // cmd / quick_reply — re-trigger the command
    let _rawId = item.id || "";
    const _cleanId = _rawId.startsWith("BTN:") ? _rawId.slice(4).trim() : _rawId.trim();
    const _cmdParsed = parseCommandBody(_cleanId);
    const _cmdText = _cmdParsed.isCommand ? _cleanId : (CONFIG.PREFIX ? `${CONFIG.PREFIX}${_cleanId}` : _cleanId);
    if (!_cleanId) {
      await sendReply(sock, msg, `❌ Option ${n} has no command attached.`);
      return;
    }
    await sendReply(sock, msg, `⚡ *Running:* \`${_cmdText}\``);
    try {
      const _parts = (parseCommandBody(_cmdText).raw || _cmdText).split(/\s+/);
      const _cmdName = (_parts[0] || "").toLowerCase();
      const _cmdArgs = _parts.slice(1).filter(Boolean);
      const _handler = commands.get(_cmdName);
      if (_handler) {
        const _fakeMsg = { ...msg, message: { conversation: _cmdText } };
        await _handler(sock, _fakeMsg, _cmdArgs);
      } else {
        await sendReply(sock, msg, `❌ Command *${_cmdName}* not found.`);
      }
    } catch (_e) {
      await sendReply(sock, msg, `❌ Failed to run option ${n}: ${_e.message}`);
    }
  }
});

// ─── .pmlist — re-display the last text-menu for this chat ────────────────────
cmd(["pmlist","showmenu","menulist"], { desc: "Re-display the last text menu for this chat — .pmlist", category: "UTILITY" }, async (sock, msg) => {
  const jid = msg.key.remoteJid;
  const stash = _menuPickStore.get(jid);
  if (!stash || (Date.now() - stash.ts) > 10 * 60 * 1000) {
    await sendReply(sock, msg, `❌ No active menu in this chat.\n_Menus expire after 10 minutes. Run a command first._`);
    return;
  }
  const _NUMS = ["1️⃣","2️⃣","3️⃣","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣","9️⃣","🔟"];
  const _ago = Math.round((Date.now() - stash.ts) / 1000);
  const _agoStr = _ago < 60 ? `${_ago}s ago` : `${Math.round(_ago / 60)}m ago`;
  let _out = `📋 *Last Menu* _(${_agoStr})_\n\n`;
  stash.items.forEach((it, i) => { _out += `${_NUMS[i] || `${i + 1}.`} ${it.text || "Option"}\n`; });
  await sendReply(sock, msg, _out);
});

// ═══════════════════════════════════════════════════════════════════════════════
//  SAFE MODE — hides all adult cmds + locks NSFW / strips adult settings
// ═══════════════════════════════════════════════════════════════════════════════
cmd("safemode", { desc: "Toggle safe mode (hide all 18+ commands)", category: "OWNER", ownerOnly: true }, async (sock, msg, args) => {
  const ownerJ = getOwnerJid();
  const ownerS = getSettings(ownerJ);
  const sub = (args[0] || "").toLowerCase();
  if (sub === "on") ownerS.safeMode = true;
  else if (sub === "off") ownerS.safeMode = false;
  else ownerS.safeMode = !ownerS.safeMode;

  if (ownerS.safeMode) {
    ownerS.adultMode = false; ownerS.adultDl = false;
    if (_goonState.timer) { clearInterval(_goonState.timer); _goonState.timer = null; }
    _goonState.active = false;
    const cs = getSettings(msg.key.remoteJid);
    cs.adultMode = false; cs.adultDl = false; cs.safeMode = true;
  } else {
    const cs = getSettings(msg.key.remoteJid);
    cs.safeMode = false;
  }
  try { saveNow && saveNow(); } catch {}
  await sendReply(sock, msg,
    `🛡️ *Safe Mode: ${ownerS.safeMode ? "✅ ON" : "❌ OFF"}*\n\n${ownerS.safeMode ? "All 18+ commands are now hidden and disabled." : "Adult commands are available again (still gated by adult mode)."}`);
});

// ═══════════════════════════════════════════════════════════════════════════════
//  TRUECALLER — number lookup (multi-API fallback)
// ═══════════════════════════════════════════════════════════════════════════════
cmd("truecaller", { desc: "Look up info on a phone number", category: "TOOLS" }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `Usage: *${CONFIG.PREFIX}truecaller <number>*\n\nExample: ${CONFIG.PREFIX}truecaller +2348012345678`); return; }
  await react(sock, msg, "🔍");
  const raw = args[0].replace(/[^\d+]/g, "");
  const cleaned = raw.startsWith("+") ? raw : "+" + raw;
  const bare = cleaned.replace("+", "");

  const jid = msg.key.remoteJid;
  const statusMsg = await sock.sendMessage(jid, { text: `📞 *Truecaller Lookup*\n\n🔍 Looking up *${cleaned}*...` }, { quoted: msg });

  const pick = (...vals) => vals.find(v => v !== undefined && v !== null && String(v).trim() !== "");
  const normalize = (r = {}) => {
    if (!r || typeof r !== "object") return null;
    const obj = {
      name: pick(r.name, r.fullName, r.displayName, r.caller_name, r.callerName),
      altName: pick(r.altName, r.alt_name, r.secondaryName),
      gender: pick(r.gender, r.sex),
      email: pick(r.email, r.mail),
      carrier: pick(r.carrier, r.operator, r.provider, r.line_provider, r.service_provider),
      lineType: pick(r.lineType, r.line_type, r.type, r.phone_type, r.numberType),
      location: pick(r.location, r.address, r.city, r.phone_region, r.region),
      country: pick(r.country, r.countryName, r.country_name, r.countryCode, r.country_code),
      timezone: pick(r.timezone, r.time_zone, r.timeZone),
      spamScore: pick(r.spamScore, r.spam_score, r.score, r.spam_likelihood),
      valid: r.valid || r.phone_valid || r.is_valid || false,
      tags: Array.isArray(r.tags) ? r.tags.filter(Boolean) : [],
    };
    return (obj.name || obj.carrier || obj.country || obj.location || obj.valid) ? obj : null;
  };
  const merge = (base, extra) => {
    if (!extra) return base;
    for (const k of ["name","altName","gender","email","carrier","lineType","location","country","timezone","spamScore"]) {
      if (!base[k] && extra[k]) base[k] = extra[k];
    }
    base.tags = [...new Set([...(base.tags||[]),...(extra.tags||[])])].filter(Boolean);
    if (!base.valid && extra.valid) base.valid = true;
    return base;
  };

  const sources = [
    // 1. numvalidate.com — free, no key, returns carrier + country + valid
    async () => {
      const { data } = await axios.get(`https://numvalidate.com/api/validate?number=${encodeURIComponent(cleaned)}`, { timeout: 12000, headers: { "User-Agent": "Mozilla/5.0" } });
      if (!data) return null;
      return normalize({ carrier: data.carrier, country: data.country, location: data.location, lineType: data.line_type, valid: data.valid });
    },
    // 2. veriphone.io — free demo key
    async () => {
      const { data } = await axios.get(`https://api.veriphone.io/v2/verify?phone=${encodeURIComponent(cleaned)}&key=demo_key`, { timeout: 12000, headers: { "User-Agent": "Mozilla/5.0" } });
      if (!data?.phone_valid && !data?.carrier) return null;
      return normalize({ carrier: data.carrier, country: data.country_name, location: data.phone_region, lineType: data.phone_type, valid: data.phone_valid });
    },
    // 3. Abstract Phone Validation (free tier 250req/month)
    async () => {
      const key = process.env.ABSTRACT_PHONE_KEY || "a9ef3254e69b4e4291897e47ee28de7b";
      const { data } = await axios.get(`https://phonevalidation.abstractapi.com/v1/?api_key=${key}&phone=${bare}`, { timeout: 12000 });
      if (!data?.valid && !data?.carrier) return null;
      return normalize({ carrier: data.carrier?.name, country: data.country?.name, location: data.location, lineType: data.type, timezone: data.timezone?.name, valid: data.valid });
    },
    // 4. apilayer numverify (free tier, HTTPS)
    async () => {
      const key = process.env.NUMVERIFY_KEY;
      if (!key) return null;
      const { data } = await axios.get(`https://api.apilayer.com/number_verification/validate?number=${bare}`, { timeout: 12000, headers: { "apikey": key } });
      if (!data?.valid) return null;
      return normalize({ carrier: data.carrier, country: data.country_name, location: data.location, lineType: data.line_type, valid: data.valid });
    },
    // 5. Prexzyvilla truecaller (primary real-name source)
    async () => {
      const r = await prexzyGet("/stalk/truecaller", { q: cleaned, phone: cleaned, number: cleaned }, 20000);
      const d = r?.data?.data || r?.data?.result || r?.data || r?.result;
      return normalize(d);
    },
    // 5b. siputzx (sometimes works)
    async () => {
      const { data } = await axios.get(`https://api.siputzx.my.id/api/tools/truecaller?q=${encodeURIComponent(cleaned)}`, { timeout: 12000, headers: { "User-Agent": "Mozilla/5.0" } });
      const r = data?.data || data?.result || data;
      return normalize(r);
    },
    // 5c. callerinfo (scrape-based)
    async () => {
      const { data } = await axios.get(`https://api.davidcyriltech.my.id/truecaller?number=${encodeURIComponent(bare)}`, { timeout: 12000, headers: { "User-Agent": "Mozilla/5.0" } });
      const r = data?.result || data?.data || data;
      return normalize(r);
    },
    // 6. GIFTED API
    async () => {
      if (!CONFIG.GIFTED_KEY) return null;
      const { data } = await axios.get(`${CONFIG.GIFTED_API}/api/tools/truecaller?apikey=${CONFIG.GIFTED_KEY}&q=${encodeURIComponent(cleaned)}`, { timeout: 12000 });
      return normalize(data?.result || data?.data || data);
    },
    // 7. ryzendesu
    async () => {
      const { data } = await axios.get(`https://api.ryzendesu.vip/api/tools/truecaller?phone=${encodeURIComponent(cleaned)}`, { timeout: 12000, headers: { "User-Agent": "Mozilla/5.0" } });
      return normalize(data?.result || data?.data || data);
    },
    // 8. nexoracle
    async () => {
      const { data } = await axios.get(`https://api.nexoracle.com/tools/truecaller?apikey=free_key@maher_apis&q=${encodeURIComponent(cleaned)}`, { timeout: 12000, headers: { "User-Agent": "Mozilla/5.0" } });
      return normalize(data?.result || data?.data || data);
    },
  ];

  let info = { tags: [], valid: false };
  for (const fn of sources) {
    try {
      const r = await fn();
      if (r) info = merge(info, r);
    } catch {}
  }

  // Guaranteed country-code fallback — parse from E.164 prefix
  if (!info.country) {
    const _ccMap = { "1":"United States/Canada","7":"Russia","20":"Egypt","27":"South Africa","30":"Greece","31":"Netherlands","32":"Belgium","33":"France","34":"Spain","36":"Hungary","39":"Italy","40":"Romania","41":"Switzerland","43":"Austria","44":"United Kingdom","45":"Denmark","46":"Sweden","47":"Norway","48":"Poland","49":"Germany","51":"Peru","52":"Mexico","53":"Cuba","54":"Argentina","55":"Brazil","56":"Chile","57":"Colombia","58":"Venezuela","60":"Malaysia","61":"Australia","62":"Indonesia","63":"Philippines","64":"New Zealand","65":"Singapore","66":"Thailand","81":"Japan","82":"South Korea","84":"Vietnam","86":"China","90":"Turkey","91":"India","92":"Pakistan","93":"Afghanistan","94":"Sri Lanka","95":"Myanmar","98":"Iran","212":"Morocco","213":"Algeria","216":"Tunisia","218":"Libya","220":"Gambia","221":"Senegal","222":"Mauritania","223":"Mali","224":"Guinea","225":"Cote d'Ivoire","226":"Burkina Faso","227":"Niger","228":"Togo","229":"Benin","230":"Mauritius","231":"Liberia","232":"Sierra Leone","233":"Ghana","234":"Nigeria","235":"Chad","236":"Central African Republic","237":"Cameroon","238":"Cabo Verde","239":"São Tomé and Príncipe","240":"Equatorial Guinea","241":"Gabon","242":"Congo","243":"DR Congo","244":"Angola","245":"Guinea-Bissau","246":"British Indian Ocean Territory","247":"Ascension Island","248":"Seychelles","249":"Sudan","250":"Rwanda","251":"Ethiopia","252":"Somalia","253":"Djibouti","254":"Kenya","255":"Tanzania","256":"Uganda","257":"Burundi","258":"Mozambique","260":"Zambia","261":"Madagascar","262":"Réunion","263":"Zimbabwe","264":"Namibia","265":"Malawi","266":"Lesotho","267":"Botswana","268":"Eswatini","269":"Comoros","27":"South Africa","971":"UAE","972":"Israel","973":"Bahrain","974":"Qatar","975":"Bhutan","976":"Mongolia","977":"Nepal","992":"Tajikistan","993":"Turkmenistan","994":"Azerbaijan","995":"Georgia","996":"Kyrgyzstan","998":"Uzbekistan" };
    const _bn = bare;
    for (const [cc, country] of Object.entries(_ccMap).sort((a,b) => b[0].length - a[0].length)) {
      if (_bn.startsWith(cc)) { info.country = country; break; }
    }
  }

  if (!(info.name || info.carrier || info.country || info.location || info.valid || (info.tags||[]).length)) {
    await editMessage(sock, jid, null,
`📞 *Truecaller Lookup*

📱 Number: *${cleaned}*
❌ No caller information found.

_Possible reasons:_
• Privacy settings — number hidden on Truecaller
• Number not in Truecaller database
• Try: ${CONFIG.PREFIX}truecaller +234XXXXXXXXXX`);
    await react(sock, msg, "❌");
    return;
  }

  const out =
`📞 *Truecaller Lookup*

📱 *Number:* ${cleaned}
👤 *Name:* ${info.name || "—"}${info.altName ? `\n🪪 *Alt Name:* ${info.altName}` : ""}${info.gender ? `\n⚧️ *Gender:* ${info.gender}` : ""}${info.email ? `\n📧 *Email:* ${info.email}` : ""}
📡 *Carrier:* ${info.carrier || "—"}
📶 *Line Type:* ${info.lineType || "—"}
📍 *Location:* ${info.location || "—"}
🌍 *Country:* ${info.country || "—"}${info.timezone ? `\n🕒 *Timezone:* ${info.timezone}` : ""}${(info.tags||[]).length ? `\n🏷️ *Tags:* ${info.tags.join(", ")}` : ""}${info.spamScore ? `\n🚨 *Spam Score:* ${info.spamScore}` : ""}`;

  await editMessage(sock, jid, null, out);
  await react(sock, msg, "✅");
});

// ════════════════════════════════════════════════════════════════════════
// 🆕 EXTRAS PATCH (additive — DOES NOT modify or replace any existing logic)
// Adds: menuMode (text|button|list|flow), .togglemenu, profile-pic cache,
// fixed button/list/flow UI senders, and a smart router for the chosen mode.
// Existing session, text menu, antilink/antisticker, and command system are
// fully preserved.
// ════════════════════════════════════════════════════════════════════════
const __MENU_MODES = ["text", "button", "list", "flow"];

function __getMenuMode() {
  try {
    const s = getSettings(getOwnerJid());
    if (!s.menuMode) s.menuMode = s.buttonsMode ? "list" : "text";
    if (!__MENU_MODES.includes(s.menuMode)) s.menuMode = "text";
    return s.menuMode;
  } catch { return "text"; }
}

function __setMenuMode(mode) {
  const s = getSettings(getOwnerJid());
  s.menuMode = mode;
  // Back-compat: only keep legacy list-mode flag on for the original interactive list path
  s.buttonsMode = (mode === "list");
  try { saveNow(); } catch {}
  return mode;
}

let __botPpCache = null;
let __botPpFetchedAt = 0;
const __PP_FALLBACK = "https://i.ibb.co/2dfHLT5/whatsapp-bot.png";
async function __getBotPp(sock) {
  try {
    const now = Date.now();
    if (__botPpCache && (now - __botPpFetchedAt) < 6 * 60 * 60 * 1000) return __botPpCache;
    const me = sock?.user?.id;
    if (me) {
      const url = await sock.profilePictureUrl(me, "image").catch(() => null);
      if (url) { __botPpCache = url; __botPpFetchedAt = now; return url; }
    }
  } catch {}
  __botPpCache = __PP_FALLBACK;
  __botPpFetchedAt = Date.now();
  return __botPpCache;
}

function __ppContext(ppUrl, body) {
  if (!ppUrl) return undefined;
  return {
    externalAdReply: {
      title: (typeof CONFIG !== "undefined" && CONFIG.BOT_NAME) || "MIAS BOT",
      body: body || "Powered by 𝑷𝑹𝑬𝑪𝑰𝑶𝑼𝑺 x",
      thumbnailUrl: ppUrl,
      sourceUrl: (typeof CONFIG !== "undefined" && CONFIG.BOT_URL) || "https://wa.me",
      mediaType: 1,
      renderLargerThumbnail: false,
      showAdAttribution: false,
    }
  };
}

// ── .togglemenu : cycle text → button → list → flow (or set explicitly) ──
cmd(["togglemenu", "menutoggle", "switchmenu", "menumode"], { desc: "Cycle menu UI: text → button → list → flow", category: "OWNER", ownerOnly: true }, async (sock, msg, args) => {
  const cur = __getMenuMode();
  const arg = (args[0] || "").toLowerCase();
  let next;
  if (__MENU_MODES.includes(arg)) next = arg;
  else { const i = __MENU_MODES.indexOf(cur); next = __MENU_MODES[(i + 1) % __MENU_MODES.length]; }
  __setMenuMode(next);
  await _sendPlainReply(sock, msg, `🔁 *Menu Mode → ${next.toUpperCase()}*

Cycle order: text → button → list → flow
• ${CONFIG.PREFIX}togglemenu              → cycle to next mode
• ${CONFIG.PREFIX}togglemenu text|button|list|flow → set directly
• ${CONFIG.PREFIX}smartmenu               → render the menu in current mode

Session is preserved. Existing text menu is untouched.`);
});

// ── .btnmenu : quick-reply BUTTONS UI ─────────────────────────────────────────
cmd(["btnmenu", "buttonmenu", "buttonsui"], { desc: "Send menu as quick-reply buttons", category: "OWNER", ownerOnly: true }, async (sock, msg) => {
  const jid = msg.key.remoteJid;
  const coverBuf = await getBotPic().catch(() => null);
  const bodyText = `*${CONFIG.BOT_NAME}*\nChoose an action below.`;

  // 1) Send cover image as its own bubble first (always renders the pic)
  let imgSent = false;
  if (coverBuf && !isNewsletterJid(jid)) {
    try {
      await sock.sendMessage(jid, { image: coverBuf }, { quoted: msg });
      imgSent = true;
    } catch (eImg) { console.log("[btnmenu cover]", eImg?.message); }
  }

  // 2) Send interactive buttons via the new handler system
  //    (GKTW if installed, Baileys native-flow otherwise, plain text last resort)
  const actionButtons = [
    { text: "MENU",    id: `${CONFIG.PREFIX}menu`,    type: "quick_reply" },
    { text: "HELP",    id: `${CONFIG.PREFIX}help`,    type: "quick_reply" },
    { text: "PING",    id: `${CONFIG.PREFIX}ping`,    type: "quick_reply" },
    { text: "RUNTIME", id: `${CONFIG.PREFIX}runtime`, type: "quick_reply" },
  ];
  const footer = `${CONFIG.BOT_NAME} v${CONFIG.VERSION}`;
  const quotedRef = imgSent ? undefined : msg;

  try {
    const { sendButtons: _hSendButtons } = await import("./handlers/interactiveHandler.js");
    await _hSendButtons(sock, jid, imgSent ? "Tap a button below:" : bodyText, actionButtons, { footer, quoted: quotedRef });
    await sendMenuSong(sock, jid, msg);
  } catch (e) {
    console.log("[btnmenu]", e?.message);
    // Final fallback: inline native-flow
    try {
      await sendNativeFlowButtons(sock, jid, quotedRef, imgSent ? "Tap a button below:" : bodyText,
        actionButtons.map(b => ({ id: b.id, text: b.text })), footer);
      await sendMenuSong(sock, jid, msg);
    } catch {
      if (!imgSent) await _sendPlainReply(sock, msg, `Buttons UI not supported on this WhatsApp client.\nTry: ${CONFIG.PREFIX}togglemenu list`);
    }
  }
});

