// .unzip / .extract — Extract files from a ZIP archive one by one
cmd(["unzip","extract","zipextract","fileextract"], { desc: "Extract files from a ZIP archive — reply to a zip doc with .unzip", category: "DOWNLOAD" }, async (sock, msg, args) => {
  const jid = msg.key.remoteJid;
  // Get quoted doc or direct doc
  const q = msg.message?.extendedTextMessage?.contextInfo?.quotedMessage;
  const doc = msg.message?.documentMessage || q?.documentMessage;
  if (!doc) {
    await sendReply(sock, msg, `📦 *Zip Extractor*

_Reply to a ZIP file with *${CONFIG.PREFIX}unzip*_

*Supported:* .zip archives
*Limit:* 50 MB per file`);
    return;
  }
  const fname = doc.fileName || "archive";
  const ext = fname.split(".").pop().toLowerCase();
  if (!["zip"].includes(ext)) {
    await sendReply(sock, msg, `❌ Only ZIP archives are supported right now.`);
    return;
  }
  await react(sock, msg, "📦");
  const statusMsg = await sock.sendMessage(jid, { text: `📦 Unpacking *${fname}*...` }, { quoted: msg });
  try {
    // Download the zip buffer
    const stream = await downloadContentFromMessage(doc, "document");
    let zipBuf = Buffer.from([]);
    for await (const chunk of stream) zipBuf = Buffer.concat([zipBuf, chunk]);

    // Use JSZip (or AdmZip if available) to extract
    let entries = [];
    try {
      const AdmZip = require("adm-zip");
      const zip = new AdmZip(zipBuf);
      entries = zip.getEntries().filter(e => !e.isDirectory && e.getData().length > 0);
    } catch {
      // Fallback: manual zip central directory parse
      await editMessage(sock, jid, null, `❌ Could not parse ZIP. Make sure it's a valid .zip file.`);
      return;
    }

    if (!entries.length) {
      await editMessage(sock, jid, null, `📦 *${fname}* is empty or has no extractable files.`);
      return;
    }

    const limit = Math.min(entries.length, 20); // max 20 files to avoid spam
    await editMessage(sock, jid, null, `📦 *${fname}*

🗂️ Found *${entries.length}* file${entries.length > 1 ? "s" : ""} — sending ${limit}...`);

    let sent = 0;
    for (let i = 0; i < limit; i++) {
      const entry = entries[i];
      try {
        const fileBuf = entry.getData();
        if (fileBuf.length > 50 * 1024 * 1024) {
          await sock.sendMessage(jid, { text: `⚠️ *${entry.entryName}* — too large (${(fileBuf.length/1024/1024).toFixed(1)} MB), skipped.` }, { quoted: msg });
          continue;
        }
        const _mimeMap = { jpg:"image/jpeg",jpeg:"image/jpeg",png:"image/png",gif:"image/gif",mp4:"video/mp4",mp3:"audio/mpeg",pdf:"application/pdf",txt:"text/plain" };
        const _fExt = entry.entryName.split(".").pop().toLowerCase();
        const _mime = _mimeMap[_fExt] || "application/octet-stream";
        await sock.sendMessage(jid, {
          document: fileBuf,
          mimetype: _mime,
          fileName: entry.entryName.split("/").pop() || entry.entryName,
          caption: `📄 *${entry.entryName}*
📦 From: _${fname}_
🔢 File ${i+1}/${limit}`
        }, { quoted: msg });
        sent++;
        if (i < limit - 1) await new Promise(r => setTimeout(r, 500)); // rate limit
      } catch { /* skip unreadable entry */ }
    }

    await editMessage(sock, jid, null, `✅ Extracted *${sent}* of ${entries.length} file${entries.length > 1 ? "s" : ""} from *${fname}*${entries.length > 20 ? `
_First 20 only — archive has ${entries.length} total_` : ""}`);
    await react(sock, msg, "✅");
  } catch (e) {
    await editMessage(sock, jid, null, `❌ Extraction failed: ${e.message}`);
    await react(sock, msg, "❌");
  }
});

