// ─── AI Code Gen helper — tries 5 sources ────────────────────────────────────
async function _aiGenerateCode(language, prompt, timeoutMs = 40000) {
  const sysPrompt = `You are an expert ${language} programmer. Write ONLY the code, no explanation, no markdown fences. Task: ${prompt}`;
  // 1. Prexzyvilla
  try {
    const r = await prexzyGet("/ai/prompttocode", { prompt, language }, timeoutMs);
    const d = r.data;
    const code = d?.data?.code || d?.code || d?.response || d?.text || d?.result || (typeof d?.data === "string" ? d.data : null);
    if (code && code.length > 10) return { code, source: "Prexzyvilla" };
  } catch {}
  // 2. Prexzyvilla aichat with explicit code request
  try {
    const r2 = await prexzyGet("/ai/aichat", { prompt: sysPrompt }, 30000);
    const d2 = r2.data;
    const code2 = d2?.data?.response || d2?.response || d2?.text || d2?.result || (typeof d2?.data === "string" ? d2.data : null);
    if (code2 && code2.length > 10) return { code: code2, source: "Prexzyvilla/Chat" };
  } catch {}
  // 3. Nexoracle GPT
  try {
    const { data: nd } = await axios.get(`https://api.nexoracle.com/ai/gpt?apikey=free_key@maher_apis&prompt=${encodeURIComponent(sysPrompt)}`, { timeout: 25000 });
    const nc = nd?.result || nd?.response || nd?.message || nd?.text;
    if (nc && nc.length > 10) return { code: nc, source: "Nexoracle" };
  } catch {}
  // 4. siputzx Llama3
  try {
    const { data: sd } = await axios.get(`https://api.siputzx.my.id/api/ai/llama33?prompt=${encodeURIComponent(sysPrompt)}`, { timeout: 25000 });
    const sc = sd?.data || sd?.result || sd?.response;
    if (sc && sc.length > 10) return { code: sc, source: "Llama3" };
  } catch {}
  // 5. Blackbox AI
  try {
    const bbResp = await axios.post("https://www.blackbox.ai/api/chat", {
      messages: [{ role: "user", content: sysPrompt }],
      codeModelMode: true, agentMode: {},
    }, { timeout: 25000, headers: { "Content-Type": "application/json", "User-Agent": "Mozilla/5.0" } });
    const bbCode = typeof bbResp.data === "string" ? bbResp.data : bbResp.data?.response;
    if (bbCode && bbCode.length > 10) return { code: bbCode, source: "BlackboxAI" };
  } catch {}
  return null;
}
