cmd(["quizguess","prexzyquiz","pquiz"], { desc: "Prexzyvilla quiz — guess the correct answer", category: "GAMES" }, async (sock, msg, args) => {
  await react(sock, msg, "🎯");
  const level = args[0] || "easy";
  const r = await prexzyGet("/game/quizguess", { level }, 20000);
  const d = r.data?.data || r.data;
  if (!r.ok || !d) { await sendReply(sock, msg, `❌ Could not get quiz question.`); return; }
  const question = d.question || d.q || d.text || "Unknown question";
  const opts = d.options || d.choices || d.answers || [];
  let out = `🎯 *Quiz — Guess the Answer*\n\n❓ *${question}*\n\n`;
  if (opts.length) opts.forEach((o, i) => { out += `  ${String.fromCharCode(65+i)}) ${o}\n`; });
  const ans = d.answer || d.correct || d.correctAnswer;
  if (ans) out += `\n||Answer: *${ans}*||`;
  out += ``;
  await sendReply(sock, msg, out);
  await react(sock, msg, "✅");
  try {
    await sendNativeFlowButtons(sock, msg.key.remoteJid, msg,
      `🎯 *Quiz ready!*`,
      [
        { text: "🔄 Next Question", id: `${CONFIG.PREFIX}quizguess ${level}` },
        { text: "🎲 Random Quiz",   id: `${CONFIG.PREFIX}quizrandom` },
      ],
      `${CONFIG.BOT_NAME} • Quiz`
    );
  } catch {}
});

