// .imdbsearch — IMDb movie search
cmd(["imdbsearch","imdb2","movieinfo2"], { desc: "IMDb movie/series search — .imdbsearch <title>", category: "SEARCH" }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `Usage: *${CONFIG.PREFIX}imdbsearch <movie/series title>*`); return; }
  await react(sock, msg, "🎬");
  const r = await prexzyGet("/search/imdb", { query: args.join(" ") }, 25000);
  const d = r.data?.data || r.data;
  if (!r.ok || !d) { await sendReply(sock, msg, `❌ IMDb search failed.`); return; }
  const items = Array.isArray(d) ? d : (d.results || d.result || [d]);
  let out = `🎬 *IMDb Search — "${args.join(" ")}"*\n\n`;
  items.slice(0, 5).forEach((it, i) => {
    const t = it?.title || it?.name || it?.Title || "Unknown";
    const y = it?.year || it?.Year || it?.releaseDate || "";
    const tp = it?.type || it?.Type || it?.mediaType || "";
    const rt = it?.rating || it?.imdbRating || "";
    out += `*${i+1}.* 🎥 *${t}*${y ? ` (${y})` : ""}\n`;
    if (tp) out += `   📌 Type: ${tp}\n`;
    if (rt) out += `   ⭐ Rating: ${rt}\n`;
    if (it?.url || it?.link) out += `   🔗 ${it.url || it.link}\n`;
    out += "\n";
  });
  out += ``;
  await sendReply(sock, msg, out);
  await react(sock, msg, "✅");
  try {
    const _imdbFirst = items[0];
    const _imdbUrl = _imdbFirst?.url || _imdbFirst?.link;
    const _imdbBtns = [];
    if (_imdbUrl) _imdbBtns.push({ type: "url", text: "🎬 Open on IMDb", url: _imdbUrl });
    _imdbBtns.push({ type: "url", text: "🔍 Search IMDb", url: `https://www.imdb.com/find?q=${encodeURIComponent(args.join(" "))}` });
    await sendCTAButtons(sock, msg.key.remoteJid, msg,
      `🎬 *IMDb — "${args.join(" ")}"*`,
      _imdbBtns,
      `${CONFIG.BOT_NAME} • IMDb`
    );
  } catch {}
});

// .wallpaper — HD wallpaper search
cmd(["wallpaper","wall","hdwallpaper"], { desc: "Search HD wallpapers — .wallpaper <query>", category: "SEARCH" }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `Usage: *${CONFIG.PREFIX}wallpaper <query>*`); return; }
  await react(sock, msg, "🖼️");
  const r = await prexzyGet("/search/wallpaper", { query: args.join(" ") }, 25000);
  const d = r.data?.data || r.data;
  const items = Array.isArray(d) ? d : (d?.results || d?.wallpapers || d?.images || (d?.url ? [d] : null));
  if (!r.ok || !items?.length) { await sendReply(sock, msg, `❌ No wallpapers found for: _${args.join(" ")}_`); return; }
  const pick = items[Math.floor(Math.random() * Math.min(items.length, 5))];
  const imgUrl = pick?.url || pick?.image || pick?.imageUrl || pick?.src || (typeof pick === "string" ? pick : null);
  if (imgUrl) {
    try {
      const buf = Buffer.from((await axios.get(imgUrl, { responseType: "arraybuffer", timeout: 30000 })).data);
      await sock.sendMessage(msg.key.remoteJid, { image: buf, caption: `🖼️ *HD Wallpaper*\n🔍 "${args.join(" ")}"` }, { quoted: msg });
      await react(sock, msg, "✅"); return;
    } catch {}
  }
  // fallback: text list
  let out = `🖼️ *Wallpaper Results — "${args.join(" ")}"*\n\n`;
  items.slice(0, 5).forEach((it, i) => { const u = it?.url || it?.image || (typeof it === "string" ? it : null); if (u) out += `*${i+1}.* ${u}\n`; });
  out += ``;
  await sendReply(sock, msg, out);
  await react(sock, msg, "✅");
});

