// ── AI: Music From Lyrics ──────────────────────────────────────────
cmd(["musiclyrics","makemusic","musicfromlyrics"], { desc: "Generate music from lyrics — .musiclyrics <lyrics>", category: "AI" }, async (sock, msg, args) => {
  const lyrics = args.join(" ");
  if (!lyrics) { await sendReply(sock, msg, `Usage: *${CONFIG.PREFIX}musiclyrics <lyrics>*`); return; }
  await react(sock, msg, "🎵");
  const r = await prexzyGet("/ai/musicfromlyrics", { lyrics }, 60000);
  const d = r.data;
  const audioUrl = d?.url || d?.audio_url || d?.result || d?.data?.url || (typeof d?.data === "string" ? d.data : null);
  const title = d?.title || d?.data?.title || "Generated Music";
  if (!r.ok || !audioUrl) { await sendReply(sock, msg, `❌ Music generation failed. Try with different lyrics.`); return; }
  try {
    const buf = Buffer.from((await axios.get(audioUrl, { responseType: "arraybuffer", timeout: 90000 })).data);
    await sock.sendMessage(msg.key.remoteJid, { audio: buf, mimetype: "audio/mpeg", ptt: false }, { quoted: msg });
    await react(sock, msg, "✅");
  } catch {
    await sendReply(sock, msg, `🎵 *Music Generated!*\n\n🔗 ${audioUrl}\n📄 *Title:* ${title}`);
  }
});

