// ── AI: Sora Watermark Remover ────────────────────────────────────
cmd(["soraremover","rmwatermark","removewatermark"], { desc: "Remove watermark from an image (Sora AI) — reply to image", category: "AI" }, async (sock, msg, args) => {
  await react(sock, msg, "✨");
  const quoted = msg.message?.extendedTextMessage?.contextInfo?.quotedMessage || msg.message?.imageMessage;
  const imgMsg = quoted?.imageMessage || (msg.message?.imageMessage);
  if (!imgMsg) { await sendReply(sock, msg, `Usage: *Reply to an image* with *${CONFIG.PREFIX}soraremover*`); return; }
  try {
    const imgBuf = await sock.downloadMediaMessage(msg);
    const b64 = Buffer.isBuffer(imgBuf) ? imgBuf.toString("base64") : null;
    if (!b64) throw new Error("No image data");
    const r = await prexzyGet("/ai/soraremover", { image: b64 }, 60000);
    const d = r.data;
    const resultUrl = d?.url || d?.image || d?.result || d?.data?.url || (typeof d?.data === "string" ? d.data : null);
    if (!r.ok || !resultUrl) throw new Error("No result URL");
    const buf = Buffer.from((await axios.get(resultUrl, { responseType: "arraybuffer", timeout: 45000 })).data);
    await sock.sendMessage(msg.key.remoteJid, { image: buf, caption: `✨ *Watermark Removed*` }, { quoted: msg });
    await react(sock, msg, "✅");
  } catch (e) {
    await sendReply(sock, msg, `❌ Watermark removal failed: ${e.message?.slice(0,80)}`);
  }
});

