// ── Basketball Scores ────────────────────────────────────────────
cmd(["basketball","nba","basketballscore"], { desc: "Basketball scores/schedule — .basketball [team]", category: "SEARCH" }, async (sock, msg, args) => {
  const query = (args.join(" ") || "").trim();
  await react(sock, msg, "🏀");
  const r = await prexzyGet("/sports/basketball", query ? { team: query } : {}, 20000);
  const d = r.data;
  const text_data = d?.data || d?.result || d?.text || d?.schedule || "";
  const games = d?.data?.games || d?.games || d?.matches || [];
  if (!r.ok || (!text_data && !games.length)) {
    // Fallback: Google search
    await sendReply(sock, msg, `🏀 *Basketball ${query || ""}*\n\n🔗 https://www.google.com/search?q=${encodeURIComponent("basketball scores " + (query || "today"))}`);
    return;
  }
  let text = `🏀 *Basketball${query ? " — " + query : " Scores"}*\n\n`;
  if (typeof text_data === "string" && text_data) {
    text += text_data.slice(0, 1000);
  } else if (Array.isArray(games) && games.length) {
    games.slice(0, 10).forEach((g, i) => {
      const home = g?.home || g?.home_team || "";
      const away = g?.away || g?.away_team || "";
      const score = g?.score || g?.result || "";
      text += `${i+1}. *${home}* vs *${away}*${score ? ` — ${score}` : ""}\n`;
    });
  }
  text += ``;
  await sendReply(sock, msg, text);
  await react(sock, msg, "✅");
});

