// ── Send Anonymous Email ──────────────────────────────────────────
cmd(["sendemail","anonmail","emailsend"], { desc: "Send anonymous email — .sendemail <to>|<subject>|<body>", category: "TOOLS", ownerOnly: true }, async (sock, msg, args) => {
  const full = args.join(" ");
  if (!full || !full.includes("|")) { await sendReply(sock, msg, `Usage: *${CONFIG.PREFIX}sendemail <to>|<subject>|<body>*\nExample: *.sendemail test@gmail.com|Hello|This is a test*`); return; }
  const parts = full.split("|");
  const to = parts[0]?.trim();
  const subject = parts[1]?.trim() || "No Subject";
  const body = parts.slice(2).join("|").trim() || "No body";
  if (!to || !to.includes("@")) { await sendReply(sock, msg, `❌ Invalid email address.`); return; }
  await react(sock, msg, "📧");
  const r = await prexzyGet("/tools/sendemail", { to, subject, message: body }, 30000);
  const d = r.data;
  const success = r.ok && (d?.status === "success" || d?.sent || d?.success || d?.message?.includes?.("sent"));
  if (!success) { await sendReply(sock, msg, `❌ Failed to send email. Try again later.`); return; }
  await sendReply(sock, msg, `📧 *Email Sent!*\n\n📬 *To:* ${to}\n📌 *Subject:* ${subject}`);
  await react(sock, msg, "✅");
});

// ── HTML to Image ────────────────────────────────────────────────
cmd(["html2img","htmltoimg","htmlrender"], { desc: "Render HTML as image — .html2img <html code>", category: "TOOLS" }, async (sock, msg, args) => {
  const html = args.join(" ");
  if (!html) { await sendReply(sock, msg, `Usage: *${CONFIG.PREFIX}html2img <html>*\nExample: *.html2img <h1 style="color:red">Hello!</h1>*`); return; }
  await react(sock, msg, "🖼️");
  const r = await prexzyGet("/tools/html2img", { html }, 35000);
  const d = r.data;
  const imgUrl = d?.url || d?.image || d?.result || (typeof d?.data === "string" ? d.data : null);
  if (!r.ok || !imgUrl) {
    // Try screenshotLayer as fallback
    try {
      const buf = Buffer.from((await axios.get(`${CONFIG.PREXZY_API}/ssweb/screenshotLayer?url=${encodeURIComponent("data:text/html," + html)}`, { responseType: "arraybuffer", timeout: 30000 })).data);
      if (buf && buf.length > 500) {
        await sock.sendMessage(msg.key.remoteJid, { image: buf, caption: `🖼️ *HTML Rendered*` }, { quoted: msg });
        await react(sock, msg, "✅"); return;
      }
    } catch {}
    await sendReply(sock, msg, `❌ HTML render failed.`); return;
  }
  const buf = Buffer.from((await axios.get(imgUrl, { responseType: "arraybuffer", timeout: 45000 })).data);
  await sock.sendMessage(msg.key.remoteJid, { image: buf, caption: `🖼️ *HTML Rendered*` }, { quoted: msg });
  await react(sock, msg, "✅");
});

// ── HTML Encode/Decode ────────────────────────────────────────────
cmd(["htmlencode","htmldecode","htmlecnc"], { desc: "Encode/Decode HTML entities — .htmlencode encode|decode <text>", category: "TOOLS" }, async (sock, msg, args) => {
  const mode = (args[0] || "").toLowerCase();
  const text = args.slice(1).join(" ");
  if (!mode || !text || (mode !== "encode" && mode !== "decode")) { await sendReply(sock, msg, `Usage: *${CONFIG.PREFIX}htmlencode encode|decode <text>*`); return; }
  await react(sock, msg, "🔤");
  const r = await prexzyGet("/tools/htmlecnc", { type: mode, text }, 20000);
  const d = r.data;
  const result = d?.result || d?.text || d?.data || (typeof d === "string" ? d : null);
  if (!r.ok || !result) {
    // Fallback: simple JS encode/decode
    let fallback;
    if (mode === "encode") fallback = text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
    else fallback = text.replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&#39;/g, "'");
    await sendReply(sock, msg, `🔤 *HTML ${mode.charAt(0).toUpperCase()+mode.slice(1)}*\n\n${fallback}`);
    return;
  }
  await sendReply(sock, msg, `🔤 *HTML ${mode.charAt(0).toUpperCase()+mode.slice(1)}*\n\n${result}`);
  await react(sock, msg, "✅");
});

