const _IMGSTYLE_MAP = {
  realisticimg:  { ep: "/ai/realistic",    label: "Realistic Image",    emoji: "📸" },
  animeimg:      { ep: "/ai/anime",        label: "Anime Style Image",  emoji: "🎌" },
  fantasyimg:    { ep: "/ai/fantasy",      label: "Fantasy Image",      emoji: "🧙" },
  cyberpunkimg:  { ep: "/ai/cyberpunk",    label: "Cyberpunk Image",    emoji: "🤖" },
  watercolorimg: { ep: "/ai/watercolor",   label: "Watercolor Image",   emoji: "🎨" },
  oilpainting:   { ep: "/ai/oil-painting", label: "Oil Painting Image", emoji: "🖼️" },
  pixelart:      { ep: "/ai/pixel-art",    label: "Pixel Art Image",    emoji: "👾" },
  sketchimg:     { ep: "/ai/sketch",       label: "Sketch Drawing",     emoji: "✏️" },
  cartoonimg:    { ep: "/ai/cartoon",      label: "Cartoon Image",      emoji: "🎭" },
  abstractimg:   { ep: "/ai/abstract",     label: "Abstract Art Image", emoji: "🌀" },
  minimalistimg: { ep: "/ai/minimalist",   label: "Minimalist Image",   emoji: "⬜" },
  surrealimg:    { ep: "/ai/surreal",      label: "Surreal Image",      emoji: "🌈" },
  vintageimg:    { ep: "/ai/vintage",      label: "Vintage/Retro Image",emoji: "📷" },
  steampunkimg:  { ep: "/ai/steampunk",    label: "Steampunk Image",    emoji: "⚙️" },
  horrorimg:     { ep: "/ai/horror",       label: "Horror Dark Image",  emoji: "👻" },
  scifiimg:      { ep: "/ai/sci-fi",       label: "Sci-Fi Image",       emoji: "🚀" },
  popartimg:     { ep: "/ai/pop-art",      label: "Pop Art Image",      emoji: "🎆" },
};
for (const [_isCmd, _isInfo] of Object.entries(_IMGSTYLE_MAP)) {
  cmd(_isCmd, { desc: `${_isInfo.label} — .${_isCmd} <prompt>`, category: "AI" }, async (sock, msg, args) => {
    const prompt = args.join(" ");
    if (!prompt) { await sendReply(sock, msg, `Usage: *${CONFIG.PREFIX}${_isCmd} <prompt>*\nExample: ${CONFIG.PREFIX}${_isCmd} a warrior in the forest`); return; }
    await react(sock, msg, _isInfo.emoji);
    const r = await prexzyGet(_isInfo.ep, { prompt, negative_prompt: "" }, 60000);
    if (!r.ok) { await sendReply(sock, msg, `❌ Image generation failed.`); return; }
    const d = r.data?.data || r.data?.result || r.data;
    const _dArr = Array.isArray(d) ? d[0] : (Array.isArray(d?.images) ? d.images[0] : null);
    const imgUrl = d?.url || d?.image_url || d?.image || d?.output || d?.result
      || (typeof _dArr === "string" ? _dArr : (_dArr?.url || _dArr?.image))
      || (typeof d === "string" && d.startsWith("http") ? d : null);
    if (!imgUrl) { await sendReply(sock, msg, `❌ No image URL in response.`); return; }
    const buf = Buffer.from((await axios.get(imgUrl, { responseType: "arraybuffer", timeout: 60000 })).data);
    await sock.sendMessage(msg.key.remoteJid, { image: buf, caption: `${_isInfo.emoji} *${_isInfo.label}*\n\n📝 Prompt: _${prompt}_` }, { quoted: msg });
    await react(sock, msg, "✅");
  });
}

