const _STYLETEXT_MAP = {
  allstyles:          { ep: "/tools/allstyles",         label: "All Text Styles" },
  circledtext:        { ep: "/tools/circled",           label: "Circled Text" },
  circlednegtext:     { ep: "/tools/circledneg",        label: "Circled (neg) Text" },
  fullwidthtext:      { ep: "/tools/fullwidth",         label: "Full Width Text" },
  mathboldtext:       { ep: "/tools/mathbold",          label: "Math Bold Text" },
  mathboldfraktur:    { ep: "/tools/mathboldfraktur",   label: "Math Bold Fraktur Text" },
  mathbolditalic:     { ep: "/tools/mathbolditalic",    label: "Math Bold Italic Text" },
  mathboldscript:     { ep: "/tools/mathboldscript",    label: "Math Bold Script Text" },
  mathdoublestruck:   { ep: "/tools/mathdoublestruck",  label: "Math Double-Struck Text" },
  mathmonospace:      { ep: "/tools/mathmonospace",     label: "Math Monospace Text" },
  mathsanstext:       { ep: "/tools/mathsans",          label: "Math Sans Text" },
  mathsansbold:       { ep: "/tools/mathsansbold",      label: "Math Sans Bold Text" },
  mathsansbolditalic: { ep: "/tools/mathsansbolditalic",label: "Math Sans Bold Italic Text" },
  mathsansitalic:     { ep: "/tools/mathsansitalic",    label: "Math Sans Italic Text" },
  parenthesized:      { ep: "/tools/parenthesized",     label: "Parenthesized Text" },
  regionalindicator:  { ep: "/tools/regionalindicator", label: "Regional Indicator Text" },
  squaredtext:        { ep: "/tools/squared",           label: "Squared Text" },
  squarednegtext:     { ep: "/tools/squaredneg",        label: "Squared (neg) Text" },
  tagtext:            { ep: "/tools/tag",               label: "Tag Style Text" },
  acutetext:          { ep: "/tools/acute",             label: "A-cute Text" },
  cjkthaitext:        { ep: "/tools/cjkthai",           label: "CJK+Thai Text" },
  curvy1text:         { ep: "/tools/curvy1",            label: "Curvy 1 Text" },
  curvy2text:         { ep: "/tools/curvy2",            label: "Curvy 2 Text" },
  curvy3text:         { ep: "/tools/curvy3",            label: "Curvy 3 Text" },
  fauxcyrillic:       { ep: "/tools/fauxcyrillic",      label: "Faux Cyrillic Text" },
  fauxethiopic:       { ep: "/tools/fauxethiopic",      label: "Faux Ethiopic Text" },
  mathfraktur:        { ep: "/tools/mathfraktur",       label: "Math Fraktur Text" },
  rockdotstext:       { ep: "/tools/rockdots",          label: "Rock Dots Text" },
  smallcapstext:      { ep: "/tools/smallcaps",         label: "Small Caps Text" },
  strokedtext:        { ep: "/tools/stroked",           label: "Stroked Text" },
  subscripttext:      { ep: "/tools/subscript",         label: "Subscript Text" },
  superscripttext:    { ep: "/tools/superscript",       label: "Superscript Text" },
  invertedtext:       { ep: "/tools/inverted",          label: "Inverted Text" },
  reversedtext:       { ep: "/tools/reversed",          label: "Reversed Text" },
};

for (const [stCmd, stInfo] of Object.entries(_STYLETEXT_MAP)) {
  cmd(stCmd, { desc: `${stInfo.label} — .${stCmd} <text>`, category: "TOOLS" }, async (sock, msg, args) => {
    const text = args.join(" ");
    if (!text) { await sendReply(sock, msg, `Usage: *${CONFIG.PREFIX}${stCmd} <text>*`); return; }
    await react(sock, msg, "✨");
    const r = await prexzyGet(stInfo.ep, { text });
    if (!r.ok) { await sendReply(sock, msg, `❌ Style conversion failed.`); return; }
    const d = r.data?.data || r.data;
    if (stCmd === "allstyles") {
      const styles = d?.styles || d?.results || d || {};
      let out = `✨ *All Text Styles for: "${text}"*\n\n`;
      if (typeof styles === "object") {
        for (const [name, val] of Object.entries(styles).slice(0, 20)) {
          out += `*${name}:* ${val}\n`;
        }
      } else out += String(styles).slice(0, 2000);
      out += ``;
      await sendReply(sock, msg, out);
    } else {
      const result = d?.styled || d?.result || d?.text || d?.output || (typeof d === "string" ? d : JSON.stringify(d));
      await sendReply(sock, msg, `✨ *${stInfo.label}*\n\n${result}`);
    }
    await react(sock, msg, "✅");
  });
}

