// ═══════════════════════════════════════════════════════════════════════════
// .HELP COMMAND — Comprehensive all-commands guide
// ═══════════════════════════════════════════════════════════════════════════
  // ── .creator / .creatoroff — lock/unlock bot to creator-only mode ──────────────// ═══════════════════════════════════════════════════════════════════════════════
//  MENU3 — Compact "dope" menu: listed names only, no descriptions, with bot pic
// ═══════════════════════════════════════════════════════════════════════════════
cmd(["menu3","fastmenu","quickmenu"], { desc: "Compact listed menu (no descriptions)", category: "INFO" }, async (sock, msg, args) => {
  await react(sock, msg, "📋");
  const P = CONFIG.PREFIX;
  const jid = msg.key.remoteJid;
  // Gather category filter if provided
  const filterCat = (args[0] || "").toLowerCase().trim();
  // Build flat sorted list of unique primary commands (no aliases, no adult)
  const seen = new Set();
  const byCategory = {};
  for (const [name, entry] of commands.entries()) {
    if (entry.adult) continue;
    const aliases = Array.isArray(entry.aliases) ? entry.aliases : [];
    const isPrimary = !aliases.length || aliases[0] === name;
    if (!isPrimary) continue;
    if (seen.has(name)) continue;
    seen.add(name);
    const cat = (entry.category || "OTHER").toUpperCase();
    if (filterCat && !cat.toLowerCase().includes(filterCat)) continue;
    if (!byCategory[cat]) byCategory[cat] = [];
    byCategory[cat].push(name);
  }
  const catOrder = Object.keys(byCategory).sort();
  if (!catOrder.length) { await sendReply(sock, msg, `❌ No commands found${filterCat ? " in category: " + filterCat : ""}.`); return; }
  // Build message — one command per line with category header
  const chunks = [];
  for (const cat of catOrder) {
    const cmds = byCategory[cat].sort();
    let block = `*┤ ${cat} ├*\n`;
    cmds.forEach(c => { block += `${P}${c}\n`; });
    chunks.push(block);
  }
  const header = `📋 *${CONFIG.BOT_NAME} Commands* • ${seen.size} total\n_${CONFIG.VERSION}_\n\n`;
  const footer = ``;
  // WhatsApp has a 65535 char message limit — split into pages if needed
  const MAX = 8000;
  let page = header;
  for (const chunk of chunks) {
    if ((page + chunk).length > MAX) {
      try { await sock.sendMessage(jid, { text: page.trimEnd() + footer }, { quoted: msg }); } catch { await sendReply(sock, msg, page.trimEnd() + footer); }
      page = "*📋 (continued)*\n\n";
      await new Promise(r => setTimeout(r, 400));
    }
    page += chunk;
  }
  if (page.trim().length > 5) {
    try { await sock.sendMessage(jid, { text: page.trimEnd() + footer }, { quoted: msg }); } catch { await sendReply(sock, msg, page.trimEnd() + footer); }
  }

  // ── FALLBACK ENDPOINTS (merged from duplicate cmd registrations) ──
  // fallback URL: http://localhost:${PORT}/debug`;
  // fallback URL: http://localhost:${PORT}/debug-api`;
});

