// ── .vcfcast / .vcfbroadcast — build and send a VCF file from a list of numbers ──
cmd(["vcfcast","vcfbroadcast","makevcf"], {
  desc: "Build a VCF contacts file from phone numbers — .vcfcast <name> | +2348012345678 | +2348098765432 ...",
  category: "TOOLS",
  ownerOnly: true,
}, async (sock, msg, args) => {
  const jid = msg.key.remoteJid;
  const P = CONFIG.PREFIX;
  const full = args.join(" ").trim();
  if (!full) {
    await sendReply(sock, msg,
`📇 *VCF Broadcast Usage*

*${P}vcfcast <contact name> | <numbers, one per line or separated by |>*

Example:
${P}vcfcast MIAS MDX | +2348012345678 | +2348098765432 | +2349031234567

• Numbers must start with country code (+234...)
• Name is used for all contacts (numbered: Name 1, Name 2…)
• A .vcf file will be sent — save to phone to import all at once`);
    return;
  }

  // Parse: split by | or newline
  const parts = full.split(/[\|\n]+/).map(s => s.trim()).filter(Boolean);
  if (parts.length < 2) {
    await sendReply(sock, msg, `❌ Provide a name AND at least one number, separated by *|*\n\nExample:\n${P}vcfcast MIAS MDX | +2348012345678 | +2349031234567`);
    return;
  }

  const contactName = parts[0];
  const numbers = parts.slice(1).map(n => n.replace(/[^\d+]/g, "").replace(/^\+/, "")).filter(n => n.length >= 7);
  if (!numbers.length) {
    await sendReply(sock, msg, `❌ No valid numbers found. Numbers must be in international format: +2348012345678`);
    return;
  }

  await react(sock, msg, "📇");
  const statusMsg = await sock.sendMessage(jid, { text: `📇 *VCF Builder*\n\n⬡ Building ${numbers.length} contact(s)...` }, { quoted: msg });
  const stKey = statusMsg.key;

  let vcf = "";
  numbers.forEach((num, i) => {
    const name = numbers.length === 1 ? contactName : `${contactName} ${i + 1}`;
    vcf +=
`BEGIN:VCARD\r\nVERSION:3.0\r\nFN:${name}\r\nTEL;type=CELL;type=VOICE;waid=${num}:+${num}\r\nEND:VCARD\r\n`;
  });

  const vcfBuf = Buffer.from(vcf, "utf8");
  const fileName = `${contactName.replace(/\s+/g, "_")}_${numbers.length}_contacts.vcf`;

  await editMessage(sock, jid, stKey, `📇 *VCF Builder*\n\n⬢ Building ${numbers.length} contact(s)... ✅\n⬡ Sending file...`);
  await sock.sendMessage(jid, {
    document: vcfBuf,
    mimetype: "text/vcard",
    fileName,
    caption: `📇 *VCF File Ready*\n\n👤 Name: *${contactName}*\n📱 Contacts: *${numbers.length}*\n\n_Save this file to your phone and open it to import all contacts at once._`,
  }, { quoted: msg });
  await editMessage(sock, jid, stKey, `📇 *VCF Builder*\n\n⬢ Building contacts... ✅\n⬢ Sending file... ✅\n\n✅ *Done! ${numbers.length} contact(s) in VCF file.*`);
  await react(sock, msg, "✅");
});

// ── .vcfread / .importvcf — parse a replied VCF and show contact list ──
cmd(["vcfread","importvcf","readvcf"], {
  desc: "Read a VCF file and list all contacts — reply to a .vcf document",
  category: "TOOLS",
}, async (sock, msg, args) => {
  const jid = msg.key.remoteJid;
  const P = CONFIG.PREFIX;
  // Accept VCF from quoted or direct document
  const _ctx = msg.message?.extendedTextMessage?.contextInfo;
  const _qDoc = _ctx?.quotedMessage?.documentMessage;
  const _doc = msg.message?.documentMessage || _qDoc;
  if (!_doc) {
    await sendReply(sock, msg, `📋 *VCF Reader*\n\nReply to a *.vcf* document with *${P}vcfread*`);
    return;
  }
  const mime = _doc.mimetype || "";
  const fname = _doc.fileName || "";
  if (!mime.includes("vcard") && !fname.endsWith(".vcf")) {
    await sendReply(sock, msg, `❌ That doesn't look like a VCF file. Send a *.vcf* contacts file.`);
    return;
  }
  await react(sock, msg, "📋");
  const statusMsg = await sock.sendMessage(jid, { text: `📋 *VCF Reader*\n\n⬡ Downloading file...\n⬡ Parsing contacts...` }, { quoted: msg });
  const stKey = statusMsg.key;
  try {
    const _src = _qDoc ? _ctx.quotedMessage.documentMessage : msg.message.documentMessage;
    const _msgType = _qDoc ? "document" : "document";
    const stream = await downloadContentFromMessage(_src, "document");
    let buf = Buffer.from([]);
    for await (const chunk of stream) buf = Buffer.concat([buf, chunk]);
    const text = buf.toString("utf8");
    // Parse VCF entries
    const vcards = text.split(/BEGIN:VCARD/i).filter(s => s.trim());
    const contacts = vcards.map(card => {
      const fn = (card.match(/FN[^:]*:(.+)/i) || [])[1]?.trim() || "";
      const tel = (card.match(/TEL[^:]*:(.+)/i) || [])[1]?.trim() || "";
      return { fn, tel };
    }).filter(c => c.fn || c.tel);
    if (!contacts.length) {
      await editMessage(sock, jid, stKey, `📋 *VCF Reader*\n\n⚠️ No contacts found in file.`);
      return;
    }
    const lines = contacts.slice(0, 200).map((c, i) => `${i + 1}. *${c.fn}* — ${c.tel || "no number"}`);
    const out =
`📋 *VCF Contacts List*
━━━━━━━━━━━━━━━━━━━━

📱 *Total:* ${contacts.length} contacts${contacts.length > 200 ? " (showing first 200)" : ""}

${lines.join("\n")}

━━━━━━━━━━━━━━━━━━━━`;
    await editMessage(sock, jid, stKey, `📋 *VCF Reader*\n\n⬢ Downloading file... ✅\n⬢ Parsing contacts... ✅`);
    await sendLongText(sock, jid, out, msg);
    await react(sock, msg, "✅");
  } catch (e) {
    await editMessage(sock, jid, stKey, `📋 *VCF Reader*\n\n❌ Error: ${e.message}`);
  }
});

