// Generic DC AI text helper
async function _dcAiText(endpoint, paramKey, query) {
  const r = await dcGet(endpoint, { [paramKey]: query }, 22000);
  if (!r.ok) return null;
  const d = r.data?.data || r.data?.result || r.data;
  return d?.text || d?.message || d?.result || d?.response || d?.answer || d?.content ||
         d?.output || (typeof d === "string" && d.length > 3 ? d : null);
}

