cmd(["dcremovebg","removebgdc","rmbgdc"], { desc: "Remove image background via DC — reply to image", category: "TOOLS" }, async (sock, msg, args) => {
  const jid = msg.key.remoteJid;
  const P = CONFIG.PREFIX;
  const _ctx = msg.message?.extendedTextMessage?.contextInfo;
  const img = msg.message?.imageMessage || _ctx?.quotedMessage?.imageMessage;
  if (!img) { await sendReply(sock, msg, `🖼️ *Background Remover (DC)*\n\nReply to an image with *${P}dcremovebg*`); return; }
  await react(sock, msg, "✂️");
  const st = await sock.sendMessage(jid, { text: `✂️ *BG Remover (DC)*\n\n⬡ Uploading image...\n⬡ Removing background...` }, { quoted: msg });
  try {
    const _src = msg.message?.imageMessage || _ctx?.quotedMessage?.imageMessage;
    const stream = await downloadContentFromMessage(_src, "image");
    let buf = Buffer.from([]);
    for await (const c of stream) buf = Buffer.concat([buf, c]);
    // Upload to catbox first for a URL, then pass to DC removebg
    const FormData_rbg = (await import("form-data")).default;
    const form = new FormData_rbg();
    form.append("reqtype", "fileupload");
    form.append("fileToUpload", buf, { filename: "image.jpg", contentType: "image/jpeg" });
    const upRes = await axios.post("https://catbox.moe/user.php", form, { headers: form.getHeaders(), timeout: 30000 });
    const imgUrl = upRes.data?.trim();
    if (!imgUrl || !imgUrl.startsWith("http")) { await editMessage(sock, jid, st.key, `❌ Upload failed.`); return; }
    const r = await dcGet("/removebg", { url: imgUrl }, 30000);
    const d = r.data?.data || r.data?.result || r.data;
    const outUrl = d?.url || d?.image || d?.result || (typeof d === "string" && d.startsWith("http") ? d : null);
    if (outUrl) {
      const outBuf = Buffer.from((await axios.get(outUrl, { responseType: "arraybuffer", timeout: 25000 })).data);
      await sock.sendMessage(jid, { image: outBuf, caption: `✂️ *Background Removed!*` }, { quoted: msg });
      await editMessage(sock, jid, st.key, `✂️ *BG Removed!* ✅`);
      await react(sock, msg, "✅");
    } else { await editMessage(sock, jid, st.key, `❌ BG removal failed.`); }
  } catch(e) { await editMessage(sock, jid, st.key, `❌ Error: ${e.message}`); }
});

