cmd(["dcimagen","imagendc","dcflux","dcai2img"], { desc: "Generate AI image via DC — .dcimagen <prompt>", category: "AI" }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}dcimagen <prompt>\nExample: ${CONFIG.PREFIX}dcimagen a sunset over Lagos`); return; }
  await react(sock, msg, "🎨");
  const prompt = args.join(" ");
  const jid = msg.key.remoteJid;
  const st = await sock.sendMessage(jid, { text: `🎨 *AI Image Generator (DC)*\n\n⬡ Generating image...\n_Prompt: ${prompt.slice(0,80)}_` }, { quoted: msg });
  try {
    let imgUrl = null;
    const _eps = [
      { ep: "/flux", param: "prompt" },
      { ep: "/fluxpro", param: "prompt" },
      { ep: "/diffusion", param: "prompt" },
      { ep: "/animagine", param: "prompt" },
      { ep: "/epicrealism", param: "prompt" },
    ];
    for (const { ep, param } of _eps) {
      if (imgUrl) break;
      try {
        const r = await dcGet(ep, { [param]: prompt }, 40000);
        const d = r.data?.data || r.data?.result || r.data;
        imgUrl = d?.url || d?.image || d?.output || d?.imageUrl || (typeof d === "string" && d.startsWith("http") ? d : null);
      } catch {}
    }
    if (!imgUrl) { await editMessage(sock, jid, st.key, `❌ Image generation failed.`); return; }
    const buf = Buffer.from((await axios.get(imgUrl, { responseType: "arraybuffer", timeout: 40000 })).data);
    await sock.sendMessage(jid, { image: buf, caption: `🎨 *AI Image*\n\n_"${prompt}"_` }, { quoted: msg });
    await editMessage(sock, jid, st.key, `🎨 *AI Image* — Done! ✅`);
    await react(sock, msg, "✅");
  } catch(e) { await editMessage(sock, jid, st.key, `❌ Error: ${e.message}`); }
});

