cmd(["dcupload","uploaddc","dcuploader"], { desc: "Upload a file to catbox via DC — reply to any file", category: "TOOLS" }, async (sock, msg, args) => {
  const jid = msg.key.remoteJid;
  const P = CONFIG.PREFIX;
  const _ctx = msg.message?.extendedTextMessage?.contextInfo;
  const _doc = msg.message?.documentMessage || _ctx?.quotedMessage?.documentMessage;
  const _img = msg.message?.imageMessage || _ctx?.quotedMessage?.imageMessage;
  const _vid = msg.message?.videoMessage || _ctx?.quotedMessage?.videoMessage;
  const _aud = msg.message?.audioMessage || _ctx?.quotedMessage?.audioMessage;
  const media = _doc || _img || _vid || _aud;
  if (!media) { await sendReply(sock, msg, `📤 *Uploader (DC)*\n\nReply to a file, image, video, or audio with *${P}dcupload*`); return; }
  await react(sock, msg, "📤");
  const st = await sock.sendMessage(jid, { text: `📤 *Uploader (DC)*\n\n⬡ Downloading file...\n⬡ Uploading to catbox...` }, { quoted: msg });
  try {
    const type = _doc ? "document" : _img ? "image" : _vid ? "video" : "audio";
    const stream = await downloadContentFromMessage(media, type);
    let buf = Buffer.from([]);
    for await (const c of stream) buf = Buffer.concat([buf, c]);
    const fname = _doc?.fileName || `file_${Date.now()}.${type === "image" ? "jpg" : type === "video" ? "mp4" : type === "audio" ? "mp3" : "bin"}`;
    const mime = media.mimetype || "application/octet-stream";
    const FormData_ul = (await import("form-data")).default;
    const form = new FormData_ul();
    form.append("reqtype", "fileupload");
    form.append("fileToUpload", buf, { filename: fname, contentType: mime });
    const upRes = await axios.post("https://catbox.moe/user.php", form, { headers: form.getHeaders(), timeout: 60000 });
    const url = upRes.data?.trim();
    if (url && url.startsWith("http")) {
      await editMessage(sock, jid, st.key,
`📤 *Upload Done! (catbox)*

🔗 *Link:* ${url}
📂 *File:* ${fname}`);
      await react(sock, msg, "✅");
    } else { await editMessage(sock, jid, st.key, `❌ Upload failed.`); }
  } catch(e) { await editMessage(sock, jid, st.key, `❌ Error: ${e.message}`); }
});

