// ─── AI Music: Suno / Mubert / Mureka / AIVA ────────────────────────────────
cmd(["dcaimusic","aimusicdc","dcmusicgen"], { desc: "Generate AI music via DC (Suno/Mubert/Mureka/AIVA) — .dcaimusic <describe>", category: "AI" }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}dcaimusic <music description>\n\nExamples:\n${CONFIG.PREFIX}dcaimusic chill lofi hip hop with rain sounds\n${CONFIG.PREFIX}dcaimusic epic orchestral battle music\n${CONFIG.PREFIX}dcaimusic afrobeats love song`); return; }
  await react(sock, msg, "🎶");
  const prompt = args.join(" ");
  const jid = msg.key.remoteJid;
  const stMsg = await sock.sendMessage(jid, { text: `🎶 *MIAS MDX — AI Music*\n\n⬡ Submitting generation task...\n⬡ Waiting for audio (1-3 min)...\n⬡ Sending...` }, { quoted: msg });
  const stKey = stMsg.key;

  const _pollTask = async (statusEndpoint, taskId, maxWait) => {
    const start = Date.now();
    while (Date.now() - start < maxWait) {
      await new Promise(r => setTimeout(r, 8000));
      try {
        const r = await dcGet(statusEndpoint, { task_id: taskId }, 15000);
        const d = r.data?.data || r.data;
        if (!r.ok) continue;
        const status = String(d?.status || d?.state || "").toLowerCase();
        if (["complete","completed","done","success","finished"].includes(status)) {
          return d?.audio_url || d?.url || d?.mp3 || d?.audio || d?.download_url;
        }
        if (["failed","error","cancelled"].includes(status)) return null;
      } catch {}
    }
    return null;
  };

  let audioUrl = null;
  // 1) Suno via DC
  if (!audioUrl) {
    try {
      const cr = await dcPost("/aimusic/suno/create", { prompt }, 30000);
      const taskId = cr.ok && (cr.data?.data?.task_id || cr.data?.task_id);
      if (taskId) {
        await editMessage(sock, jid, stKey, `🎶 *AI Music (Suno)*\n\n✅ Task submitted — polling...`);
        audioUrl = await _pollTask("/aimusic/suno/status", taskId, 180000);
      }
    } catch {}
  }
  // 2) Mubert via DC
  if (!audioUrl) {
    try {
      const cr = await dcPost("/aimusic/mubert/create", { prompt, duration: 60 }, 30000);
      const taskId = cr.ok && (cr.data?.data?.task_id || cr.data?.task_id);
      if (taskId) {
        await editMessage(sock, jid, stKey, `🎶 *AI Music (Mubert)*\n\n✅ Task submitted — polling...`);
        audioUrl = await _pollTask("/aimusic/mubert/status", taskId, 120000);
      }
    } catch {}
  }
  // 3) Mureka via DC
  if (!audioUrl) {
    try {
      const cr = await dcPost("/aimusic/mureka/create", { prompt }, 30000);
      const taskId = cr.ok && (cr.data?.data?.task_id || cr.data?.task_id);
      if (taskId) {
        await editMessage(sock, jid, stKey, `🎶 *AI Music (Mureka)*\n\n✅ Task submitted — polling...`);
        audioUrl = await _pollTask("/aimusic/mureka/status", taskId, 120000);
      }
    } catch {}
  }
  // 4) AIVA via DC
  if (!audioUrl) {
    try {
      const cr = await dcPost("/aimusic/aiva/create", { prompt }, 30000);
      const taskId = cr.ok && (cr.data?.data?.task_id || cr.data?.task_id);
      if (taskId) {
        await editMessage(sock, jid, stKey, `🎶 *AI Music (AIVA)*\n\n✅ Task submitted — polling...`);
        audioUrl = await _pollTask("/aimusic/aiva/status", taskId, 120000);
      }
    } catch {}
  }
  // 5) Simple DC aimusicgen fallback
  if (!audioUrl) { try { const r = await dcGet("/aimusic/generate", { prompt }, 90000); if (r.ok) audioUrl = r.data?.url || r.data?.audio || r.data?.data?.url; } catch {} }
  // 6) Prexzy fallback
  if (!audioUrl) { try { const r = await prexzyGet("/ai/aimusic", { prompt }, 60000); if (r.ok) audioUrl = r.data?.url || r.data?.audio || r.data?.data?.url; } catch {} }

  if (!audioUrl) { await editMessage(sock, jid, stKey, `🎶 *AI Music*\n\n❌ Generation failed or timed out. Try again with a shorter/simpler prompt.`); return; }
  await editMessage(sock, jid, stKey, `🎶 *AI Music*\n\n✅ Generated! Downloading audio...`);
  try {
    const buf = Buffer.from((await axios.get(audioUrl, { responseType: "arraybuffer", timeout: 60000 })).data);
    await sock.sendMessage(jid, { audio: buf, mimetype: "audio/mpeg", ptt: false, fileName: "ai_music.mp3" }, { quoted: msg });
    await editMessage(sock, jid, stKey, `🎶 *AI Music*\n\n✅ Done!\n_Prompt: ${prompt.slice(0,60)}_`);
  } catch { await sendReply(sock, msg, `🎶 *AI Music Generated!*\n\n📥 Download: ${audioUrl}`); }
  await react(sock, msg, "✅");

  // ── FALLBACK ENDPOINTS (merged from duplicate cmd registrations) ──
  // fallback prexzy: prexzyGet('/ai/musicfromdesc', args)
  // fallback prexzy: prexzyGet('/ai/gemimage', args)
  // fallback prexzy: prexzyGet('/ai/gemini', args)
  // fallback prexzy: prexzyGet('/ai/gpt-5', args)
});

// ─── Canvas: Jail Effect ─────────────────────────────────────────────────────
cmd(["dcjail","jaildc","jaileffect"], { desc: "Apply jail bars over image via DC — reply/url", category: "TOOLS" }, async (sock, msg, args) => {
  await react(sock, msg, "🔒");
  let imgUrl = args[0] && args[0].startsWith("http") ? args[0] : null;
  if (!imgUrl) {
    const q = msg.message?.imageMessage || msg.message?.extendedTextMessage?.contextInfo?.quotedMessage?.imageMessage;
    if (q) {
      try {
        const m = await sock.downloadMediaMessage({ message: { imageMessage: q } });
        const FormData = (await import("form-data")).default || require("form-data");
        const fd = new FormData();
        // Upload the downloaded bytes directly. A throwaway /tmp file for
        // every image command could accumulate until the bot hit ENOSPC.
        fd.append("file", m, { filename: "image.jpg", contentType: "image/jpeg" });
         const upload = await dcRequest("/uploader/catbox", { method: "POST", body: fd, headers: fd.getHeaders(), timeout: 30000 });
         imgUrl = upload.data?.url || upload.data?.data?.url;
      } catch {}
    }
  }
  if (!imgUrl) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}dcjail <image URL>\nOr reply to an image with ${CONFIG.PREFIX}dcjail`); return; }
  const jid = msg.key.remoteJid;
  let imgBuf = null;
  try { const buf = await dcGetBinary("/canvas/jail", { image: imgUrl }, 30000); if (buf && buf.length > 500) imgBuf = buf; } catch {}
  if (!imgBuf) { try { const r = await dcGet("/canvas/jail", { image: imgUrl }, 30000); if (r.ok) { const d = r.data?.result || r.data?.url || r.data; if (typeof d === "string" && d.startsWith("http")) imgBuf = Buffer.from((await axios.get(d, { responseType: "arraybuffer", timeout: 30000 })).data); } } catch {} }
  if (!imgBuf) { try { const r = await prexzyGet("/canvas/jail", { image: imgUrl }, 25000); if (r.ok) { const u = r.data?.result || r.data?.url; if (u && u.startsWith("http")) imgBuf = Buffer.from((await axios.get(u, { responseType: "arraybuffer", timeout: 25000 })).data); } } catch {} }
  if (!imgBuf) { await sendReply(sock, msg, `❌ Jail effect failed.`); return; }
  await sock.sendMessage(jid, { image: imgBuf, caption: `🔒 *Jail Effect*` }, { quoted: msg });
  await react(sock, msg, "✅");
});

