// ─── Movies: General Search ───────────────────────────────────────────────────
cmd(["dcmovie","moviedc","dcmoviesearch"], { desc: "Search movies via DC — .dcmovie <title>", category: "INFO" }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}dcmovie <movie title>`); return; }
  await react(sock, msg, "🎬");
  const q = args.join(" ");
  let result = null;
  try { const r = await dcGet("/movie/search", { q }, 20000); if (r.ok) { const d = r.data?.data || r.data; result = Array.isArray(d) ? d : d?.results || [d]; } } catch {}
  if (!result?.length) { try { const r = await prexzyGet("/movie/search", { q }, 20000); if (r.ok) { const d = r.data?.data || r.data; result = Array.isArray(d) ? d : []; } } catch {} }
  if (!result?.length) { try { const { data } = await axios.get(`https://api.siputzx.my.id/api/m/tmdb?query=${encodeURIComponent(q)}`, { timeout: 15000 }); result = data?.data || data?.result; } catch {} }
  if (!result?.length) { await sendReply(sock, msg, `❌ No movies found for: *${q}*`); return; }
  const movie = Array.isArray(result) ? result[0] : result;
  const title = movie?.title || movie?.name || q;
  const year = movie?.year || movie?.release_year || movie?.release_date?.slice(0, 4) || "";
  const rating = movie?.rating || movie?.vote_average || movie?.score || "";
  const overview = movie?.overview || movie?.synopsis || movie?.description || "";
  const poster = movie?.poster_path ? `https://image.tmdb.org/t/p/w500${movie.poster_path}` : (movie?.thumbnail || movie?.poster || null);
  const text = `🎬 *${title}${year ? ` (${year})` : ""}*\n${rating ? `⭐ Rating: ${rating}\n` : ""}${overview ? `\n📝 ${overview.slice(0, 400)}${overview.length > 400 ? "..." : ""}` : ""}`;
  const jid = msg.key.remoteJid;
  if (poster) { try { const b = Buffer.from((await axios.get(poster, { responseType: "arraybuffer", timeout: 15000 })).data); await sock.sendMessage(jid, { image: b, caption: text }, { quoted: msg }); } catch { await sendReply(sock, msg, text); } }
  else { await sendReply(sock, msg, text); }
  await react(sock, msg, "✅");
});

