// ─── Tools: Currency Converter ────────────────────────────────────────────────
cmd(["dccurrency","currencydc","dcconvert"], { desc: "Currency converter via DC — .dccurrency <amount> <FROM> <TO>", category: "TOOLS" }, async (sock, msg, args) => {
  if (args.length < 3) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}dccurrency <amount> <FROM> <TO>\n\nExample: ${CONFIG.PREFIX}dccurrency 100 USD EUR`); return; }
  await react(sock, msg, "💱");
  const [amountStr, from, to] = args;
  const amount = parseFloat(amountStr);
  if (isNaN(amount)) { await sendReply(sock, msg, `❌ Invalid amount: *${amountStr}*`); return; }
  let result = null;
  try { const r = await dcGet("/tools/convert", { amount, from: from.toUpperCase(), to: to.toUpperCase() }, 15000); if (r.ok) result = r.data?.data || r.data; } catch {}
  if (!result) { try { const r = await prexzyGet("/tools/currency", { amount, from: from.toUpperCase(), to: to.toUpperCase() }, 15000); if (r.ok) result = r.data?.data || r.data; } catch {} }
  if (!result) {
    try {
      const { data } = await axios.get(`https://api.exchangerate-api.com/v4/latest/${from.toUpperCase()}`, { timeout: 10000 });
      const rate = data?.rates?.[to.toUpperCase()];
      if (rate) result = { result: (amount * rate).toFixed(4), from: from.toUpperCase(), to: to.toUpperCase(), rate: rate.toFixed(6) };
    } catch {}
  }
  if (!result) { await sendReply(sock, msg, `❌ Could not convert ${from.toUpperCase()} to ${to.toUpperCase()}.`); return; }
  const converted = result?.result || result?.converted || result?.value || result?.to_amount || "";
  const rate = result?.rate || result?.exchange_rate || "";
  await sendReply(sock, msg, `💱 *Currency Converter*\n\n💰 ${amount} ${from.toUpperCase()} = *${converted} ${to.toUpperCase()}*\n${rate ? `📊 Rate: 1 ${from.toUpperCase()} = ${rate} ${to.toUpperCase()}` : ""}`);
  await react(sock, msg, "✅");
});

