// ─── Tools: Image Upscale ─────────────────────────────────────────────────────
cmd(["dcupscale","upscaledc","dcimgupscale"], { desc: "Upscale image via DC — .dcupscale <url> [2x|4x]", category: "TOOLS" }, async (sock, msg, args) => {
  const imgUrl = args[0] || null;
  if (!imgUrl || !imgUrl.startsWith("http")) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}dcupscale <image URL> [2x|4x]`); return; }
  await react(sock, msg, "🔍");
  const jid = msg.key.remoteJid;
  const stMsg = await sock.sendMessage(jid, { text: `🔍 *Upscaling image...*` }, { quoted: msg });
  const stKey = stMsg.key;
  let imgBuf = null;
  try { const buf = await dcGetBinary("/tools/upscale", { url: imgUrl, width: 4096, height: 4096 }, 60000); if (buf && buf.length > 500) imgBuf = buf; } catch {}
  if (!imgBuf) { try { const r = await dcGet("/tools/upscale", { url: imgUrl, width: 2048, height: 2048 }, 60000); if (r.ok) { const d = r.data?.result || r.data?.url || r.data; if (typeof d === "string" && d.startsWith("http")) imgBuf = Buffer.from((await axios.get(d, { responseType: "arraybuffer", timeout: 40000 })).data); } } catch {} }
  if (!imgBuf) { try { const r = await prexzyGet("/tools/upscale", { url: imgUrl }, 50000); if (r.ok) { const u = r.data?.url || r.data?.result; if (u && u.startsWith("http")) imgBuf = Buffer.from((await axios.get(u, { responseType: "arraybuffer", timeout: 40000 })).data); } } catch {} }
  if (!imgBuf) { await editMessage(sock, jid, stKey, `🔍 *Upscale*\n\n❌ Upscaling failed.`); return; }
  await sock.sendMessage(jid, { image: imgBuf, caption: `🔍 *Image Upscaled*` }, { quoted: msg });
  await editMessage(sock, jid, stKey, `🔍 *Upscale*\n\n✅ Done!`);
  await react(sock, msg, "✅");
});

// ─── Tools: SauceNAO ─────────────────────────────────────────────────────────
cmd(["dcsaucenao","saucenaodc","dcrevsearch"], { desc: "Reverse image search via DC — reply/url", category: "TOOLS" }, async (sock, msg, args) => {
  await react(sock, msg, "🔍");
  let imgUrl = args[0] && args[0].startsWith("http") ? args[0] : null;
  if (!imgUrl) {
    const q = msg.message?.imageMessage || msg.message?.extendedTextMessage?.contextInfo?.quotedMessage?.imageMessage;
    if (q) {
      try {
        const m = await sock.downloadMediaMessage({ message: { imageMessage: q } });
        const FormData = (await import("form-data")).default || require("form-data");
        const fd = new FormData();
        fd.append("file", m, { filename: "image.jpg", contentType: "image/jpeg" });
         const upload = await dcRequest("/uploader/catbox", { method: "POST", body: fd, headers: fd.getHeaders(), timeout: 30000 });
         imgUrl = upload.data?.url || upload.data?.data?.url;
      } catch {}
    }
  }
  if (!imgUrl) { await sendReply(sock, msg, `Usage: Reply to an image with *${CONFIG.PREFIX}dcsaucenao*\nOr: ${CONFIG.PREFIX}dcsaucenao <image URL>`); return; }
  let result = null;
  try { const r = await dcGet("/tools/saucenao", { url: imgUrl }, 25000); if (r.ok) result = r.data?.data || r.data; } catch {}
  if (!result) { try { const { data } = await axios.get(`https://saucenao.com/search.php?output_type=2&numres=3&url=${encodeURIComponent(imgUrl)}`, { timeout: 20000 }); result = data?.results?.[0]; } catch {} }
  if (!result) { await sendReply(sock, msg, `❌ Could not identify image source.`); return; }
  const results = Array.isArray(result) ? result.slice(0, 3) : [result];
  const text = `🔍 *SauceNAO Results*\n\n${results.map((r, i) => `${i + 1}. *${r?.data?.title || r?.header?.index_name || "Unknown"}*\n   Similarity: ${r?.header?.similarity || r?.similarity || "?"}\n   ${r?.data?.ext_urls?.[0] || r?.url || ""}`).join("\n\n")}`;
  await sendReply(sock, msg, text);
  await react(sock, msg, "✅");
});

