// ─── Search: Lyrics ───────────────────────────────────────────────────────────
cmd(["dclyrics","lyricsdc","dcsonglyrics"], { desc: "Search song lyrics via DC — .dclyrics <song name>", category: "SEARCH" }, async (sock, msg, args) => {
  if (!args.length) { await sendReply(sock, msg, `Usage: ${CONFIG.PREFIX}dclyrics <song name>\nOr: ${CONFIG.PREFIX}dclyrics <song> - <artist>`); return; }
  await react(sock, msg, "🎤");
  const input = args.join(" ");
  const [songPart, artistPart] = input.split(/\s+-\s+/);
  const t = (songPart || "").trim();
  const a = (artistPart || "").trim();
  let result = null;
  try { const r = await dcGet("/lyrics/search", { q: `${t} ${a}`.trim() }, 20000); if (r.ok) { const d = r.data?.data || r.data; result = Array.isArray(d) ? d[0] : d; } } catch {}
  if (!result?.lyrics && !result?.syncedLyrics) { try { const r = await dcGet("/lyrics", { t, a: a || t }, 20000); if (r.ok) result = r.data?.data || r.data; } catch {} }
  if (!result?.lyrics && !result?.syncedLyrics) { try { const r = await prexzyGet("/search/lyrics", { q: `${t} ${a}`.trim() }, 20000); if (r.ok) result = r.data?.data || r.data; } catch {} }
  if (!result?.lyrics && !result?.syncedLyrics) { try { const { data } = await axios.get(`https://api.siputzx.my.id/api/s/lyrics?title=${encodeURIComponent(t)}&artist=${encodeURIComponent(a || t)}`, { timeout: 15000 }); result = data?.data || data; } catch {} }
  if (!result || (!result.lyrics && !result.syncedLyrics)) { await sendReply(sock, msg, `❌ No lyrics found for: *${t}${a ? " by " + a : ""}*`); return; }
  const title_ = result?.title || result?.track || t;
  const artist_ = result?.artist || result?.artist_name || a || "";
  const lyrics = result?.lyrics || result?.syncedLyrics || result?.content || "No lyrics found";
  const lyricsClean = lyrics.replace(/\[\d{2}:\d{2}\.\d{2,3}\]/g, "").trim();
  const text = `🎤 *${title_}${artist_ ? ` — ${artist_}` : ""}*\n\n${lyricsClean.slice(0, 3500)}${lyricsClean.length > 3500 ? "\n\n_(lyrics truncated)_" : ""}`;
  await sendReply(sock, msg, text);
  await react(sock, msg, "✅");
});

