      if (!st) { await sendReply(sock, msg, "ℹ️ No sync has run yet. Use `.sync` to start one."); return; }
      const dur = st.lastEnd && st.lastStart ? Math.round((st.lastEnd - st.lastStart) / 100) / 10 : null;
      const cfg = __miasReadJsCfg();
      const prefix = cfg[myNum] || cfg.default || "J";
