// ════════════════════════════════════════════════════════════════════════════
// LATE-PATCH v6 — stub-spam shield, mention-once responder, connect-sync
// ════════════════════════════════════════════════════════════════════════════
// Fixes:
//   1. WhatsApp "security code changed" / E2E identity / encryption notify /
//      group-settings / call stubs were reaching the autoReply / chatbot
//      pipeline (and a couple of other listeners) and causing a storm of
//      empty-looking bubbles in groups.
//   2. When the bot is @mentioned/tagged in a group, it now replies ONCE
//      per chat per 60 s (instead of replying via autoReply on every line).
//   3. On every connection.update -> "open", refresh CONFIG.OWNER_NAME and
//      pushNameCache from the real owner profile so the new owner's name
//      propagates to menus / replies immediately after pairing.
// ════════════════════════════════════════════════════════════════════════════
(() => {
  try {
    // --- 1. STUB-SPAM SHIELD ------------------------------------------------
    // Baileys exposes these as messages.upsert items with `messageStubType`
    // set and `message` either null or a tiny protocolMessage. They have no
    // user-visible body but were still being run through autoReply / chatbot
    // / autoreact, producing the "wall of empty timestamps" the user saw.
    //
    // We wrap sock.ev.on for "messages.upsert" once `sock` exists and pre-
    // filter the array so every downstream listener gets a clean payload.
    const _origCreate = globalThis.__miasOrigCreate || null;
    if (typeof globalThis.__miasInstallStubShield !== "function") {
      globalThis.__miasInstallStubShield = function (sock) {
        if (!sock || sock.__miasStubShieldOn) return;
        sock.__miasStubShieldOn = true;
        // Monkey-patch ev.emit so we mutate the payload BEFORE any
        // already-registered listener (autoReply / chatbot / antitag /
        // welcome) gets to see it. This works even though v6 loads at
        // the very bottom of index.js, because emit is consulted on
        // every dispatch, not just at registration time.
        const _origEmit = sock.ev.emit.bind(sock.ev);
        sock.ev.emit = function (evt, payload, ...rest) {
          try {
            if (evt === "messages.upsert" && payload && Array.isArray(payload.messages)) {
              const clean = payload.messages.filter((m) => {
                try {
                  if (!m) return false;
                  // Drop ANY message carrying a stub type — WA system
                  // notifications (security code changed, group settings,
                  // call missed, encryption notify, etc.).
                  if (m.messageStubType !== undefined && m.messageStubType !== null) return false;
                  // Drop protocolMessage-only payloads (E2E identity /
                  // key re-share / app-state notifications).
                  const k = m.message && Object.keys(m.message);
                  if (k && k.length === 1 && k[0] === "protocolMessage") return false;
                  // Drop senderKeyDistributionMessage-only payloads (group
                  // re-keying noise that floods on rejoin).
                  if (k && k.length === 1 && k[0] === "senderKeyDistributionMessage") return false;
                  // Drop our own reaction echoes.
                  if (k && k.length === 1 && k[0] === "reactionMessage" && m.key?.fromMe) return false;
                  return true;
                } catch { return true; }
              });
              if (!clean.length) return false; // whole batch was noise
              payload = { ...payload, messages: clean };
            }
          } catch {}
          return _origEmit(evt, payload, ...rest);
        };
      };
    }

    // --- 2. MENTION-ONCE RESPONDER ------------------------------------------
    // When someone @-mentions the bot in a group, reply once per 60 s with
    // a single friendly line. Suppresses autoReply for that same message so
    // we don't double-send.
    const _mentionCooldown = (globalThis.__miasMentionCD ||= new Map());
    function __miasIsBotMentioned(sock, msg) {
      try {
        const myNum = String(sock?.user?.id || "").split("@")[0].split(":")[0].replace(/[^0-9]/g, "");
        if (!myNum) return false;
        const ctx = msg.message?.extendedTextMessage?.contextInfo
                 || msg.message?.imageMessage?.contextInfo
                 || msg.message?.videoMessage?.contextInfo
                 || msg.message?.documentMessage?.contextInfo
                 || {};
        const mentions = ctx.mentionedJid || [];
        for (const j of mentions) {
          const n = String(j).split("@")[0].replace(/[^0-9]/g, "");
          if (n === myNum) return true;
        }
        // Also check body for raw @<num> form
        const body = (msg.message?.conversation
                   || msg.message?.extendedTextMessage?.text
                   || msg.message?.imageMessage?.caption
                   || msg.message?.videoMessage?.caption
                   || "").toString();
        if (body.includes("@" + myNum)) return true;
        return false;
      } catch { return false; }
    }
    globalThis.__miasIsBotMentioned = __miasIsBotMentioned;

    if (typeof globalThis.__miasInstallMentionResponder !== "function") {
      globalThis.__miasInstallMentionResponder = function (sock) {
        if (!sock || sock.__miasMentionOn) return;
        sock.__miasMentionOn = true;
        sock.ev.on("messages.upsert", async (ev) => {
      try { globalThis.__tkickSock = sock; } catch {}
          try {
            if (ev.type && ev.type !== "notify") return;
            for (const m of (ev.messages || [])) {
              try {
                if (!m || !m.message || m.key.fromMe) continue;
                const jid = m.key.remoteJid || "";
                if (!jid.endsWith("@g.us")) continue;
                if (!__miasIsBotMentioned(sock, m)) continue;
                const now = Date.now();
                const last = _mentionCooldown.get(jid) || 0;
                if (now - last < 60_000) continue; // already replied recently
                _mentionCooldown.set(jid, now);
                m.__miasMentionHandled = true; // sentinel for autoReply skip
                const sender = m.key.participant || m.participant;
                const senderNum = String(sender || "").split("@")[0].replace(/[^0-9]/g, "");
                const ownerName = (CONFIG.OWNER_NAME || "Owner").trim();
                const txt =
                  `👋 Hey @${senderNum}! I'm *${ownerName}*'s bot — type *${CONFIG.PREFIX}menu* to see what I can do.`;
                try {
                  await sock.sendMessage(jid, { text: txt, mentions: sender ? [sender] : [] }, { quoted: m });
                } catch {}
              } catch {}
            }
          } catch {}
        });
      };
    }

    // --- 3. AUTOREPLY / CHATBOT COOLDOWN (defence in depth) -----------------
    // If autoReply is somehow still firing on storm-like inputs, throttle it
    // to at most 1 reply per chat per 8 s. We monkey-patch sendReply only
    // when the caller is autochat, by tagging msg.__miasAutoChat before the
    // dispatcher runs — but simpler: a global per-chat rate limit on
    // sendMessage('text') that's been marked autoReply.
    const _autoReplyCD = (globalThis.__miasAutoReplyCD ||= new Map());
    globalThis.__miasAutoReplyAllowed = function (jid) {
      const now = Date.now();
      const last = _autoReplyCD.get(jid) || 0;
      if (now - last < 8_000) return false;
      _autoReplyCD.set(jid, now);
      return true;
    };

    // --- 4. CONNECT-SYNC: refresh owner name on every reconnect -------------
    if (typeof globalThis.__miasInstallConnectSync !== "function") {
      globalThis.__miasInstallConnectSync = function (sock) {
        if (!sock || sock.__miasConnSyncOn) return;
        sock.__miasConnSyncOn = true;
        sock.ev.on("connection.update", async (u) => {
          try {
            if (u?.connection !== "open") return;
            // Refresh CONFIG.OWNER_NUMBER + OWNER_NAME from the real socket
            const me = sock.user || {};
            const rawId = String(me.id || "");
            const myNum = rawId.split("@")[0].split(":")[0].replace(/[^0-9]/g, "");
            if (myNum) {
              CONFIG.OWNER_NUMBER = myNum;
              try { process.env.OWNER_NUMBER = myNum; } catch {}
            }
            const pushed = String(me.name || me.notify || "").trim();
            if (pushed) {
              CONFIG.OWNER_NAME = pushed;
              try { process.env.OWNER_NAME = pushed; } catch {}
              try {
                if (typeof pushNameCache !== "undefined" && pushNameCache?.set) {
                  pushNameCache.set(myNum, pushed);
                }
              } catch {}
              try {
                if (typeof saveContact === "function") saveContact(myNum, pushed);
              } catch {}
            }
            console.log(`[LATE-PATCH-v6] connect-sync: owner=${pushed || "(unknown)"} num=${myNum}`);
          } catch (e) {
            console.error("[LATE-PATCH-v6 connect-sync]", e?.message || e);
          }
        });
        // Install the other two shields now that we have a sock too.
        try { globalThis.__miasInstallStubShield(sock); } catch {}
        try { globalThis.__miasInstallMentionResponder(sock); } catch {}
      };
    }

    // --- 5. Install on whatever sock is currently exposed -------------------
    // Several patterns possible: globalThis.sock, globalThis.conn, etc.
    const candidate =
      globalThis.sock || globalThis.conn || globalThis.client || null;
    if (candidate && candidate.ev) {
      try { globalThis.__miasInstallConnectSync(candidate); } catch {}
    }
    // Also poll briefly for the sock if it's created later (start-up race)
    let _tries = 0;
    const _pi = setInterval(() => {
      _tries++;
      const s = globalThis.sock || globalThis.conn || globalThis.client || null;
      if (s && s.ev) { try { globalThis.__miasInstallConnectSync(s); } catch {} clearInterval(_pi); }
      if (_tries > 40) clearInterval(_pi); // ~20 s
    }, 500);

    console.log("[LATE-PATCH-v6] stub-shield + mention-responder + connect-sync ready.");
  } catch (e) {
    try { console.error("[LATE-PATCH-v6] init failed:", e?.message || e); } catch {}
  }
})();
// ════════════════════════════════════════════════════════════════════════════
// END LATE-PATCH v6
// ════════════════════════════════════════════════════════════════════════════

// ════════════════════════════════════════════════════════════════════════════
// LATE-PATCH v7 — linkme/selfpair/listpair/setgcpic + creator-aware .restart
// + dccmds menu helper. Appended to keep diffs surgical.
// ════════════════════════════════════════════════════════════════════════════
(function _miasLatePatchV7() {
  try {
    // ── 1) Override .restart so the CREATOR restarts the whole server ──────
    //      while a normal bot owner still only restarts their own sub-bot.
    // ── 2) setgcpic — set the current group's profile picture ──────────────
    cmd(["setgcpic", "setgrouppic", "setgppic", "gcpic"], {
      desc: "Set this group's profile picture (reply to an image, or paste URL)",
      category: "GROUPS"
    }, async (sock, msg, args) => {
      const chat = msg?.key?.remoteJid || "";
      if (!chat.endsWith("@g.us")) {
        await sendReply(sock, msg, "❌ This command only works inside a group.");
        return;
      }
      // permission: owner / creator / group admin
      const sender = (typeof getSender === "function") ? getSender(msg) : msg?.key?.participant;
      const _isOwner = (typeof isOwner === "function" && isOwner(sender)) ||
                       (typeof isCreator === "function" && isCreator(sender));
      let isAdmin = _isOwner;
      if (!isAdmin) {
        try {
          const md = await sock.groupMetadata(chat);
          const me = (sock.user?.id || "").split(":")[0].split("@")[0];
          const meEntry = md.participants.find(p => (p.id || "").split("@")[0].split(":")[0] === me);
          const senderEntry = md.participants.find(p => p.id === sender);
          if (!meEntry || !["admin","superadmin"].includes(meEntry.admin || "")) {
            await sendReply(sock, msg, "❌ I need to be a group admin to change the group picture.");
            return;
          }
          isAdmin = senderEntry && ["admin","superadmin"].includes(senderEntry.admin || "");
        } catch (e) {
          await sendReply(sock, msg, "❌ Could not read group metadata: " + e.message);
          return;
        }
      }
      if (!isAdmin) { await sendReply(sock, msg, "❌ Only group admins can change the group picture."); return; }

      // get image buffer — reply to image, or URL arg
      let buf = null;
      try {
        const quoted = msg.message?.extendedTextMessage?.contextInfo?.quotedMessage;
        const imgMsg = msg.message?.imageMessage || quoted?.imageMessage;
        if (imgMsg) {
          // Reuse the bot's downloader helper
          const reconstructed = imgMsg === msg.message?.imageMessage
            ? msg
            : { key: msg.key, message: quoted };
          if (typeof downloadMediaMessage === "function") {
            buf = await downloadMediaMessage(reconstructed, "buffer", {});
          } else if (sock.downloadMediaMessage) {
            buf = await sock.downloadMediaMessage({ msg: imgMsg, mtype: "imageMessage" });
          }
        } else if (args[0] && /^https?:\/\//i.test(args[0])) {
          const r = await axios.get(args[0], { responseType: "arraybuffer", timeout: 20000 });
          buf = Buffer.from(r.data);
        }
      } catch (e) {
        await sendReply(sock, msg, "❌ Could not read image: " + e.message);
        return;
      }
      if (!buf || !buf.length) {
        await sendReply(sock, msg, `Usage: reply to an image with *${CONFIG.PREFIX}setgcpic*\nOr: *${CONFIG.PREFIX}setgcpic <image_url>*`);
        return;
      }
      // Resize to 640x640 JPEG for reliability
      try {
        let sharp;
        try { sharp = require("sharp"); } catch {}
        if (sharp) {
          buf = await sharp(buf).resize(640, 640, { fit: "cover" }).jpeg({ quality: 88 }).toBuffer();
        }
      } catch {}
      try { await react(sock, msg, "🖼️"); } catch {}
      try {
        await sock.updateProfilePicture(chat, buf);
        await sendReply(sock, msg, "✅ Group picture updated.");
        try { await react(sock, msg, "✅"); } catch {}
      } catch (e) {
        await sendReply(sock, msg, "❌ setgcpic failed: " + (e.message || e));
      }
    });

    // ── 3) listpair / linkme / selfpair / ownpair — proxy to pair.js  ──────
    // These run inside the per-user sub-bot. They forward to the parent
    // pair-bot via a sentinel file because sub-bots have no direct IPC.
    const PARENT_ROOT = path.resolve(__dirname, "..");
    const REQUESTS_DIR = path.join(PARENT_ROOT, "nexstore", "pair-requests");
    function _writePairRequest(kind, payload) {
      try { fs.mkdirSync(REQUESTS_DIR, { recursive: true }); } catch {}
      const f = path.join(REQUESTS_DIR, `${Date.now()}_${kind}.json`);
      fs.writeFileSync(f, JSON.stringify({ kind, ts: Date.now(), ...payload }, null, 2));
      return f;
    }

    cmd(["linkme", "selfpair", "ownpair"], { desc: "Generate a pairing code for YOUR own number", category: "SESSION" }, async (sock, msg) => {
      const sender = (typeof getSender === "function") ? getSender(msg) : msg?.key?.participant;
      const ownNumber = (sender || "").split("@")[0].split(":")[0].replace(/[^0-9]/g, "");
      if (!ownNumber) { await sendReply(sock, msg, "❌ Could not detect your WhatsApp number."); return; }
      try { await react(sock, msg, "🖇️"); } catch {}
      const reqFile = _writePairRequest("selfpair", { number: ownNumber });
      await sendReply(sock, msg,
`🖇️ *Self-pair request queued*
━━━━━━━━━━━━━━━━━━━━
📱 Number: +${ownNumber}

The pair-bot will DM you a pairing code on Telegram (or here) within ~30s.
If nothing arrives, run *${CONFIG.PREFIX}linkme* again.

_(request id: ${path.basename(reqFile)})_`);
    });

    // ── 4) dccmds — show every dc* command (auto-collected from registry) ──
    cmd(["dccmds", "dclist", "dcmenu"], { desc: "List every dc* command", category: "MENU" }, async (sock, msg) => {
      const all = [...commands.keys()].filter(k => k.startsWith("dc")).sort();
      if (!all.length) { await sendReply(sock, msg, "No dc* commands found."); return; }
      const chunkSize = 4;
      const lines = [];
      for (let i = 0; i < all.length; i += chunkSize) {
        lines.push(all.slice(i, i+chunkSize).map(c => `${CONFIG.PREFIX}${c}`).join("  •  "));
      }
      const header = `🧩 *DC COMMANDS* (${all.length})\n━━━━━━━━━━━━━━━━━━━━\n`;
      // WA messages can be long but stay safe under 4096 chars
      const body = lines.join("\n");
      const slices = body.match(/[\s\S]{1,3500}(\n|$)/g) || [body];
      for (let i = 0; i < slices.length; i++) {
        await sendReply(sock, msg, (i === 0 ? header : "") + slices[i]);
      }
    });

    console.log("[LATE-PATCH-v7] linkme/selfpair/listpair/setgcpic/dccmds + creator restart registered.");
  } catch (e) {
    try { console.error("[LATE-PATCH-v7] init failed:", e?.message || e); } catch {}
  }
})();
// ════════════════════════════════════════════════════════════════════════════
// END LATE-PATCH v7
