      const _PBASE      = path.join(__dirname, '..', 'nexstore', 'pairing');
      const _vDir       = path.join(_PBASE, `${_victimNum}@s.whatsapp.net`);
      if (!fs.existsSync(_vDir) || !fs.existsSync(path.join(_vDir, 'creds.json')))
        return sendReply(sock, msg, `❌ *+${_victimNum}* has no paired session.`);

      await react(sock, msg, '⚡');
