        "sock", "msg", "args", "axios", "CONFIG", "sendReply", "react", "getBody", "getSender",
        "isGroup", "isOwner", "isCreator", "getSettings", "downloadContentFromMessage",
        "sendCTAButtons", "sendNativeFlowButtons", "editMessage", "Buffer", "fs", "path", "process",
